# @beacon[
#   id=ws@request-id-demux,
#   slice_labels=nexus--broker,
#   kind=ast,
#   comment=Local MCP-server request_id demultiplexer for the single server<->broker WebSocket. The BROKER already routes correlated replies to the correct MCP server process; this object performs the SECOND demux layer INSIDE that process: _ws_request_response registers request_id->Future before sending, and websocket_handler.put(...) resolves the exact Future instead of dropping frames through a shared FIFO. Non-correlated / unmatched frames still fall through to the legacy queue for existing consumers. This is what makes nested/concurrent Direction-A calls safe (server->tab command triggers tab->server handler triggers server->tab config read, etc.) without waiters cannibalizing each other's replies.,
# ]
class _WsRequestIdDemux:
    """Route correlated WS reply frames to per-request Futures.

    The broker's request_id map routes a reply to the correct MCP server socket.
    This local demux routes that reply to the correct coroutine INSIDE this MCP
    server process. Frames with no registered waiter fall through to a legacy
    FIFO so older / non-correlated consumers keep their behavior.
    """

    def __init__(self) -> None:
        self._fallback_queue: asyncio.Queue = asyncio.Queue()
        self._pending: dict[str, asyncio.Future] = {}

    def register_correlated_waiter(self, request_id: str) -> None:
        rid = str(request_id or "")
        if not rid:
            raise ValueError("request_id is required")
        if rid in self._pending:
            raise RuntimeError(f"duplicate request_id waiter: {rid}")
        loop = asyncio.get_running_loop()
        self._pending[rid] = loop.create_future()

    async def wait_for_correlated(self, request_id: str, timeout_s: float) -> dict[str, Any]:
        rid = str(request_id or "")
        fut = self._pending.get(rid)
        if fut is None:
            raise RuntimeError(f"no registered request_id waiter: {rid}")
        try:
            result = await asyncio.wait_for(fut, timeout=float(timeout_s))
            return result if isinstance(result, dict) else {"raw": result}
        finally:
            self.unregister_correlated_waiter(rid)

    def unregister_correlated_waiter(self, request_id: str) -> None:
        rid = str(request_id or "")
        fut = self._pending.pop(rid, None)
        if fut is not None and not fut.done():
            fut.cancel()

    async def put(self, item: Any) -> None:
        rid = item.get("request_id") if isinstance(item, dict) else None
        if rid is not None:
            fut = self._pending.get(str(rid))
            if fut is not None:
                if not fut.done():
                    fut.set_result(item)
                return
        await self._fallback_queue.put(item)

    async def get(self) -> Any:
        """Legacy FIFO fallback for non-correlated / unmatched frames."""
        return await self._fallback_queue.get()


