                # render block), so derive the group fields inline from the
                # already-resolved `chosen` group for this early stale reply.
                await _reply({
                    "success": True,
                    "slice_row_stale": True,
                    "markdown": "",
                    "group_id": (chosen.get("id") if isinstance(chosen, dict) else None),
                    "group_name": (chosen.get("name") if isinstance(chosen, dict) else None),
                    "cache_sourced": True,
                    "error": (
                        "A selected row no longer matches the current "
                        "cache/config. Re-apply the view (and refresh the "
                        "nodes cache if you edited Workflowy)."
                    ),
                })
