            want_key = _slice_row_key(
                {"uuid": r_uuid, "ancestor_path": r_path, "occurrence": r_occ}
            )
            matched = next(
                (rr for rr in rows if _slice_row_key(rr) == want_key), None
            )
            if matched is None:
                await _reply({
                    "success": True,
                    "slice_row_stale": True,
                    "markdown": "",
                    "group_id": _grp_id,
                    "group_name": _grp_name,
                    "cache_sourced": True,
                    "error": (
                        "This applied view no longer matches the current "
                        "cache/config (the clicked row is gone). Re-apply it "
                        "(and refresh the nodes cache if you edited "
                        "Workflowy)."
                    ),
                })
                return
