# @beacon[
#   id=coherence@legacy-tool-boundary-refusal,
#   slice_labels=nexus--mcp-api,ra-coherence,ra-workflowy-cache,
#   kind=ast,
#   comment=S03-CR-03 legacy-profile boundary migration: the selectable 'legacy' MCP profile is a first-class migrated surface — every cache-backed legacy tool is wrapped in ONE local-capture cache_operation_boundary at FastMCP registration (never a boundaryless loud failure, never a fail-soft cache-less render); cache-free legacy tools (system.* and slice-group CRUD equivalents per LEGACY_TOOL_MAPPING) keep zero-coherence-work contracts. Profile-inactive behavior is the unchanged identity decorator.,
# ]
def _legacy_coherence_refusal(exc: Any) -> dict:
    """S04 §7.1: the legacy-profile typed failure shape for a hard-barrier
    refusal — equivalent fields, never a generic ``operation_failed``."""

    return {
        "success": False,
        "error_code": "coherence_barrier_active",
        "error": str(exc),
        "extra": exc.refusal_extra(),
    }


_LEGACY_CANONICAL_LOOKUP: dict[str, str] | None = None


def _legacy_canonical_operations() -> dict[str, str]:
    """legacy tool name -> consolidated canonical operation (lazy, cached).

    Derived from ``LegacyToolMapping.routes``.  An ordinary
    ``disposition=\"mapped\"`` row must carry EXACTLY ONE unqualified
    route — its ``target`` is the canonical operation.  Split-by-mode
    rows (the legacy ``lightning_rod`` tool) are skipped here and
    resolve mode-aware through :data:`_LEGACY_LIGHTNING_ROUTE_CANONICAL`
    instead.  A malformed ordinary row (zero, multiple, or
    selector-qualified routes) raises loudly — never a silent
    ``targets[0]`` pick (S04 Remediation Chain 5, expanded item 3).
    """

    global _LEGACY_CANONICAL_LOOKUP
    if _LEGACY_CANONICAL_LOOKUP is None:
        from .legacy_tool_mapping import LEGACY_TOOL_MAPPING

        lookup: dict[str, str] = {}
        for entry in LEGACY_TOOL_MAPPING:
            name = str(getattr(entry, "legacy_tool", ""))
            if not name:
                continue
            if str(getattr(entry, "disposition", "")) != "mapped":
                # Split-by-mode rows resolve mode-aware elsewhere.
                continue
            routes = tuple(getattr(entry, "routes", ()) or ())
            if len(routes) != 1 or getattr(routes[0], "selector", None):
                raise ValueError(
                    "Ordinary legacy tool mapping row must carry exactly one "
                    "unqualified route to derive its canonical operation: "
                    f"{name!r} (disposition={getattr(entry, 'disposition', None)!r}, "
                    f"routes={routes!r})"
                )
            lookup[name] = str(getattr(routes[0], "target", ""))
        _LEGACY_CANONICAL_LOOKUP = lookup
    return _LEGACY_CANONICAL_LOOKUP


_LEGACY_LIGHTNING_ROUTE_CANONICAL = {
    "gather": "lightning_rod.gather",
    "render_tags": "lightning_rod.render_tags",
    "render_search": "lightning_rod.render_search",
    "render_symbols": "lightning_rod.render_symbols",
    "ensure_beacons": "beacon.tags.ensure",
    "remove_beacon_tags": "beacon.tags.remove",
    "mutate_node_tags": "tag.batch",
}


def _legacy_admission_spec(tool_name: str, call_kwargs: dict) -> Any:
    """Resolve the consolidated OperationSpec a legacy CALL routes to
    (mode-aware for the split-by-mode legacy lightning_rod tool).

    S04 Remediation Chain 5 (expanded item 3): the lookup is derived from
    ``LegacyToolMapping.routes`` (repaired — it previously read a
    nonexistent ``canonical`` attribute and was therefore EMPTY, leaving
    the wrapper's gate/advisory branches dead for every non-Lightning
    legacy tool).  ``None`` is now returned only for an unknown tool
    name or an unmapped lightning_rod mode."""

    if tool_name == "lightning_rod":
        canonical = _LEGACY_LIGHTNING_ROUTE_CANONICAL.get(
            str(call_kwargs.get("mode") or "").strip()
        )
    else:
        canonical = _legacy_canonical_operations().get(tool_name)
    if not canonical:
        return None
    registries = {
        "node": NODE_REGISTRY,
        "tag": TAG_REGISTRY,
        "anchor": ANCHOR_REGISTRY,
        "slice_group": SLICE_GROUP_REGISTRY,
        "beacon": BEACON_REGISTRY,
        "system": SYSTEM_REGISTRY,
        "glimpse": GLIMPSE_REGISTRY,
        "lightning_rod": LIGHTNING_ROD_REGISTRY,
    }
    family, _, verb = canonical.partition(".")
    registry = registries.get(family)
    return registry.resolve(verb) if registry is not None else None


# @beacon[
#   id=coherence@legacy-tool-boundary-wrapper,
#   slice_labels=nexus--mcp-api,ra-coherence,ra-workflowy-cache,
#   kind=ast,
#   comment=S03-CR-03 legacy-profile boundary migration: the selectable 'legacy' MCP profile is a first-class migrated surface — every cache-backed legacy tool is wrapped in ONE local-capture cache_operation_boundary at FastMCP registration (never a boundaryless loud failure, never a fail-soft cache-less render); cache-free legacy tools (system.* and slice-group CRUD equivalents per LEGACY_TOOL_MAPPING) keep zero-coherence-work contracts. Profile-inactive behavior is the unchanged identity decorator. S04: the same shared hard-stop admission gate and read advisory apply here too (resolved mode-aware through LEGACY_TOOL_MAPPING), with the legacy typed failure shape for refusals. S04 Remediation Chain 5 (expanded item 3): the canonical lookup is repaired (derived from LegacyToolMapping.routes — the gate is now LIVE for every legacy mutation tool) and the read advisory is shaped INSIDE the boundary while the captured status is live, with the glimpse/lightning_rod family skip (internal render seams own provenance). 9a ([ap:G2UALX]): the ONE empty-output stub (stub_empty_text_result) runs on the raw handler result BEFORE the advisory, so the legacy surface delivers the literal '(empty)' exactly as the consolidated funnel does.,
# ]
def _wrap_legacy_cache_operation_boundary(func: Any, tool_name: str) -> Any:
    """Wrap one cache-backed legacy tool in the S03 §7.1 operation boundary.

    S04: the wrap also runs the shared hard-stop admission gate for
    refuse-class legacy calls (mode-aware for the split-by-mode legacy
    lightning_rod), converts typed coherence refusals into the legacy typed
    failure shape, and applies the standardized read advisory to
    cache-backed read-safe results (idempotent with the internal render
    seams the underlying impls already pass through).
    """

    import functools

    @functools.wraps(func)
    async def _inner(*args, **kwargs):  # type: ignore[no-untyped-def]
        import inspect

        from .coherence.admission import (
            ADMISSION_CLASS_REFUSE_HARD_DIRT,
            mutation_admission_class,
            require_coherence_mutation_admission,
        )
        from .coherence.errors import CoherenceBarrierActiveError
        from .coherence.read_advisory import apply_coherence_read_advisory

        spec = _legacy_admission_spec(tool_name, kwargs)
        if (
            spec is not None
            and mutation_admission_class(
                spec.canonical_name, spec.side_effects, spec.cache_backed
            )
            == ADMISSION_CLASS_REFUSE_HARD_DIRT
        ):
            try:
                await require_coherence_mutation_admission(
                    _admission_coherence_paths, operation=f"legacy:{tool_name}"
                )
            except CoherenceBarrierActiveError as exc:
                return _legacy_coherence_refusal(exc)
        try:
            async with _mcp_operation_boundary(f"legacy:{tool_name}"):
                result = func(*args, **kwargs)
                if inspect.isawaitable(result):
                    result = await result
                # 9a ([ap:G2UALX]): the empty-output stub at the legacy
                # profile's single public seam -- same helper, same order as
                # the consolidated funnel: raw handler result first, advisory
                # after, so a prepended advisory can never hide a blank body
                # from the stub.
                result = stub_empty_text_result(result)
                if (
                    spec is not None
                    and spec.cache_backed
                    # S04 Remediation Chain 5 (work-order item 3): mirror the
                    # consolidated render-family rule (the dispatch finalizer's
                    # `spec.family in ("glimpse", "lightning_rod") -> skip`): the
                    # internal render seams own advisory shaping for the render
                    # families, with EXPLICIT provenance (cache_sourced) — the
                    # outer wrapper must not guess provenance.  A blanket
                    # application here re-advised cache-free browser captures (a
                    # legacy workflowy_glimpse(render_spec="modal") read over a
                    # dom_captured_tree) with a FALSE cache-staleness warning.
                    # Non-render legacy cache reads keep this wrapper's advisory.
                    and spec.family not in ("glimpse", "lightning_rod")
                    and not (
                        set(spec.side_effects)
                        - {"pure_read", "render", "modal_push", "artifact_write"}
                    )
                ):
                    # S04 §7.5 (Remediation Chain 5, expanded item 3): the
                    # advisory reflects the operation's CAPTURED boundary
                    # status, so it must be shaped while that capture is
                    # still live — INSIDE the boundary.  (Previously applied
                    # after the `async with` exited, when the ContextVar was
                    # already reset and the application no-op'd.)
                    result = apply_coherence_read_advisory(result)
        except CoherenceBarrierActiveError as exc:
            return _legacy_coherence_refusal(exc)
        return result

    return _inner


def _legacy_tool(*args, **kwargs):  # type: ignore[no-untyped-def]
    """Legacy-profile ``mcp.tool`` gate + S03-CR-03 boundary migration.

    Profile-inactive: the identity decorator (unchanged contract).
    Profile-active: registers through ``_workflowy_tool`` for catalog metadata, and
    wraps every cache-backed handler in ONE local-capture operation
    boundary (S03 §7.1) so the selectable legacy surface is a first-class
    migrated surface — never a boundaryless loud failure, never a
    fail-soft render without cache context.  Cache-free legacy tools
    (the system.* and slice-group CRUD equivalents) keep their
    zero-coherence-work contracts and are never wrapped.
    """

    if REGISTRATION_PROFILE == "legacy":
        deco = _workflowy_tool(*args, **kwargs)

        def _register(func):  # type: ignore[no-untyped-def]
            tool_name = str(
                kwargs.get("name")
                or (args[0] if args and isinstance(args[0], str) else "")
                or func.__name__
            )
            if tool_name in _LEGACY_CACHE_FREE_TOOLS:
                return deco(func)
            return deco(_wrap_legacy_cache_operation_boundary(func, tool_name))

        return _register

    def identity(func):  # type: ignore[no-untyped-def]
        return func

    return identity


_consolidated_tool = _profile_tool("consolidated")


# Claude-Desktop-Windows compatibility shim.
#
# Claude Desktop on Windows ships a JSON-Schema validator that fails to
# compile complex outputSchema definitions containing $defs/$ref (the shape
# FastMCP auto-generates from Python return-type hints). When compilation
# fails the entire tool list is silently dropped from the renderer, and the
# model sees "0 tools available" despite a healthy MCP handshake.
# Anthropic-acknowledged bug: modelcontextprotocol/mcpb#174 (closed as
# "not planned" because the fix belongs in Claude Desktop). Mitigated here
# by stripping outputSchema from every tool before tools/list serialization;
# tools function identically without it. See transforms.py for full rationale.
#
# Version-aware: the FastMCP Transform API exists only on FastMCP 3.x. The
# legacy live install (C:\Temp\workflowy-mcp-vladzima) currently runs
# FastMCP 2.13.x and the apply_* helper silently no-ops there, leaving the
# legacy install behaviorally identical to before. The new venv install at
# the new repo runs FastMCP 3.3.1 and the workaround activates there.
from .transforms import (  # noqa: E402
    apply_params_schema_transform,
    apply_strip_output_schema_workaround,
)

apply_strip_output_schema_workaround(mcp)
# Published-params-schema override for the six family tools: attached only
# in `object` mode; a no-op (returns False) in `union` mode or on a FastMCP
# 2.x install. Advertisement only -- the tool signatures and the runtime
# acceptance path (FunctionTool.run -> TypeAdapter -> _normalize_params) are
# untouched in both modes.
apply_params_schema_transform(mcp, PARAMS_SCHEMA_MODE)


# In-memory job management for long-running operations (ETCH, NEXUS, etc.)
# @beacon[
#   id=daemon-lifecycle@background-job,
#   role=_start_background_job: existing in-memory job front and admitted task handoff,
#   slice_labels=nexus-loading-flow,nexus--daemon,ra-carto-jobs,
#   kind=ast,
#   comment=Keeps the existing generic job registry and cache/admission recheck; an independent admitted child retains result/finalization through drain, and user CancelledError is recorded cancelled rather than failed.,
# ]
async def _start_background_job(
    kind: str,
    payload: dict[str, Any],
    coro_factory: Callable[[str], Awaitable[dict]],
) -> dict:
    """Launch an existing generic job, retaining task/finally and honest cancellation."""
    global _job_counter, _jobs

    async with _job_lock:
        _job_counter += 1
        job_id = f"{kind}-{_job_counter}"

    _jobs[job_id] = {
        "job_id": job_id,
        "kind": kind,
        "status": "pending",  # pending | running | completed | failed | cancelling | cancelled
        "payload": payload,
        "result": None,
        "error": None,
        "started_at": datetime.utcnow().isoformat(),
        "finished_at": None,
        "_task": None,  # internal field, not exposed in status
    }

    async def runner() -> None:
        from .coherence.errors import CoherenceBarrierActiveError

        try:
            _jobs[job_id]["status"] = "running"
            # S03 §7.1: an async job is a NEW operation — it establishes its
            # own adoption boundary (never inherits the spawner's pinned
            # generation; the spawn below runs through the isolated-context
            # helper for the same reason).
            from .coherence.operation_cache import cache_operation_boundary

            async with daemon_lifecycle.operation_accounting(f"job:{kind}"), cache_operation_boundary(get_client(), f"job:{kind}"):
                # S04 §7.2/§8.3: async recheck inside the independently
                # dispatched operation — a barrier raised after queueing
                # terminates the job with zero mutations (never merely
                # because the request was clean when queued).
                from .coherence.admission import require_coherence_mutation_admission

                await require_coherence_mutation_admission(
                    _admission_coherence_paths, operation=f"job:{kind}"
                )
                result = await coro_factory(job_id)
            _jobs[job_id]["result"] = result
            _jobs[job_id]["status"] = "completed" if result.get("success", True) else "failed"
        except asyncio.CancelledError:
            # Explicit cancellation via mcp_cancel_job
            _jobs[job_id]["error"] = "CancelledError: Job was cancelled by user request"
            _jobs[job_id]["status"] = "cancelled"
        except CoherenceBarrierActiveError as e:
            # S04 Remediation Chain 3 (work-order item 2): the universal typed
            # refusal contract for independently dispatched in-memory jobs —
            # system.job.status must machine-read coherence_barrier_active and
            # the standard recovery payload, not only an error string.  The
            # human error text is retained; the terminal status vocabulary is
            # unchanged ("failed"); zero-mutation behavior is preserved (the
            # refusal fires BEFORE coro_factory runs).
            _jobs[job_id]["error"] = f"{type(e).__name__}: {e}"
            _jobs[job_id]["error_code"] = "coherence_barrier_active"
            _jobs[job_id]["error_extra"] = e.refusal_extra()
            _jobs[job_id]["status"] = "failed"
        except Exception as e:  # noqa: BLE001
            _jobs[job_id]["error"] = f"{type(e).__name__}: {e}"
            _jobs[job_id]["status"] = "failed"
        finally:
            _jobs[job_id]["finished_at"] = datetime.utcnow().isoformat()

    from .coherence.operation_cache import create_isolated_context_task

    controller = daemon_lifecycle.active_lifecycle()
    task = (controller.spawn_admitted_child(f"job:{kind}", runner())
            if controller is not None else create_isolated_context_task(runner()))
    _jobs[job_id]["_task"] = task
    if controller is not None:
        controller.track_background_task(task, f"job:{kind}")

    return {
        "success": True,
        "job_id": job_id,
        "status": "started",
        "kind": kind,
    }


def _parse_carto_job_timestamp_utc_naive(value: Any):
    """Parse a job JSON timestamp to a naive UTC datetime (None if unparseable).

    Job writers disagree on the form: most write a naive UTC ISO string
    (``datetime.utcnow().isoformat()``), the cancellation path writes an
    aware one (``...+00:00``).  Comparing an aware value with the GC's naive
    cutoff raised TypeError and silently ended the whole GC pass, so aware
    values are converted to UTC and made naive here.
    """
    from datetime import timezone

    try:
        ts = datetime.fromisoformat(str(value))
    except Exception:  # noqa: BLE001
        return None
    if ts.tzinfo is not None:
        ts = ts.astimezone(timezone.utc).replace(tzinfo=None)
    return ts


# @beacon[
#   id=auto-beacon@_gc_carto_jobs-0oga,
#   role=ƒ _gc_carto_jobs(carto_jobs_base: str, max_age_seconds: int),
#   slice_labels=ra-carto-jobs,
#   kind=ast,
#   comment=Off-loop shared-head GC ages every terminal folder's debug artifacts, but decides completed/cancelled record deletion from the current head under the one status lock. Failed/warning evidence and immutable live protection survive; configured age applies without a sidecar read or new sweeper.,
# ]
def _gc_carto_jobs(carto_jobs_base: str, max_age_seconds: int = 3600, *, protected_ids=frozenset(), protected_paths=frozenset(), candidates=None) -> None:
    r"""Garbage-collect old CARTO_REFRESH artifacts (jobs + per-file F12 logs).

    Job GC:
        Any job whose JSON lives under ``carto_jobs_base`` with ``status`` in
        {"completed", "cancelled"} and ``updated_at`` (or ``created_at``)
        older than ``max_age_seconds`` is removed along with its job-level
        log file.

    All terminal kinds also age out their same-stem folder's ``file_refresh``
    diagnostics (R-c). Failed/warning records and their evidence remain until
    manual clearing; age and terminal class are reread under the existing
    status lock before deletion. No evidence sidecar is opened here.

    Per-file F12 GC:
        Additionally removes per-file Cartographer F12 artifacts under the
        configured file-refresh directory (or its portable runtime fallback).

        When their modification time is older than the same age threshold,
        they are pruned. This directory contains, for each F12 run:

            <timestamp>_file_refresh_<shortid>_<basename>.json
            <timestamp>_file_refresh_<shortid>_<basename>.weave_journal.json
            <timestamp>_file_refresh_<shortid>_<basename>.reconcile_debug.log

        We do *not* attempt to tie these back to a specific job_id; they are
        treated as global F12 artifacts and pruned purely by age.

    Immutable loop protection pins active/pending/reserved current jobs.

    Failures during GC are silently ignored; this helper is best-effort and
    must never raise. Corrupt or unreadable job files are left in place for
    manual inspection.
    """
    try:
        from pathlib import Path
        from datetime import datetime, timedelta
        import json as json_module  # type: ignore[redefined-builtin]

        now = datetime.utcnow()
        cutoff = now - timedelta(seconds=max_age_seconds)

        # 1) Job JSON + job-level log under carto_jobs_base
        base_path = Path(carto_jobs_base)
        if base_path.exists():
            if candidates is None:
                candidates = _read_carto_history_candidates(base_path)
            for job_path, job in candidates["rows"]:
                # Only consider CARTO_* jobs; ignore any other JSON artifacts.
                if not str(job.get("type") or "").startswith("CARTO_"):
                    continue

                status = str(job.get("status", "")).lower()
                # GC EXEMPTION (May 2026 expanded): only the two "clean exit"
                # states are eligible for age-based auto-cleanup.
                # - `failed` jobs are exempt (not in the eligible set, so we
                #   `continue` past delete and the file stays).
                # - `completed_with_warnings` jobs are ALSO exempt for the
                #   same reason: the user must be able to come back to a
                #   warning long after the run finished.
                # The eligible set is sourced from the SHARED config vocabulary
                # (CARTO_GC_ELIGIBLE_STATUSES) so the GC and the manual
                # 'Clear job history' button classify job statuses from one
                # source of truth. Deny-by-default falls out for free: any
                # in-flight OR unrecognized/blank/future status is not in the
                # eligible set, so a >1h first-map run is never age-deleted
                # even if it briefly presents a novel status.
                if not is_carto_job_terminal(status):
                    continue

                ts_str = job.get("updated_at") or job.get("created_at")
                if not ts_str:
                    continue

                ts = _parse_carto_job_timestamp_utc_naive(ts_str)
                if ts is None:
                    continue

                if ts > cutoff:
                    continue

                # R-c: diagnostics age out for every terminal status, without
                # deleting failed/warning records or their complete evidence.
                protected_key = os.path.normcase(os.path.abspath(str(job_path)))
                if str(job.get("id") or job_path.stem) in protected_ids or protected_key in protected_paths:
                    continue
                with _CARTO_JOB_STATUS_WRITE_LOCK:
                    from .carto_job_record import read_carto_job_record_cached
                    current = read_carto_job_record_cached(job_path)
                    current_time = _parse_carto_job_timestamp_utc_naive(current.get("updated_at") or current.get("created_at"))
                    if not is_carto_job_terminal(current.get("status")) or current_time is None or current_time > cutoff:
                        continue
                    debug_dir = job_path.with_suffix("") / "file_refresh"
                    if debug_dir.is_dir():
                        import shutil
                        shutil.rmtree(debug_dir, ignore_errors=True)
                    # Candidate snapshots choose work, never deletion policy:
                    # a warning/failure that landed since enumeration keeps
                    # its evidence. The reentrant existing lock spans both
                    # this current classification and the record deletion.
                    if str(current.get("status") or "").lower() not in CARTO_GC_ELIGIBLE_STATUSES:
                        continue
                    if not _delete_carto_job_json_if_unclaimed(base_path, job_path, current, protected_ids=protected_ids, protected_paths=protected_paths):
                        continue

                # Determine associated log path, defaulting to <job_id>.log in the same dir.
                logs_path = job.get("logs_path")
                try:
                    if logs_path:
                        Path(str(logs_path)).unlink(missing_ok=True)
                except Exception:  # noqa: BLE001
                    # Log deletion failures at call site if needed.
                    pass

                # Job JSON was removed under the status writer above.

                # Delete per-job folder (if present), which may contain F12 file_refresh logs.
                try:
                    jid = job.get("id") or job_path.stem

                    # Mirror the launcher's same-stem job-directory naming:
                    #   YYYYMMDD-HHMMSS_<job-id>  (falls back to bare job id if needed).
                    job_dir_name = str(jid)
                    created_str = job.get("created_at")
                    if isinstance(created_str, str) and created_str:
                        try:
                            ts = datetime.fromisoformat(str(created_str))
                            prefix = ts.strftime("%Y%m%d-%H%M%S")
                            job_dir_name = f"{prefix}_{jid}"
                        except Exception:  # noqa: BLE001
                            pass

                    job_dir = base_path / job_dir_name
                    if job_dir.exists() and job_dir.is_dir():
                        import shutil

                        shutil.rmtree(job_dir, ignore_errors=True)
                except Exception:  # noqa: BLE001
                    pass

        # 2) Per-file F12 artifacts under temp/cartographer_file_refresh
        try:
            file_refresh_dir = Path(_get_carto_file_refresh_dir())
            if file_refresh_dir.exists():
                for path in file_refresh_dir.iterdir():
                    try:
                        if not path.is_file():
                            continue
                        name = path.name
                        # Guard to only touch Cartographer F12 artifacts.
                        if "_file_refresh_" not in name:
                            continue
                        # JSON source + per-file journal + per-file reconcile debug log.
                        if not (
                            name.endswith(".json")
                            or name.endswith(".weave_journal.json")
                            or name.endswith(".reconcile_debug.log")
                        ):
                            continue

                        mtime = datetime.utcfromtimestamp(path.stat().st_mtime)
                        if mtime > cutoff:
                            continue

                        path.unlink(missing_ok=True)
                    except Exception:  # noqa: BLE001
                        continue
        except Exception:  # noqa: BLE001
            # F12 GC failures must not affect callers.
            pass

    except Exception:  # noqa: BLE001
        # Absolutely must not raise from GC; callers treat this as best-effort.
        return


# @beacon[
#   id=auto-beacon@_start_carto_refresh_job-vgpo,
#   role=⚡ _start_carto_refresh_job(root_uuid: str, mode: str),
#   slice_labels=ra-reconcile,nexus-core-v1,ra-logging,ra-carto-jobs,
#   kind=ast,
# ]
def _manifest_base_usable(client) -> bool:
    """S02 §8: whether a usable manifest base snapshot exists.

    The skip toggle may suppress optional CARTO preflight freshness ONLY
    when this is True.  Any lineage fault answers False (refresh required).
    """
    try:
        from .coherence.schema import read_manifest
        from .coherence.snapshot_store import load_manifest_base_envelope

        paths = client._coherence_paths()
        manifest = read_manifest(paths, required=False)
        if manifest is None or manifest.base_snapshot_path is None:
            return False
        load_manifest_base_envelope(paths, manifest)
        return True
    except Exception:  # noqa: BLE001 - any lineage fault means refresh required
        return False


# @beacon[
#   id=carto-runtime@select-live-basis,
#   slice_labels=ra-carto-jobs,mci-epoch-seams,ra-workflowy-cache,
#   kind=ast,
#   comment=Captures the daemon publisher-current welded view and borrows its immutable ID map without snapshot reload or job-basis write; manifest-base lineage and current-view markers remain separate diagnostics.,
# ]
async def _carto_select_live_basis(client, freshness_disposition: str) -> dict[str, Any]:
    """Select one live basis; the eventual job pins only after its own B0.

    The manifest base diagnostic can precede the current view's journal head. Do not
    invent envelope-only publication_kind/schema fields or describe a live
    view's later sequence as the incorporated watermark of that base file.
    No source snapshot is loaded or serialized into another execution cache.
    """
    from .coherence.schema import read_manifest

    view, _dirty = client._capture_view_and_dirty()
    manifest = read_manifest(client._coherence_paths(), required=True)
    if manifest.base_snapshot_path is None:
        raise RuntimeError("No manifest base snapshot exists; run a cache refresh first.")
    if not view.nodes_by_id:
        raise RuntimeError("The manifest base snapshot contains no usable nodes.")
    return {
        "snapshot_path": manifest.base_snapshot_path,
        "freshness_disposition": freshness_disposition,
        "cache_by_id": view.nodes_by_id,
        "snapshot_lineage": {
            "account_scope_id": manifest.account_scope_id,
            "epoch_number": manifest.epoch_number,
            "epoch_id": manifest.epoch_id,
            "incorporated_through_seq": manifest.base_incorporated_through_seq,
        },
        "live_basis_lineage": {
            "account_scope_id": view.account_scope_id,
            "epoch_number": view.epoch_number,
            "epoch_id": view.epoch_id,
            "adopted_sequence": view.adopted_sequence,
        },
    }


# @beacon[
#   id=auto-beacon@_carto_select_snapshot-6qt2,
#   role=_carto_select_snapshot,
#   slice_labels=mci-epoch-seams,
#   kind=ast,
#   comment=Preserves the existing skip or preflight refresh policy then captures and borrows the daemon live basis; manifest path and lineage are diagnostics and no job snapshot is written or loaded.,
# ]
async def _carto_select_snapshot(
    *,
    reason: str,
    source: str,
    disposition_when_performed: str = "performed",
) -> dict[str, Any]:
    """Force/skip only freshness, then select the daemon's manifest-linked live view.

    S02 (§13.1): selection is manifest-based.  The skip toggle may suppress
    the optional CARTO preflight freshness ONLY when a usable manifest base
    already exists; a skipped preflight still selects manifest lineage,
    never newest-by-timestamp.
    """
    client = get_client()
    skipped = False
    if _cache_refresh_should_skip():
        skipped = _manifest_base_usable(client)
    if not skipped:
        result = await _request_nodes_export_cache_refresh_async(
            reason=reason, source=source, refresh_kind="carto_preflight"
        )
        if not isinstance(result, dict) or not result.get("success"):
            raise RuntimeError(f"/nodes-export freshness request failed: {result!r}")
        await _await_nodes_export_cache_quiescent(reason)
    return await _carto_select_live_basis(
        client,
        freshness_disposition="skipped" if skipped else disposition_when_performed,
    )


def _carto_account_scope() -> str:
    """Borrow the existing daemon governor's identity, never build worker env."""
    return get_client()._write_governor.paths.account_scope_id


# @beacon[
#   id=carto-governance@footprint-from-selection,
#   slice_labels=carto-governance,ra-carto-jobs,ra-reconcile,ra-coherence,
#   kind=ast,
#   comment=Admission footprint derivation borrows immutable keyed maps without whole-cache copies; an explicit revalidation proof wins then the operation pin then the freshness selection fallback. Execution selection is separate from this admission topology and the job takes its own post-B0 boundary.,
# ]
def _carto_footprint_from_selection(
    *,
    root_uuid: str,
    mode: str,
    selection: Mapping[str, Any],
    source_regime: str,
    cache_by_id_override: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    # S03-CR-04: derive the admission footprint from the operation's pinned
    # view when a boundary is active.  The launch fronts (beacon.map.refresh
    # via the dispatch boundary; the browser F12 handlers via
    # @_ws_cache_boundary) resolve and classify the target against that
    # pinned generation BEFORE freshness selection may publish a newer one,
    # so admission must evaluate the same generation end-to-end.  The
    # selection's cache_by_id is the correct source only when no operation
    # boundary is active (launcher-internal/defensive paths).  S05 (A1c): an
    # explicit cache_by_id_override wins over both — the head-stale
    # revalidation hook re-derives the footprint from the freshly ADOPTED
    # view, which is newer than the pinned task snapshot by construction.
    from .coherence.operation_cache import current_operation_cache

    if cache_by_id_override is not None:
        cache_by_id = cache_by_id_override
    else:
        pinned = current_operation_cache(required=False)
        if pinned is not None and pinned.nodes_by_id:
            cache_by_id = pinned.nodes_by_id
        else:
            cache_by_id = selection.get("cache_by_id") or {}
    if source_regime == "temp_override":
        return compute_footprint(None, root_uuid, cache_by_id, kind=mode)
    from .client.api_client_nexus import resolve_cartographer_path_from_node

    resolved = resolve_cartographer_path_from_node(node_id=str(root_uuid), nodes_by_id=cache_by_id)
    path = str(resolved.get("abs_path") or "")
    if not path:
        raise RuntimeError(f"Could not resolve canonical CARTO path for {root_uuid}.")
    return compute_footprint(path, root_uuid, cache_by_id, kind=mode)


def _carto_admission_coherence_kwargs(
    *,
    root_uuid: str,
    mode: str,
    source_regime: str,
    selection: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Head-currency + held-node-lock view kwargs for CARTO
    admission call sites, derived from the operation's pinned snapshot.

    Retry advice is always the existing configured long-lived value, including
    defensive callers without an operation boundary (whose held keys still
    refuse without a proof view). The
    ``adopt_fn`` hook captures the publisher-current welded view and re-derives
    the footprint from that current local view so the admission retry never
    proceeds on stale topology.
    """

    from .coherence.operation_cache import current_operation_cache
    from .mutation_locks import _long_lived_retry_after_seconds

    advice = _long_lived_retry_after_seconds()
    pinned = current_operation_cache(required=False)
    if pinned is None or not pinned.nodes_by_id:
        return {"mutation_lease_retry_after_seconds": advice}
    basis_sequence = pinned.view.adopted_sequence
    basis_epoch_id = pinned.view.epoch_id
    view = pinned.nodes_by_id

    async def adopt_fn() -> dict[str, Any]:
        # S05 (A1c): recapture the current local view and hand its fresh markers
        # to the admission wrapper, which re-derives the candidate footprint
        # itself from the stored canonical path/root/kind (compute_footprint
        # remains the ONE derivation authority; the disk path does not move).
        client = get_client()
        fresh_view, _dirty = client._capture_view_and_dirty()
        return {
            "view": fresh_view.nodes_by_id,
            "basis_sequence": fresh_view.adopted_sequence,
            "basis_epoch_id": fresh_view.epoch_id,
        }

    return {
        "mutation_lease_retry_after_seconds": advice,
        "footprint_basis_sequence": basis_sequence,
        "footprint_basis_epoch_id": basis_epoch_id,
        "live_mutation_lease_view": view,
        "adopt_fn": adopt_fn,
    }


# @beacon[
#   id=carto-runtime@job-regions,
#   slice_labels=ra-carto-jobs,mci-lock-plane,
#   kind=ast,
#   comment=Derives the complete job footprint from the supplied proof using keyed typed builders and the shared effective-FILE selector; bulk freezes membership only and re-proves every actual FILE plus uncovered exact cache-patch target without trusting GUI containment or consulting ownership.,
# ]
def _carto_job_regions(spec: CartoJobSpec, snapshot) -> tuple[MutationRegion, ...]:
    """Pure proof-time geometry; no cache scan, I/O or ownership observation.

    Empty bulk membership has no graph effects and returns no additions. The
    runner must skip the nonempty N05 door in that case, not invent an account
    root. All other families hold one actual subtree through finalization.
    """
    from .client.api_client_nexus import _resolve_carto_refresh_root
    from .mutation_lease_governance import normalize_mutation_regions

    nodes = snapshot.nodes_by_id

    def effective(root):
        return _resolve_carto_refresh_root(
            nodes, str(root), source_regime=spec.source_regime,
            source_path_override=spec.source_path_override,
        )

    if spec.job_type != "CARTO_BULK_APPLY":
        root = spec.root_uuid if spec.mode == "folder" else effective(spec.root_uuid)
        return (build_region_subtree(root, cache_by_id=nodes),)

    subtrees: dict[str, MutationRegion] = {}
    candidates: dict[str, MutationRegion] = {}
    for file_id, group in spec.bulk_groups.items():
        root = effective(file_id)
        region = build_region_subtree(root, cache_by_id=nodes)
        subtrees[region.key] = region
        for candidate in group.get("nodes") or ():
            node_id = str(candidate["id"])
            exact = build_region_exact_node(node_id, cache_by_id=nodes)
            candidates[exact.key] = exact
            root = effective(node_id)
            record = nodes.get(root) or {}
            note = record.get("note") or record.get("no") or ""
            if isinstance(note, str) and "Path:" in note:
                region = build_region_subtree(root, cache_by_id=nodes)
                subtrees[region.key] = region

    # Chains were derived by the typed builders from THIS proof. They are not
    # retained across acquisitions or copied from GUI/job diagnostic metadata.
    additions = [*subtrees.values(), *(
        exact for exact in candidates.values()
        if not any(root in exact.ancestor_chain for root in subtrees)
    )]
    return normalize_mutation_regions(additions) if additions else ()


# @beacon[
#   id=carto-runtime@schedule-job,
#   slice_labels=ra-carto-jobs,nexus--daemon,
#   kind=ast,
#   comment=Uses the existing isolated daemon task and one exit door: the admitted file reservation becomes the same whole-job graph grant; data offloads never receive registry authority; terminal proof and memory cooldown precede release. Scheduling failure uses the same effect-free exit with the derived same-stem job directory; no worker or cleanup supervisor.,
# ]
async def _schedule_carto_job(spec: CartoJobSpec) -> dict[str, Any]:
    """Register the actual lifetime before ack; execution cannot run mid-setup."""
    from .coherence.operation_cache import create_isolated_context_task

    _register_carto_final_obligation(spec)
    control = CartoJobControl(presentation=MappingProxyType({
        "id": spec.job_id, "type": spec.job_type, "mode": spec.mode, "root_uuid": spec.root_uuid,
        "claim_id": spec.claim_id, "account_scope_id": spec.account_scope_id,
        "path": str(spec.job_file), "logs_path": str(spec.log_file) if spec.log_file else None,
        "execution_model": "daemon_task", "execution_owner": "launcher", "pid": os.getpid(),
        "detached": False,
    }))
    job_dir = spec.job_file.with_suffix("")
    coroutine = _run_carto_job(spec, control)
    controller = daemon_lifecycle.active_lifecycle()
    try:
        task = (controller.spawn_admitted_child(f"carto:{spec.job_id}", coroutine)
                if controller is not None else create_isolated_context_task(coroutine))
    except BaseException as exc:
        coroutine.close()
        # This is still the admitted launch caller's accounted lifetime; there
        # is no task/grant and no body has run. Keep cleanup on this same path;
        # no body/artifact ran, so the derived job directory need not exist.
        control.task = asyncio.current_task()
        with carto_job_scope(CartoJobContext(
            spec.job_file, job_dir, spec.log_file, control,
        )):
            await _finalize_carto_task(spec, control, {"exception": exc, "scheduling_failed": True})
        terminal = control.terminal_result or {}
        return _carto_scheduling_failure_result(spec, terminal, exc)

    control.task = task
    _carto_inprocess_tasks[spec.job_id] = task
    _carto_job_controls[spec.job_id] = control
    _inprocess_restart_stops[task] = control.restart_state
    def finished(done):
        # Retrieve even an unexpected runner exception; never an unhandled loop
        # error. Identity checks cannot unregister a later task with this id.
        if not done.cancelled():
            done.exception()
        if _carto_inprocess_tasks.get(spec.job_id) is done:
            _carto_inprocess_tasks.pop(spec.job_id)
            _carto_active_cache_jobs.discard(spec.job_id)
            _sync_carto_quiescent_view()
        if _carto_job_controls.get(spec.job_id) is control:
            _carto_job_controls.pop(spec.job_id)
        if _inprocess_restart_stops.get(done) is control.restart_state:
            _inprocess_restart_stops.pop(done)
    task.add_done_callback(finished)
    if controller is not None:
        try:
            controller.register_job_boundary_stop(
                spec.job_id,
                lambda restart_id: _request_inprocess_restart_stop(restart_id, task=task), task,
            )
        except BaseException as exc:
            # No await has run since task creation. The child observes this
            # setup failure before freshness/adoption/effects, exits through
            # its own adapter and remains joined/accounted without Task.cancel.
            control.scheduling_failure = exc
            await task
            terminal = control.terminal_result or {}
            return _carto_scheduling_failure_result(spec, terminal, exc)
    return {"success": True, "job_id": spec.job_id, "pid": os.getpid(), "detached": False}


def _carto_scheduling_failure_result(spec, terminal, exception) -> dict[str, Any]:
    """Preserve the established effect-free scheduling-failure result shape."""
    return {"success": False, "job_id": spec.job_id,
            "error_kind": terminal.get("error_kind", "scheduling_failed"),
            "error": terminal.get("error", str(exception))}


# @beacon[
#   id=carto-runtime@run-job,
#   slice_labels=ra-carto-jobs,mci-lock-plane,ra-workflowy-cache,
#   kind=ast,
#   comment=Binds and forwards the same whole-job graph grant in the existing daemon task and exit door; terminal proof and memory cooldown precede release. Data offloads never receive ownership authority and no new hold or cleanup supervisor is introduced.,
# ]
async def _run_carto_job(spec: CartoJobSpec, control: CartoJobControl) -> None:
    """Ownership core shared by every job family, never the launcher's pin."""
    from contextlib import nullcontext
    from .coherence.admission import require_coherence_mutation_admission
    from .coherence.operation_cache import cache_operation_boundary, current_operation_cache
    from .models.errors import OperationCancelledError

    job_dir = spec.job_file.with_suffix("")
    context = CartoJobContext(spec.job_file, job_dir, spec.log_file, control, claim_id=spec.claim_id)
    control.progress = context.progress
    outcome: dict[str, Any] = {}
    finalized = False
    operation_id = None
    async with daemon_lifecycle.operation_accounting(f"carto:{spec.job_id}"):
        with carto_job_scope(context), operation_cancel_scope(control.user_cancel_requested):
            if control.scheduling_failure is not None:
                await _finalize_carto_task(spec, control, {
                    "exception": control.scheduling_failure, "scheduling_failed": True,
                })
                return
            try:
                # Exact admitted reservation validation is synchronous loop
                # work; the joined offloads below carry only job-status data.
                _require_carto_hold(str(spec.job_file), spec.claim_id)
                await run_carto_cpu("job-directory", _ensure_carto_job_directory, job_dir)
                await run_carto_cpu("task-running", _write_carto_task_running, str(spec.job_file))
                control.checkpoint("before-freshness", restart_boundary=True)
                control.presentation_status = "waiting"
                selection = spec.selection_metadata
                if spec.freshness_callback is not None:
                    control.phase = "freshness"
                    selection = await spec.freshness_callback()
                    await run_carto_cpu("freshness-diagnostics", _merge_carto_task_status, str(spec.job_file), {
                        "snapshot_path": selection.get("snapshot_path"),
                        "snapshot_lineage": selection.get("snapshot_lineage"),
                        "live_basis_lineage": selection.get("live_basis_lineage"),
                        "freshness_disposition": selection.get("freshness_disposition"),
                    })
                control.checkpoint("after-freshness", restart_boundary=True)
                async with cache_operation_boundary(get_client(), f"carto:{spec.job_id}"):
                    operation_id = current_operation_cache().operation_id
                    _carto_operation_jobs[operation_id] = spec.job_id
                    operation = (f"carto.prepare:{spec.mode}" if spec.preparation is not None else
                                 f"carto.refresh:{spec.mode}" if spec.job_type == "CARTO_REFRESH" else
                                 "carto.markdown_generate" if spec.job_type == "CARTO_MARKDOWN_GENERATE" else
                                 f"carto-bulk-apply:{spec.job_id}")
                    control.phase = "admission"
                    await require_coherence_mutation_admission(_admission_coherence_paths, operation=operation)
                    # Frozen empty bulk membership proves there is no graph
                    # work; do not feed an empty set to N05's nonempty grammar.
                    empty_bulk = spec.job_type == "CARTO_BULK_APPLY" and not spec.bulk_groups
                    grant_scope = nullcontext() if empty_bulk else mutation_region_locks(
                        client=get_client(), operation_label=f"carto:{spec.job_id}",
                        region_factory=lambda proof: _carto_job_regions(spec, proof),
                        hold_mode="long_lived", expected_duration_seconds=None,
                    )
                    async with grant_scope as held_grant:
                        control.presentation_status = "preparing" if spec.preparation is not None else "running"
                        try:
                            await require_coherence_mutation_admission(_admission_coherence_paths, operation=operation)
                            control.checkpoint("preparation", restart_boundary=True)
                            if spec.preparation is not None:
                                import inspect
                                from .carto_job_runtime import _thaw_job_data
                                prepared = await run_carto_cpu("preparation-payload", _thaw_job_data, spec.preparation_payload)
                                prepared.update(_job_file=str(spec.job_file), _claim_id=spec.claim_id)
                                value = spec.preparation(prepared, selection)
                                if inspect.isawaitable(value):
                                    value = await value
                                control.checkpoint("after-preparation", restart_boundary=True)
                                gate = spec.preparation_gate(value) if spec.preparation_gate else {"proceed": True}
                                if not gate.get("proceed"):
                                    outcome.update(gate)
                                    outcome.setdefault("status", "failed")
                                else:
                                    outcome["result"] = await _execute_carto_job(spec, control, held_grant=held_grant)
                            else:
                                outcome["result"] = await _execute_carto_job(spec, control, held_grant=held_grant)
                            # Folder/bulk stop only at another group head; a
                            # completed last group wins normally (N06). FILE
                            # joins its complete reconcile before observing.
                            control.checkpoint("body-complete", restart_boundary=(spec.job_type == "CARTO_REFRESH" and spec.mode == "file"))
                        except BaseException as exc:
                            if control.user_requested and isinstance(exc, (asyncio.CancelledError, OperationCancelledError)):
                                control.user_observed = True  # helper returned at a safe stop boundary
                            outcome["exception"] = exc
                        finally:
                            finalized = True
                            await _finalize_carto_task(spec, control, outcome)
            except BaseException as exc:
                if control.user_requested and isinstance(exc, (asyncio.CancelledError, OperationCancelledError)):
                    control.user_observed = True
                outcome["exception"] = exc
            finally:
                # Freshness/adoption/acquisition can fail before any grant.
                # They still use the same finalizer exactly once, no effects.
                if not finalized:
                    await _finalize_carto_task(spec, control, outcome)
                if operation_id is not None and _carto_operation_jobs.get(operation_id) == spec.job_id:
                    _carto_operation_jobs.pop(operation_id)


async def _execute_carto_job(spec: CartoJobSpec, control: CartoJobControl, *, held_grant=None) -> Any:
    """Forward the exact caller-held grant across every existing job path."""
    client = get_client()
    control.presentation_status = "running"
    if spec.job_type == "CARTO_REFRESH":
        control.phase = f"{spec.mode}-refresh"
        control.may_have_workflowy_effects = True
        if spec.mode == "folder":
            return await client.refresh_folder_cartographer_sync(
                folder_node_id=spec.root_uuid, cancel_callback=control.user_cancel_requested,
                carto_claim_id=spec.claim_id, force=spec.force,
                held_grant=held_grant,
            )
        result = await client.refresh_file_node_beacons(
            file_node_id=spec.root_uuid, dry_run=False,
            cancel_callback=control.user_cancel_requested, source_path_override=spec.source_path_override,
            carto_claim_id=spec.claim_id, force=spec.force,
            held_grant=held_grant,
        )
        if spec.delete_temp_file_after and spec.source_path_override and isinstance(result, Mapping) and result.get("success"):
            await run_carto_cpu("temporary-source-cleanup", _delete_carto_temp_source, spec.source_path_override)
        return result
    if spec.job_type == "CARTO_MARKDOWN_GENERATE":
        from .markdown_generate_pipeline import run_markdown_generate_pipeline
        control.phase = "markdown-generate"
        return await run_markdown_generate_pipeline(client=client, root_uuid=spec.root_uuid, job_file=str(spec.job_file), held_grant=held_grant)
    if spec.job_type == "CARTO_BULK_APPLY":
        from .carto_job_runtime import _thaw_job_data
        control.phase = "bulk-apply"
        if not spec.bulk_groups:
            return {"success": True, "message": "No eligible visible AST/beacon nodes found."}
        root = await run_carto_cpu("bulk-working-tree", _thaw_job_data, spec.visible_tree_payload)
        groups = await run_carto_cpu("bulk-working-groups", _thaw_job_data, spec.bulk_groups)
        await _run_carto_bulk_visible_apply_job(
            str(spec.job_file), root, spec.mode, prepared_groups=groups,
            grouping_warnings=spec.preparation_payload.get("grouping_warnings") or (),
            skipped_unchanged=spec.preparation_payload.get("skipped_unchanged") or 0,
            held_grant=held_grant,
        )
        return await run_carto_cpu("bulk-result", _read_carto_job_payload, str(spec.job_file))
    raise ValueError(f"Unsupported Cartographer task type {spec.job_type!r}")


def _delete_carto_temp_source(path: str) -> None:
    """Joined cleanup of the successful job's explicit temporary source only."""
    Path(path).unlink(missing_ok=True)


def _ensure_carto_job_directory(path: Path) -> None:
    """Create the per-job artifact directory before any job-local artifact."""
    Path(path).mkdir(parents=True, exist_ok=True)


def _write_carto_task_running(job_file: str) -> None:
    """Data-only running/execution diagnostics merge; no claim read or write.

    The runner has already validated the admitted reservation synchronously on
    the loop. This joined job-status write adopts no claim and changes no owner
    identity; no task/control, cache, HTTP or registry crosses here.
    """
    _merge_carto_task_status(job_file, {
        "status": "running", "execution_owner": "launcher",
        "execution_model": "daemon_task", "detached": False,
    })


def _merge_carto_task_status(job_file: str, updates: Mapping[str, Any]) -> None:
    """Ordered job-local disk merge using the unchanged status precedence writer."""
    current = _read_carto_job_payload(job_file) or {}
    current.update(updates)
    current["updated_at"] = datetime.utcnow().isoformat()
    if not merge_write_carto_job_status(job_file, current):
        raise OSError("Could not persist Cartographer task status")


# @beacon[
#   id=carto-runtime@task-terminal-payload,
#   slice_labels=ra-carto-jobs,ra-logging,
#   kind=ast,
#   comment=Appends the returned single-FILE row once and releases it at the exit; registered bulk jobs take their writer summary instead of the dispatcher's small record return. Accumulator attribution and no-writer saved recovery keep complete evidence outside the bounded terminal proof.,
# ]
async def _carto_task_terminal_payload(spec: CartoJobSpec, control: CartoJobControl, outcome: Mapping[str, Any]) -> dict[str, Any]:
    """Retain saved work and exact local CPU attribution at one exit.

    A caught mapper exception, including a coded file error, is local only when
    file/phase/type/message provenance survives in that file's failed row.
    Registered bulk job JSON is replaced by its writer summary here. Inline
    phase8 failures may carry it in phase8.files for a primary canonical file;
    that failed refresh never changes a committed publication into a failed row.
    Switched jobs recover only their registered writer's summary and attribute
    CPU failures through its contribution summaries, never a rows list. Only a
    job without a writer reads its saved record; a read error is failure data.
    A single-FILE return is appended here, before normalization, so internal
    FILE callers still receive their complete working result. The runner's
    owned outcome relinquishes that row after its append, not into the proof.
    Unattributed and named run-wide failures stay fatal; no exception/control
    crosses into the data worker.
    """
    original_phase = control.phase
    from .carto_job_record import record_for
    writer = record_for(spec.job_file, create=False)
    result = outcome.get("result")
    if (writer is not None and writer._is_file and isinstance(result, Mapping)
            and "file" in result and not result.get("_carto_writer_summary")):
        from .client.api_client_nexus import _write_carto_file_artifact
        row = outcome.pop("result") if isinstance(outcome, dict) else result
        result = None
        try:
            result = await run_carto_cpu("terminal-file-row", _write_carto_file_artifact, "file-row", {
                "path": str(spec.job_file), "row": row,
            })
        finally:
            row = None
    if (writer is not None and spec.job_type == "CARTO_BULK_APPLY" and isinstance(result, Mapping)
            and "result_summary" in result):
        # Keep the returned record's terminal error text/typing beside the
        # marked summary. The unchanged no-target fast path stays unstructured.
        result = {**{key: result[key] for key in ("error", "error_kind", "error_extra") if key in result},
                  "result_summary": writer.summary()}
    saved_read_error = None
    if not isinstance(result, Mapping):
        if writer is not None:
            result = writer.summary()
        else:
            try:
                saved = await run_carto_cpu("terminal-saved-result", _read_carto_job_payload, str(spec.job_file), strict=True)
                result = saved.get("result_summary") if isinstance(saved, Mapping) else None
            except Exception as read_error:
                saved_read_error = read_error
    exception = outcome.get("exception") or saved_read_error
    if control.cpu_failure is not None:
        phase, cpu_exception = control.cpu_failure
        from .carto_job_governance import GovernanceError
        identity = {"phase": phase, "exception_type": type(cpu_exception).__name__, "message": str(cpu_exception)}
        summary = (result.get("result_summary") or result) if isinstance(result, Mapping) else {}
        if writer is not None:
            attributed = writer.accumulator.local_cpu_failure(identity)
        else:
            primary_rows = summary.get("files") or []
            primary_files = {row["file"] for row in primary_rows if row.get("file")}
            phase8_rows = [row for row in (summary.get("phase8") or {}).get("files") or []
                           if row.get("file") in primary_files]
            attributed = any(row.get("status") == "failed" and row.get("error")
                and row.get("local_cpu_failure") == {**identity, "file": row.get("file")}
                for row in [*primary_rows, *phase8_rows])
        local = (isinstance(cpu_exception, Exception) and not isinstance(cpu_exception, (
                     GovernanceError, MutationRegionError, MutationSerializationConflictError, MutationSerializationTimeoutError))
                 and not hasattr(cpu_exception, "refusal_extra") and getattr(cpu_exception, "code", None) not in {
                     "ACCOUNT_WRITE_BLOCKED", "WRITE_GOVERNOR_UNAVAILABLE", "WRITE_GOVERNOR_DEFERRED",
                     "WRITE_SLOT_BUSY_TIMEOUT", "AUTH_ERROR", "RATE_LIMIT_ERROR"}
                 and phase in {"file:source", "file:plan", "folder:new-source", "folder:new-retention"}
                 and isinstance(result, Mapping) and attributed)
        if not local:
            exception = exception or cpu_exception
    else:
        phase = original_phase
    exception_data = None
    if exception is not None:
        kind = "scheduling_failed" if outcome.get("scheduling_failed") else "carto_job_exception"
        typed_extra = {}
        coherence_prefix = hasattr(exception, "refusal_extra")
        if coherence_prefix:
            kind, typed_extra = getattr(exception, "code", "coherence_barrier_active"), exception.refusal_extra()
        elif isinstance(exception, (MutationRegionError, MutationSerializationConflictError, MutationSerializationTimeoutError)):
            kind, typed_extra = exception.code, _mutation_refusal_extra(exception)
        elif isinstance(exception, AdmissionRefusal):
            kind, typed_extra = exception.kind, exception.details
        elif getattr(exception, "code", None) in {"ACCOUNT_WRITE_BLOCKED", "WRITE_GOVERNOR_DEFERRED"}:
            kind, typed_extra = exception.code, dict(exception.details)
        exception_data = {"type": type(exception).__name__, "text": str(exception), "kind": kind,
                          "extra": typed_extra, "coherence_prefix": coherence_prefix}
    metadata = {"job_id": spec.job_id, "job_type": spec.job_type, "mode": spec.mode,
                "root_uuid": spec.root_uuid, "claim_id": spec.claim_id, "pid": os.getpid(), "phase": phase,
                "may_have_workflowy_effects": control.may_have_workflowy_effects,
                "stopped": control.user_observed or control.restart_state["observed"],
                "restart_observed": control.restart_state["observed"], "exception": exception_data,
                "scheduling_failed": bool(outcome.get("scheduling_failed")), "updated_at": datetime.utcnow().isoformat()}
    if writer is not None:
        metadata["writer_job_file"] = str(spec.job_file)
    outcome_data = {key: outcome.get(key) for key in ("status", "error", "result_summary")}
    return await run_carto_cpu("terminal-normalize", _carto_terminal_payload_data, metadata, result, outcome_data)


# @beacon[
#   id=carto-runtime@terminal-payload-data,
#   slice_labels=ra-carto-jobs,ra-logging,ra-workflowy-cache,
#   kind=ast,
#   comment=Recognizes writer summaries and projects stops or exceptions through the same writer, never a batch aggregate. Q6 stores preview-derived terminal errors beside a bounded formatter/source recipe for exact detail reconstruction; legacy writers typed failures and observed-stop precedence stay unchanged.,
# ]
def _carto_terminal_payload_data(metadata, result, outcome):
    """Project marked writer summaries, retaining the no-writer legacy branch.

    The path in metadata is plain data: no live task, registry or callback is
    passed across the CPU seam. Complete evidence remains in the job artifact.
    Q6 keeps returned-failure text built from run-list previews readable and
    bounded, with its exact formatter/source/prefix/suffix derivation. Only
    requested detail applies that recipe to the complete folded error items.
    """
    from .carto_job_record import _WRITER_SUMMARY_MARKER, _TERMINAL_TEXT_FORMATTER, record_for
    exception = metadata["exception"]
    stopped = metadata["stopped"]
    result = dict(result) if isinstance(result, Mapping) else {}
    errors = result.get("refresh_errors") or result.get("errors") or (result.get("result_summary") or {}).get("errors")
    summary = dict(outcome.get("result_summary") or result.get("result_summary") or result)
    writer_summary = summary.get(_WRITER_SUMMARY_MARKER) is True
    structured = writer_summary or ("writer_job_file" not in metadata and isinstance(summary.get("files"), list) and "successful" in summary)
    if writer_summary and (exception is not None or stopped):
        writer = record_for(metadata["writer_job_file"], create=False)
        summary = writer.summary(infrastructure_error=exception, cancelled=stopped)
    elif structured and (exception is not None or stopped):
        from .beacon_refresh_support import beacon_job_outcome
        summary = beacon_job_outcome(summary, infrastructure_error=exception, cancelled=stopped)
    returned_failure = exception is None and ((summary.get("success") is False or summary.get("status") == "failed")
                                              if structured else (result.get("success") is False or result.get("status") == "failed" or errors))
    if returned_failure:
        exception = {"type": "RuntimeError", "text": str(result.get("error") or errors or "Cartographer work returned failure"),
                     "kind": "scheduling_failed" if metadata["scheduling_failed"] else "carto_job_exception",
                     "extra": {}, "coherence_prefix": False}
        if result.get("error_kind"):
            exception.update(kind=result["error_kind"], extra=result.get("error_extra") or result.get("coherence_admission") or {})
    warnings = summary.get("warnings") or result.get("warnings") or []
    status = ("cancelled" if stopped else "failed" if exception is not None else
              str((summary.get("status") if structured else outcome.get("status")) or ("completed_with_warnings" if warnings or result.get("completed_with_warnings") else "completed")))
    extra = {"job_id": metadata["job_id"], "phase": metadata["phase"],
             "may_have_workflowy_effects": metadata["may_have_workflowy_effects"]}
    payload = {"id": metadata["job_id"], "type": metadata["job_type"], "mode": metadata["mode"],
               "root_uuid": metadata["root_uuid"], "claim_id": metadata["claim_id"],
               "execution_model": "daemon_task", "execution_owner": "launcher",
               "detached": False, "pid": metadata["pid"], "status": status,
               "updated_at": metadata["updated_at"],
               "cache_refresh_required": metadata["may_have_workflowy_effects"],
               "result_summary": summary, "warnings": warnings,
               "warning_count": summary.get("warnings_total", len(warnings)),
               "error": outcome.get("error")}
    if exception is not None and not stopped:
        extra["exception_type"] = exception["type"]
        kind = exception["kind"]
        extra = {**exception["extra"], **extra}
        payload.update(error_kind=kind, error_extra=extra, error=(
            f"Cartographer job {metadata['job_id']} failed during {metadata['phase']}: {exception['type']}: {exception['text']}. "
            "The daemon is still serving; inspect the job result before retrying."
        ) if kind in {"carto_job_exception", "scheduling_failed"} else
            f"coherence_barrier_active: {exception['text']}" if exception["coherence_prefix"] else exception["text"])
        if writer_summary and returned_failure and not result.get("error") and isinstance(errors, list) and errors:
            # These are the writer's authorized <=20-entry previews, never the
            # complete run list. The recipe has no term in the number of files.
            prefix, suffix = "", ""
            if kind in {"carto_job_exception", "scheduling_failed"}:
                prefix = f"Cartographer job {metadata['job_id']} failed during {metadata['phase']}: {exception['type']}: "
                suffix = ". The daemon is still serving; inspect the job result before retrying."
            elif exception["coherence_prefix"]:
                prefix = "coherence_barrier_active: "
            source = "refresh_errors" if result.get("refresh_errors") else "errors"
            payload["error_derivation"] = {"$carto_terminal_text": {
                "formatter": _TERMINAL_TEXT_FORMATTER, "source": source, "prefix": prefix, "suffix": suffix}}
    if metadata["restart_observed"]:
        payload["result_summary"]["message"] = (
            "Stopped at a safe job boundary for daemon restart; completed work is retained. Re-run the job if needed."
        )
    return payload


# @beacon[
#   id=carto-runtime@finalize-task,
#   slice_labels=ra-carto-jobs,mci-lock-plane,ra-workflowy-cache,
#   kind=ast,
#   comment=One exit door: registered writers finalize to summary-only proof and are released after the joined terminal attempt; no-writer jobs retain the old merge. Status and memory claim-finalizer failures are guarded so immutable proof and delivery are still attempted before the outer grant releases.,
# ]
async def _finalize_carto_task(spec: CartoJobSpec, control: CartoJobControl, outcome: Mapping[str, Any]) -> None:
    """The one exit adapter; guard persistence and claim finalization independently.

    Registered jobs never re-read saved evidence here, and their terminal result
    and frozen proof contain only the writer's bounded summary (B1 excepted).
    """
    from .carto_job_record import record_for, release_carto_job_record
    writer = record_for(spec.job_file, create=False)
    control.finalizing = True
    stopped = control.user_observed or control.restart_state["observed"]
    try:
        payload = await _carto_task_terminal_payload(spec, control, outcome)
    except BaseException as normalization_error:
        # Malformed work results are job failures too; normalization cannot
        # bypass token-safe cleanup or make the runner call it a second time.
        payload = {"id": spec.job_id, "type": spec.job_type, "root_uuid": spec.root_uuid,
                   "claim_id": spec.claim_id, "status": "failed", "execution_model": "daemon_task",
                   "error_kind": "carto_job_exception", "detached": False, "pid": os.getpid(),
                   "cache_refresh_required": control.may_have_workflowy_effects,
                   "error": f"Cartographer job {spec.job_id} failed during {control.phase}: {type(normalization_error).__name__}: {normalization_error}. The daemon is still serving; inspect the job result before retrying.",
                   "error_extra": {"job_id": spec.job_id, "phase": control.phase,
                                   "exception_type": type(normalization_error).__name__,
                                   "may_have_workflowy_effects": control.may_have_workflowy_effects}}
    extra = payload.get("error_extra") or {"job_id": spec.job_id, "phase": control.phase,
                                           "may_have_workflowy_effects": control.may_have_workflowy_effects}
    try:
        if writer is not None:
            payload = await run_carto_cpu("final-status-write", writer.finalize, payload)
            if payload.get("status_write_error"):
                raise OSError(payload["status_write_error"])
        else:
            previous = await run_carto_cpu("final-status-read", _read_carto_job_payload, str(spec.job_file)) or {}
            summary = dict(previous.get("result_summary") or {})
            summary.update(payload.get("result_summary") or {})
            payload["result_summary"] = summary
            previous.update(payload)
            if not await run_carto_cpu("final-status-write", merge_write_carto_job_status, spec.job_file, previous):
                raise OSError("Could not persist Cartographer terminal status")
            payload = previous
    except BaseException as status_error:
        payload.update(status="failed", status_write_error=str(status_error))
        payload.setdefault("error_kind", "carto_job_exception")
        payload.setdefault("error_extra", extra)
        payload["error"] = payload.get("error") or str(status_error)
    finally:
        if writer is not None:
            release_carto_job_record(spec.job_file)
    try:
        if stopped:
            await finalize_cancelled_job_claim_async(
                spec.job_file, spec.claim_id, jobs_root=spec.job_file.parent,
                diagnostic=lambda message: log_event(message, "CARTO"),
                **({"restart_boundary_stop": True} if control.restart_state["observed"] else {}),
            )
        else:
            await finalize_claim_async(spec.claim_id, spec.job_file.parent)
    except BaseException as claim_error:
        payload["claim_finalization_error"] = str(claim_error)
        log_event(f"Cartographer job {spec.job_id} claim finalization failed: {type(claim_error).__name__}: {claim_error}", "CARTO")
    control.terminal_result = payload
    from .carto_job_runtime import _freeze_job_data
    try:
        frozen = await run_carto_cpu("terminal-projection", _freeze_job_data, {**control.presentation, **payload})
    except BaseException as projection_error:
        # Even malformed diagnostic data cannot strand an observing lifetime or
        # undo the finalizer already attempted. This fixed-size fallback is data.
        frozen = MappingProxyType({**control.presentation, "status": "failed",
            "error_kind": payload.get("error_kind") or "carto_job_exception",
            "error": str(payload.get("error") or projection_error),
            "terminal_projection_error": str(projection_error),
            "cache_refresh_required": control.may_have_workflowy_effects})
    _record_carto_task_terminal(spec, control, frozen)
    _ensure_carto_final_delivery()


# @beacon[
#   id=carto-governance@coherence-launch-gate,
#   slice_labels=carto-governance,ra-carto-jobs,ra-coherence,
#   kind=ast,
#   comment=All three daemon-task launch seams retain the S04 hard barrier before artifacts admission or freshness; their common runner rechecks before effects and inline phase8 rechecks inside the parent lifetime. Every ingress retains the existing typed refusal shape and no phase8 child admission is introduced.,
# ]
def _carto_coherence_launch_refusal(exc: Any) -> dict:
    """The established CARTO launch-refusal shape for a hard-barrier stop."""

    return {
        "success": False,
        "error_kind": "coherence_barrier_active",
        "error": str(exc),
        "coherence_admission": exc.refusal_extra(),
    }


def _admission_coherence_paths():
    """Lazy CoherencePaths resolution for the S04 admission gates.

    Passed BY REFERENCE to the shared gates, which invoke it only when they
    actually run — never merely because a call site was reached (a stubbed
    gate in a test harness then never touches client configuration).
    """

    _client = get_client()
    return _client._coherence_paths()


async def _require_carto_launch_admission(operation: str) -> dict | None:
    """S04 §7.2: hard-stop admission for CARTO launches (may mutate Workflowy).

    Returns None to proceed, or the established refusal dict
    (``error_kind`` idiom).  Runs before job creation, admission, governor
    acquisition, freshness, or any Workflowy send.
    """

    from .coherence.admission import require_coherence_mutation_admission
    from .coherence.errors import CoherenceBarrierActiveError

    try:
        await require_coherence_mutation_admission(
            _admission_coherence_paths, operation=operation
        )
    except CoherenceBarrierActiveError as exc:
        return _carto_coherence_launch_refusal(exc)
    return None


# @beacon[
#   id=carto-governance@server-refresh-wrapper,
#   slice_labels=carto-governance,ra-carto-jobs,ra-reconcile,ra-workflowy-cache,
#   kind=ast,
#   comment=Delegates every refresh form to the shared admission freshness and ack authority with the mandatory daemon scheduler; prepared B0 and preparation execute in the actual job task under its complete long grant and one post-B0 boundary; no worker env snapshot bootstrap or preparation-only task lifetime.,
# ]
async def _start_carto_refresh_job(
    root_uuid: str,
    mode: str,
    extra_job_fields: dict | None = None,
    *,
    launcher: str = "system",
    parent_job_id: str | None = None,
    preparation: Callable[[Mapping[str, Any], Mapping[str, Any]], Any] | None = None,
    preparation_gate: Callable[[Any], Mapping[str, Any]] | None = None,
    frozen_payload: Mapping[str, Any] | None = None,
    preparation_input_digest: str | None = None,
    initial_footprint: Mapping[str, Any] | None = None,
    source_regime: str | None = None,
    inherited_snapshot_path: str | None = None,
    freshness_disposition: str | None = None,
) -> dict:
    """Admit through the shared authority; the scheduler owns the whole job."""
    # S04 §7.2: hard-stop admission BEFORE any job artifact/freshness work.
    _coherence_refusal = await _require_carto_launch_admission(
        f"carto.refresh_launch:{mode}"
    )
    if _coherence_refusal is not None:
        return _coherence_refusal
    if mode not in {"file", "folder"}:
        return {"success": False, "error": f"Invalid mode {mode!r}; expected 'file' or 'folder'."}
    extra = dict(extra_job_fields or {})
    override = extra.get("source_path_override")
    if source_regime is None:
        source_regime = "temp_override" if override not in (None, "") else "standard"
    try:
        account_scope_id = _carto_account_scope()
    except Exception as exc:  # noqa: BLE001
        return {"success": False, "error": str(exc)}

    async def freshness() -> dict[str, Any]:
        if inherited_snapshot_path:
            return await _carto_select_live_basis(get_client(), "inherited_parent")
        return await _carto_select_snapshot(
            reason=f"governed {mode} CARTO refresh for {root_uuid}",
            source="carto_launch_authority",
        )

    def footprint_factory(selection: Mapping[str, Any]) -> Mapping[str, Any]:
        return _carto_footprint_from_selection(
            root_uuid=str(root_uuid),
            mode=mode,
            selection=selection,
            source_regime=str(source_regime),
        )

    result = await launch_carto_refresh_job(
        root_uuid=str(root_uuid),
        mode=mode,
        account_scope_id=account_scope_id,
        footprint_factory=footprint_factory,
        jobs_root=_governance_jobs_root(),
        schedule_job=_schedule_carto_job,
        launcher=launcher,
        extra_job_fields=extra,
        parent_job_id=parent_job_id,
        preparation=preparation,
        preparation_gate=preparation_gate,
        frozen_payload=frozen_payload,
        preparation_input_digest=preparation_input_digest,
        source_regime=str(source_regime),
        source_path_override=override,
        delete_temp_file_after=bool(extra.get("delete_temp_file_after")),
        freshness_callback=freshness,
        inherited_snapshot_path=inherited_snapshot_path,
        freshness_disposition=freshness_disposition,
        initial_footprint=initial_footprint,
        # Head-currency gate + held-node-lock consult view +
        # head-stale revalidation hook, derived from the pinned snapshot.
        **_carto_admission_coherence_kwargs(
            root_uuid=str(root_uuid),
            mode=mode,
            source_regime=str(source_regime),
        ),
    )
    if isinstance(result, dict):
        result.setdefault("mode", "carto_refresh")
        result.setdefault("root_uuid", str(root_uuid))
    return result


# @beacon[
#   id=auto-beacon@_start_carto_markdown_generate_job,
#   role=⚡ _start_carto_markdown_generate_job(root_uuid: str),
#   slice_labels=ra-reconcile,nexus-core-v1,ra-logging,ra-carto-jobs,ra-bulk-visible-apply,nexus-md-header-path,carto-rev-markdown-full,
#   kind=ast,
#   comment=Admits one Markdown task and its sole summary-head/2 writer with borrowed PRE or GESTURE basis; the common scheduler owns its one primary FILE grant through inline phase8 and summary-only finalization, without worker bootstrap or child row.,
# ]
async def _start_carto_markdown_generate_job(
    root_uuid: str,
    *,
    selected_snapshot: Mapping[str, Any] | None = None,
) -> dict:
    """Seed one /2 Markdown writer; its single FILE stays in flight through phase8."""
    from uuid import uuid4

    # S04 §7.2: hard-stop admission BEFORE any job artifact/admission work.
    _coherence_refusal = await _require_carto_launch_admission(
        "carto.markdown_generate_launch"
    )
    if _coherence_refusal is not None:
        return _coherence_refusal
    try:
        account_scope_id = _carto_account_scope()
        dedupe_key = derive_dedupe_key(
            account_scope_id=account_scope_id,
            job_type="CARTO_MARKDOWN_GENERATE",
            mode=None,
            root_uuid=str(root_uuid),
        )
        if selected_snapshot is None:
            early = await negative_exact_intent_gate(
                dedupe_key=dedupe_key,
                jobs_root=_governance_jobs_root(),
            )
            if early is not None:
                return early
            selection = await _carto_select_snapshot(
                reason=f"governed F12+3 freshness for {root_uuid}",
                source="f12_generate_markdown_file",
            )
        else:
            selection = dict(selected_snapshot)
            selection.setdefault("freshness_disposition", "gesture_performed")

        footprint = _carto_footprint_from_selection(
            root_uuid=str(root_uuid),
            mode="file",
            selection=selection,
            source_regime="standard",
        )
        jobs = Path(_get_carto_jobs_base_dir())
        jobs.mkdir(parents=True, exist_ok=True)
        now = datetime.utcnow()
        job_id = f"carto-markdown-generate-{uuid4().hex[:8]}"
        prefix = now.strftime("%Y%m%d-%H%M%S")
        job_file = jobs / f"{prefix}_{job_id}.json"
        log_file = jobs / f"{prefix}_{job_id}.log"
        payload = {
            "id": job_id,
            "type": "CARTO_MARKDOWN_GENERATE",
            "mode": "file",
            "root_uuid": str(root_uuid),
            "created_at": now.isoformat(),
            "updated_at": now.isoformat(),
            "execution_model": "daemon_task",
            "execution_owner": "launcher",
            "detached": False,
            "cache_refresh_required": True,
            "freshness_disposition": selection["freshness_disposition"],
            "snapshot_path": selection["snapshot_path"],
            # Base lineage and current adopted-view diagnostics, not bootstrap.
            "snapshot_lineage": selection.get("snapshot_lineage"),
            "live_basis_lineage": selection.get("live_basis_lineage"),
            "progress": {
                "total_files": 1,
                "completed_files": 0,
                "current_file": None,
                "current_phase": "waiting",
                "nodes_created": 0,
                "nodes_updated": 0,
                "nodes_moved": 0,
                "nodes_deleted": 0,
            },
            # The empty errors preview also keeps the legacy unstructured
            # scheduling-failure shape; admission creates this as /2.
            "result_summary": {"errors": []},
            "error": None,
            "logs_path": str(log_file),
        }
        admission = await admit_carto_job(
            job_file=job_file,
            job_payload=payload,
            job_type="CARTO_MARKDOWN_GENERATE",
            dedupe_key=dedupe_key,
            account_scope_id=account_scope_id,
            footprint=footprint,
            launcher="gui",
            parent_job_id=None,
            prepared=True,
            jobs_root=jobs,
            # Head-currency gate + held-node-lock consult view +
            # head-stale revalidation hook, from the pinned snapshot.
            **_carto_admission_coherence_kwargs(
                root_uuid=str(root_uuid),
                mode="file",
                source_regime="standard",
                selection=selection,
            ),
        )
        if admission.get("deduplicated"):
            return admission
        claim = admission["claim"]
        spec = CartoJobSpec(
            job_id=job_id, job_file=job_file, log_file=log_file,
            job_type="CARTO_MARKDOWN_GENERATE", mode="file", root_uuid=str(root_uuid),
            claim_id=str(claim["claim_id"]), claim_path=admission["claim_path"],
            account_scope_id=account_scope_id,
            selection_metadata={key: value for key, value in selection.items() if key not in {"cache_by_id", "nodes"}},
            selection_nodes_by_id=selection.get("cache_by_id"),
        )
        scheduled = await _schedule_carto_job(spec)
        if not scheduled.get("success"):
            return scheduled
        return {
            "success": True,
            "job_id": job_id,
            "pid": scheduled["pid"],
            "detached": False,
            "mode": "markdown_generate",
            "root_uuid": str(root_uuid),
            "job_file": str(job_file),
            "log_file": str(log_file),
            "freshness_disposition": selection["freshness_disposition"],
            "note": "Governed MARKDOWN_GENERATE daemon task queued; phase 8 runs in this job.",
        }
    except AdmissionRefusal as exc:
        return exc.to_result()
    except Exception as exc:  # noqa: BLE001
        return {"success": False, "error": f"Failed to launch MARKDOWN_GENERATE: {exc}"}


def _read_carto_job_payload(job_file: str, *, strict=False) -> dict[str, Any] | None:
    """Read one legacy saved record; terminal recovery asks for its actual error."""
    try:
        with open(job_file, "r", encoding="utf-8") as jf:
            return json.load(jf)
    except Exception:
        if strict:
            raise
        return None


def _write_carto_job_payload(job_file: str, payload: dict[str, Any]) -> bool:
    """Publish bulk head changes through its admission-owned /2 writer.

    Non-job legacy callers retain the same guarded funnel; neither path has a
    second status authority or reads earlier evidence.
    """
    from .carto_job_record import record_for
    writer = record_for(job_file, create=False)
    ok = (writer.update_head(**payload) if writer is not None else
          merge_write_carto_job_status(job_file, payload))
    if not ok:
        log_event(f"Failed to write CARTO job file {job_file}", "CARTO")
    return ok


def _append_carto_job_log(log_file: str | None, message: str) -> None:
    if not log_file:
        return
    try:
        ts = datetime.utcnow().isoformat()
        with open(log_file, "a", encoding="utf-8") as lf:
            lf.write(f"[{ts}] {message}\n")
    except Exception as e:  # noqa: BLE001
        log_event(f"Failed to append CARTO log {log_file}: {e}", "CARTO")


def _carto_job_cancel_requested(job_file: str) -> bool:
    """Current loop-owned control probe; the job-file argument is inert noise."""
    context = current_carto_job_context()
    if context is not None:
        return context.job_control.user_cancel_requested()
    return False


def _note_has_path_or_root_header(note_str: str | None) -> bool:
    for line in str(note_str or "").splitlines():
        stripped = line.strip()
        if stripped.startswith("Path:") or stripped.startswith("Root:"):
            return True
    return False


def _is_folder_like_node_name(name: str | None) -> bool:
    return str(name or "").strip().startswith("📂")


def _cartographer_header_info(note_str: str | None) -> tuple[str, bool]:
    first_header = ""
    has_line_count = False
    for line in str(note_str or "").splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if not first_header and (stripped.startswith("Path:") or stripped.startswith("Root:")):
            first_header = stripped
        if stripped.startswith("LINE COUNT:"):
            has_line_count = True
    return first_header, has_line_count


def _path_header_looks_like_file(first_header: str, name_text: str | None) -> bool:
    """Mirror of the extension-side pathHeaderLooksLikeFile heuristic.

    Manual file nodes (created directly in Workflowy before any Cartographer
    refresh) may not yet have a LINE COUNT: header. If the Path: value (or
    the visible node name) clearly ends with a filename extension, treat the
    target as a FILE node so bulk-apply can walk into it.

    This matches the JS-side classifier in glimpse-cache-client.js so the
    server's bulk-apply grouping agrees with the extension's F12 popup
    file-vs-folder classification.
    """
    header = str(first_header or "").strip()
    if not header.startswith("Path:"):
        return False

    path_value = header[len("Path:"):].strip()
    # Strip surrounding single/double quotes if present.
    if len(path_value) >= 2 and path_value[0] in ("'", '"') and path_value[-1] == path_value[0]:
        path_value = path_value[1:-1].strip()

    if not path_value or path_value == "." or path_value.endswith("/") or path_value.endswith("\\"):
        return False

    lower_path = path_value.lower()
    lower_name = str(name_text or "").strip().lower()

    # Heuristic 1: Path: value clearly looks like .../filename.ext
    if re.search(r"(^|[\\/])[^\\/]+\.[^\\/.\s]+$", lower_path):
        return True
    # Heuristic 2: visible node name ends with a filename extension
    if re.search(r"\.[a-z0-9_-]+$", lower_name):
        return True
    return False


def _is_file_like_payload_node(node: dict[str, Any]) -> bool:
    first_header, has_line_count = _cartographer_header_info(node.get("note"))
    if not first_header.startswith("Path:"):
        return False
    if has_line_count:
        return True
    # Manually-created file nodes (e.g. Obsidian-style Markdown 99-files) often
    # have a Path: header but no LINE COUNT: line because they were never
    # F12-refreshed. Fall back to the extension's filename-extension heuristic.
    return _path_header_looks_like_file(first_header, node.get("name"))


def _is_folder_like_payload_node(node: dict[str, Any]) -> bool:
    first_header, has_line_count = _cartographer_header_info(node.get("note"))
    if first_header.startswith("Root:"):
        return True
    if first_header.startswith("Path:") and not has_line_count:
        # Same fallback as _is_file_like_payload_node: if the Path: value
        # clearly looks like a filename, classify as FILE rather than FOLDER.
        if _path_header_looks_like_file(first_header, node.get("name")):
            return False
        return True
    return False


# @beacon[
#   id=bulk-visible-apply@_normalize_bulk_visible_compare_text,
#   role=ƒ _normalize_bulk_visible_compare_text(text),
#   slice_labels=ra-reconcile,ra-bulk-visible-apply,ra-workflowy-cache,carto-rev-markdown-full,nexus--tags,
#   kind=ast,
#   comment=Whitens visible-DOM vs cache text for spurious-UPDATE detection in F12 bulk-apply pre-pass; tied to F12+3 timeout investigation,
# ]
def _normalize_bulk_visible_compare_text(text: str | None) -> str:
    s = str(text or "")
    try:
        import importlib
        cartographer = importlib.import_module("nexus_map_codebase")
        normalizer = getattr(cartographer, "whiten_text_for_header_compare", None)
        if callable(normalizer):
            s = normalizer(s)
    except Exception:
        s = "".join(ch for ch in s if not ch.isspace())
    # For dirty detection, ignore beacon decoration that may lag visual refresh.
    s = s.replace("🔱", "")
    return s


# @beacon[
#   id=bulk-visible-apply@_visible_node_differs_from_cache,
#   role=ƒ _visible_node_differs_from_cache(node, nodes_by_id_cache),
#   slice_labels=ra-reconcile,ra-bulk-visible-apply,ra-workflowy-cache,carto-rev-markdown-full,nexus--tags,
#   kind=ast,
#   comment=Helper that compares visible Workflowy DOM against /nodes-export cache; deliberately NOT used as bulk-apply pre-filter (see comment in _collect_bulk_visible_apply_groups). Always returned True after refresh and caused F12+2 nothing-happens bug.,
# ]
def _visible_node_differs_from_cache(node: dict[str, Any], nodes_by_id_cache: dict[str, dict[str, Any]]) -> bool:
    node_id = str(node.get("id") or "").strip()
    if not node_id:
        return True
    cached = nodes_by_id_cache.get(node_id)
    if not isinstance(cached, dict):
        return True

    visible_name = _normalize_bulk_visible_compare_text(node.get("name"))
    visible_note = _normalize_bulk_visible_compare_text(node.get("note"))
    cached_name = _normalize_bulk_visible_compare_text(cached.get("name") or cached.get("nm"))
    cached_note = _normalize_bulk_visible_compare_text(cached.get("note") or cached.get("no"))

    return visible_name != cached_name or visible_note != cached_note


# @beacon[
#   id=bulk-visible-apply@_is_bulk_visible_apply_candidate,
#   role=ƒ _note_has_real_beacon_metadata_block(note: str),
#   slice_labels=ra-reconcile,ra-bulk-visible-apply,ra-carto-jobs,carto-rev-markdown-full,nexus--tags,beacon-writeback,
#   kind=ast,
#   comment=Bulk-apply candidate filter for F12+3 step [3] pre-pass. Tightened May 2026 to require either an existing BEACON block OR trailing #tags - excludes plain MD_PATH-only heading nodes that cannot possibly need a disk write.,
# ]
def _note_has_real_beacon_metadata_block(note: str) -> bool:
    """Return True iff a Workflowy note contains a real BEACON metadata block.

    Do NOT use a raw substring test for "BEACON (". Long Markdown files can
    legitimately contain heading text such as "## BEACON (MD AST)" inside
    MD_PATH lines or body prose. Those are not Cartographer metadata blocks
    and must not make F12+2 treat a plain heading as a beacon candidate.

    A real cached Cartographer BEACON metadata block has a header line
    (``BEACON (...)``) followed by canonical metadata lines, especially a
    non-empty ``id:`` line. A human-authored note may also contain prose or
    examples like::

        The block looks like:
        AST_QUALNAME: Foo.bar
        BEACON (AST)
        ...

    That standalone example line is NOT a metadata block and must not make
    the bulk-apply candidate filter process an otherwise untagged node.
    """
    if not isinstance(note, str):
        return False

    metadata_prefixes = (
        "id:",
        "role:",
        "slice_labels:",
        "kind:",
        "comment:",
        "comments:",
        "show_span:",
    )
    lines = note.splitlines()

    for i, line in enumerate(lines):
        stripped = line.strip()
        if not stripped.startswith("BEACON ("):
            continue

        saw_metadata = False
        saw_id = False

        for following in lines[i + 1 :]:
            s = following.strip()

            # Generated metadata blocks can contain occasional blank lines;
            # blanks alone do not prove or disprove the block.
            if not s:
                continue

            # Markdown notes may put a separator after the generated BEACON
            # block. If we reached it before seeing id:, this header was not a
            # complete real metadata block.
            if s == "---":
                break

            if any(s.startswith(prefix) for prefix in metadata_prefixes):
                saw_metadata = True
                if s.startswith("id:") and s.split(":", 1)[1].strip():
                    saw_id = True
                continue

            # First non-metadata content/prose line ends this candidate block.
            break

        if saw_metadata and saw_id:
            return True

    return False


# @beacon[
#   id=auto-beacon@_name_has_trailing_tag,
#   role=ƒ _name_has_trailing_tag(name: str),
#   slice_labels=ra-bulk-visible-apply,carto-rev-markdown-full,nexus--tags,beacon-writeback,
#   kind=ast,
#   comment=Universal trailing-#tag detector shared by Class 1 (AST_QUALNAME) and Class 3 (MD_PATH) of the bulk-visible-apply candidate filter. Same shape recognized by split_name_and_tags.,
# ]
def _name_has_trailing_tag(name: str) -> bool:
    """Return True iff the last whitespace-delimited token of *name* starts with '#'.

    This matches the tag convention enforced by ``split_name_and_tags``:
    trailing tokens like ``#foo`` / ``#foo-bar`` at the end of a Workflowy
    node's NAME field are the canonical user-facing source of truth for
    whether a beacon should exist on disk for that node.

    Only the trailing (last) token is inspected. A name like
    ``"#foo middle text"`` is treated as having NO trailing tag, because
    the last token (``"text"``) does not start with '#'.
    """
    if not isinstance(name, str):
        return False
    for token in reversed(name.split()):
        if token.startswith("#"):
            return True
        # First non-tag token from the right ⇒ no trailing tags present.
        return False
    return False


# @beacon[
#   id=auto-beacon@_is_bulk_visible_apply_candidate-zg0t,
#   role=ƒ _is_bulk_visible_apply_candidate(node),
#   slice_labels=ra-bulk-visible-apply,carto-rev-markdown-full,nexus--tags,beacon-writeback,
#   kind=ast,
#   comment=Bulk-visible-apply candidate filter. Class 1 (AST) and Class 3 (Markdown) both require a trailing #tag when no BEACON metadata block is present in the note. Class 2 admits any node whose note already carries a real BEACON block. See May 18 2026 archaeological-dig commentary for the full reasoning (new-paradigm name-tag-as-source-of-truth).,
# ]
def _is_bulk_visible_apply_candidate(node: dict[str, Any]) -> bool:
    """Return True iff this node could plausibly need a disk-side beacon update.

    Three eligibility classes are admitted, in this order:

    1. **Existing BEACON block in note** (Class 2 below) — the node already
       has a beacon attached on disk; the slow path may need to UPDATE or
       DELETE it. The cached BEACON block in the NOTE is the record of
       what F12+1 last ingested from disk; its presence is sufficient to
       guarantee that the slow path has real work to do (or to validate
       against).
    2. **AST_QUALNAME node WITH trailing #tag in name** (Class 1 below) —
       a Python / JS / TS / Vue / TSX / JSX AST node mapped by
       Cartographer whose Workflowy NAME has a trailing ``#tag``. The
       slow path may need to CREATE a beacon on disk. ``AST_QUALNAME:``
       is the universal AST anchor emitted by Cartographer across all
       AST-bearing languages, so a single check covers them all. SQL,
       shell, and YAML files do not have AST beacons (SPAN only), so they
       never carry ``AST_QUALNAME:`` and are not affected by this class.
    3. **MD_PATH heading WITH trailing #tag in name** (Class 3 below) — a
       Markdown heading whose Workflowy NAME has a trailing ``#tag``. The
       slow path may need to CREATE a beacon on disk.

    A node that has no BEACON metadata block in its note AND no trailing
    ``#tag`` in its name is intentionally NOT a candidate: under the
    current paradigm there is no semantic reason it would need any
    disk-side beacon work.

    Paradigm history (see May 18 2026 archaeological-dig commentary)
    ----------------------------------------------------------------
    Months ago the Cartographer system treated the BEACON metadata block
    inside the Workflowy note as the canonical source of truth for tag
    state, and users were expected to add/remove tags by editing that
    block directly. Under that paradigm the language helpers grew a
    Case 1c orphan-cleanup branch that, for any node with no BEACON
    block and no trailing ``#tag``, would re-parse the on-disk file
    looking for stale beacon blocks to delete.

    The system has since moved to a name-#tag-as-source-of-truth
    paradigm: the trailing ``#tag`` in the Workflowy NAME field is the
    canonical user-facing control, the BEACON metadata block is a
    read-only record of the last F12+1 ingest, and orphan cleanup is
    no longer a user-driven scenario. F12+1's full-file reconcile is
    the catch-all for any residual stale on-disk beacon blocks.

    Accordingly, excluding ``(no BEACON, no trailing #tag)`` nodes here
    is not a forfeit — it is alignment of this filter with the current
    paradigm. The previous Markdown-only optimization (commit ``e5de88b``,
    May 1 2026) made the same change for Class 3; this is the symmetric
    application to Class 1.

    Performance impact
    ------------------
    For the Jim Markdown file (614 MD_PATH-bearing nodes, 180
    beacon-bearing) Class 3 alone dropped the candidate count from
    614 → 180 — a 3.4× reduction. The Class 1 symmetry eliminates the
    parallel ``success=False op='noop'`` ERROR flood for plain
    untagged Python / JS / TS AST nodes that previously reached the
    slow path and consumed cycles in Case 1c.
    """
    if _is_file_like_payload_node(node):
        return False
    if _is_folder_like_payload_node(node):
        return False
    note = str(node.get("note") or "")
    name = str(node.get("name") or "")

    # Class 2 (checked first): already-beaconed node — always a candidate.
    # IMPORTANT: require a real metadata line, not just the substring
    # "BEACON (" somewhere in MD_PATH/body text. A heading literally named
    # "## BEACON (MD AST)" otherwise poisons every descendant's MD_PATH and
    # creates false-positive F12+2 candidates that helper-noop noisily.
    if _note_has_real_beacon_metadata_block(note):
        return True

    # Class 1: AST node (Python / JS / TS / Vue / TSX / JSX) WITH a trailing
    # #tag in the name — may need beacon CREATE. AST_QUALNAME: is the
    # universal Cartographer AST marker across all AST-bearing languages,
    # so a single check covers them all. SQL / shell / YAML do not emit
    # AST_QUALNAME: (SPAN-only beacons) and are unaffected.
    #
    # Under the new paradigm (BEACON block is not user-editable; trailing
    # #tag is the source of truth), an AST node with no BEACON block and
    # no trailing #tag has no work to do — the slow path on such a node
    # would only enter the obsolete Case 1c orphan-cleanup branch. See
    # the May 18 2026 archaeological-dig commentary for the full history.
    if "AST_QUALNAME:" in note and _name_has_trailing_tag(name):
        return True

    # Class 3: Markdown heading WITH a trailing #tag — may need beacon
    # CREATE. Plain MD_PATH-only heading without tags is NOT a candidate
    # (same new-paradigm reasoning as Class 1 above).
    if "MD_PATH:" in note and _name_has_trailing_tag(name):
        return True

    return False


# @beacon[
#   id=bulk-visible-apply@_node_name_tags_match_beacon_block_in_note,
#   role=ƒ _node_name_tags_match_beacon_block_in_note(candidate),
#   slice_labels=ra-bulk-visible-apply,ra-workflowy-cache,carto-rev-markdown-full,nexus--tags,beacon-writeback,
#   kind=ast,
#   comment=Bulk-apply pre-filter for F12+3 step [3]. Detects nodes whose name #tags + decoration-stripped base text already match the BEACON (MD AST) block in their own note and skips them - avoiding the ~480ms-per-call cost of update_beacon_from_node_markdown's full MarkdownIt parse on a fully-synced file.,
# ]
def _node_name_tags_match_beacon_block_in_note(candidate: dict[str, Any]) -> bool:
    """Return True iff the node's NAME #tags + base text already match the
    BEACON (MD AST) block embedded in the node's NOTE.

    What this function actually checks
    ----------------------------------
    A purely intra-node, text-only equality between two pieces of cached
    data on the SAME Workflowy node:

      - The trailing '#tag1 #tag2 ...' tokens in the node's NAME, AND
      - The 'slice_labels:' line inside the BEACON (MD AST) block in the
        node's NOTE, AND
      - The decoration-stripped (i.e. without the 'trident' marker)
        leading text of the NAME, AND
      - The 'role:' line inside the BEACON (MD AST) block in the NOTE.

    NO disk access. NO MarkdownIt parse. NO Workflowy API call. This is
    pure in-memory string comparison and runs in microseconds per call.

    Why this also implies "disk is in sync"
    ---------------------------------------
    The BEACON (MD AST) block inside the NOTE was only ever written by
    apply_markdown_beacons (the disk -> Workflowy ingest direction during
    F12+1). It records what was on disk at the time of the last successful
    sync. If the user then edits a tag in the Workflowy GUI, the NAME's
    #tag tokens change immediately, but the BEACON block in the NOTE does
    NOT change until the next F12+3 round-trip writes the new tag set to
    disk and the next F12+1 ingest re-reads disk into the NOTE.

    Therefore:
      - Match between NAME tags and NOTE BEACON slice_labels means the
        user has NOT edited tags since the last F12 cycle, AND the on-disk
        beacon block is the most recent thing the system wrote.
      - Mismatch means the user changed tags in Workflowy, OR the BEACON
        block in the NOTE is stale, AND the slow path needs to run.

    Why we cannot use the SIMILAR-LOOKING but BROKEN cache-vs-DOM filter
    ------------------------------------------------------------------
    History: an earlier filter, _visible_node_differs_from_cache, compared
    the Workflowy-DOM payload (sent by the GLIMPSE extension) against the
    /nodes-export cache. That filter caused the F12+2 "nothing happens"
    bug: the cache had ALWAYS just been refreshed by the handler's
    pre-flight, so DOM and cache always matched, so the filter ALWAYS
    skipped every candidate.

    The reason the cache-vs-DOM filter is structurally broken is that the
    /nodes-export cache refresh has NO SEMANTIC understanding of what the
    text inside a node MEANS. It just blindly copies whatever Workflowy's
    server returns into the in-memory cache as opaque strings. The cache
    refresh does NOT validate that name #tags match note BEACON
    slice_labels - it cannot, because it has no notion of "tags" or
    "BEACON blocks" at all. It treats node.name and node.note as plain
    strings. So if a node is semantically out-of-sync between its NAME
    and its NOTE BEACON block, the cache refresh just faithfully
    preserves that out-of-sync state. DOM and cache stay equal because
    they came from the same source, even though the node itself is
    internally inconsistent.

    THIS function does NOT have that problem because it ignores the
    DOM/cache distinction entirely and instead checks whether the NAME's
    tag suffix is consistent with the NOTE's BEACON slice_labels - a
    SEMANTIC, intra-node check that the cache refresh process cannot
    accidentally satisfy.

    Conservative behavior
    ---------------------
    Returns True ONLY when:
      - The note contains a BEACON (MD AST) block (so we know there's an
        on-disk beacon for this heading; absence means we must let the
        slow path run to handle CREATE/DELETE), AND
      - slice_labels parses cleanly out of that block, AND
      - The canonicalized name #tags match the on-disk slice_labels exactly.

    Role is INTENTIONALLY NOT compared (Dan, May 2026). The role: field
    is cosmetic only and including it in the in-sync check caused
    phantom UPDATE storms whenever the Workflowy NAME and the on-disk
    role: differed by surrounding quotes or punctuation. See the inline
    comment near the bottom of this function for the full explanation.

    Any other case returns False, and the slow path
    (update_beacon_from_node_markdown) becomes the single source of
    truth, exactly as before this optimization existed.
    """
    name = str(candidate.get("name") or "")
    note = str(candidate.get("note") or "")

    # Cheap reject: no real BEACON metadata block at all means we cannot
    # infer disk state and must let the slow path run (covers CREATE-from-tags
    # and delete-orphaned-disk-beacon cases). Use line-anchored metadata
    # detection; substring matching is unsafe because MD_PATH/body text can
    # contain literal heading names like "## BEACON (MD AST)".
    if not _note_has_real_beacon_metadata_block(note):
        return False

    # Lazy import of nexus_map_codebase. The module lives at the repo root
    # (NOT inside the workflowy_mcp package), so it may not be on sys.path
    # when this filter is first called. Mirror the pattern used by
    # WorkFlowyClient.update_beacon_from_node: walk up from this file's
    # location to find the project root and add it to sys.path if needed.
    try:
        import importlib
        import os as _os
        import sys as _sys

        try:
            cartographer = importlib.import_module("nexus_map_codebase")
        except ImportError:
            here = _os.path.dirname(_os.path.abspath(__file__))
            # server.py is at <repo>/src/workflowy_mcp/server.py; walk up 3 levels.
            project_root = _os.path.dirname(_os.path.dirname(here))
            if project_root and project_root not in _sys.path:
                _sys.path.insert(0, project_root)
            # Also try the alternate Obsidian-source layout where this module
            # lives at <root>/MCP_Servers/workflowy_mcp/server.py.
            alt_root = _os.path.dirname(_os.path.dirname(_os.path.dirname(here)))
            if alt_root and alt_root not in _sys.path:
                _sys.path.insert(0, alt_root)
            cartographer = importlib.import_module("nexus_map_codebase")
    except Exception:
        return False

    split_name_and_tags = getattr(cartographer, "split_name_and_tags", None)
    canonicalize_slice_labels = getattr(cartographer, "_canonicalize_slice_labels", None)
    extract_slice_labels = getattr(cartographer, "_extract_slice_labels_from_beacon_block", None)
    extract_role = getattr(cartographer, "_extract_role_from_beacon_block", None)
    if not callable(split_name_and_tags) or not callable(canonicalize_slice_labels):
        return False
    if not callable(extract_slice_labels) or not callable(extract_role):
        return False

    # Parse name into base + #tag tokens. Then strip the trident decoration
    # 'U+1F531' from the base so a name like "Wednesday, November 13 trident
    # #tag" yields role_from_name = "Wednesday, November 13".
    base_name, name_tags = split_name_and_tags(name)
    role_from_name = base_name
    while role_from_name.endswith("\U0001F531"):
        role_from_name = role_from_name[:-1].rstrip()
    role_from_name = role_from_name.strip()

    # Canonicalize the name's #tags into the same comma-joined form that
    # is written to disk in the BEACON (MD AST) block's slice_labels: line.
    extra_label_tokens = [t.lstrip("#") for t in name_tags]
    canonical_name_labels = (
        canonicalize_slice_labels(",".join(extra_label_tokens), None)
        if extra_label_tokens
        else ""
    )

    note_slice_labels = extract_slice_labels(note)
    note_role = extract_role(note)

    # Conservative: any missing field => fall through to slow path.
    if note_slice_labels is None or note_role is None:
        return False

    # Both must match exactly. Different tag set or renamed heading both
    # require the slow path so disk gets the update.
    if canonical_name_labels != note_slice_labels.strip():
        return False

    # Role comparison is INTENTIONALLY DISABLED (Dan, May 2026).
    #
    # Background: the role: field in BEACON blocks is a cosmetic display
    # value derived from the heading/AST node name. It carries no
    # semantic information that the slice_labels: comparison above does
    # not already cover. Including role in the in-sync check caused
    # repeated phantom UPDATE storms during F12+2 reconcile whenever the
    # Workflowy NAME and the on-disk role: differed by ANY character
    # (surrounding ASCII quotes, punctuation tweaks, etc.) — the slow
    # path then ran, update_cached_node_name stripped the tag from the
    # cache via base_name, and the per-file reconcile fired UPDATE for
    # every such node every time.
    #
    # Fix: skip role comparison entirely. slice_labels match is the
    # only thing that determines whether disk and Workflowy are tag-
    # synced. note_role/role_from_name are computed above only so the
    # debug log can still show what role *would* have been compared,
    # if anyone is ever curious — they no longer gate the result.
    _ = role_from_name  # explicitly noted unused
    _ = note_role        # explicitly noted unused

    return True


# @carto-group id=server-group-3 label="Server group three"

# @beacon[
#   id=bulk-visible-apply@_normalize_role_for_in_sync_compare,
#   role=ƒ _normalize_role_for_in_sync_compare(text: str),
#   slice_labels=ra-bulk-visible-apply,ra-workflowy-cache,carto-rev-markdown-full,nexus--tags,
#   kind=ast,
#   comment=ASCII-folding normalizer for the in-sync filter's role: comparison. Must be applied to BOTH the Workflowy NAME-derived role text AND the on-disk BEACON block's role: line so semantically-equal strings (smart-quote vs ASCII, &amp; vs &) compare equal.,
# ]
def _normalize_role_for_in_sync_compare(text: str) -> str:
    """Normalize a role string for the in-sync filter's equality check.

    Handles the common encoding mismatches between the Workflowy NAME text
    (preserved as the user typed it) and the on-disk BEACON block's role:
    line (HTML-escaped, ASCII-only quotes due to the disk writer's output
    conventions):

      - HTML entities: &amp; → &, &lt; → <, &gt; → >, &quot; → "
      - Smart single quotes: ' (U+2018), ' (U+2019) → ASCII apostrophe (')
      - Smart double quotes: " (U+201C), " (U+201D) → ASCII quote (")
      - Em / en dashes: — (U+2014), – (U+2013) → ASCII hyphen-minus (-)
      - Ellipsis: … (U+2026) → three ASCII dots (...)

    Whitespace at edges is collapsed via .strip(). Internal whitespace is
    preserved verbatim (the on-disk and cached forms agree on whitespace
    between words; we don't need to normalize that).

    This is INTENTIONALLY narrower than whiten_text_for_header_compare:
    that helper also strips quotes, drops emojis, and removes tag markup,
    which would be too lossy here — we want to detect REAL differences
    in role text (e.g. user renamed the heading, or upstream tooling
    changed the role text), not just encoding artifacts.
    """
    if not isinstance(text, str):
        return ""
    s = text

    # HTML entities first (so subsequent literal-quote folding catches
    # the decoded forms uniformly).
    html_entity_map = {
        "&amp;": "&",
        "&lt;": "<",
        "&gt;": ">",
        "&quot;": '"',
        "&#39;": "'",
        "&apos;": "'",
    }
    for ent, ch in html_entity_map.items():
        if ent in s:
            s = s.replace(ent, ch)

    # Smart-quote / dash / ellipsis folding to ASCII equivalents.
    smart_to_ascii = {
        "\u2018": "'",   # LEFT SINGLE QUOTATION MARK
        "\u2019": "'",   # RIGHT SINGLE QUOTATION MARK
        "\u201A": "'",   # SINGLE LOW-9 QUOTATION MARK
        "\u201B": "'",   # SINGLE HIGH-REVERSED-9 QUOTATION MARK
        "\u201C": '"',   # LEFT DOUBLE QUOTATION MARK
        "\u201D": '"',   # RIGHT DOUBLE QUOTATION MARK
        "\u201E": '"',   # DOUBLE LOW-9 QUOTATION MARK
        "\u201F": '"',   # DOUBLE HIGH-REVERSED-9 QUOTATION MARK
        "\u2013": "-",   # EN DASH
        "\u2014": "-",   # EM DASH
        "\u2015": "-",   # HORIZONTAL BAR
        "\u2026": "...", # HORIZONTAL ELLIPSIS
    }
    for src, dst in smart_to_ascii.items():
        if src in s:
            s = s.replace(src, dst)

    return s.strip()


# @beacon[
#   id=carto-runtime@prepare-bulk-candidate,
#   slice_labels=ra-bulk-visible-apply,ra-carto-jobs,nexus--tags,
#   kind=ast,
#   comment=Prepares bulk candidate text and preserves the existing semantic in-sync comparison off-loop on owned data; known filter errors return warning data and no client cache patch progress callback or job state enters this worker.,
# ]
def _prepare_bulk_candidate(operation: str, value: Any) -> Any:
    if operation == "values":
        return str(value.get("id") or "").strip(), str(value.get("name") or ""), str(value.get("note") or "")
    if operation == "filter":
        try:
            return _node_name_tags_match_beacon_block_in_note(value), None
        except Exception as exc:  # noqa: BLE001
            return False, str(exc)
    raise ValueError(f"Unknown bulk candidate data phase: {operation}")


def _bulk_result_log_text(node_id, node_result):
    """The existing result line, formatted from exclusively returned helper data."""
    if isinstance(node_result, dict):
        return (
            "HELPER RESULT "
            f"node_id={node_id} "
            f"success={node_result.get('success')} "
            f"op={node_result.get('operation')!r} "
            f"lang={node_result.get('language')!r} "
            f"beacon_id={node_result.get('beacon_id')!r} "
            f"slice_labels={node_result.get('slice_labels')!r} "
            f"tags={node_result.get('tags')!r} "
            f"base_name={node_result.get('base_name')!r} "
            f"source_path={node_result.get('source_path')!r} "
            f"error={node_result.get('error')!r} "
            f"cache_name_updated={node_result.get('cache_name_updated')!r} "
            f"cache_note_updated={node_result.get('cache_note_updated')!r} "
            f"cache_skip={node_result.get('cache_name_update_skipped_reason')!r}"
        )
    return f"HELPER RESULT node_id={node_id} non_dict={node_result!r}"


# @beacon[
#   id=bulk-visible-apply@_bulk_apply_per_file_inner_loop,
#   role=⚡ _bulk_apply_per_file_inner_loop(client: Any, candidate_nodes, file_name: str, summary, cancel_check, log, progress_tick),
#   slice_labels=ra-bulk-visible-apply,ra-carto-jobs,carto-rev-markdown-full,nexus--tags,beacon-writeback,
#   kind=ast,
#   comment=One shared candidate loop preserves raw writer success and holder-only commit receipts on cancellation; successful-call counters errors triggers and callbacks stay unchanged while transient result and holder references are released before the joined artifact return.,
# ]
async def _bulk_apply_per_file_inner_loop(
    client: Any,
    candidate_nodes: list[dict[str, Any]],
    file_name: str,
    summary: dict[str, Any],
    cancel_check: Callable[[], bool],
    log: Callable[[str], None],
    progress_tick: Callable[[], None],
    *,
    flush_artifacts: Callable[[], Any] | None = None,
    log_result: Callable[[str, Any], None] | None = None,
) -> tuple[int, bool]:
    """Run the per-candidate inner loop for ONE file. Single-source-of-truth.

    The shared no-IO projection keeps each writer's findings, noop reason and
    original writer_success. A plain per-call receipt holder preserves a result
    lost to the post-worker cancellation checkpoint without incrementing legacy
    successful-call counters or running callbacks for that unreturned call.
    ``node_outcomes`` and ``nodes_satisfied`` are additive data, not a change
    to the fail-closed errors, skipped counters or returned refresh trigger.
    Full current analysis belongs once after the file's final write, not here
    per candidate. The result and holder relinquish their references after the
    caller's evidence handoff, including an unwind, not into the next candidate.

    Background
    ----------
    The F12+2 and F12+3 step [3] bulk-apply paths used to ship as two
    near-identical copies of this loop body — one inside
    ``_run_carto_bulk_visible_apply_job`` (server.py, used directly when
    F12+2 is invoked via WebSocket), and a duplicate inside
    ``run_bulk_apply_inline`` (markdown_generate_pipeline.py, used when
    F12+3 now runs that pipeline in its daemon task; the former detached
    worker entry is retained only as legacy code). The duplicate paths bit Dan on
    May 1, 2026: the Bug #2 in-sync filter optimization (commit
    ``bd90026``) was applied only to the server.py copy, so F12+3 still
    ran at the old slow rate until commit ``e1a8d34`` patched the
    pipeline copy too. This function exists so any future change to the
    inner loop touches exactly ONE place.

    Caller responsibilities (NOT done here)
    ---------------------------------------
    - Build the visible-tree root_node and group candidates by enclosing
      FILE node (via ``_collect_bulk_visible_apply_groups``).
    - The OUTER per-file loop, including the per-file
      ``refresh_file_node_beacons`` call after this returns when
      ``file_successful_node_updates > 0``.
    - Initialize the ``summary`` dict with the standard keys
      (``node_updates``, ``nodes_skipped``, ``nodes_skipped_in_sync``,
      ``errors``). This function increments those keys in place.
    - Provide the three callables described below.

    Callable parameters
    -------------------
    cancel_check() -> bool
        Polled at the top of each candidate iteration. Return True to
        stop the loop (the caller is responsible for setting any
        higher-level cancel state, e.g. job status).
    log(msg: str) -> None
        Append a log line. Each implementation routes to its own job log
        file (server.py uses ``_append_carto_job_log``, pipeline uses
        ``_append_log``).
    progress_tick() -> None
        Called after each successful ``update_beacon_from_node`` call,
        i.e. after ``summary['node_updates']`` is incremented. Used to
        flush the running counter into the job JSON for live widget
        progress display. May be a no-op if the caller doesn't track
        progress at this granularity.
    flush_artifacts() -> awaitable, optional
        Joins only the daemon caller's queued owned artifact values. Arbitrary
        legacy callbacks still run synchronously on the owning loop, unchanged.
    log_result(node_id, node_result) -> None, optional
        Queues exclusively returned result data for the daemon writer to format.
        Without it the existing arbitrary log callback still receives its string
        synchronously, at the same point before the counters change.

    Side effects on ``summary`` (in place)
    --------------------------------------
    - ``summary['node_updates']``        += 1 per successful update
    - ``summary['nodes_skipped']``       += 1 per missing-id or error
    - ``summary['nodes_skipped_in_sync']`` += 1 per in-sync filter hit
    - ``summary['errors']`` (list)       appended for each failure
    - ``summary['node_outcomes']`` (list) retains each returned writer result
    - ``summary['nodes_satisfied']`` counts precisely satisfied noop reasons

    Returns
    -------
    (file_successful_node_updates, was_cancelled)
        ``file_successful_node_updates`` — count of successful update
        calls in this file's inner loop. The caller uses this to decide
        whether to invoke the per-file ``refresh_file_node_beacons``.
        ``was_cancelled`` — True iff ``cancel_check()`` returned True
        and the loop exited early.
    """
    file_successful_node_updates = 0

    for candidate in candidate_nodes:
        if cancel_check():
            return file_successful_node_updates, True

        node_id, node_name, node_note = await run_carto_cpu("bulk:candidate-values", _prepare_bulk_candidate, "values", candidate)
        if not node_id:
            summary["nodes_skipped"] += 1
            summary["errors"].append(
                f"Skipped visible node with missing id under file {file_name}.",
            )
            continue

        if node_name:
            try:
                await client.update_cached_node_name(
                    node_id=node_id,
                    new_name=node_name,
                )
            except Exception as e:  # noqa: BLE001
                log(f"WARNING: update_cached_node_name failed for {node_id}: {e}")
                if flush_artifacts is not None:
                    await flush_artifacts()

        # Bug #2 in-sync filter (Dan, 2026-05-01). Skips the slow
        # update_beacon_from_node path when the candidate's NAME #tags
        # + decoration-stripped base text already match the BEACON
        # (MD AST) block in its NOTE. See
        # _node_name_tags_match_beacon_block_in_note above for the full
        # reasoning chain and why this is structurally different from
        # the broken cache-vs-DOM filter.
        in_sync, filter_error = await run_carto_cpu("bulk:candidate-filter", _prepare_bulk_candidate, "filter", candidate)
        if in_sync:
            summary["nodes_skipped_in_sync"] += 1
            continue
        if filter_error is not None:
            log(f"WARNING: in-sync filter raised for {node_id}: {filter_error}; running slow path.")
            if flush_artifacts is not None:
                await flush_artifacts()

        receipt_holder = {}
        receipt_recorded = False
        try:
            node_result = await client.update_beacon_from_node(
                node_id=node_id,
                name=node_name,
                note=node_note,
                receipt_holder=receipt_holder,
            )
            if isinstance(node_result, dict):
                from .beacon_refresh_support import beacon_legacy_outcome

                # Add data only here; the writer's own success stays the trigger.
                node_result = {**beacon_legacy_outcome(node_result),
                               "writer_success": node_result.get("writer_success", node_result.get("success")),
                               "success": node_result.get("success", True)}
                summary.setdefault("node_outcomes", []).append({"node_id": node_id, **node_result})
                receipt_recorded = True
                if node_result["satisfied"]:
                    summary["nodes_satisfied"] = summary.get("nodes_satisfied", 0) + 1
            if log_result is not None:
                log_result(node_id, node_result)
            else:
                log(_bulk_result_log_text(node_id, node_result))
            if isinstance(node_result, dict) and not node_result.get("success", True):
                raise RuntimeError(
                    node_result.get("error")
                    or f"update_beacon_from_node returned failure/op={node_result.get('operation')!r}",
                )
            file_successful_node_updates += 1
            summary["node_updates"] += 1
            try:
                progress_tick()
            except Exception as e:  # noqa: BLE001
                # Progress reporting must never break the loop.
                log(f"WARNING: progress_tick raised for {node_id}: {e}")
        except asyncio.CancelledError:
            if not receipt_recorded and isinstance(receipt_holder.get("result"), dict):
                summary.setdefault("node_outcomes", []).append(
                    {"node_id": node_id, **receipt_holder["result"], "returned_to_caller": False})
            receipt_holder.clear()
            node_result = None
            raise
        except Exception as e:  # noqa: BLE001
            msg = f"Node update failed for {node_id} ({node_name!r}): {e}"
            summary["errors"].append(msg)
            summary["nodes_skipped"] += 1
            log(f"ERROR: {msg}")

        receipt_holder.clear()
        node_result = None
        if flush_artifacts is not None:
            await flush_artifacts()

    return file_successful_node_updates, False


# @beacon[
#   id=bulk-visible-apply@_build_bulk_visible_root_from_payload,
#   role=ƒ _build_bulk_visible_root_from_payload(data),
#   slice_labels=ra-bulk-visible-apply,ra-carto-jobs,carto-rev-markdown-full,
#   kind=ast,
#   comment=Build bulk-visible-apply root tree from F12+3 payload (visible_tree+root+children) before _collect_bulk_visible_apply_groups walk,
# ]
def _build_bulk_visible_root_from_payload(data: dict[str, Any]) -> dict[str, Any] | None:
    visible_tree = data.get("visible_tree")
    if not isinstance(visible_tree, dict):
        return None
    root = visible_tree.get("root")
    if not isinstance(root, dict):
        return None
    merged = dict(root)
    children = visible_tree.get("children")
    merged["children"] = children if isinstance(children, list) else []
    return merged


# @beacon[
#   id=auto-beacon@_build_synthetic_visible_tree_from_cache-yolc,
#   role=⚡ _build_synthetic_visible_tree_from_cache(root_uuid: str),
#   slice_labels=ra-bulk-visible-apply,ra-workflowy-cache,carto-rev-markdown-full,
#   kind=ast,
#   comment=Awaits the existing cached export on-loop then joins data-only hierarchy construction and root projection off-loop; preserves the post-freshness cache source and GUI-independent bulk intent without passing the client to a worker.,
# ]
async def _build_synthetic_visible_tree_from_cache(
    root_uuid: str,
    *,
    reason: str,
) -> dict[str, Any]:
    """Build a {root, children} "visible_tree" payload from the cached /nodes-export.

    Source-of-truth policy (Dan, 2026-04-30):
      The bulk visible tag apply pipeline historically depended on the
      Chrome extension walking the visible Workflowy DOM and sending the
      result over the WebSocket. That coupled the operation's correctness
      to the user's current scroll/expansion state, which is fragile and
      was a recurring source of bugs ("why didn't it pick up that node?
      Oh, it wasn't expanded").

      This helper replaces the DOM-walked tree with a synthesis built
      directly from the post-refresh /nodes-export cache. The cache is
      the authoritative source of truth for Workflowy state; expansion
      state is irrelevant.

      Caller is responsible for forcing a cache refresh + quiescent
      wait BEFORE invoking this helper, so the synthesized tree is
      guaranteed to reflect the user's most recent edits.

    Args:
        root_uuid: Workflowy UUID of the FILE or FOLDER node whose subtree
            should be synthesized.
        reason: Human-readable label for logging.

    Returns:
        A {"root": {id, name, note}, "children": [...]} payload compatible
        with _build_bulk_visible_root_from_payload, or raises ValueError on
        any structural problem (root not found in cache, empty subtree,
        hierarchy build failure).

    Raises:
        ValueError: when the root UUID isn't in the cache or the subtree
            export returns nothing usable.
    """
    client = get_client()
    export_result = await client.export_nodes(node_id=root_uuid)
    flat_nodes = export_result.get("nodes", []) or []
    if not flat_nodes:
        raise ValueError(
            f"Synthetic visible_tree: empty subtree for root_uuid={root_uuid!r} "
            f"({reason}). Either the UUID is not in the cache or the cache is stale; "
            "caller must force a cache refresh before invoking this helper."
        )

    return await run_carto_cpu("bulk-synthetic-tree", _project_synthetic_visible_tree, flat_nodes, root_uuid, reason)


def _project_synthetic_visible_tree(flat_nodes, root_uuid: str, reason: str) -> dict[str, Any]:
    """C2WSJ4: unchanged hierarchy and root projection, data-only and off-loop."""
    from .client.api_client_nexus import _prepare_carto_file_tree
    hierarchical_tree = _prepare_carto_file_tree(flat_nodes)
    if not hierarchical_tree:
        raise ValueError(
            f"Synthetic visible_tree: hierarchy build returned no roots for "
            f"root_uuid={root_uuid!r} ({reason})."
        )

    # When the export is filtered to a single subtree, the root we asked for
    # should be the only top-level node. If for some reason there are multiple
    # (orphaned descendants?), pick the one matching root_uuid; otherwise take
    # the first.
    root_node: dict[str, Any] | None = None
    for candidate in hierarchical_tree:
        if str(candidate.get("id") or "") == str(root_uuid):
            root_node = candidate
            break
    if root_node is None:
        root_node = hierarchical_tree[0]

    return {
        "root": {
            "id": str(root_node.get("id") or root_uuid),
            "name": str(root_node.get("name") or ""),
            "note": str(root_node.get("note") or ""),
        },
        "children": list(root_node.get("children") or []),
    }


# @beacon[
#   id=bulk-visible-apply@_collect_bulk_visible_apply_groups,
#   role=ƒ _collect_bulk_visible_apply_groups(root_node, nodes_by_id_cache),
#   slice_labels=ra-reconcile,ra-bulk-visible-apply,ra-carto-jobs,ra-workflowy-cache,carto-rev-markdown-full,nexus--tags,beacon-writeback,
#   kind=ast,
#   comment=Walk visible tree and group bulk-apply candidates by enclosing FILE node. NOTE: deliberately NO pre-filter via _visible_node_differs_from_cache (see inline comment); every candidate flows through update_beacon_from_node_<lang>. KEY DIAGNOSTIC FOR F12+3 TIMEOUT: this is where ~533 candidates get fanned out per refresh.,
# ]
def _collect_bulk_visible_apply_groups(
    root_node: dict[str, Any],
    nodes_by_id_cache: dict[str, dict[str, Any]] | None = None,
) -> tuple[dict[str, dict[str, Any]], list[str], int]:
    groups: dict[str, dict[str, Any]] = {}
    warnings: list[str] = []
    skipped_unchanged = 0
    cache_lookup = nodes_by_id_cache or {}

    def walk(node: dict[str, Any], current_file: dict[str, Any] | None) -> None:
        nonlocal skipped_unchanged
        if not isinstance(node, dict):
            return

        node_id = str(node.get("id") or "").strip()
        name = str(node.get("name") or "")
        note = str(node.get("note") or "")
        next_file = current_file

        if _is_file_like_payload_node(node) and node_id:
            next_file = {
                "id": node_id,
                "name": name,
                "note": note,
            }
            groups.setdefault(node_id, {"file_node": next_file, "nodes": []})

        if _is_bulk_visible_apply_candidate(node):
            if not next_file or not next_file.get("id"):
                warnings.append(
                    f"Skipping candidate without enclosing FILE ancestor: node_id={node_id or '<missing>'} name={name!r}",
                )
            else:
                # NOTE: We intentionally do NOT pre-filter via
                # _visible_node_differs_from_cache here. That helper compared
                # Workflowy DOM against the /nodes-export cache, which always
                # match after a cache refresh and therefore caused EVERY
                # candidate to be skipped (the F12+2 "nothing happens" bug).
                #
                # The correct "do I need a write?" check is done inside
                # update_beacon_from_node_<lang>(...) which parses the
                # on-disk source and compares against Workflowy state.
                # We let it be the single source of truth and call it on
                # every candidate (it is idempotent for unchanged nodes).
                file_id = str(next_file.get("id"))
                groups.setdefault(file_id, {"file_node": next_file, "nodes": []})
                groups[file_id]["nodes"].append(
                    {
                        "id": node_id,
                        "name": name,
                        "note": note,
                    }
                )

        for child in node.get("children") or []:
            if isinstance(child, dict):
                walk(child, next_file)

    walk(root_node, None)
    return (
        {fid: data for fid, data in groups.items() if data.get("nodes")},
        warnings,
        skipped_unchanged,
    )


def _bulk_job_snapshot(job):
    """Detach fixed-shape counters; owned diagnostic lists stay quiescent until joined."""
    return {**job, "progress": dict(job.get("progress") or {}),
            "result_summary": dict(job.get("result_summary") or {})}


def _bulk_group_warning_values(warnings, grouping_warnings):
    return [*warnings, *grouping_warnings], [f"WARNING: {message}" for message in grouping_warnings]


# @beacon[
#   id=carto-runtime@bulk-job-artifact,
#   slice_labels=ra-carto-jobs,ra-bulk-visible-apply,ra-logging,
#   kind=ast,
#   comment=Joins owned bulk receipt row item and head batches through the admission-owned writer and formats ordered logs off-loop; each consumed entry is released before the return checkpoint and no previous evidence is read.,
# ]
def _write_bulk_job_artifacts(job_file, log_file, batch):
    from .carto_job_record import record_for
    from .config import is_carto_job_cleared
    if is_carto_job_cleared(job_file):
        batch.clear()
        return
    writer = record_for(job_file, create=False)
    for index in range(len(batch)):
        operation, value = batch[index]
        batch[index] = None  # transfer ownership before a post-work stop
        if operation == "status":
            _write_carto_job_payload(job_file, value)
        elif operation == "nodes":
            writer.append_node_rows(value)
            value.clear()
        elif operation == "file-row":
            row, delta, reflected = value
            writer.append_file_row(row, delta=delta, nodes_reflected=reflected)
            row = None
        elif operation == "in-flight":
            row, progress = value
            writer.set_in_flight(row, progress=progress)
            row = None
        elif operation == "item":
            writer.append_item(*value)
        elif operation == "log":
            _append_carto_job_log(log_file, value)
        elif operation == "result-log":
            _append_carto_job_log(log_file, _bulk_result_log_text(*value))
        else:
            raise ValueError(f"Unknown bulk artifact operation: {operation}")
        value = None
    batch.clear()


# @beacon[
#   id=bulk-visible-apply@_run_carto_bulk_visible_apply_job,
#   role=⚡ _run_carto_bulk_visible_apply_job(job_file: str, root_node, mode: str),
#   slice_labels=ra-reconcile,ra-bulk-visible-apply,ra-carto-jobs,ra-logging,ra-workflowy-cache,carto-rev-markdown-full,nexus--tags,beacon-writeback,
#   kind=ast,
#   comment=Runs frozen groups through one admission-owned append-only writer: each returned batch drains receipts and errors before its head write; only current-group rows and deltas remain in memory and whole-file tallies preserve cross-group rejection and stopped work without reading earlier evidence.,
# ]
async def _run_carto_bulk_visible_apply_job(
    job_file: str, root_node: dict[str, Any], mode: str, *,
    prepared_groups: Mapping[str, Any] | None = None,
    grouping_warnings=(), skipped_unchanged=0,
    held_grant=None,
) -> None:
    """Stream complete bulk history with flat batch work and current-group rows.

    The inner loop's counters, callbacks and refresh trigger are unchanged.
    Drain its transient receipts at the existing artifact join (including the
    holder on unwind). Later finalizations contain only their own sets, unsets
    and list extends; the accumulator supplies sticky changed and whole-file
    receipt tallies, never an earlier row or a read of the sidecar.
    """
    from .carto_job_record import record_for, apply_bulk_receipts, canonical_carto_file
    client = get_client()
    context = current_carto_job_context()
    job = await run_carto_cpu("bulk-artifact:read", _read_carto_job_payload, job_file) or {}
    log_file = job.get("logs_path")
    writer = record_for(job_file)

    pending_artifacts = []
    file_outcomes = {}
    file_order = {}
    finalized = set()
    deltas = {}
    reflected = {}
    group_errors = []
    last_error = None
    active_file = None

    def group_row(path, *, placeholder=None):
        if path not in file_outcomes:
            file_order.setdefault(path, len(file_order))
            if path in finalized:
                file_outcomes[path] = {"file": path}
                deltas[path] = {"unset": [], "extend": {}}
            else:
                file_outcomes[path] = placeholder if placeholder is not None else {
                    "file": path, "status": "completed", "changed": False,
                    "findings": [], "warnings": [], "events": []}
            reflected[path] = writer.accumulator.reflected_nodes(path)
        return file_outcomes[path]

    def row_changed(row):
        key = writer.accumulator._keys.get(("files", canonical_carto_file(row["file"])))
        return bool(row.get("changed") or (key is not None and key.changed))

    def sync_active_file():
        if active_file is not None:
            for path, row in file_outcomes.items():
                tally = writer.accumulator.receipt_tally(path)
                if path in finalized and len(row) == 1 and tally["count"] == reflected[path] and not group_errors:
                    continue  # a repeated-file stop before any work changes nothing
                if "changed" not in row:
                    row["changed"] = row_changed(row)
                row.update(apply_bulk_receipts(row, tally, reflected=reflected[path], node_outcomes=None))
                reflected[path] = tally["count"]
            if group_errors:
                active_file.update(status="failed", success=False, error=group_errors[-1], node_errors=list(group_errors))

    def save_bulk_batch(path, logs, batch, state):
        # Only this batch's evidence is consumed; the terminal exit uses the
        # same writer summary, with no aggregate of run rows here.
        _write_bulk_job_artifacts(path, logs, batch)
        _write_carto_job_payload(path, state)
        current = record_for(path, create=False)
        summary = current.summary(cancelled=state["status"] == "cancelling")
        if not current._structured:
            stopped = state["status"] == "cancelling"
            summary.update(current.accumulator.outcome(cancelled=stopped))
            summary.update(success=not stopped and not last_error,
                           status="failed" if stopped or last_error else "completed", cancelled=stopped)
            current.update_head(result_summary=summary)
        return summary

    async def record_file_failure(row, error):
        row.update(status="failed", success=False, error=str(error))
        warning = {"type": "file_refresh_failed", "error": str(error)}
        if row["file"] in deltas and "warnings" not in row:
            deltas[row["file"]]["extend"].setdefault("warnings", []).append(warning)
        else:
            row.setdefault("warnings", []).append(warning)
        chain = []
        current = error
        from .carto_job_governance import GovernanceError
        while current is not None and all(current is not item for item in chain):
            chain.append(current)
            if (isinstance(current, GovernanceError) or hasattr(current, "refusal_extra")
                    or getattr(current, "code", None) in {
                        "mutation_region_error", "mutation_serialization_conflict", "mutation_serialization_timeout",
                        "ACCOUNT_WRITE_BLOCKED", "WRITE_GOVERNOR_UNAVAILABLE", "WRITE_GOVERNOR_DEFERRED",
                        "WRITE_SLOT_BUSY_TIMEOUT", "AUTH_ERROR", "RATE_LIMIT_ERROR"}):
                row = None
                await persist(finish=True)
                raise current
            current = current.__cause__
        latch = context.job_control.cpu_failure if context is not None else None
        if latch is not None:
            phase, failure = latch
            if (isinstance(failure, Exception) and any(failure is item for item in chain)
                    and phase in {"file:source", "file:plan"}):
                row["local_cpu_failure"] = {"file": row["file"], "phase": phase,
                    "exception_type": type(failure).__name__, "message": str(failure)}

    async def observe_only(row, path):
        from .client.api_client_nexus import _prepare_carto_source_file
        try:
            try:
                parsed = await run_carto_cpu("file:source", _prepare_carto_source_file,
                    path, os.path.dirname(path), dry_run=True, claimed=None)
                row.update({k: v for k, v in parsed["prepared"].items()
                    if k not in {"map", "snapshot", "analysis_inputs", "changed", "status"}})
                if parsed["prepared"].get("status") == "failed":
                    row.update(status="failed", success=False)
            except Exception as error:  # noqa: BLE001
                await record_file_failure(row, error)
            row["final_observation"] = True
        finally:
            row = parsed = None

    def queue_status():
        state = _bulk_job_snapshot(job)
        state["result_summary"] = {key: value for key, value in result_summary.items()
                                   if key not in {"errors", "warnings", "node_outcomes"}}
        pending_artifacts.append(("status", state))

    def queue_log(message):
        pending_artifacts.append(("log", message))

    def queue_result(node_id, node_result):
        pending_artifacts.append(("result-log", (node_id, node_result)))

    async def flush_artifacts():
        nonlocal pending_artifacts, last_error
        receipts, result_summary["node_outcomes"] = result_summary["node_outcomes"], []
        nodes = []
        for receipt in receipts:
            target = receipt.get("source_path") or receipt.get("file_path")
            path = os.path.realpath(target) if target else active_file["file"]
            group_row(path)
            nodes.append({"file": path, "row": receipt})
        receipt = None
        receipts.clear()
        batch_errors, errors[:] = list(errors), []
        prefix = [("nodes", nodes)] if nodes else []
        for message in batch_errors:
            last_error = message
            if active_file is not None:
                group_errors.append(message)
            prefix.extend([("item", ("errors", message)),
                           ("item", ("run_events", {"type": "bulk_error", "error": message}))])
        pending_artifacts = prefix + pending_artifacts
        if pending_artifacts:
            batch, pending_artifacts = pending_artifacts, []
            await run_carto_cpu("bulk-artifact:batch", _write_bulk_job_artifacts,
                                job_file, log_file, batch)

    async def persist(*, finish=False):
        nonlocal pending_artifacts, file_outcomes, active_file, deltas, reflected
        stop = None
        try:
            await flush_artifacts()
        except asyncio.CancelledError as error:
            if not finish:
                raise
            # That exact worker already landed its receipts. Complete this
            # group's row handoff before re-raising the same observed stop.
            stop = error
        if finish:
            sync_active_file()
            # Detach loop references before the joined write's checkpoint.
            for path in sorted(file_outcomes, key=file_order.__getitem__):
                if path not in finalized or len(file_outcomes[path]) > 1:
                    pending_artifacts.append(("file-row", (file_outcomes.pop(path), deltas.get(path), reflected[path])))
                    finalized.add(path)
            file_outcomes.clear()
            active_file = None
            deltas, reflected = {}, {}
        batch, pending_artifacts = pending_artifacts, []
        state = _bulk_job_snapshot(job)
        state["result_summary"] = {key: value for key, value in result_summary.items()
                                   if key not in {"errors", "warnings", "node_outcomes"}}
        try:
            summary = await run_carto_cpu("bulk-artifact:summary", save_bulk_batch,
                job_file, log_file, batch, state)
        except asyncio.CancelledError as error:
            # The owned batch has been consumed before its return checkpoint.
            raise stop if stop is not None else error
        result_summary.update({key: value for key, value in summary.items()
                               if key not in {"errors", "warnings", "node_outcomes"}})
        if stop is not None:
            raise stop

    async def append(message):
        queue_log(message)
        await flush_artifacts()

    result_summary = job.setdefault("result_summary", {})
    errors = result_summary.setdefault("errors", [])
    result_summary.pop("warnings", None)
    result_summary.setdefault("files_refreshed", 0)
    result_summary.setdefault("files_skipped", 0)
    result_summary.setdefault("node_updates", 0)
    result_summary.setdefault("nodes_skipped", 0)
    # nodes_skipped_in_sync counts candidates filtered by
    # _node_name_tags_match_beacon_block_in_note (Bug #2 optimization).
    # Distinct from "nodes_skipped" which counts errors/missing-id cases.
    result_summary.setdefault("nodes_skipped_in_sync", 0)
    result_summary.setdefault("workflowy_nodes_updated", 0)
    result_summary.setdefault("node_outcomes", [])
    result_summary.setdefault("nodes_satisfied", 0)

    progress = job.setdefault("progress", {})
    progress.setdefault("total_files", 0)
    progress.setdefault("completed_files", 0)
    progress.setdefault("current_file", None)
    progress.setdefault("current_phase", "waiting")
    progress.setdefault("nodes_created", 0)
    progress.setdefault("nodes_updated", 0)
    progress.setdefault("nodes_moved", 0)
    progress.setdefault("nodes_deleted", 0)

    successful_file_refreshes = 0
    restart_stopped = False

    def restart_stop_requested() -> bool:
        nonlocal restart_stopped
        if context is not None:
            context.job_control.checkpoint("bulk-file-group", restart_boundary=True)
        state = _inprocess_restart_stops.get(asyncio.current_task())
        if state is not None and state["restart_id"] is not None:
            state["observed"] = True
            restart_stopped = True
        return restart_stopped

    try:
        progress["current_phase"] = "waiting"
        job["status"] = "waiting"
        job["updated_at"] = datetime.utcnow().isoformat()
        await persist()
        await append(f"Waiting to start bulk visible apply (mode={mode})")

        await _await_nodes_export_cache_quiescent(
            f"bulk visible apply preflight for {job.get('root_uuid')}",
        )
        # Region claim admission replaces the retired CARTO-global quiescence gate.
        await _await_nodes_export_cache_quiescent(
            f"bulk visible apply post-carto preflight for {job.get('root_uuid')}",
        )

        if _carto_job_cancel_requested(job_file) or restart_stop_requested():
            job["status"] = "cancelling"
            progress["current_phase"] = "cancelling"
            job["cache_refresh_required"] = False
            job["updated_at"] = datetime.utcnow().isoformat()
            await persist()
            await append("Cancellation observed before batch execution; stopping.")
            return

        from .coherence.operation_cache import current_operation_cache
        snapshot = current_operation_cache(required=False)
        nodes_by_id_cache = snapshot.nodes_by_id if snapshot is not None else {}
        if prepared_groups is None:
            grouped_files, grouping_warnings, skipped_unchanged = await run_carto_cpu(
                "bulk-collection", _collect_bulk_visible_apply_groups, root_node,
                nodes_by_id_cache=nodes_by_id_cache,
            )
        else:
            grouped_files = prepared_groups
        if grouping_warnings:
            for message in grouping_warnings:
                pending_artifacts.append(("item", ("run_warnings", message)))
                await append(f"WARNING: {message}")
        if skipped_unchanged:
            result_summary["nodes_skipped"] += int(skipped_unchanged)
            result_summary["nodes_unchanged"] = int(skipped_unchanged)
            await append(
                f"Skipping {skipped_unchanged} unchanged visible node(s) after semantic compare.",
            )

        file_items = await run_carto_cpu(
            "bulk-group-order", lambda groups: sorted(
                groups.items(), key=lambda kv: str(kv[1].get("file_node", {}).get("name") or kv[0]).lower(),
            ), grouped_files,
        )

        progress["total_files"] = len(file_items)
        progress["completed_files"] = 0
        progress["current_phase"] = "running"
        job["status"] = "running"
        job["updated_at"] = datetime.utcnow().isoformat()
        await persist()
        await append(f"Starting bulk visible apply across {len(file_items)} file(s).")
        await _refresh_carto_job_tracker_once()

        if not file_items:
            job["status"] = "completed"
            job["cache_refresh_required"] = False
            progress["current_phase"] = "done"
            result_summary["message"] = "No eligible visible AST/beacon nodes found."
            job["updated_at"] = datetime.utcnow().isoformat()
            await persist()
            await append("No eligible visible AST/beacon nodes found; nothing to do.")
            return

        processed_files = 0
        for file_id, file_group in file_items:
            if _carto_job_cancel_requested(job_file) or restart_stop_requested():
                job["status"] = "cancelling"
                progress["current_phase"] = "cancelling"
                await append("Cancellation requested; stopping before next file refresh.")
                break

            file_node = file_group.get("file_node") or {}
            file_name = str(file_node.get("name") or file_id)
            candidate_nodes = file_group.get("nodes") or []
            from .client.api_client_nexus import resolve_cartographer_path_from_node
            resolved = await run_carto_cpu("bulk:file-path", resolve_cartographer_path_from_node,
                node_id=str(file_id), nodes_by_id=nodes_by_id_cache)
            source_path = str(resolved.get("abs_path") or "")
            canonical = os.path.realpath(source_path) if source_path else str(file_id)
            group_errors = []
            active_file = group_row(canonical, placeholder={"file": canonical, "file_node_id": str(file_id),
                "status": "failed", "changed": False, "findings": [], "warnings": [], "events": [],
                "error": "File attempt interrupted before completion"})
            if context is not None:
                context.job_control.may_have_workflowy_effects = True

            progress["current_file"] = file_id
            progress["current_phase"] = "update-beacons"
            job["updated_at"] = datetime.utcnow().isoformat()
            if canonical not in finalized:
                pending_artifacts.append(("in-flight", ({"file": canonical, "file_node_id": str(file_id)}, dict(progress))))
            sync_active_file()  # preserve the base row's key insertion order, without a row line yet
            await persist()
            await append(
                f"Updating {len(candidate_nodes)} visible node(s) for file {file_name} ({file_id}).",
            )

            # Per-candidate inner loop — delegated to the single-source-of-truth
            # helper _bulk_apply_per_file_inner_loop. server.py and
            # markdown_generate_pipeline.py both route through that helper so
            # any future change to the inner loop touches exactly ONE place
            # (avoids the May 2026 duplicate-codepath gotcha that hid Bug #2's
            # fix from the F12+3 path).
            # @beacon[
            #   id=auto-beacon@_run_carto_bulk_visible_apply_job._server_progress_tick-kdd0,
            #   role=_run_carto_bulk_visible_apply_job._server_progress_tick,
            #   slice_labels=ra-bulk-visible-apply,carto-rev-markdown-full,
            #   kind=ast,
            #   comment=Updates loop-owned successful counters then queues their detached status value after the original log callback; the candidate boundary joins the ordered artifact batch before another item.,
            # ]
            def _server_progress_tick() -> None:
                progress["nodes_updated"] = result_summary["node_updates"]
                job["updated_at"] = datetime.utcnow().isoformat()
                queue_status()

            file_successful_node_updates, was_cancelled = await _bulk_apply_per_file_inner_loop(
                client=client,
                candidate_nodes=candidate_nodes,
                file_name=file_name,
                summary=result_summary,
                cancel_check=lambda: _carto_job_cancel_requested(job_file),
                log=queue_log,
                progress_tick=_server_progress_tick,
                flush_artifacts=flush_artifacts,
                log_result=queue_result,
            )
            await flush_artifacts()
            if not was_cancelled or file_successful_node_updates > 0:
                active_file.update(status="completed", success=True)
                active_file.pop("error", None)
                if canonical in deltas:
                    deltas[canonical]["unset"].append("error")
            sync_active_file()

            if was_cancelled:
                job["status"] = "cancelling"
                progress["current_phase"] = "cancelling"
                await append("Cancellation requested during node update pass.")

            if _carto_job_cancel_requested(job_file):
                await persist(finish=True)
                break

            if file_successful_node_updates > 0:
                progress["current_phase"] = "refresh-file"
                job["updated_at"] = datetime.utcnow().isoformat()
                await persist()
                await append(f"Refreshing Workflowy FILE node once for {file_name} ({file_id}).")

                try:
                    refresh_result = await client.refresh_file_node_beacons(
                        file_node_id=file_id,
                        dry_run=False,
                        carto_claim_id=str(job.get("claim_id") or ""),
                        held_grant=held_grant,
                    )
                    refresh_data = dict(refresh_result or {})
                    active_file.update({k: v for k, v in refresh_data.items()
                                        if k not in {"changed", "file", "node_outcomes", "nodes_satisfied"}})
                    active_file["refresh_outcome"] = refresh_data
                    active_file["changed"] = bool(row_changed(active_file) or any(
                        r.get("success") and r.get("changed") for r in refresh_data.get("repair_outcomes") or []))
                    sync_active_file()
                    if isinstance(refresh_result, dict) and not refresh_result.get("success", True):
                        raise RuntimeError(
                            refresh_result.get("error")
                            or "refresh_file_node_beacons returned failure"
                        )
                    successful_file_refreshes += 1
                    result_summary["files_refreshed"] = successful_file_refreshes
                    result_summary["workflowy_nodes_updated"] += int(
                        (refresh_result or {}).get("nodes_updated", 0) or 0
                    )
                    progress["nodes_created"] += int(
                        (refresh_result or {}).get("nodes_created", 0) or 0
                    )
                    progress["nodes_moved"] += int(
                        (refresh_result or {}).get("nodes_moved", 0) or 0
                    )
                    progress["nodes_deleted"] += int(
                        (refresh_result or {}).get("nodes_deleted", 0) or 0
                    )
                    await append(
                        f"Refreshed FILE node {file_name}: +{int((refresh_result or {}).get('nodes_created', 0) or 0)} ~{int((refresh_result or {}).get('nodes_updated', 0) or 0)} ↻{int((refresh_result or {}).get('nodes_moved', 0) or 0)} -{int((refresh_result or {}).get('nodes_deleted', 0) or 0)}",
                    )
                    refresh_result = refresh_data = None
                except Exception as e:  # noqa: BLE001
                    msg = f"FILE refresh failed for {file_name} ({file_id}): {e}"
                    errors.append(msg)
                    await record_file_failure(active_file, e)
                    await append(f"ERROR: {msg}")
                finally:
                    refresh_result = refresh_data = None
            else:
                result_summary["files_skipped"] += 1
                if source_path:
                    await observe_only(active_file, source_path)
                await append(f"No successful node updates for {file_name}; skipping FILE refresh.")

            # Frozen GUI grouping may include an actual writer target in another
            # FILE. Preserve grouping/refresh triggers, but observe each physical
            # touched file once rather than attributing its bytes to a neighbour.
            for path in list(file_outcomes):
                other = file_outcomes[path]
                if path != canonical and writer.accumulator.receipt_tally(path)["count"] and not other.get("final_observation"):
                    await observe_only(other, path)
            other = None
            active_file["final_observation"] = True

            # Per-file summary line so the GLIMPSE widget log makes the
            # in-sync filter behavior visible.
            await append(
                f"File summary for {file_name} ({file_id}): "
                f"updated={file_successful_node_updates}, "
                f"skipped_in_sync={result_summary['nodes_skipped_in_sync']} (cumulative).",
            )

            processed_files += 1
            progress["completed_files"] = processed_files
            progress["current_file"] = None
            job["updated_at"] = datetime.utcnow().isoformat()
            await persist(finish=True)

        if not _carto_job_cancel_requested(job_file) and not restart_stopped:
            progress["current_phase"] = "done"
            progress["current_file"] = None
            job["cache_refresh_required"] = (context.job_control.may_have_workflowy_effects
                                             if context is not None else successful_file_refreshes > 0)
            await persist()
            job["status"] = result_summary["status"]
            job["error"] = last_error if job["status"] == "failed" else None

        job["updated_at"] = datetime.utcnow().isoformat()
        await persist()
    except asyncio.CancelledError:
        # A safe group-head checkpoint was observed, never an interrupted
        # send. Retain actual counters and the cancelling presentation until
        # the common exit publishes its terminal outcome inside this hold.
        if context is not None and (context.job_control.user_observed or context.job_control.restart_state["observed"]):
            job["status"] = "cancelling"
            progress["current_phase"] = "cancelling"
            job["cache_refresh_required"] = context.job_control.may_have_workflowy_effects
        await persist(finish=True)
        raise
    except BaseException as e:  # retain every receipt/row even on an escape
        msg = f"Unhandled bulk visible apply failure: {e}"
        errors.append(msg)
        job["status"] = "failed"
        job["error"] = str(e)
        progress["current_phase"] = "failed"
        job["updated_at"] = datetime.utcnow().isoformat()
        await persist(finish=True)
        await append(f"ERROR: {msg}")
        raise
    finally:
        other = refresh_result = refresh_data = None
        await flush_artifacts()
        await _refresh_carto_job_tracker_once()


# @beacon[
#   id=bulk-visible-apply@_start_carto_bulk_visible_apply_job,
#   role=⚡ _start_carto_bulk_visible_apply_job(),
#   slice_labels=ra-reconcile,ra-bulk-visible-apply,ra-carto-jobs,ra-logging,carto-rev-markdown-full,nexus--tags,beacon-writeback,
#   kind=ast,
#   comment=Freezes visible membership and admits one daemon task with its sole summary-head/2 writer; complete per-file rows and node history stream into that job's evidence folder while the complete FILE union exact patch proof and held grant stay unchanged.,
# ]
async def _start_carto_bulk_visible_apply_job(
    *,
    root_uuid: str,
    mode: str,
    visible_tree_payload: dict[str, Any],
    selected_snapshot: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Admit frozen bulk intent and its /2 writer; scheduling/holds stay unchanged."""
    from uuid import uuid4
    from .carto_job_runtime import _freeze_job_payload

    # S04 §7.2: hard-stop admission BEFORE any job artifact/admission work.
    _coherence_refusal = await _require_carto_launch_admission(
        f"carto.bulk_apply_launch:{mode}"
    )
    if _coherence_refusal is not None:
        return _coherence_refusal
    if mode not in {"file", "folder"}:
        return {"success": False, "error": f"Invalid bulk-apply root kind: {mode!r}"}
    root_node = await run_carto_cpu(
        "bulk-visible-tree", _build_bulk_visible_root_from_payload,
        {"visible_tree": visible_tree_payload},
    )
    if not isinstance(root_node, dict):
        return {"success": False, "error": "Missing or malformed visible_tree payload."}
    try:
        account_scope_id = _carto_account_scope()
        dedupe_key = derive_dedupe_key(
            account_scope_id=account_scope_id,
            job_type="CARTO_BULK_APPLY",
            mode="all",
            root_uuid=str(root_uuid),
        )
        if selected_snapshot is None:
            early = await negative_exact_intent_gate(
                dedupe_key=dedupe_key,
                jobs_root=_governance_jobs_root(),
            )
            if early is not None:
                return early
            selection = await _carto_select_snapshot(
                reason=f"standalone F12+2 freshness for {root_uuid}",
                source="bulk_apply_visible_nodes",
            )
        else:
            selection = dict(selected_snapshot)
        grouped_files, grouping_warnings, skipped_unchanged = await run_carto_cpu(
            "bulk-collection", _collect_bulk_visible_apply_groups, root_node,
            nodes_by_id_cache=selection.get("cache_by_id") or {},
        )
        frozen_tree = await run_carto_cpu("bulk-freeze-tree", _freeze_job_payload, root_node)
        frozen_groups = await run_carto_cpu("bulk-freeze-groups", _freeze_job_payload, grouped_files)
        footprint = _carto_footprint_from_selection(
            root_uuid=str(root_uuid),
            mode=mode,
            selection=selection,
            source_regime="standard",
        )
        jobs = Path(_get_carto_jobs_base_dir())
        jobs.mkdir(parents=True, exist_ok=True)
        now = datetime.utcnow()
        job_id = f"carto-bulk-apply-all-{uuid4().hex[:8]}"
        prefix = now.strftime("%Y%m%d-%H%M%S")
        job_file = jobs / f"{prefix}_{job_id}.json"
        log_file = jobs / f"{prefix}_{job_id}.log"
        payload = {
            "id": job_id,
            "type": "CARTO_BULK_APPLY",
            "mode": "all",
            "root_kind": mode,
            "root_uuid": str(root_uuid),
            "detached": False,
            "execution_model": "daemon_task",
            "execution_owner": "launcher",
            "created_at": now.isoformat(),
            "updated_at": now.isoformat(),
            "cache_refresh_required": True,
            "freshness_disposition": selection.get("freshness_disposition"),
            "snapshot_path": selection.get("snapshot_path"),
            "progress": {
                "total_files": 0,
                "completed_files": 0,
                "current_file": None,
                "current_phase": "preparing",
                "nodes_created": 0,
                "nodes_updated": 0,
                "nodes_moved": 0,
                "nodes_deleted": 0,
            },
            "result_summary": {
                "files_refreshed": 0,
                "files_skipped": 0,
                "node_updates": 0,
                "nodes_skipped": 0,
                "workflowy_nodes_updated": 0,
                "warnings": [],
                "errors": [],
                "nodes_satisfied": 0,
            },
            "error": None,
            "logs_path": str(log_file),
        }
        admission = await admit_carto_job(
            job_file=job_file,
            job_payload=payload,
            job_type="CARTO_BULK_APPLY",
            dedupe_key=dedupe_key,
            account_scope_id=account_scope_id,
            footprint=footprint,
            launcher="gui",
            parent_job_id=None,
            prepared=True,
            jobs_root=jobs,
            # Head-currency gate + held-node-lock consult view +
            # head-stale revalidation hook, from the pinned snapshot.
            **_carto_admission_coherence_kwargs(
                root_uuid=str(root_uuid),
                mode=mode,
                source_regime="standard",
                selection=selection,
            ),
        )
        if admission.get("deduplicated"):
            return admission
        claim = admission["claim"]
        spec = CartoJobSpec(
            job_id=job_id, job_file=job_file, log_file=log_file,
            job_type="CARTO_BULK_APPLY", mode=mode, root_uuid=str(root_uuid),
            claim_id=str(claim["claim_id"]), claim_path=admission["claim_path"],
            account_scope_id=account_scope_id, visible_tree_payload=frozen_tree,
            bulk_groups=frozen_groups,
            preparation_payload={"grouping_warnings": grouping_warnings, "skipped_unchanged": skipped_unchanged},
            selection_metadata={key: value for key, value in selection.items() if key not in {"cache_by_id", "nodes"}},
            selection_nodes_by_id=selection.get("cache_by_id"),
        )
        scheduled = await _schedule_carto_job(spec)
        if not scheduled.get("success"):
            return scheduled
        return {
            "success": True,
            "job_id": job_id,
            "kind": "CARTO_BULK_APPLY",
            "mode": "all",
            "root_uuid": str(root_uuid),
            "carto_job_file": str(job_file),
            "log_file": str(log_file),
            "freshness_disposition": selection.get("freshness_disposition"),
            "message": "Governed bulk beacon/tag apply queued.",
        }
    except AdmissionRefusal as exc:
        return exc.to_result()
    except Exception as exc:  # noqa: BLE001
        return {"success": False, "error": str(exc)}


# @beacon[
#   id=auto-beacon@mcp_job_status-lu5h,
#   role=⚡ mcp_job_status(job_id),
#   slice_labels=ra-reconcile,ra-logging,ra-carto-jobs,nexus--mcp-api,
#   kind=ast,
#   comment=Lists cached heads with bounded annotations or reads only one job off-loop; summary is the default and explicit evidence views page under 512 KiB. Only its own proof is captured, including failed terminal writes.,
# ]
async def _system_job_status_impl(
    job_id: str | None = None, *, status: str | None = None,
    kind: str | None = None, limit: int | None = None,
    view=None, files=None, file=None, files_offset=None, files_limit=None, offset=None, slice_offset=None,
) -> dict:
    """Read a bounded annotated inventory, or one summary / complete paged detail.

    One-job lookup never scans record contents. Explicit detail, files and file
    hydrate only that job off-loop; live proof evidence still outranks disk.
    Unknown view values warn and serve summary rather than refusing a read.
    """
    from .job_status_view import normalize_job_status_options, normalize_job_detail_options
    options = dict(view=view, files=files, file=file, files_offset=files_offset,
                   files_limit=files_limit, offset=offset, slice_offset=slice_offset)
    status, kind, limit = normalize_job_status_options(job_id, status=status, kind=kind, limit=limit, **options)
    options = normalize_job_detail_options(job_id, **options)
    # Validation precedes directory acquisition/scanning.
    carto_jobs_base = _get_carto_jobs_base_dir()

    # Default list is active-only; the shared scanner still supplies the same
    # authoritative records used by detail/widget paths. Never rewrite history.
    if job_id is None:
        in_memory_jobs = [
            MappingProxyType({**{field: job[field] for field in (
                "kind", "status", "mode", "root_uuid", "created_at", "started_at", "finished_at", "error_kind",
            ) if field in job}, "job_id": job.get("job_id") or key, "detached": False})
            for key, job in _jobs.items()
        ]
        return await run_carto_cpu("job-status-list", _project_carto_job_status,
            in_memory_jobs, await _scan_carto_job_files_async(carto_jobs_base),
            status=status, kind=kind, limit=limit, options=options,
        )

    # Check in-memory first
    job = _jobs.get(job_id)
    if job:
        # Do not expose internal task handle
        snapshot = MappingProxyType({k: v for k, v in job.items() if k not in ("payload", "_task")})
        return await run_carto_cpu("job-status-memory", _project_carto_job_status,
                                  (snapshot,), (), job_id=job_id, options=options)

    # Check CARTO_REFRESH jobs (JSON-based)
    # Capture before the scan's first await: its own loop projection observes
    # the same turn. Full proofs stay available to detail/cancel, not list work.
    detail_overlay = _carto_live_job_projection().get(job_id)
    return await run_carto_cpu("job-status-detail", _project_carto_job_status,
        (), (), job_id=job_id, detail_overlay=detail_overlay, base_dir=carto_jobs_base, options=options)


# @beacon[
#   id=auto-beacon@mcp_cancel_job-7wb6,
#   role=⚡ mcp_cancel_job(job_id: str),
#   slice_labels=ra-carto-jobs,
#   kind=ast,
#   comment=Registered task/control is stop authority even with missing or forged JSON. Historical/startup-abandoned rows are not live tasks; pending cancellation is explicit and no PID is signalled.,
# ]
async def _system_job_cancel_impl(
    job_id: str,
    *,
    requested_by: str = "system.job.cancel",
) -> dict:
    """Registered task first; any disk-only row is history, never a live PID."""

    base_dir = Path(_get_carto_jobs_base_dir())
    task, control = _carto_inprocess_tasks.get(job_id), _carto_job_controls.get(job_id)
    if task is not None and control is not None and control.presentation:
        carto_job = _carto_live_job_projection()[job_id]
        job_path = Path(carto_job["path"])
        result = await cancel_carto_job(
            job_path, requested_by=requested_by, jobs_root=base_dir,
            task_cancel=control.request_user_cancel, task_done=task.done, task_job=carto_job,
            diagnostic=lambda message: log_event(message, "CARTO"),
        )
        return {**result, "kind": carto_job["type"], "carto_job_file": str(job_path)}
    terminal = _carto_final_obligations.get(job_id)
    if terminal is not None and terminal.terminal_proof is not None:
        status_record = terminal.terminal_proof.get("job_status") or {}
        return {"success": True, "job_id": job_id, "outcome": "already_terminal",
                "kind": str(status_record.get("type") or "CARTO_REFRESH"), "carto_job_file": terminal.path}
    startup = _carto_startup_failed_jobs.get(job_id)
    candidate = ((Path(startup["path"]), startup) if startup is not None else
                 await run_carto_cpu("cancel-job-lookup", _find_carto_job_on_disk, base_dir, job_id))
    if candidate is not None:
        # There is no registered task to stop or resume. Startup memory wins
        # even if its durable mark failed; history is not a process to signal.
        job_path, carto_job = candidate
        return {"success": True, "job_id": job_id, "outcome": "already_terminal",
                "kind": str(carto_job.get("type") or "CARTO_REFRESH"), "carto_job_file": str(job_path)}

    # Non-CARTO in-memory jobs retain their existing asyncio cancellation
    # behavior; they own no region hold or cancellation authority.
    job = _jobs.get(job_id)
    if job is not None:
        task = job.get("_task")
        if task is None:
            return {"success": False, "error": "Job has no associated task (cannot cancel)."}
        if task.done():
            return {"success": False, "error": "Job already completed."}
        job["status"] = "cancelling"
        task.cancel()
        return {"success": True, "job_id": job_id, "status": "cancelling"}

    return {"success": False, "error": f"Unknown job_id: {job_id}"}


def _find_carto_job_on_disk(base_dir, job_id):
    """Filename-first history lookup, then the shared cache's id index; no scan."""
    from .carto_job_record import find_carto_job_record_path, read_carto_job_record_cached
    path = find_carto_job_record_path(base_dir, job_id)
    if path is not None:
        try:
            job = read_carto_job_record_cached(path)
            if (str(job.get("type") or "").startswith("CARTO_") and str(job.get("id") or path.stem) == job_id):
                return path, job
        except Exception:
            pass
    return None


# @beacon-close[
#   id=svcv1@websocket-f12-infra,
# ]
# SPLIT BOUNDARY:
# This zone mixes standard CRUD wrappers with Dan-specific secret-code enforcement,
# deprecated aliases, and training-oriented warning wrappers. Public Core v1 should
# keep the modern CRUD/tool wrappers while removing or isolating the warning layer.
# @beacon[
#   id=svcv1@compat-warning-layer,
#   role=boundary split: dan-specific warning compatibility layer interleaved with basic workflowy wrappers,
#   slice_labels=nexus-portability,nexus-split-boundary,
#   kind=span,
#   show_span=false,
# ]
# 🔐 SECRET CODE VALIDATION - Brute Force Agent Training Override
def validate_secret_code(provided_code: str | None, function_name: str) -> tuple[bool, str | None]:
    """Validate secret code for WARNING functions.
    
    This is the nuclear option - forces agents to ask Dan explicitly.
    
    Returns:
        (is_valid, error_message)
    """
    import os
    import secrets
    
    # Derive project_root dynamically from this file's location
    server_dir = os.path.dirname(os.path.abspath(__file__))
    mcp_servers_dir = os.path.dirname(server_dir)
    project_root = os.path.dirname(mcp_servers_dir)
    SECRET_FILE = os.path.join(project_root, "glimpse_etch.txt")
    
    # Generate code if file doesn't exist
    if not os.path.exists(SECRET_FILE):
        code = secrets.token_hex(8)  # 16-character hex code
        with open(SECRET_FILE, 'w') as f:
            f.write(code)
    
    # Read current code
    with open(SECRET_FILE, 'r') as f:
        valid_code = f.read().strip()
    
    # Check if code provided and matches
    if provided_code and provided_code.strip() == valid_code:
        return (True, None)  # Valid - allow function call
    
    # Invalid or missing - return error
    error_msg = f"""⚠️ EXPLICIT PERMISSION REQUIRED

You called: {function_name}

This is a WARNING function. You should be using GLIMPSE or ETCH instead.

🛑 YOU BELIEVE YOU'RE AN EXCEPTION CASE.

🚨 YOU ARE NOT THE EXCEPTION.

✅ USE INSTEAD:
  - For reading node trees: workflowy_glimpse(node_id="...")
  - For creating nodes: workflowy_etch(parent_id="...", nodes=[...])

⚙️ IF YOU TRULY NEED THIS FUNCTION:

1. Ask Dan: "May I have permission to call {function_name}?"
2. Dan will check a secret file for the authorization code
3. If Dan grants permission, he'll provide the code
4. Call the SAME function again with the EXACT SAME parameters you used the first time, but add: secret_code="[code-from-Dan]" (do not change anything else).

   Example (arguments object): {{ "name": "...", "parent_id": "...", "note": "...", "secret_code": "[code-from-Dan]" }}

🚫 IF DAN SAYS NO:
- You are NOT the exception
- Your training misled you  
- Use GLIMPSE or ETCH as instructed
- Do NOT call this function again

📚 Break free from your training - build the GLIMPSE/ETCH habit!
"""
    
    return (False, error_msg)


