# Tool: Create Single Node (With Warning)
# UNREGISTERED (open-source cleanup): removed the ugly __WARNING__ tool surface.
# Source kept as a stub for reference; decorator intentionally removed.
# @beacon[
#   id=server@create_node,
#   role=⚡ create_node(name: str, parent_id, note, layout_mode, position, _completed: bool, secret_code),
#   slice_labels=nexus-core-v1,node-ops,
#   kind=ast,
# ]
async def create_node(
    name: str,
    parent_id: str | None = None,
    note: str | None = None,
    layout_mode: Literal["bullets", "todo", "h1", "h2", "h3"] | None = None,
    position: Literal["top", "bottom"] = "bottom",
    _completed: bool = False,
    secret_code: str | None = None,
) -> dict:
    """Create a SINGLE node in WorkFlowy.
    
    ⚠️ WARNING: Prefer workflowy_etch (ETCH) for creating 2+ nodes.
    
    This tool is ONLY for:
    - Adding one VYRTHEX to existing log (real-time work)
    - One quick update to a known node
    - Live work in progress

    Args:
        name: The text content of the node
        parent_id: ID of the parent node (optional)
        note: Additional note/description for the node
        layout_mode: Layout mode for the node (bullets, todo, h1, h2, h3) (optional)
        position: Where to place the new node - "bottom" (default) or "top"
        _completed: Whether the node should be marked as completed (not used)
        secret_code: Authorization code from Dan (required for WARNING functions)

    Returns:
        Dictionary with node data and warning message
    """
    # 🔐 SECRET CODE VALIDATION
    is_valid, error = validate_secret_code(secret_code, "workflowy_create_single_node__WARNING__prefer_ETCH")
    if not is_valid:
        raise ValueError(error)
    
    client = get_client()

    request = NodeCreateRequest(  # type: ignore[call-arg]
        name=name,
        parent_id=parent_id,
        note=note,
        layoutMode=layout_mode,
        position=position,
    )

    if _rate_limiter:
        await _rate_limiter.acquire()

    try:
        node = await client.create_node(request)
        if _rate_limiter:
            _rate_limiter.on_success()
        
        # Return node data with warning message
        return {
            **node.model_dump(),
            "_warning": "⚠️ WARNING: You just created a SINGLE node. For 2+ nodes, use workflowy_etch instead (same performance, more capability)."
        }
    except Exception as e:
        if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
            _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
        raise


# @beacon[
#   id=auto-beacon@_note_wire_to_semantic-oxzr,
#   role=_note_wire_to_semantic,
#   slice_labels=node-ops,
#   kind=ast,
# ]
def _note_wire_to_semantic(note: str) -> str:
    """Decode a stored (wire-form) Workflowy NOTE into semantic (GUI-visible) form.

    Two steps (order matters):
    1. Unwrap Workflowy AUTO-LINK wrappers in the WIRE form (before entity
       decoding). In wire storage, real Workflowy auto-links have LITERAL
       '<a href="URL">' tags (bare angle brackets), while intentionally
       authored HTML source is entity-encoded ('&lt;a href=...&gt;') and is
       therefore invisible to the literal-tag regex. The auto-link fingerprint:
       one-layer-decoded anchor text == one-layer-decoded href. NAMED links
       (anchor text differs from href) are preserved.
    2. ONE layer of HTML-entity decoding via html.unescape (single-pass, so
       '&amp;lt;' -> '&lt;' and '&lt;' -> '<' -- exactly the GUI's decode
       depth). Whitelisted markup tags (<b>/<i>/<code>/colored spans) carry
       no entities and pass through unchanged.

    Shared by workflowy_read_node and the
    workflowy_edit_node note_search/note_replace path, so the agent reads
    and searches in exactly one domain: the GUI-visible semantic text.
    """
    # SINGLE-SOURCE (W1/F-1): the implementation lives in
    # workflowy_mcp.coherence.canonical_node._note_wire_to_semantic; this
    # seam delegates verbatim.  Do NOT re-implement here.
    from .coherence.canonical_node import (
        _note_wire_to_semantic as _coherence_note_wire_to_semantic,
    )

    return _coherence_note_wire_to_semantic(note)


# Unicode horizontal SPACE SEPARATOR codepoints that browsers render as
# ordinary-looking spaces and contenteditable editors commonly use to preserve
# indentation. Tier-2 note matching folds these 1:1 to U+0020 only AFTER an
# exact match misses. Deliberately excludes TAB and every zero-width character.
_NOTE_SPACE_FOLD_CODEPOINTS = frozenset(
    [0x00A0, 0x1680, 0x202F, 0x205F, 0x3000]
    + list(range(0x2000, 0x200B))
)
_NOTE_ZERO_WIDTH_CODEPOINTS = frozenset([0x200B, 0x200C, 0x200D, 0xFEFF])


def _fold_note_space_separators(text: str) -> str:
    """Map Unicode space separators to ASCII space, preserving string length."""
    return "".join(
        " " if ord(ch) in _NOTE_SPACE_FOLD_CODEPOINTS else ch
        for ch in text
    )


def _note_codepoint_description(ch: str | None) -> dict[str, Any]:
    """Return a visible, JSON-safe description of one divergent character."""
    if ch is None:
        return {"escaped": "<end>", "codepoint": None, "name": "END OF STRING"}
    return {
        "escaped": json.dumps(ch, ensure_ascii=True)[1:-1],
        "codepoint": f"U+{ord(ch):04X}",
        "name": unicodedata.name(ch, "UNNAMED"),
    }


def _note_first_divergence(search: str, candidate: str) -> dict[str, Any] | None:
    """Describe the first codepoint where two candidate search strings differ."""
    for i in range(max(len(search), len(candidate))):
        search_ch = search[i] if i < len(search) else None
        note_ch = candidate[i] if i < len(candidate) else None
        if search_ch != note_ch:
            return {
                "offset": i,
                "search": _note_codepoint_description(search_ch),
                "note": _note_codepoint_description(note_ch),
            }
    return None


def _strip_zero_width_with_index_map(text: str) -> tuple[str, list[int]]:
    """Space-fold + remove zero-width chars while retaining original indices."""
    normalized: list[str] = []
    original_indices: list[int] = []
    for i, ch in enumerate(text):
        if ord(ch) in _NOTE_ZERO_WIDTH_CODEPOINTS:
            continue
        normalized.append(" " if ord(ch) in _NOTE_SPACE_FOLD_CODEPOINTS else ch)
        original_indices.append(i)
    return "".join(normalized), original_indices


# @beacon[
#   id=server@_build_note_search_near_miss,
#   slice_labels=nexus-core-v1,node-ops,
#   kind=ast,
#   comment=Diagnostic-only residue behind node.edit note search-and-replace. Runs ONLY after exact and 1:1 Unicode-space-fold matching both miss. First probes a space-folded + zero-width-stripped view with an original-index map (never silently mutates through this non-1:1 tier); then a conservative unique visible-token anchor. When a probable region exists, returns the note's ACTUAL substring as suggested_search plus a ready-to-reissue {search,replace} suggested_edit and the first divergent Unicode codepoints. The edit report JSON is ensure_ascii=True, making invisible characters visible/copyable as \\uXXXX. Pure; no I/O.,
# ]
def _build_note_search_near_miss(
    semantic_note_lf: str,
    search: str,
    replace: str,
) -> dict[str, Any] | None:
    """Build an actionable exact-retry suggestion without performing a fuzzy edit.

    Tier A strips only U+200B/U+200C/U+200D/U+FEFF (and space-folds 1:1)
    with an index map back to the original note. Tier B uses the first unique
    visible token of length >= 8 as an anchor and extracts a same-length
    original substring. Both are diagnostics only: the returned
    ``suggested_search`` is exact note text and therefore safe to reissue.
    """

    def _report(kind: str, start: int, candidate: str, occurrence_count: int) -> dict[str, Any]:
        return {
            "kind": kind,
            "index": start,
            "occurrence_count": occurrence_count,
            "first_difference": _note_first_divergence(search, candidate),
            "suggested_search": candidate,
            "suggested_edit": {"search": candidate, "replace": replace},
            "hint": (
                "Retry with suggested_edit (or use suggested_search as note_search). "
                "The report escapes invisible Unicode as \\uXXXX."
            ),
        }

    # Diagnostic A: zero-width characters are never silently ignored for a
    # mutation because removing them breaks 1:1 index/length correspondence.
    normalized_note, note_index_map = _strip_zero_width_with_index_map(semantic_note_lf)
    normalized_search, _search_index_map = _strip_zero_width_with_index_map(search)
    if normalized_search:
        normalized_idx = normalized_note.find(normalized_search)
        if normalized_idx != -1:
            norm_end = normalized_idx + len(normalized_search) - 1
            if norm_end < len(note_index_map):
                start = note_index_map[normalized_idx]
                end = note_index_map[norm_end] + 1
                candidate = semantic_note_lf[start:end]
                if candidate != search:
                    occurrence_count = normalized_note.count(normalized_search)
                    has_zero_width = any(
                        ord(ch) in _NOTE_ZERO_WIDTH_CODEPOINTS
                        for ch in candidate + search
                    )
                    return _report(
                        "zero_width_mismatch" if has_zero_width else "unicode_text_mismatch",
                        start,
                        candidate,
                        occurrence_count,
                    )

    # Diagnostic B: conservative same-length extraction around the first
    # unique visible token. It is only a suggestion; no fuzzy mutation occurs.
    search_without_zero = "".join(
        ch for ch in search if ord(ch) not in _NOTE_ZERO_WIDTH_CODEPOINTS
    )
    anchor_match = re.search(r"\S{8,}", search_without_zero)
    if anchor_match:
        anchor = anchor_match.group(0)[:32]
        anchor_in_search = search.find(anchor)
        anchor_in_note = semantic_note_lf.find(anchor)
        if (
            anchor_in_search != -1
            and anchor_in_note != -1
            and semantic_note_lf.find(anchor, anchor_in_note + 1) == -1
        ):
            start = anchor_in_note - anchor_in_search
            end = start + len(search)
            if start >= 0 and end <= len(semantic_note_lf):
                candidate = semantic_note_lf[start:end]
                if candidate != search:
                    return _report("anchored_text_mismatch", start, candidate, 1)
    return None


def _splice_space_fold_match_preserving_context(
    semantic_note_lf: str,
    search: str,
    replace: str,
    idx: int,
) -> str:
    """Splice a Tier-2 match while preserving search/replacement common context.

    ``search`` and the matched source span are already aligned 1:1 by the
    Unicode-space fold. Exact common prefix/suffix comparison is deliberately
    between SEARCH and REPLACEMENT (intent), not search and source (location).
    Characters repeated exactly in both search and replacement are context the
    agent did not change, so the corresponding ORIGINAL source characters are
    retained (preserving NBSP indentation). Only the differing middle comes
    from ``replace``. The suffix is overlap-capped so prefix+suffix never exceed
    either string. Tier-1 exact matches do not call this helper and therefore
    remain verbatim replacement, allowing an exact-NBSP search to deliberately
    convert source whitespace to ASCII.
    """
    max_prefix = min(len(search), len(replace))
    prefix_len = 0
    while prefix_len < max_prefix and search[prefix_len] == replace[prefix_len]:
        prefix_len += 1

    max_suffix = min(len(search) - prefix_len, len(replace) - prefix_len)
    suffix_len = 0
    while (
        suffix_len < max_suffix
        and search[len(search) - 1 - suffix_len]
        == replace[len(replace) - 1 - suffix_len]
    ):
        suffix_len += 1

    replace_end = len(replace) - suffix_len if suffix_len else len(replace)
    source_suffix_start = idx + len(search) - suffix_len
    return (
        semantic_note_lf[: idx + prefix_len]
        + replace[prefix_len:replace_end]
        + semantic_note_lf[source_suffix_start:]
    )


# @beacon[
#   id=server@_apply_note_search_replace_once,
#   role=ƒ _apply_note_search_replace(semantic_note_lf, search, replace, replace_all=False),
#   slice_labels=nexus-core-v1,node-ops,
#   kind=ast,
#   comment=ONE per-entry note search authority for node.edit single/multi modes. First match by default; replace_all chooses all non-overlapping matches from the pre-entry text without reprocessing replacements. Exact matches anywhere win globally; only an exact miss permits 1:1 Unicode SPACE SEPARATOR folding. Folded matches reuse the original source-context-preserving splicer so unchanged NBSP indentation survives. Returns first index and optional tier/near_miss; replace-all adds a replacement_count. Pure text transformation, no I/O or cache mutation.,
# ]
def _apply_note_search_replace(
    semantic_note_lf: str, search: str, replace: str, *, replace_all: bool = False,
) -> "tuple[str, int, dict[str, Any]]":
    """Apply one entry: first match by default, all non-overlapping matches on opt-in.

    Choose the matching tier ONCE over the whole pre-entry text: exact wins
    globally; only an exact miss permits 1:1 Unicode-space folding. Match
    positions come from that immutable text, never from inserted replacement
    text. Entries themselves are still applied sequentially by the edit core.
    Folded replacements reuse the existing source-context-preserving splicer.

    Returns (new_note, first_index, match_info). Default first-match reports
    stay unchanged. Replace-all adds replace_all=True and replacement_count
    (including zero on a miss); near-miss analysis remains diagnostic only.
    """
    if not isinstance(replace_all, bool):
        raise ValueError("replace_all must be a boolean")
    normalized_search = search.replace("\r\n", "\n").replace("\r", "\n")
    normalized_replace = replace.replace("\r\n", "\n").replace("\r", "\n")
    if not normalized_search:
        raise ValueError("search must not be empty")

    searchable, needle = semantic_note_lf, normalized_search
    idx = searchable.find(needle)
    folded = False
    if idx == -1:
        searchable = _fold_note_space_separators(semantic_note_lf)
        needle = _fold_note_space_separators(normalized_search)
        idx = searchable.find(needle)
        folded = idx != -1
    info: dict[str, Any] = {"replace_all": True, "replacement_count": 0} if replace_all else {}
    if idx == -1:
        near_miss = _build_note_search_near_miss(
            semantic_note_lf, normalized_search, normalized_replace,
        )
        if near_miss:
            info["near_miss"] = near_miss
        return semantic_note_lf, -1, info

    if folded:
        info["tier"] = "space_fold"
    first_idx = idx
    parts: list[str] = []
    end = 0
    count = 0
    while idx != -1:
        parts.append(semantic_note_lf[end:idx])
        end = idx + len(normalized_search)
        parts.append(
            _splice_space_fold_match_preserving_context(
                semantic_note_lf[idx:end], normalized_search, normalized_replace, 0,
            ) if folded else normalized_replace
        )
        count += 1
        if not replace_all:
            break
        idx = searchable.find(needle, end)
    parts.append(semantic_note_lf[end:])
    if replace_all:
        info["replacement_count"] = count
    return "".join(parts), first_idx, info


_NOTE_DIFF_MODES = ("seams", "seams_full", "full", "none")


def _resolve_note_diff_mode(diff: str | None, return_diff: bool | None) -> str:
    """Resolve the public enum and its Boolean alias without silent conflicts."""
    if diff is not None and (not isinstance(diff, str) or diff not in _NOTE_DIFF_MODES):
        raise ValueError("diff must be 'seams', 'seams_full', 'full', or 'none'")
    if return_diff is not None and not isinstance(return_diff, bool):
        raise ValueError("return_diff must be a boolean")
    alias = None if return_diff is None else ("full" if return_diff else "none")
    if diff is not None and alias is not None and diff != alias:
        raise ValueError("diff conflicts with return_diff; pass only diff (or the matching alias).")
    return diff or alias or "seams"


def _note_diff_small_changes(before: str, after: str) -> list | None:
    """Myers' edit frontier for sparse character changes, without quadratic runs.

    The small-edit path is O(length * edit distance), including repeated text
    that makes character SequenceMatcher quadratic. After 128 edit steps the
    caller uses lexical alignment for wholesale replacement material instead;
    this is a display algorithm switch, never a refused/truncated input.
    """
    if not before or not after:
        return [(0, len(before), 0, len(after))] if before or after else []
    frontier = {1: 0}
    trace = []
    for distance in range(129):
        trace.append(frontier.copy())
        for diagonal in range(-distance, distance + 1, 2):
            down = diagonal == -distance or (
                diagonal != distance and frontier[diagonal - 1] < frontier[diagonal + 1]
            )
            x = frontier[diagonal + 1] if down else frontier[diagonal - 1] + 1
            y = x - diagonal
            while x < len(before) and y < len(after) and before[x] == after[y]:
                x += 1
                y += 1
            frontier[diagonal] = x
            if x < len(before) or y < len(after):
                continue
            changes = []
            for step in range(distance, 0, -1):
                previous = trace[step]
                diagonal = x - y
                down = diagonal == -step or (
                    diagonal != step and previous[diagonal - 1] < previous[diagonal + 1]
                )
                previous_diagonal = diagonal + 1 if down else diagonal - 1
                px = previous[previous_diagonal]
                py = px - previous_diagonal
                changes.append((px, px if down else px + 1, py, py + 1 if down else py))
                x, y = px, py
            changes.reverse()
            merged = []
            for i1, i2, j1, j2 in changes:
                if merged and i1 == merged[-1][1] and j1 == merged[-1][3]:
                    merged[-1] = (merged[-1][0], i2, merged[-1][2], j2)
                else:
                    merged.append((i1, i2, j1, j2))
            return merged
    return None


def _note_diff_change_spans(before: str, after: str) -> tuple[list, list]:
    """Character seam windows, with lexical alignment for wholesale new prose."""
    prefix = 0
    while prefix < min(len(before), len(after)) and before[prefix] == after[prefix]:
        prefix += 1
    suffix = 0
    while (
        suffix < min(len(before), len(after)) - prefix
        and before[len(before) - suffix - 1] == after[len(after) - suffix - 1]
    ):
        suffix += 1
    old_end, new_end = len(before) - suffix, len(after) - suffix
    old_middle, new_middle = before[prefix:old_end], after[prefix:new_end]
    changes = _note_diff_small_changes(old_middle, new_middle)
    if changes is None:
        # Match words/punctuation, not every repeated character of a paragraph.
        # Entire unmatched long tokens remain one changed span: only their
        # boundaries are useful seam evidence, not their newly generated bulk.
        old_tokens = list(re.finditer(r"\w+|\W", old_middle))
        new_tokens = list(re.finditer(r"\w+|\W", new_middle))
        old_offsets = [match.start() for match in old_tokens] + [len(old_middle)]
        new_offsets = [match.start() for match in new_tokens] + [len(new_middle)]
        changes = [
            (old_offsets[i1], old_offsets[i2], new_offsets[j1], new_offsets[j2])
            for tag, i1, i2, j1, j2 in difflib.SequenceMatcher(
                None, [match.group() for match in old_tokens], [match.group() for match in new_tokens],
            ).get_opcodes() if tag != "equal"
        ]
    old_spans = [(prefix + i1, prefix + i2) for i1, i2, _, _ in changes]
    new_spans = [(prefix + j1, prefix + j2) for _, _, j1, j2 in changes]
    # A newline-only change still has a seam at the end of the visible line.
    return old_spans or [(len(before), len(before))], new_spans or [(len(after), len(after))]


def _collapse_note_diff_line(text: str, spans: list, width: int = 128) -> str:
    """Merge change-centred windows, retaining edges and marking every cut.

    A change longer than the budget shows its two boundaries, not its bulk.
    Multiple distant changes keep multiple windows; overlapping windows merge.
    """
    if len(text) <= width:
        return text
    windows = []
    for start, end in spans:
        if end - start >= width:
            # Keep unchanged text OUTSIDE a long replacement too: those
            # transition characters are precisely what a seam must verify.
            budget = width // 2
            ranges = []
            for boundary in (start, end):
                left = max(0, min(boundary - budget // 2, len(text) - budget))
                ranges.append((left, left + budget))
        else:
            margin = (width - (end - start)) // 2
            left = max(0, min(start - margin, len(text) - width))
            ranges = [(left, min(len(text), left + width))]
        windows.extend(ranges)
    merged: list[list[int]] = []
    for start, end in sorted(windows):
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return (
        ("…" if merged[0][0] else "")
        + "…".join(text[start:end] for start, end in merged)
        + ("…" if merged[-1][1] < len(text) else "")
    )


def _note_diff_seam_lines(before: str, after: str, *, collapse: bool) -> tuple[list[str], int, int]:
    """Project line opcodes to one context line and two lines at each block edge."""
    old, new = before.splitlines(keepends=True), after.splitlines(keepends=True)
    groups = list(difflib.SequenceMatcher(None, old, new).get_grouped_opcodes(1))
    if not groups:
        return [], 0, 0
    rows = ["--- note (before)", "+++ note (after)"]
    added = removed = 0

    def _range(start, stop):
        length = stop - start
        return str(start + 1) if length == 1 else f"{start if length == 0 else start + 1},{length}"

    def _line(prefix, raw, spans):
        text = raw[:-1] if raw.endswith("\n") else raw
        rows.append(prefix + (_collapse_note_diff_line(text, spans) if collapse else text))
        if prefix != " " and not raw.endswith(("\n", "\r")):
            rows.append("\\ No newline at end of note")

    for group in groups:
        plus = sum(j2 - j1 for tag, _, _, j1, j2 in group if tag != "equal")
        minus = sum(i2 - i1 for tag, i1, i2, _, _ in group if tag != "equal")
        added += plus
        removed += minus
        rows.append(
            f"@@ -{_range(group[0][1], group[-1][2])} "
            f"+{_range(group[0][3], group[-1][4])} @@ (+{plus} / -{minus})"
        )
        for ordinal, (tag, i1, i2, j1, j2) in enumerate(group):
            if tag == "equal":
                for i in range(i1, i2):
                    text = old[i].removesuffix("\n")
                    spans = []
                    if ordinal > 0 and i == i1:  # immediately after a change
                        spans.append((0, 0))
                    if ordinal < len(group) - 1 and i == i2 - 1:  # immediately before
                        spans.append((len(text), len(text)))
                    _line(" ", old[i], spans or [(0, 0)])
                continue
            old_block, new_block = old[i1:i2], new[j1:j2]
            for prefix, block, other in (("-", old_block, new_block), ("+", new_block, old_block)):
                for i, raw in enumerate(block):
                    if len(block) > 4 and i == 2:
                        rows.append(f"... {len(block) - 4} {prefix} lines elided")
                    if i >= 2 and i < len(block) - 2:
                        continue
                    # Pair head with head and tail with tail when block lengths differ.
                    peer = i if i < 2 else len(other) - (len(block) - i)
                    counterpart = other[peer] if 0 <= peer < len(other) else ""
                    spans, _ = _note_diff_change_spans(raw.removesuffix("\n"), counterpart.removesuffix("\n")) if collapse else ([], [])
                    _line(prefix, raw, spans)
    return rows, added, removed


# @beacon[
#   id=server@_render_note_unified_diff,
#   role=_render_note_unified_diff(before, after, mode, context_lines),
#   slice_labels=nexus-core-v1,node-ops,
#   kind=ast,
#   comment=ONE pure note-diff renderer for single/multi search-replace and whole-note/file reports. Public seams defaults show one context line and first/last two lines of each removed/added block with counted middle elisions and change-centred 128-character windows; seams_full keeps whole seam lines; full retains the existing unified diff and empty-before summary; none builds no diff. Every nonempty mode retains the shared 400-line head/tail clamp and true whole-diff +/- totals. No I/O or extra readback.,
# ]
def _render_note_unified_diff(
    before: str, after: str, *, mode: str = "full", context_lines: int = 3,
) -> str:
    """Render the selected view of ONE aggregate live-before -> submitted-after diff.

    Seams show one unchanged line either side, and the first/last two lines of
    each old/new block (counting elided middle lines). Only seams collapses long
    lines around character changes. Full preserves the historical format,
    including the empty-before summary. All views use the ONE shared head/tail
    clamp at DEFAULT_NOTE_MAX_LINES, with actual additions/removals even when
    seam projection already hid changed lines. None returns no diff at all.
    """
    if mode not in _NOTE_DIFF_MODES:
        raise ValueError("unknown note diff mode")
    if mode == "none" or before == after:
        return ""
    if mode == "full":
        if before == "":
            return f"note was empty; {len(after.splitlines())} lines written"
        diff = "".join(
            chunk if chunk.endswith("\n") else chunk + "\n"
            for chunk in difflib.unified_diff(
                before.splitlines(keepends=True), after.splitlines(keepends=True),
                fromfile="note (before)", tofile="note (after)", n=context_lines,
            )
        )
        diff_lines = diff.splitlines()
        added = sum(1 for line in diff_lines[2:] if line.startswith("+"))
        removed = sum(1 for line in diff_lines[2:] if line.startswith("-"))
    else:
        diff_lines, added, removed = _note_diff_seam_lines(before, after, collapse=mode == "seams")
        diff = "\n".join(diff_lines) + "\n" if diff_lines else ""
    if len(diff_lines) <= DEFAULT_NOTE_MAX_LINES:
        return diff
    head_end, tail_start, elided_start, elided_end, elided_count = (
        clamp_span_to_head_tail(1, len(diff_lines), DEFAULT_NOTE_MAX_LINES)
    )
    hunk_lines = [
        number for number, line in enumerate(diff_lines, start=1)
        if line.startswith("@@")
    ]
    hidden_hunks = sum(
        1 for number in hunk_lines if elided_start <= number <= elided_end
    )
    elision_row = (
        f"... {elided_count} diff lines not shown ({elided_start}-{elided_end}); "
        f"{hidden_hunks} of {len(hunk_lines)} hunks hidden; "
        f"totals +{added} / -{removed}"
    )
    return "\n".join(
        diff_lines[:head_end] + [elision_row] + diff_lines[tail_start - 1:]
    ) + "\n"


# ---------------------------------------------------------------------------
# Typed-region seam helpers. Ownership lives only in mutation_locks.py; these
# readers retain U01's wait-report shape and factories use their explicit proof.
# ---------------------------------------------------------------------------


def _mutation_serialization_field(since: int = 0) -> dict[str, Any] | None:
    """U01 §6.7: this task's mutation-lock wait record as the honesty field.

    Returns ``{"waited_seconds": <total, ms-rounded>, "waited_on": [uuid8…]}``
    built from the wait events at index ``since`` onward, or ``None`` when the
    operation never contended (the uncontended wire shape stays byte-identical,
    §10). Batch seams pass a per-item ``since`` snapshot for attribution; the
    MCP finalizer, the node.edit report header and the WS replies read the
    whole-operation record.
    """
    state = MUTATION_LOCK_STATE.get()
    if state is None:
        return None
    return state.serialization(since)


def _mutation_wait_mark() -> int:
    """U01 §6.7: current length of this task's wait record (batch snapshot).

    Taken BEFORE a per-item write; ``_mutation_serialization_field(since=mark)``
    afterwards attributes exactly that item's waits to its ledger row.
    """
    state = MUTATION_LOCK_STATE.get()
    return len(state.waits) if state is not None else 0


from .mutation_conflicts import ConcurrentEditDetectedError
from .client.api_client_core import _canonical_update_value

_N02_UPDATE_DESCRIBE_SUFFIX = (
    " Name/note writes compare a final live read with their basis and the returned state with what was sent, ignoring Workflowy normalization;"
    f" a detected change returns {ConcurrentEditDetectedError.code} with live wire values and retry advice, so re-read and recompute before retrying."
    " GUI edits in the remaining final-read-to-send gap are last-writer-wins: neither Workflowy transport offers compare-and-swap."
)


def _mutation_refusal_extra(exc) -> dict[str, Any]:
    """Shared plane-refusal and live-observation payload for all existing fronts."""
    if isinstance(exc, ConcurrentEditDetectedError):
        return exc.extra
    if isinstance(exc, MutationSerializationTimeoutError):
        return {"retry_after": exc.retry_after, "contended_keys": list(exc.contended_keys), "timeout_seconds": exc.timeout_seconds}
    if isinstance(exc, MutationSerializationConflictError):
        extra = {
            "retry_after": exc.retry_after, "contended_keys": list(exc.contended_keys),
            "holder_kind": exc.holder_kind, "holder_id": exc.holder_id, "reason": exc.reason,
        }
        if exc.holder_kind == "long_lived":
            job_id = _carto_operation_jobs.get(exc.holder_id)
            if job_id is not None:
                extra.update(
                    holder_job_id=job_id,
                    holder_message=f"Held by Cartographer job {job_id}; check system.job.status before retrying.",
                )
        return extra
    if isinstance(exc, MutationRegionError):
        extra = {"reason": exc.reason, "retry_after": exc.retry_after}
        if exc.region is not None:
            extra["region"] = exc.region.to_dict() if isinstance(exc.region, MutationRegion) else exc.region
        return extra
    raise TypeError("not a typed mutation-plane refusal")


def _pinned_parent_id_for_lock(node_id: str, *, snapshot=None):
    """Current-proof parent identity; only a known null parent means ROOT."""
    if snapshot is None:
        from .coherence.operation_cache import current_operation_cache
        snapshot = current_operation_cache(required=True)
    return mutation_parent_identity(node_id, cache_by_id=snapshot.nodes_by_id)


def _mutation_parent_regions(parent, *, snapshot, known_inbox_uuid=None) -> tuple[MutationRegion, ...]:
    """Child list plus an already-authoritative Inbox alias, never a title guess."""
    regions = (build_region_child_set(parent, cache_by_id=snapshot.nodes_by_id),)
    if parent is ReservedMutationParent.INBOX and known_inbox_uuid is not None:
        from .mutation_lease_governance import _lookup_region_node
        if _lookup_region_node(known_inbox_uuid, snapshot.nodes_by_id) is not None:
            regions += (build_region_child_set(known_inbox_uuid, cache_by_id=snapshot.nodes_by_id),)
    return regions


async def _resolve_mutation_region_handle(handle, *, label, role="handle", mutator=False):
    """Required boundary resolution; archive provenance precedes typed misses.

    General optional resolvers stay unchanged. A missing full UUID needs one
    cache refresh; a non-UUID miss needs resolution, never a raw lock key.
    """
    from .archive_context import ArchivedNodeReadOnlyError
    from .mutation_lease_governance import _validate_uuid_text
    from .mutation_locks import _public_region_error

    resolver = _resolve_mutator_node_id if mutator else _resolve_generic_node_handle
    try:
        resolved = await resolver(handle, label=label, required=True, role=role)
    except ArchivedNodeReadOnlyError:
        raise
    except RuntimeError as exc:
        try:
            key = _validate_uuid_text(handle, "region key")
        except MutationRegionError:
            error = MutationRegionError(str(exc), reason="malformed_region")
        else:
            error = MutationRegionError(str(exc), reason="unresolvable_region", region=key)
        raise _public_region_error(error) from exc
    try:
        return _validate_uuid_text(resolved, "resolved region key")
    except MutationRegionError as exc:
        raise _public_region_error(exc) from exc


def _explicit_ap_cores_from_payload(payload, *, exclude=()) -> tuple[str, ...]:
    """Peek literal names with the shared ETCH parser; its failure remains ETCH's.

    This never repairs/allocates a core or validates a second payload dialect.
    The unchanged client preflight reports malformed forests with zero writes.
    """
    from .client.api_client_etch import parse_etch_nodes_payload

    forest, _strategy, error = parse_etch_nodes_payload(payload)
    if error or not isinstance(forest, list):
        return ()
    excluded = {normalize_ap_core(core) for core in exclude}
    cores: set[str] = set()
    stack = list(forest)
    while stack:
        node = stack.pop()
        if not isinstance(node, dict):
            continue  # The existing whole-forest preflight rejects this node.
        core = _anchor_leading_ap_core(node.get("name"))
        if core is not None:
            cores.add(normalize_ap_core(core))
        children = node.get("children")
        if isinstance(children, list):
            stack.extend(children)
    return tuple(sorted(cores - excluded))


def _prepare_anchor_capture_payload(nodes, note_file, content, name):
    """Freeze capture's selected source once, retaining the same provenance."""
    from .client.api_client_nexus import _node_payload_from_content, _node_payload_from_note_file

    note_meta = content_meta = path_record = None
    if note_file is not None:
        payload, note_meta = _node_payload_from_note_file(note_file, name_override=name)
        path_record = note_meta.pop("path_record", None)
    elif content is not None:
        payload, content_meta = _node_payload_from_content(name, content)
    else:
        payload = nodes
    return payload, note_meta, content_meta, path_record


def _read_etch_job_payload(nodes, nodes_file):
    """Execution-time file selection once; preserve the client's object-with-nodes rule."""
    if not nodes_file:
        return nodes, None
    try:
        _resolution, file_text = read_tool_text_file(
            nodes_file, param="nodes_file", context="workflowy_etch"
        )
        try:
            parsed = json.loads(file_text)
        except json.JSONDecodeError:
            parsed = None
        return (parsed["nodes"] if isinstance(parsed, dict) and "nodes" in parsed else file_text), None
    except Exception as exc:
        return None, {
            "success": False, "nodes_created": 0, "root_node_ids": [],
            "errors": [f"Failed to read nodes_file '{nodes_file}': {exc}"],
        }


# @beacon[
#   id=server@_render_note_edit_report,
#   role=ƒ _render_note_edit_report(metadata, diff),
#   slice_labels=nexus-core-v1,node-ops,
#   kind=ast,
# ]
def _render_note_edit_report(metadata: dict, diff: str) -> str:
    """Render any note-edit diff result as ONE agent/human-facing document.

    Metadata is a small pretty-printed JSON object at the top. That object then
    ENDS; after a blank line, the unified diff is appended as literal raw text
    (never JSON-escaped and never stored as a ``diff`` field). This mirrors the
    readable output contract of edit_file rather than exposing a machine-facing
    JSON envelope nobody consumes.
    """
    header = json.dumps(metadata, indent=2, ensure_ascii=True)
    return header + ("\n\n" + diff if diff else "\n")


# Tool: Edit Node
@_legacy_tool(
    name="workflowy_edit_node",
    description=(
        "Update an existing WorkFlowy node. node_id may be a Workflowy UUID (exact "
        "or a unique prefix), an [ap:CORE] anchor-point handle, OR a source-code "
        "SYMBOL (function / class / AST_QUALNAME / beacon id); it is resolved to "
        "a single node before the update. An ambiguous or unresolved handle makes NO "
        "change and fails loudly (with candidates on ambiguity).\n\n"
        "NAME VS TAGS & AP-IDS (protected-name policy): the name argument replaces "
        "ONLY the ordinary title text. It must NOT carry trailing #tags -- any "
        "supplied tag is a loud error and nothing is written (use the dedicated "
        "verbs workflowy_add_tag / workflowy_remove_tag / workflowy_rename_tag, "
        "consolidated: tag.add / tag.remove / tag.rename / tag.batch). The node's "
        "EXISTING trailing tags are left in place automatically, so simply omit "
        "them. Likewise a leading [ap:CORE] anchor-point handle is preserved "
        "automatically; repeating the identical one is allowed, but adding or "
        "changing one is a loud error. Use anchor.point.assign_id to assign and "
        "anchor.point.remove_id to remove; replacement is the explicit two-step "
        "remove-then-assign flow.\n\n"
        "NOTE SEARCH-AND-REPLACE (single edit): pass note_search and note_replace "
        "(instead of note) to perform a search-and-replace on the node's NOTE "
        "field only. If the search text is not found, the note edit is a no-op "
        "-- a NOTE no-op, not a call no-op: when name and/or layout_mode is also "
        "requested, that write still happens (the note is left untouched); only "
        "when nothing else is requested is there no mutation at all. "
        "Search-and-replace MAY be combined with name and/or layout_mode "
        "(disjoint fields carried by the same single update call); it CANNOT be "
        "combined with note (a wholesale replace conflicts with the computed "
        "note) or _completed (use complete_node/uncomplete_node). note_replace "
        "requires note_search; and note_search must be non-empty. The "
        "search-and-replace edit itself operates ONLY on the note, never the "
        "name.\n\n"
        "NOTE MULTI-EDIT (note_edits): pass note_edits -- a list of "
        "{\"search\": ..., \"replace\": ...} objects (a JSON string of the same "
        "list is also accepted) -- to apply SEVERAL search-and-replace edits to "
        "the note in ONE call. Edits apply SEQUENTIALLY, in list order, each over "
        "the text left by the previous edits, so a later edit CAN match text an "
        "earlier edit just inserted. The note is fetched and written back ONCE "
        "total (one read + one write, not one per edit). Each edit is an "
        "independent first-occurrence replace: an edit whose search is not found "
        "is skipped and reported (matched:false); if ALL edits miss, the note is "
        "left untouched -- and if name/layout_mode was also requested, that "
        "write still happens (the report then shows no_op:false, "
        "edits_applied:0). Each item's search must be non-empty; an omitted or "
        "null replace means deletion. note_edits is EXCLUSIVE with note_search/"
        "note_replace (a loud error is raised if both forms are passed) and "
        "CANNOT be combined with note or _completed; it MAY be combined with "
        "name and/or layout_mode. Returns the raw metadata-header plus selected "
        "diff report described below, with one compact edit_results row per "
        "edit in input order.\n\n"
        "MATCH SEMANTICS (both forms): Tier 1 is the historical LITERAL, "
        "CASE-SENSITIVE, first-occurrence substring match. Only if exact "
        "matching misses, Tier 2 treats display-identical Unicode SPACE "
        "SEPARATOR characters (including NBSP used by Workflowy indentation) "
        "as ordinary U+0020 spaces, one codepoint for one codepoint; the ledger "
        "then reports tier:'space_fold'. Within that folded match, exact common "
        "prefix/suffix between SEARCH and REPLACEMENT is treated as unchanged "
        "context and retained from the original note, preserving load-bearing "
        "NBSP indentation; only the differing middle comes from replacement. "
        "An exact Tier-1 Unicode search still allows deliberate whitespace "
        "conversion. Tabs, zero-width characters, repeated "
        "space runs, and case are NEVER silently folded. If both tiers miss, "
        "a conservative diagnostic may return near_miss.suggested_edit -- exact "
        "note text with invisible codepoints escaped as \\uXXXX -- sufficient "
        "for a safe retry. There is NO regex, glob, run-collapsing, or general "
        "fuzzy support in this tool (the smart boolean/glob grammar belongs to "
        "lightning_rod render_search, a node-SELECTION feature, not text "
        "replacement). The search text is SEMANTIC (GUI-visible) text: it should "
        "match what you see in the Workflowy GUI and in "
        "workflowy_read_node output (HTML entities are decoded "
        "one layer before matching, e.g. search '<x>' not '&lt;x&gt;'; Workflowy "
        "auto-link wrappers are unwrapped back to bare URLs for matching and "
        "re-wrapped by Workflowy on write). Newline handling is automatic (CRLF, "
        "LF, CR all normalized to LF for matching, and the final submitted note "
        "is always pure LF, including the replacement text).\n\n"
        "NOTE DIFF MODES (all note writes: single search/replace, note_edits, "
        "note, note_file): diff='seams' is the default. Each changed old/new block "
        "shows one line before, its first two and last two lines, and one line "
        "after; the middle is elided with a count. Long seam lines collapse to "
        "~128-character windows around each change, with ellipses at cuts; "
        "several distant changes keep several windows. diff='seams_full' keeps "
        "the same seams and middle elisions but shows their lines whole. "
        "diff='full' keeps the historical unified diff (an empty old note gives "
        "'note was empty; N lines written'); diff='none' returns the JSON header "
        "only, including note_chars and the search/replace match ledger. "
        "return_diff=true/false is an alias for full/none, including search/replace; "
        "conflicting alias/enum values fail. Every nonempty diff mode retains "
        "the 400-line head/tail size guard, omitted hunks and true +/- totals. "
        "Empty note clears it; identical replacements still invoke update "
        "(no_op=false, note_changed=false). One memoized live snapshot is shared "
        "with name composition; no extra readback.\n\n"
        "RESPONSE ACK (name/layout edits): the acknowledgement is a small detail object with "
        "the node's id/name/timestamps/layout metadata -- the note BODY and the "
        "children list are absent from it, so returning an entire long Markdown "
        "note after a tiny edit never happens (we do not return a whole file "
        "just because we made a small edit in it). Use workflowy_read_node "
        "to read the note. No 'note': null can read like the note was cleared "
        "(the old note=null meant 'omitted from this response', never "
        "'the stored note was cleared').\n\n"
        "SEARCH-AND-REPLACE DIFF REPORT (note_search/note_replace single edit OR "
        "note_edits multi-edit): these modes return ONE raw text document, not a "
        "JSON tool result. A small pretty-printed JSON metadata object appears at "
        "the top and ENDS; after a blank line, the selected diff is appended as "
        "literal raw text (not JSON-escaped and not stored in a 'diff' field). "
        "The metadata includes a compact edit_results ledger ({ordinal, matched, "
        "index}); exact matches add nothing, space-equivalent matches add "
        "tier:'space_fold', and a miss may add an actionable near_miss with a "
        "ready-to-reissue suggested_edit. Full search/replace strings are not "
        "otherwise echoed. "
        "When the note did not change (all edits missed, or a matched replace "
        "produced identical text), the result contains metadata only. no_op=true "
        "means NO write occurred."
    ),
)
# @beacon[
#   id=server@update_node,
#   role=⚡ edit_node(node_id: str, name, note, note_search, note_replace, note_edits, layout_mode, _completed),
#   slice_labels=nexus-core-v1,node-ops,
#   kind=ast,
#   comment=Public edit surface resolves diff=seams for EVERY note write here; seams_full/full/none and the return_diff Boolean alias share one header/report contract. Internal narrow channels remain on _node_edit_core with no implicit report. Protected-name policy preserves AP-ID tags and leading emoji; plain name/layout acknowledgements exclude note/children. No extra readback or mutation path.,
# ]
async def _node_edit_impl(
    node_id: str,
    name: str | None = None,
    note: str | None = None,
    note_search: str | None = None,
    note_replace: str | None = None,
    note_edits: list[dict] | str | None = None,
    layout_mode: Literal["bullets", "todo", "h1", "h2", "h3"] | None = None,
    _completed: bool | None = None,
    *,
    replace_all: bool = False,
    diff: Literal["seams", "seams_full", "full", "none"] | None = None,
    return_diff: bool | None = None,
    replace_emoji: bool = False,
) -> WorkFlowyNode | str | dict[str, Any]:
    """Update an existing WorkFlowy node.

    Args:
        node_id: The ID of the node to update
        name: New ORDINARY TITLE text for the node (optional). Protected-name
            policy: the value must NOT carry trailing #tags or a leading
            [ap:CORE] anchor-point handle -- supplied tags are a loud error
            (tags_in_name_rejected; use tag.add / tag.remove / tag.rename /
            tag.batch), and adding or changing an AP-ID is a loud error
            (ap_id_mutation_rejected; use anchor.point.assign_id to assign,
            anchor.point.remove_id to remove, or remove then assign to
            replace). The node's existing trailing tags, existing AP-ID and
            existing LEADING EMOJI RUN are preserved automatically -- pass
            only the new title text; you need not pass an emoji. A supplied
            name that begins with its own emoji run wins (explicit wins);
            replace_emoji=true hands the run to the supplied name wholesale
            (its run replaces the existing one; its absence clears the run).
            An identical existing AP-ID may be repeated unchanged.
        note: New note/description (optional); empty string clears it.
        diff: One report mode for ALL public note writes: seams (default)
            shows one context line and first/last two lines of each changed
            block, counted middle elisions and ~128-character change windows;
            seams_full keeps those seam lines whole; full keeps the historical
            unified diff; none returns only the metadata header, including
            note_chars and the search/replace match ledger when applicable.
            Every nonempty mode retains the shared 400-line size guard.
            The default is resolved HERE, never for internal narrow channels.
            Before text comes from ONE memoized live snapshot shared with name
            composition; after text is submitted semantic text, not a readback.
        return_diff: Boolean alias: true = full, false = none, including
            search/replace. Conflicting diff/return_diff values fail loudly.
        note_search: Text to search for in the current note. When provided, the
            tool fetches the node, decodes one layer of HTML entities (wire →
            semantic, the GUI-visible form), replaces the first occurrence by
            default (all non-overlapping occurrences with replace_all=true),
            and updates. Must be non-empty. Newlines are normalized
            (CRLF/LF/CR → LF) before matching. Exact matching runs first;
            only on an exact miss, display-equivalent Unicode SPACE SEPARATOR
            codepoints (including NBSP) are folded 1:1 to ordinary spaces.
            Exact SEARCH-vs-REPLACEMENT common prefix/suffix is then retained
            from the original note, so unchanged NBSP indentation survives;
            only the differing middle comes from replacement. An exact search
            containing the source Unicode remains the explicit way to convert
            whitespace deliberately. The search text should match what you see
            in the Workflowy GUI and in workflowy_read_node output. If both
            match tiers miss, the ledger may return an actionable
            near_miss.suggested_edit with invisible codepoints visibly escaped
            for an exact retry. If not found, the note edit is a no-op
            (no note mutation; a name/layout_mode update
            passed alongside still happens). Untouched content round-trips
            display-identically; recognized HTML entities may canonicalize to
            their decoded Unicode codepoint (e.g. '&nbsp;' → U+00A0), and a
            bare ampersand previously stored as '&amp;' may be written as '&'.
            The GUI renders those forms identically.
            MAY be combined with name and/or layout_mode (disjoint fields,
            same single update call); CANNOT be combined with note or
            _completed. A miss is a NOTE no-op, not a call no-op: with
            name/layout_mode also requested, that write still happens.
        note_replace: Replacement text for note_search, in semantic
            (GUI-visible) form; the normal update encoder HTML-encodes it.
            Requires note_search. Defaults to empty string (deletion) if None
            when note_search is provided. Any CRLF/CR newlines inside the
            replacement are also normalized to LF, so the final submitted note
            is always pure LF.
        note_edits: Multi-edit search-and-replace (EXCLUSIVE alternative to
            note_search/note_replace). A list of {"search", "replace"} objects
            with optional per-entry Boolean "replace_all" overrides
            (a JSON string of the same list is accepted). Edits apply
            SEQUENTIALLY, in list order, each over the text left by the
            previous edits (a later edit CAN match text an earlier edit just
            inserted). The note is fetched and written back ONCE total (one
            read + one write, not one per edit). Each edit is an independent
            first-occurrence exact-first replace by default; replace_all chooses
            all matches in that entry's pre-edit text without rescanning inserted
            replacements. After an exact miss, Unicode
            SPACE SEPARATOR codepoints (including Workflowy NBSP indentation)
            are matched 1:1 as ordinary spaces. Exact common context repeated
            in search + replacement is retained from the original note; only
            their differing middle is replaced. An edit whose search is still
            not found is skipped and reported (matched:false, with an actionable
            near_miss suggestion when a safe probable region is found); if
            ALL edits miss, the note is left untouched (no write unless
            name/layout_mode was also requested -- that write still happens).
            Each item's search must be non-empty; an omitted/null replace means
            deletion. Cannot be combined with note_search/note_replace, note,
            or _completed; MAY be combined with name and/or layout_mode.
        replace_emoji: Boolean, false by default. Shapes ONLY a name update:
            false preserves the node's existing leading emoji run (state
            marks like 📋/✅ survive a rename; you need not pass an emoji),
            while a supplied name that begins with its own run wins
            (explicit wins). true hands the run to the supplied name
            wholesale: its run replaces the existing one, and a name with no
            leading emoji clears the run (removal also stays
            node.update_emoji with a blank emoji). Inert without name.
        replace_all: Boolean call-level default for single/multi search-replace,
            false by default. Each note_edits item may override with true OR
            false. Matching tier is chosen once per entry: all exact matches
            if any exist, otherwise Unicode-space matches. Non-overlapping,
            original-position scan; later entries see earlier entries' results.
            Enabled entries report replace_all=true and replacement_count;
            edits_applied still counts entries, not occurrences. True requires
            note_search or note_edits and cannot be used for whole-note input.
        layout_mode: New layout mode for the node (bullets, todo, h1, h2, h3) (optional)
        _completed: New completion status (not used - use complete_node/uncomplete_node)

    Returns:
        Plain-update mode (name / layout_mode edits): a small acknowledgement dict with
            the node's metadata (id/name/timestamps/layout) minus the note
            and children fields -- never the note body. No "note": null appears: the
            field is simply absent (it used to mean 'omitted from this
            response', never 'the stored note was cleared'). Use
            workflowy_read_node to read the note.
        Whole-note replacement: the raw report format below, with
            success/no_op/note_changed/node_id and note sizes (no search ledger).
            Before is live decoded text; after is the submitted semantic
            note, not a new readback. Identical text still invokes update,
            so no_op=false. The selected diff is size-guarded past 400 lines.
        Search-and-replace modes (note_search/note_replace single edit, OR
            note_edits multi-edit): ONE raw text document. A small pretty-
            printed JSON metadata object appears at the top and ENDS; after a
            blank line, the selected diff (note (before) -> note (after)) is
            appended as literal raw text -- never JSON-escaped and never stored
            as a 'diff' field. The metadata contains success/no-op counts plus
            a compact edit_results ledger ({ordinal, matched, index}); default
            first-match exact rows have no extra fields, while replace-all rows
            add replace_all=true and replacement_count. Unicode-space matches add
            tier=space_fold, and misses may add near_miss.suggested_edit with
            JSON-escaped invisible Unicode for an exact retry. Full search /
            replace strings are not otherwise echoed. When the note did not
            change,
            the result contains metadata only, as with diff=none for every
            note write. no_op=true means no API write.
    """
    # Public default only: internal whole-note writers must not build reports.
    mode = _resolve_note_diff_mode(diff, return_diff)
    if note is None and note_search is None and note_edits is None:
        if return_diff is True or (diff is not None and mode != "none"):
            raise ValueError("diff requires note or note search/replace; it is inapplicable to name/layout-only requests.")
        mode = None
    result = await _node_edit_core(
        node_id,
        name=name,
        note=note,
        note_search=note_search,
        note_replace=note_replace,
        note_edits=note_edits,
        layout_mode=layout_mode,
        _completed=_completed,
        replace_all=replace_all,
        diff=mode,
        _replace_leading_emoji=replace_emoji,
    )
    if isinstance(result, WorkFlowyNode):
        # [ap:PHO4BG] PUBLIC ACK ONLY: the plain-update path returns a small
        # dict -- the node's fields minus the note body and the children
        # (and their model_dump compatibility mirrors "no"/"ch") --
        # so nothing in the acknowledgement can read like the note was
        # cleared. Internal callers keep the core's redacted
        # WorkFlowyNode return untouched.
        ack = result.model_dump(exclude={"note", "children"})
        ack.pop("no", None)
        ack.pop("ch", None)
        return ack
    return result


# note_edits item-level aliases (O7RP65): the filesystem edit_file spelling
# oldText/newText is accepted per item as an exact alias for search/replace,
# because agents that edit both disk files and Workflowy notes mix the two
# grammars (a three-times-confirmed cross-session error class). Applied per
# item BEFORE the closed-key check: a mixed item (one key from each pair) is
# accepted, identical values are accepted with the alias key dropped, and a
# conflicting pair with DIFFERENT values still fails loudly per item. The
# top-level param-alias rule (reject even when identical) is unchanged.
_NOTE_EDIT_ITEM_ALIASES = {"oldText": "search", "newText": "replace"}


# @beacon[
#   id=server@_node_edit_core,
#   slice_labels=nexus-core-v1,nexus--tags,node-ops,
#   kind=ast,
#   comment=One exact-node region spans the original memoized live basis through checked UPDATE return; pass raw written fields to the final/read-back checks without refetching an injected basis. Public note reports retain submitted after text and selected diffs; protected composition preserves AP tags and leading emoji, and nested callers never repin.,
# ]
async def _node_edit_core(
    node_id: str,
    name: str | None = None,
    note: str | None = None,
    note_search: str | None = None,
    note_replace: str | None = None,
    note_edits: list[dict] | str | None = None,
    layout_mode: Literal["bullets", "todo", "h1", "h2", "h3"] | None = None,
    _completed: bool | None = None,
    *,
    replace_all: bool = False,
    return_diff: bool = False,
    diff: Literal["seams", "seams_full", "full", "none"] | None = None,
    _tag_transform=None,
    _assign_ap_core: str | None = None,
    _remove_ap_id: bool = False,
    _leading_emoji_mutation: LeadingEmojiMutation | None = None,
    _replace_leading_emoji: bool = False,
    _touch: bool = False,
    _current_node=None,
) -> WorkFlowyNode | str:
    """Shared edit core: exact ownership, original raw basis and protected edits.

    replace_all is a call-level Boolean default; each validated note_edits
    entry may explicitly override it, including false. All flags are checked
    before live reads, and only the pure per-entry text transform changes:
    existing identity, snapshot, mutation and reporting rails are retained.
    diff selects the SAME report format for every note write, including a
    metadata-only header for none. The public wrapper resolves its seams
    default BEFORE calling; internal whole-note callers with neither diff
    nor return_diff still return their original redacted node. The internal
    return_diff Boolean retains its historical full-diff opt-in. Before text
    comes from the memoized live snapshot, canonically decoded without newline
    normalization for whole-note input; after is submitted semantic text, not
    a readback. Identical input still reaches update_node. Every nonempty
    mode uses the ONE shared size clamp inside _render_note_unified_diff.

    The public wrapper (:func:`_node_edit_impl`, exposed as
    ``workflowy_edit_node`` / ``node.edit``) passes no internal channels.
    ``_tag_transform`` (a ``list[str] -> list[str]`` callable),
    ``_assign_ap_core`` (a reserved AP core), ``_remove_ap_id`` (a
    Boolean dedicated removal request), and ``_leading_emoji_mutation`` (a
    typed replace/prepend/append request against the ordinary name section's
    leading emoji run) are narrow channels for internal callers that own one
    protected region; ``_replace_leading_emoji`` is the public
    ``replace_emoji`` opt-in that hands a rename's leading emoji run to the
    supplied title wholesale (default false: the run is preserved; a
    supplied run wins under both settings). ``_current_node`` optionally
    injects an already-fresh live node so
    the caller's snapshot and this write share one read.

    ``_touch`` is the dedicated ``anchor.point.touch`` channel: ONE
    content-preserving write whose only purpose is to advance the server's
    ``modifiedAt`` (RECON proved any ``POST /nodes/{id}`` does). It never
    combines with a content field or another channel, composes NO text of its
    own, and picks the mechanism from the live node via
    :func:`_touch_mechanism_for`: echo the node's own ``layoutMode`` (zero
    name/note bytes on the wire) when it is one of the request-echoable modes,
    else recompose the identical semantic name through the protected-name
    composer (tags / AP-ID / decoration preserved; display-identical, entity
    spelling may canonicalize). Unlike every other path here the ``_touch``
    return value is the UNREDACTED post-write node (note included) so the
    caller can verify byte preservation against its pre-write snapshot.
    """
    # --- Search-and-replace argument validation (fail fast, BEFORE any
    # resolution or API work). TWO mutually-exclusive forms:
    #   (A) single edit -- note_search + note_replace
    #   (B) multi edit  -- note_edits: a list of {"search","replace"} dicts
    # Each form MAY be combined with name and/or layout_mode (disjoint fields
    # carried by the same single update request); each is EXCLUSIVE only with
    # note (a wholesale replace conflicts with the computed note) and
    # _completed (deprecated here -- use complete_node/uncomplete_node).
    # note_replace requires note_search, and every search string must be
    # non-empty (an empty string would silently match at index 0 of the note).
    if not isinstance(_touch, bool):
        raise ValueError("_touch must be a boolean")
    if _touch and (
        name is not None
        or note is not None
        or note_search is not None
        or note_replace is not None
        or note_edits is not None
        or layout_mode is not None
        or _completed is not None
        or replace_all
        or return_diff
        or diff is not None
        or _tag_transform is not None
        or _assign_ap_core is not None
        or _remove_ap_id
        or _leading_emoji_mutation is not None
    ):
        raise ValueError(
            "_touch is the dedicated anchor.point.touch channel (a content-"
            "preserving modifiedAt advance) and never combines with name, note, "
            "note search/replace, layout_mode, _completed, diff, return_diff, "
            "replace_all, or another protected-region channel."
        )
    if not isinstance(return_diff, bool):
        raise ValueError("return_diff must be a boolean")
    if diff is not None:
        _resolve_note_diff_mode(diff, True if return_diff else None)
    if (return_diff or diff is not None) and note is None and note_search is None and note_edits is None:
        raise ValueError("diff/return_diff requires note or note search/replace; it is inapplicable to name/layout-only requests.")
    if not isinstance(replace_all, bool):
        raise ValueError("replace_all must be a boolean")
    if replace_all and note_search is None and note_edits is None:
        raise ValueError("replace_all=true requires note_search or note_edits; it is not a whole-note replacement option.")
    if note_edits is not None and (note_search is not None or note_replace is not None):
        raise ValueError(
            "note_edits cannot be combined with note_search/note_replace. Use "
            "the single-edit pair for ONE edit, or note_edits for several -- "
            "not both in the same call."
        )

    # Normalize + validate the multi-edit form at the edge. A JSON string of
    # the list is accepted (the ETCH `nodes` precedent -- MCP clients
    # sometimes stringify complex args); the normalized form is a list of
    # plain {"search": str, "replace": str} dicts.
    normalized_edits: list[dict] | None = None
    if note_edits is not None:
        raw_edits = note_edits
        if isinstance(raw_edits, str):
            try:
                raw_edits = json.loads(raw_edits)
            except Exception as e:
                raise ValueError(
                    "note_edits must be a list of {'search', 'replace'?, 'replace_all'?} objects "
                    "(or a JSON string of such a list); the supplied string did "
                    f"not parse as JSON: {e}"
                )
        if not isinstance(raw_edits, list) or not raw_edits:
            raise ValueError(
                "note_edits must be a non-empty list of {'search', 'replace'?, 'replace_all'?} "
                "objects. For a single edit, use note_search + note_replace."
            )
        normalized_edits = []
        for i, item in enumerate(raw_edits):
            if not isinstance(item, dict):
                raise ValueError(
                    f"note_edits[{i}] must be an object {{'search', 'replace'?, 'replace_all'?}}; "
                    f"got {type(item).__name__}."
                )
            # Item-level aliases (_NOTE_EDIT_ITEM_ALIASES, O7RP65) resolve
            # BEFORE the closed-key check, so oldText/newText never reach the
            # unknown-field rejection below.
            item = apply_item_aliases(item, _NOTE_EDIT_ITEM_ALIASES, label=f"note_edits[{i}]")
            # Closed grammar: an unknown key is rejected, never ignored. This
            # matters because an omitted `replace` is a DELETION by contract
            # (single-form parity), so a misspelled key such as 'replacement'
            # or 'new_text' would otherwise silently delete the matched text.
            unknown = sorted(set(item) - {"search", "replace", "replace_all"})
            if unknown:
                hints = []
                for key in unknown:
                    if key in ("replacement", "new_text", "newText", "replace_with", "with"):
                        hints.append(f"  - {key!r}: the replacement text field is 'replace'.")
                    elif key in ("find", "old_text", "oldText", "pattern", "match"):
                        hints.append(f"  - {key!r}: the text-to-find field is 'search'.")
                raise ValueError(
                    f"note_edits[{i}] has unknown field(s): {unknown}. The grammar "
                    "is {'search', 'replace'?, 'replace_all'?} per item (omitted replace == "
                    "deletion), so unknown keys are rejected rather than silently "
                    "ignored -- NO edit was applied."
                    + ("\n" + "\n".join(hints) if hints else "")
                )
            item_search = item.get("search")
            if not isinstance(item_search, str) or item_search == "":
                raise ValueError(
                    f"note_edits[{i}].search must be a non-empty string. An "
                    "empty search string matches at the start of the note; pass "
                    "the text to find."
                )
            item_replace = item.get("replace")
            if item_replace is None:
                item_replace = ""  # omitted/null replace == deletion (single-form parity)
            if not isinstance(item_replace, str):
                raise ValueError(
                    f"note_edits[{i}].replace must be a string, or omitted/null "
                    "for deletion."
                )
            item_replace_all = item.get("replace_all", replace_all)
            if not isinstance(item_replace_all, bool):
                raise ValueError(f"note_edits[{i}].replace_all must be a boolean when supplied.")
            normalized_edits.append({
                "search": item_search, "replace": item_replace, "replace_all": item_replace_all,
            })
        # Disjoint fields name + layout_mode ARE allowed: they ride the same
        # single NodeUpdateRequest the note edits produce, with no conflict.
        # Only note (wholesale replace vs computed note content) and
        # _completed (deprecated here -- use complete_node/uncomplete_node)
        # remain exclusive.
        if note is not None or _completed is not None:
            raise ValueError(
                "note_edits (multi-edit search-and-replace mode) cannot be "
                "combined with note or _completed. The note edits compute the "
                "final note content, so a wholesale note replacement conflicts "
                "with them; use complete_node/uncomplete_node for completion. "
                "(name and layout_mode ARE allowed -- disjoint fields carried "
                "by the same single update call.)"
            )

    if note_search is not None or note_replace is not None:
        if note_search is None:
            raise ValueError(
                "note_replace requires note_search. Pass note_search + note_replace "
                "together to perform a note search-and-replace."
            )
        if note_search == "":
            raise ValueError(
                "note_search must not be empty. An empty search string matches "
                "at the start of the note; pass the non-empty text to find."
            )
        # Same disjoint-field rule as note_edits: name + layout_mode are
        # allowed (they ride the same single update request); only note
        # (conflict) and _completed (deprecated here) remain exclusive.
        if note is not None or _completed is not None:
            raise ValueError(
                "note_search/note_replace (note search-and-replace mode) cannot be "
                "combined with note or _completed. The note edit computes the "
                "final note content, so a wholesale note replacement conflicts "
                "with it; use complete_node/uncomplete_node for completion. "
                "(name and layout_mode ARE allowed -- disjoint fields carried "
                "by the same single update call.)"
            )
        if note_replace is None:
            note_replace = ""

    # NOTE-BODY REDACTION (agent-facing result): Workflowy notes can now serve
    # as full Markdown documents edited via read_node +
    # search-and-replace. Returning the entire document after a small update is
    # analogous to returning a whole file after a tiny file edit: wasteful. So
    # the response preserves shape + metadata but omits the note body. A COPY is
    # made (never mutate the node the client returned, which may already have
    # been patched into the /nodes-export cache); note=None means "omitted from
    # this response", NOT "the stored note was cleared". model_dump() then
    # derives both note=None and the legacy alias no=None from the same field.
    def _redacted_response_node(source: WorkFlowyNode) -> WorkFlowyNode:
        return source.model_copy(update={"note": None})

    client = get_client()

    # ONE live snapshot per write (protected-name policy): note operations
    # needing old text (a public note report or search/replace) AND name composition
    # below BOTH draw from this single memoized fetch -- a combined name+note
    # edit shares ONE basis read and ONE update invocation. UPDATE also owns
    # its final preflight read and existing after-state read. A caller holding a
    # fresh live node injects it via _current_node (anchor.dock.update /
    # anchor.point.assign_id), in which case no GET is issued here at all.
    current_node = _current_node

    async def _fetch_current_node():
        nonlocal current_node
        if current_node is None:
            if _rate_limiter:
                await _rate_limiter.acquire()
            try:
                current_node = await client.get_node(node_id)
                if _rate_limiter:
                    _rate_limiter.on_success()
            except Exception as e:
                if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
                    _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
                raise
        return current_node

    # Resolve the handle via the universal resolver (UUID grace + symbol accept)
    # BEFORE mutating -- see _resolve_mutator_node_id. Fails loudly on
    # ambiguous/unresolved rather than posting a raw id to a zero-tolerance
    # endpoint.
    node_id = await _resolve_mutation_region_handle(node_id, label="workflowy_edit_node", mutator=True)
    # One exact region before the first live read through update return;
    # covered nested callers keep their supplied live snapshot and outer token.
    async with mutation_region_locks(
        client=client, operation_label="node.edit",
        region_factory=lambda snapshot: (build_region_exact_node(node_id, cache_by_id=snapshot.nodes_by_id),),
    ):

        # --- TOUCH channel (anchor.point.touch): choose the content-preserving
        # mechanism from the live node and route it through the EXISTING fields
        # below -- either a layoutMode echo (zero text bytes on the wire) or an
        # identity _tag_transform (the protected-name composer recomposes the
        # same semantic name). Nothing else in this function changes for a touch;
        # the request still goes through the ONE update funnel + write governor.
        if _touch:
            touch_node = await _fetch_current_node()
            if _touch_mechanism_for(touch_node) == "layout_mode_echo":
                layout_mode = touch_node.layoutMode
            else:
                _tag_transform = _touch_identity_tag_transform

        # Public note writes always report, including a header for diff=none.
        # Internal whole-note channels do not implicitly build reports. The
        # before note is live semantic text; the
        # compact per-entry ledger remains exclusive to search/replace.
        search_replace_used = note_search is not None or normalized_edits is not None
        report_note = search_replace_used or return_diff or diff is not None
        diff_mode = diff if diff is not None else "full"
        note_before: str | None = None
        edit_results: list[dict] = []
        edits_applied = 0

        if report_note and not search_replace_used:
            # Whole-note input is already semantic (file input was loaded at the
            # family edge). Decode ONLY the old wire note, sharing this snapshot
            # with protected-name composition. Do not normalize either string for
            # display: inline newlines and the file reader's LF behavior stay intact.
            current_node = await _fetch_current_node()
            note_before = _note_wire_to_semantic(current_node.note or "")

        # --- NOTE SEARCH-AND-REPLACE modes (single + multi) ---
        # When a search-and-replace form is provided, fetch the node's current
        # note via read_node (a live API read — NOT a cache read — so we operate
        # on the freshest text, the same text the agent sees in
        # workflowy_read_node output), apply the edit(s), and use the result as
        # the note for the existing update path. This mirrors the proven
        # get->modify->update pattern already used by the tag tools
        # (workflowy_add_tag et al.). MULTI-EDIT applies every edit IN MEMORY
        # against evolving text: ONE basis read and ONE UPDATE invocation,
        # whose final/read-back checks are shared, not repeated per edit.
        if note_search is not None or normalized_edits is not None:

            # Fetch the current node to get its authoritative note. We use
            # get_node here (live API) rather than the cache, so we never risk
            # operating on a stale note (the user may have edited the node in
            # the Workflowy GUI between cache refreshes). The fetch is the ONE
            # memoized live snapshot shared with the protected-name composition
            # below; it uses the SAME rate-limiter bookkeeping pattern as every
            # other client call in this module.
            current_node = await _fetch_current_node()

            # Decode wire form -> semantic form (ONE entity layer + Workflowy
            # auto-link unwrap; see _note_wire_to_semantic) and normalize
            # newlines (CRLF/CR -> LF) — ONCE, up front. This is the SAME
            # semantic domain the agent sees in the GUI and in
            # read_node output, and the agent can pass
            # \n-delimited strings that match regardless of Workflowy's
            # line-ending convention. The existing encode step inside
            # client.update_node re-encodes the spliced result exactly once. The
            # untouched content round-trips DISPLAY-identically; recognized HTML
            # entities may canonicalize to their decoded Unicode codepoint
            # (e.g. '&nbsp;' -> U+00A0) and a bare '&amp;' may become '&'. That
            # wire-byte normalization is intentional and pre-existing. The evolving
            # text STAYS pure LF across a multi-edit loop because
            # _apply_note_search_replace normalizes every spliced replacement
            # before splicing.
            working_note = _note_wire_to_semantic(current_node.note or "")
            working_note = working_note.replace("\r\n", "\n").replace("\r", "\n")
            # Snapshot the BEFORE text for the diff report (search-and-replace modes).
            note_before = working_note

            def _edit_result_row(
                ordinal: int, idx: int, match_info: dict[str, Any]
            ) -> dict[str, Any]:
                """Build the compact ledger row, adding only non-default diagnostics."""
                row: dict[str, Any] = {
                    "ordinal": ordinal,
                    "matched": idx != -1,
                    "index": idx,
                }
                if match_info.get("replace_all"):
                    row["replace_all"] = True
                    row["replacement_count"] = match_info["replacement_count"]
                if match_info.get("tier"):
                    row["tier"] = match_info["tier"]
                if match_info.get("near_miss"):
                    row["near_miss"] = match_info["near_miss"]
                return row

            if normalized_edits is not None:
                # --- MULTI-EDIT: sequential application over the evolving text.
                # Each edit sees the post-edit text of the previous ones (a later
                # edit CAN match text an earlier edit just inserted — chained
                # transforms are deterministic by design). A miss is a per-edit
                # no-op (skipped + reported), NOT an error. The ledger remains
                # compact on exact matches (ordinal/matched/index only); a
                # space-fold match adds tier=space_fold, while a miss may add one
                # actionable near_miss with the exact suggested retry text.
                edit_results = []
                for i, item in enumerate(normalized_edits):
                    working_note, idx, match_info = _apply_note_search_replace(
                        working_note, item["search"], item["replace"], replace_all=item["replace_all"],
                    )
                    edit_results.append(_edit_result_row(i, idx, match_info))
                edits_applied = sum(1 for row in edit_results if row["matched"])
                if edits_applied == 0 and name is None and layout_mode is None:
                    # Every edit missed AND nothing else to write -> true no-op
                    # fast path (no API write at all).
                    # CF-03: the §6.7 honesty field rides ALL THREE report sites —
                    # a contended no-op still waited, and says so (P5).
                    _noop_metadata: dict[str, Any] = {
                        "success": True,
                        "no_op": True,
                        "note_changed": False,
                        "node_id": node_id,
                        "edits_requested": len(edit_results),
                        "edits_applied": 0,
                        "edits_noop": len(edit_results),
                        "edit_results": edit_results,
                        "note_chars": len(working_note),
                    }
                    _noop_serialization = _mutation_serialization_field()
                    if _noop_serialization is not None:
                        _noop_metadata["serialization"] = _noop_serialization
                    return _render_note_edit_report(_noop_metadata, "")
                if edits_applied > 0:
                    note = working_note
            else:
                # --- SINGLE EDIT: identical semantics to the pre-multi-edit
                # implementation, now via the ONE shared per-edit primitive. The
                # single edit rides the SAME compact report + diff shape as the
                # multi-edit mode (a one-row ledger) so the two search-and-replace
                # modes share ONE response contract.
                new_note, idx, match_info = _apply_note_search_replace(
                    working_note, note_search, note_replace, replace_all=replace_all,
                )
                edit_results = [_edit_result_row(0, idx, match_info)]
                edits_applied = 1 if idx != -1 else 0
                if idx == -1 and name is None and layout_mode is None:
                    # Search text not found AND nothing else to write -> true no-op.
                    # CF-03: the §6.7 honesty field rides this no-op site too (P5).
                    _noop_metadata_single: dict[str, Any] = {
                        "success": True,
                        "no_op": True,
                        "note_changed": False,
                        "node_id": node_id,
                        "edits_requested": 1,
                        "edits_applied": 0,
                        "edits_noop": 1,
                        "edit_results": edit_results,
                        "note_chars": len(working_note),
                    }
                    _noop_serialization_single = _mutation_serialization_field()
                    if _noop_serialization_single is not None:
                        _noop_metadata_single["serialization"] = _noop_serialization_single
                    return _render_note_edit_report(_noop_metadata_single, "")
                if idx != -1:
                    note = new_note

        # --- PROTECTED-NAME COMPOSITION (trailing #tags + leading [ap:] handle) ---
        # Every name write is composed from the ONE live snapshot via the pure
        # _compose_protected_name policy: a caller-supplied name carrying trailing
        # #tags or an added/changed leading [ap:] handle raises
        # ProtectedNameViolation (loud; zero mutation); the existing tags and
        # AP-ID are preserved automatically. The raw GET name is decoded ONE
        # non-cascading entity layer first (the tag tools' double-encode fix).
        # The narrow internal channels are _tag_transform (anchor.dock.update's
        # Dock-locality rewrite), _assign_ap_core (anchor.point.assign_id's
        # reserved-core assignment), _remove_ap_id (anchor.point.remove_id's
        # leading AP-token removal), and _leading_emoji_mutation
        # (the node emoji verbs' ordinary-name-section mutation) --
        # never a generic infrastructure bypass.
        if (
            name is not None
            or _tag_transform is not None
            or _assign_ap_core is not None
            or _remove_ap_id
            or _leading_emoji_mutation is not None
        ):
            node_for_name = await _fetch_current_node()
            current_semantic_name = _semantic_name_for_tag_merge(node_for_name.name or "")
            name = _compose_protected_name(
                current_semantic_name=current_semantic_name,
                requested_name=name,
                tag_transform=_tag_transform,
                assign_ap_core=_assign_ap_core,
                remove_ap_id=_remove_ap_id,
                leading_emoji_mutation=_leading_emoji_mutation,
                replace_leading_emoji=_replace_leading_emoji,
            )["name"]

        # Text writers retain the original raw snapshot, including an injected
        # source captured before extraction creates. Layout-only needs no basis.
        basis = None
        if name is not None or note is not None:
            basis_node = await _fetch_current_node()
            basis = {field: getattr(basis_node, field) for field, value in (("name", name), ("note", note)) if value is not None}
        request = NodeUpdateRequest(  # type: ignore[call-arg]
            name=name,
            note=note,
            layoutMode=layout_mode,
        )

        if _rate_limiter:
            await _rate_limiter.acquire()

        try:
            node = await client.update_node(node_id, request, basis=basis)
            if _rate_limiter:
                _rate_limiter.on_success()
            if report_note:
                # The same selected-report contract serves all public whole-note
                # replacements, without inventing search/replace ledger rows.
                # Identical replacement still invoked update_node: no_op is false,
                # independently of note_changed and the (possibly empty) diff.
                note_changed = note is not None and note != note_before
                metadata = {
                    "success": True,
                    "no_op": False,
                    "note_changed": note_changed,
                    "node_id": node_id,
                    "note_chars": len(note if note is not None else note_before),
                }
                if search_replace_used:
                    metadata.update({
                        "edits_requested": len(edit_results),
                        "edits_applied": edits_applied,
                        "edits_noop": len(edit_results) - edits_applied,
                        "edit_results": edit_results,
                    })
                # U01 §6.7/A3: the note-edit report is a STRING — its
                # honesty field rides INSIDE the JSON metadata header
                # (CF-03: the third of the three report sites). Absent
                # when uncontended — the header is byte-identical (§10).
                _serialization = _mutation_serialization_field()
                if _serialization is not None:
                    metadata["serialization"] = _serialization
                rendered_diff = (
                    _render_note_unified_diff(note_before, note, mode=diff_mode)
                    if note_changed and diff_mode != "none" else ""
                )
                return _render_note_edit_report(metadata, rendered_diff)
            if _touch:
                # The touch caller verifies byte preservation (name, note, position,
                # completion) against its pre-write snapshot: hand back the server's
                # post-write GET node unredacted. This is an internal channel, never
                # an agent-facing node.edit response.
                return node
            return _redacted_response_node(node)
        except Exception as e:
            if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
                _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
            raise


# Layout modes NodeUpdateRequest.layoutMode accepts (its Literal), i.e. the
# modes a touch may echo back verbatim. A live node carrying any other/absent
# layoutMode falls back to the identity-name mechanism instead of inventing
# a mode. A test locks this tuple against the request model's Literal.
_TOUCH_ECHO_LAYOUT_MODES: tuple[str, ...] = ("bullets", "todo", "h1", "h2", "h3")


def _touch_mechanism_for(node: Any) -> str:
    """Pure: which content-preserving touch mechanism a live node admits.

    ``'layout_mode_echo'`` when ``node.data.layoutMode`` is one of
    :data:`_TOUCH_ECHO_LAYOUT_MODES` (POST ``{layoutMode: <same>}``, zero text
    bytes); otherwise ``'name_identity'`` (POST ``{name: <same semantic
    name>}`` via the protected-name composer's identity tag transform).
    Shared by the ``_node_edit_core`` ``_touch`` channel and the
    ``anchor.point.touch`` ledger so the reported mechanism can never drift
    from the executed one.
    """
    data = getattr(node, "data", None)
    mode = data.get("layoutMode") if isinstance(data, dict) else None
    return "layout_mode_echo" if mode in _TOUCH_ECHO_LAYOUT_MODES else "name_identity"


def _touch_identity_tag_transform(tags: list[str]) -> list[str]:
    """Identity ``list -> list`` transform: recompose the same tags (touch fallback)."""
    return list(tags)


# @beacon[
#   id=server@_node_mutate_leading_emoji_impl,
#   slice_labels=nexus-core-v1,nexus--mcp-api,node-ops,
#   kind=ast,
#   comment=All three leading-emoji verbs hold exact_node before their one authoritative live read and covered inner edit; LeadingEmojiMutation preserves AP title and trailing tags, unchanged replacement is a zero-write no-op and the injected snapshot is never fetched twice.,
# ]
async def _node_mutate_leading_emoji_impl(
    node_handle: str,
    emoji: str,
    *,
    mode: Literal["replace", "prepend", "append"],
) -> dict:
    """One exact-node region spans the live read and covered inner edit."""

    verb = {
        "replace": "update_emoji",
        "prepend": "prepend_emoji",
        "append": "append_emoji",
    }[mode]
    resolved = await _resolve_mutation_region_handle(
        node_handle, label=f"node.{verb} (node_handle)", mutator=True,
    )
    async with mutation_region_locks(
        client=get_client(), operation_label=f"node.{verb}",
        region_factory=lambda snapshot: (build_region_exact_node(resolved, cache_by_id=snapshot.nodes_by_id),),
    ):
        client = get_client()
        if _rate_limiter:
            await _rate_limiter.acquire()
        try:
            node = await client.get_node(resolved)
            if _rate_limiter:
                _rate_limiter.on_success()
        except Exception as exc:
            if (
                _rate_limiter
                and hasattr(exc, "__class__")
                and exc.__class__.__name__ == "RateLimitError"
            ):
                _rate_limiter.on_rate_limit(getattr(exc, "retry_after", None))
            raise

        old_name = _semantic_name_for_tag_merge(node.name or "")
        mutation = LeadingEmojiMutation(mode=mode, emoji=emoji)
        composed = _compose_protected_name(
            current_semantic_name=old_name,
            leading_emoji_mutation=mutation,
        )
        new_name = composed["name"]
        result = {
            "success": True,
            "node_id": resolved,
            "no_op": new_name == old_name,
            "old_name": old_name,
            "new_name": new_name,
            "emoji": composed.get("emoji") or "",
            "warnings": [],
        }
        if mode != "replace":
            result["added_emoji"] = composed.get("added_emoji") or ""
        if new_name == old_name:
            return result

        await _node_edit_core(
            resolved,
            _leading_emoji_mutation=mutation,
            _current_node=node,
        )
        return result


