# @beacon[
#   id=server@_node_note_concat_impl,
#   slice_labels=node-ops,
#   kind=ast,
#   comment=Append/prepend under one exact-node region, retaining the original raw basis for the checked injected-snapshot edit with no extra basis fetch. Preserve LF decoding, explicit separators and empty-note semantics; UPDATE owns final/read-back verification, with no search sentinel or name/tag rewrite.,
# ]
async def _node_note_concat_impl(
    node_handle: str,
    text: str,
    separator: str = "\n",
    *,
    position: Literal["append", "prepend"],
) -> dict:
    """One region spans the original note basis, concatenation and checked edit."""

    if not isinstance(text, str) or text == "":
        raise ValueError(
            "text must be a non-empty string: an append/prepend with no text "
            "would silently do nothing; pass the part to add."
        )
    if not isinstance(separator, str):
        raise ValueError(
            "separator must be a string (pass \"\" for exact concatenation "
            "with nothing between the parts)."
        )

    verb = "append_note" if position == "append" else "prepend_note"
    resolved = await _resolve_mutation_region_handle(
        node_handle, label=f"node.{verb} (node_handle)", mutator=True,
    )
    async with mutation_region_locks(
        client=get_client(), operation_label=f"node.{verb}",
        region_factory=lambda snapshot: (build_region_exact_node(resolved, cache_by_id=snapshot.nodes_by_id),),
    ):
        node, old_note = await _read_live_node_note(resolved)
        # Same pure-LF normalization the note search-and-replace path applies
        # to its working text after the wire->semantic decode.
        old_note = old_note.replace("\r\n", "\n").replace("\r", "\n")
        # Byte-exact concatenation on the semantic domain; an EMPTY existing
        # note takes the separator nowhere (there is nothing to separate).
        if position == "append":
            new_note = old_note + separator + text if old_note else text
        else:
            new_note = text + separator + old_note if old_note else text
        await _node_edit_core(resolved, note=new_note, _current_node=node)
        from .note_lines import split_note_lines

        return {
            "success": True,
            "node_id": resolved,
            "position": position,
            "note_chars": len(new_note),
            "note_lines": len(split_note_lines(new_note)),
            "added_chars": len(new_note) - len(old_note),
            "warnings": [],
        }


# @beacon[
#   id=server@_node_append_note_impl,
#   role=_node_append_note_impl,
#   slice_labels=node-ops,
#   kind=ast,
#   comment=Thin re-front for node.append_note over the ONE _node_note_concat_impl (position='append'): the text lands AFTER the existing note, joined by the explicit separator (default newline).,
# ]
async def _node_append_note_impl(
    node_handle: str, text: str, separator: str = "\n"
) -> dict:
    """Append text AFTER the node's existing note (separator explicit)."""
    return await _node_note_concat_impl(
        node_handle, text, separator, position="append"
    )


# @beacon[
#   id=server@_node_prepend_note_impl,
#   role=_node_prepend_note_impl,
#   slice_labels=node-ops,
