# @beacon[
#   id=server@live-note-read,
#   slice_labels=nexus--mcp-api,node-ops,ra-snippet-range,
#   kind=ast,
#   comment=THE one rate-limited live GET and wire-to-semantic note decode behind node.read and anchor.point.read. Accepts an already-resolved UUID; returns the live node plus its decoded note without framing, windowing, cache publication or another read. Structured node.read sets decode_note=False to preserve its raw WorkFlowyNode contract. Archive Reads U2 (§4.6): ONE branch before the GET — when the operation's pinned map holds an overlay record for the id, the node is built from the record (WorkFlowyNode.model_validate) and returned with the note VERBATIM: no live GET, no rate-limiter acquire, no wire decode (archive text is cache-semantic; E7), the name the 📦 overlay name. Every note read (node.read, anchor.point.read, dock.get_description, single-node search, estate note reads) inherits it.
# ]
async def _read_live_node_note(
    node_id: str, *, decode_note: bool = True
) -> tuple[WorkFlowyNode, str]:
    """Fetch once and decode once for the note fronts (never a cache note).

    Archive Reads U2 (§4.6): when the current operation's pinned map holds
    an OVERLAY record for this id (the re-run's augmented snapshot, or an
    include run), the node is built from the record and returned with its
    note VERBATIM — no live GET, no rate-limiter acquire, no wire decode
    (E7: archive text is cache-semantic already; the name is the overlay
    name, 📦-marked).  ``decode_note`` is irrelevant on this branch: the
    record's note is served as stored, in both spellings.
    """
    from .archive_context import is_archive_record
    from .coherence.operation_cache import current_operation_cache

    snapshot = current_operation_cache(required=False)
    record = (
        (snapshot.nodes_by_id or {}).get(node_id)
        if snapshot is not None
        else None
    )
    if record is not None and is_archive_record(record):
        node = WorkFlowyNode.model_validate(
            {
                "id": str(record.get("id") or node_id),
                "name": record.get("name"),
                "note": record.get("note"),
                "priority": record.get("priority"),
                "data": record.get("data"),
                "createdAt": record.get("createdAt"),
                "modifiedAt": record.get("modifiedAt"),
                "completedAt": record.get("completedAt"),
                "parentId": record.get("parentId"),
            }
        )
        return node, str(record.get("note") or "")
    if _rate_limiter:
        await _rate_limiter.acquire()
    try:
        node = await get_client().get_node(node_id)
        if _rate_limiter:
            _rate_limiter.on_success()
        note = _note_wire_to_semantic(node.note or "") if decode_note else ""
        return node, note
    except Exception as e:
        if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
            _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
        raise


# Tool: Read Node (single node by UUID, as a document by default)
@_legacy_tool(
    name="workflowy_read_node",
    description=(
        "Read a single WorkFlowy node as a DOCUMENT (name, note, and metadata for "
        "that one node only — does NOT return children). node_id may be a "
        "Workflowy UUID (exact or a unique prefix) OR an [ap:CORE] anchor-point "
        "handle (not a source-code symbol slot); an ambiguous handle returns a "
        "disambiguation list. For reading whole subtrees, prefer workflowy_glimpse "
        "(GLIMPSE) or workflowy_scry (SCRY); this is the lightweight single-node "
        "read.\n\n"
        "DEFAULT (as_raw_node=True): return the note as a raw plain-text string "
        "(like readTextSnippet or readFile) -- the note is treated as a full "
        "Markdown DOCUMENT. Format: first line '[name: not editable] <name>', "
        "blank line, then note contents with ONE layer of HTML entities decoded "
        "(the semantic, GUI-visible form; Workflowy auto-link wrappers are "
        "unwrapped back to bare URLs). This is the form to read when composing "
        "note_search / note_edits text for workflowy_edit_node -- what you see is "
        "exactly what the search matches.\n\n"
        "as_raw_node=False: return the structured WorkFlowyNode object instead."
    ),
)
# @beacon[
#   id=server@get_node,
#   role=⚡ read_node(node_id: str, as_raw_node: bool, output_file),
#   slice_labels=nexus-core-v1,nexus--mcp-api,node-ops,
#   kind=ast,
#   comment=Single-node front over _read_live_node_note (ONE rate-limited fetch/decode with anchor.point.read) and snippet_view.render_note_body (ONE guard/window/number/exact body with anchor.point.read). Shared validate_note_read_lines validates before I/O; only the banner differs between fronts. Optional output_file atomically writes ONLY the exact decoded note as strict UTF-8, never framing/advisories. Public view= keeps the 400-line guard and size_only via render_guarded_note_view/render_guarded_lines; internal view=None stays unguarded, and structured/file output is never guarded. No cache or journal writes.,
# ]
async def _node_read_impl(
    node_id: str,
    as_raw_node: bool = True,
    *,
    output_file: str | None = None,
    offset: int | None = None,
    limit: int | None = None,
    with_line_numbers: bool = False,
    view: SnippetViewOptions | None = None,
) -> WorkFlowyNode | str | dict[str, Any]:
    """Read a single WorkFlowy node, optionally saving only its note to disk.

    Returns the node's own name/note/metadata only (not its children). Use
    GLIMPSE or SCRY when you need a full subtree.

    Args:
        node_id: Exact UUID, unique prefix, or [ap:CORE] handle.
        as_raw_node: When True (the default), return the note as a raw
            plain-text string (first line: '[name: not editable] <name>',
            blank line, then note contents with ONE layer of HTML entities
            decoded -- the semantic, GUI-visible form). This treats the note as
            a full Markdown document and is the form to read when composing
            note_search / note_edits text for workflowy_edit_node. When False,
            return the structured WorkFlowyNode object.
        output_file: Optional non-blank path. Requires as_raw_node=True.
            Writes ONLY the note string using the same canonical wire decode
            as an ordinary read: no name banner, advisory, metadata stripping,
            Markdown rendering, heading changes, or added/truncated whitespace.
            Strict UTF-8, no BOM or newline translation. The parent directory
            must exist. Atomically replaces an existing destination only after
            encoding and writing succeed; failures leave it untouched.

        offset: Nonnegative count of note-body lines to skip (0-based).
        limit: Positive maximum line count, or None to read through EOF.
        with_line_numbers: Display 1-based, right-aligned note line numbers.
            A window (offset > 0 or limit not None) omits the name banner.
            Numbering alone keeps the banner outside the numbered note body.
            Line mode normalizes terminators via split_note_lines; ordinary
            reads and output_file keep their exact pre-existing byte contract.
        view: The shared note-read guard plan (snippet_view.normalize_note_view_params,
            passed by the PUBLIC read front only). A whole-note read longer
            than view.max_lines (default 400 = 300 head + 100 tail; 0 opts
            out) returns the name banner, the one-line "note:" size header,
            the head rows, ONE elision row naming the hidden range and the
            start_line/end_line window that reads it back, and the tail rows;
            size_only returns the header alone. Explicit windows and
            output_file are never guarded. Internal callers pass None (the
            default) and read unguarded — the guard lives at the public
            front, one implementation with beacon.snippet.

    Returns:
        Raw document text, the structured node when as_raw_node=False, or a
        small file-write acknowledgement when output_file is supplied. System
        advisories remain on that acknowledgement through the existing dispatch
        finalizer; they are NEVER inserted into the exported note.
    """
    from .mcp_api_registry import OperationValidationError

    # None is the internal omitted-offset sentinel (effective skip is zero).
    # Keeping presence here gives the family and legacy front ONE validation
    # authority, including explicit offset=0 with structured/file output.
    line_requested = offset is not None or limit is not None or with_line_numbers
    offset = validate_note_read_lines(offset, limit, with_line_numbers)
    if view is not None and (not as_raw_node or output_file is not None):
        raise OperationValidationError(
            "invalid_parameter_combination",
            "view applies to the raw document read only; it cannot be combined with as_raw_node=false or output_file",
        )
    windowed = offset > 0 or limit is not None
    if line_requested and (not as_raw_node or output_file is not None):
        raise OperationValidationError(
            "invalid_parameter_combination",
            "Line options require as_raw_node=true and cannot be combined with output_file",
        )
    path_resolution = None
    if output_file is not None:
        if not isinstance(output_file, str) or not output_file.strip():
            raise OperationValidationError(
                "invalid_parameter_type", "output_file must be a non-blank path string"
            )
        if not as_raw_node:
            raise OperationValidationError(
                "invalid_parameter_combination",
                "output_file exports the Markdown note only; it requires as_raw_node=true",
            )
        # Host-aware resolution AFTER the existing validation and BEFORE
        # client.get_node (§13 row 1 — a refused output_file fails with zero
        # API calls). ToolPathError propagates → the kernel's operation_failed
        # envelope carries the teaching message, as its OSErrors surface today
        # (§6.7).
        path_resolution = resolve_tool_path(
            output_file, param="output_file", context="node.read", direction="write"
        )

    # Resolve the handle at the boundary via the narrow generic-node resolver
    # (UUID / unique prefix / [ap:CORE] AP-ID; NO symbol) BEFORE the raw read --
    # read_node targets a plain Workflowy node, so a code-symbol slot would be a
    # footgun. Ambiguous/unresolved raises; the raw client.get_node stays
    # exact-UUID-only.
    node_id = await _resolve_generic_node_handle(node_id, label="workflowy_read_node")

    node, note = await _read_live_node_note(node_id, decode_note=as_raw_node)
    try:
        if as_raw_node:
            name = node.name or ""
            if output_file is not None:
                import tempfile
                from pathlib import Path

                # Encode BEFORE creating/opening any file. Never use replacement
                # characters, ignored errors, or surrogatepass: invalid Unicode
                # fails loudly rather than exporting corrupt UTF-8 or losing text.
                payload = note.encode("utf-8")
                # The atomic temp+os.replace contract is preserved byte for
                # byte (I6) — only on the RESOLVED destination; the temp-file
                # naming derives from the resolved path (P-permitted internal).
                destination = Path(path_resolution.resolved)
                temporary = None
                try:
                    # Same-directory temp + replace is an artifact delivery only,
                    # not a Cartographer mutation or a cache/journal publication.
                    with tempfile.NamedTemporaryFile(
                        mode="wb", dir=destination.parent,
                        prefix=f".{destination.name}.", suffix=".tmp", delete=False,
                    ) as handle:
                        temporary = Path(handle.name)
                        handle.write(payload)
                        handle.flush()
                        os.fsync(handle.fileno())
                    os.replace(temporary, destination)
                finally:
                    if temporary is not None:
                        temporary.unlink(missing_ok=True)
                return {
                    "success": True,
                    "node_id": node_id,
                    # P3 argument echo: REQUESTED byte-identical; the RESOLVED
                    # string rides the path_record only.
                    "output_file": output_file,
                    "bytes_written": len(payload),
                    "encoding": "utf-8",
                    "path_record": path_resolution.as_dict(),
                }
            body = render_note_body(note, offset, limit, with_line_numbers, view, windowed)
            if windowed:
                return body
            return f"[name: not editable] {name}\n\n{body}"

        return node
    except Exception as e:
        if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
            _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
        raise


