# @beacon[
#   id=server@delete_node,
#   role=delete_node,
#   slice_labels=nexus-core-v1,node-ops,
#   kind=ast,
#   comment=Delete holds subtree(target) and the proof-current former parent's child list through the existing governed cascade; no atomic-API exception to descendant exclusion.,
# ]
async def _node_delete_impl(node_id: str) -> dict:
    """Delete under subtree(target) plus its current former-parent child list.

    Args:
        node_id: The ID of the node to delete

    Returns:
        Dictionary with success status
    """
    client = get_client()

    node_id = await _resolve_mutation_region_handle(node_id, label="workflowy_delete_node", mutator=True)
    async with mutation_region_locks(
        client=client, operation_label="node.delete",
        region_factory=lambda snapshot: (
            build_region_subtree(node_id, cache_by_id=snapshot.nodes_by_id),
            *_mutation_parent_regions(_pinned_parent_id_for_lock(node_id, snapshot=snapshot), snapshot=snapshot),
        ),
    ):

        if _rate_limiter:
            await _rate_limiter.acquire()

        try:
            success = await client.delete_node(node_id)
            if _rate_limiter:
                _rate_limiter.on_success()
            return {"success": success, "deleted_id": node_id}
        except Exception as e:
            if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
                _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
            raise


# @beacon[
#   id=node-children@set-completion,
#   slice_labels=nexus--mcp-api,nexus-core-v1,node-ops,
#   kind=ast,
#   comment=Complete/uncomplete holds only exact_node(target); the informational pinned child count stays inside the hold and the existing governed mutation and compact acknowledgement remain unchanged.,
# ]
async def _node_set_completion_impl(node_id: str, *, completed: bool) -> dict[str, Any]:
    """Change completion under exact-node ownership and report source children.

    child_count includes ALL direct children in the pinned operation cache;
    null means the node was absent, not zero. This acknowledgement is not a
    guard/transaction and does not change the existing completion semantics.
    """
    from .coherence.operation_cache import current_operation_cache
    from .node_child_counts import build_direct_child_counts

    client = get_client()
    label = "workflowy_complete_node" if completed else "workflowy_uncomplete_node"
    node_id = await _resolve_mutation_region_handle(node_id, label=label, mutator=True)
    async with mutation_region_locks(
        client=client, operation_label=label,
        region_factory=lambda snapshot: (build_region_exact_node(node_id, cache_by_id=snapshot.nodes_by_id),),
    ):
        child_count = build_direct_child_counts(current_operation_cache().view.nodes_by_id).get(node_id)
        if _rate_limiter:
            await _rate_limiter.acquire()
        try:
            node = await (client.complete_node(node_id) if completed else client.uncomplete_node(node_id))
            if _rate_limiter:
                _rate_limiter.on_success()
            # Closed acknowledgement shape: even nested `data`, `children` or
            # legacy aliases cannot smuggle a giant note back into the response.
            return {
                "id": node.id, "name": node.name, "completed": node.cp,
                "completedAt": node.completedAt, "modifiedAt": node.modifiedAt,
                "child_count": child_count, "child_count_source": "operation_cache",
            }
        except Exception as e:
            if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
                _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
            raise


