# Tool: Move Node
@_legacy_tool(
    name="workflowy_move_node",
    description=(
        "Move a WorkFlowy node to a new parent. node_id may be a Workflowy UUID "
        "(exact or a unique prefix), an [ap:CORE] anchor-point handle, OR a "
        "source-code SYMBOL (function / class / AST_QUALNAME / beacon id); it is "
        "resolved to a single node before the move (ambiguous/unresolved fails "
        "loudly, moving nothing). parent_id likewise accepts a UUID / UUID-prefix / "
        "[ap:CORE] handle / symbol, OR a special target key such as 'inbox', OR "
        "None for root; a special key or None passes through unchanged."
    ),
)
# @beacon[
#   id=server@move_node,
#   role=⚡ move_node(node_id: str, parent_id, position: str),
#   slice_labels=nexus-core-v1,node-ops,
#   kind=ast,
#   comment=Required target/destination resolution precedes exact_node(target) plus proof-current old/new child-list ownership; root and Inbox retain wire sentinels and MOVE deliberately commutes with capture under the moved node.,
# ]
async def _node_move_impl(
    node_id: str,
    parent_id: str | None = None,
    position: str = "top",
) -> bool:
    """Move under exact target plus both current parent child-list regions.
    
    Args:
        node_id: The ID of the node to move
        parent_id: The new parent node ID (UUID, target key like 'inbox', or None for root)
        position: Where to place the node ('top' or 'bottom', default 'top')
        
    Returns:
        True if move was successful
    """
    client = get_client()

    node_id = await _resolve_mutation_region_handle(
        node_id, label="workflowy_move_node (node_id)", mutator=True,
    )
    if parent_id is None or (isinstance(parent_id, str) and not parent_id.strip()):
        destination = ReservedMutationParent.ROOT
    elif isinstance(parent_id, str) and parent_id.strip().lower() == "inbox":
        parent_id = "inbox"
        destination = ReservedMutationParent.INBOX
    else:
        parent_id = await _resolve_mutation_region_handle(
            parent_id,
            label="workflowy_move_node (parent_id)",
            role="parent", mutator=True,
        )
        destination = parent_id
    async with mutation_region_locks(
        client=client, operation_label="node.move",
        region_factory=lambda snapshot: (
            build_region_exact_node(node_id, cache_by_id=snapshot.nodes_by_id),
            *_mutation_parent_regions(_pinned_parent_id_for_lock(node_id, snapshot=snapshot), snapshot=snapshot),
            *_mutation_parent_regions(destination, snapshot=snapshot),
        ),
    ):

        if _rate_limiter:
            await _rate_limiter.acquire()

        try:
            success = await client.move_node(node_id, parent_id, position)
            if _rate_limiter:
                _rate_limiter.on_success()
            return success
        except Exception as e:
            if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
                _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
            raise

# @beacon-close[
#   id=svcv1@compat-warning-layer,
# ]
# CORE V1 KEEPER:
# Export-node and explicit nodes-export cache refresh are core utilities around
# the public Workflowy surface and cached Ether semantics.
# @beacon[
#   id=svcv1@export-and-cache-core,
#   role=core keeper: export-node and explicit nodes-export cache utilities,
#   slice_labels=nexus-portability,nexus-core-v1,
#   kind=span,
#   show_span=false,
# ]
# Tool: Export Nodes
@_legacy_tool(
    name="workflowy_export_node",
    description=(
        "Export a WorkFlowy node with all its children. node_id may be a Workflowy "
        "UUID (exact or a unique prefix) OR an [ap:CORE] anchor-point handle (not a "
        "source-code symbol slot); omit it entirely to export ALL nodes. An "
        "ambiguous handle returns a disambiguation list."
    ),
)
# @beacon[
#   id=server@export_node,
#   role=⚡ export_node(node_id, output_file, archive_name, archive_description),
#   slice_labels=nexus-core-v1,node-ops,
#   kind=ast,
# ]
async def _node_export_impl(
    node_id: str | None = None,
    *,
    output_file: str | None = None,
    archive_name: str | None = None,
    archive_description: str | None = None,
) -> dict:
    """Export all nodes or filter to specific node's subtree.

    Args:
        node_id: ID of the node to export (omit to export all nodes).
                 If provided, exports only that node and all its descendants.
        output_file: Optional non-blank path. When supplied, the export is
                 written as ONE verified workflowy-nexus-archive file (the
                 nodes-export records plus an ``archive`` metadata block)
                 and the call answers a small acknowledgement carrying
                 ``verified: true`` -- never the nodes. The archive reads
                 the local cache only: run system.cache.refresh first to
                 include recent GUI edits.
        archive_name: archive.name in the file (default: the root record's
                 name, or "Workflowy vault" for the whole vault).
        archive_description: archive.description in the file.

    Returns:
        Without output_file: dictionary containing 'nodes' list with
        exported node data (unchanged). With output_file: the archive
        acknowledgement. Rate limit: 1 request per minute for full export.
    """
    # S1: type checks, before any path, cache or client call.
    if output_file is not None and (
        not isinstance(output_file, str) or not output_file.strip()
    ):
        raise OperationValidationError(
            "invalid_parameter_type",
            "output_file must be a non-blank path string",
        )
    if archive_name is not None and not isinstance(archive_name, str):
        raise OperationValidationError(
            "invalid_parameter_type", "archive_name must be a string or null"
        )
    if archive_description is not None and not isinstance(archive_description, str):
        raise OperationValidationError(
            "invalid_parameter_type",
            "archive_description must be a string or null",
        )
    if output_file is not None and isinstance(node_id, str) and not node_id.strip():
        raise OperationValidationError(
            "invalid_parameter_type",
            "node_handle must be a non-blank string when output_file is "
            "supplied; omit it (or pass null) to export the whole vault",
        )

    # S2: combination check.
    if output_file is None and (
        archive_name is not None or archive_description is not None
    ):
        raise OperationValidationError(
            "invalid_parameter_combination",
            "archive_name and archive_description require output_file",
        )

    # S4: host-aware resolution BEFORE any cache or client call -- a refused
    # path fails with zero reads and zero bytes written anywhere.
    path_resolution = None
    if output_file is not None:
        path_resolution = resolve_tool_path(
            output_file,
            param="output_file",
            context="node.export",
            direction="write",
        )
        # S5: destination checks -- the only filesystem reads before the cache
        # is read. The durable writer would create missing parent directories;
        # this tool refuses them instead (matching node.read).
        if os.path.isdir(path_resolution.resolved):
            raise ToolPathError(
                f"node.export output_file: {output_file} names a directory; "
                "nothing was written"
            )
        parent_dir = os.path.dirname(path_resolution.resolved)
        if not os.path.isdir(parent_dir):
            raise ToolPathError(
                f"node.export output_file: parent directory {parent_dir} does "
                "not exist; create it first; nothing was written"
            )

    client = get_client()

    # S6: resolve the handle at the boundary (UUID / unique prefix / [ap:CORE]
    # AP-ID; NO symbol) BEFORE the raw export. node_id is OPTIONAL here: None /
    # '' means "export ALL nodes", so only resolve when a handle was actually
    # supplied -- a bare export-all must pass straight through untouched.
    # (With output_file a blank string was already refused at S1.)
    if node_id is not None and str(node_id).strip():
        node_id = await _resolve_generic_node_handle(
            node_id, label="workflowy_export_node"
        )

    # S7: the one selection call, shared by the in-band and archive paths.
    if _rate_limiter:
        await _rate_limiter.acquire()

    try:
        data = await client.export_nodes(node_id)
        if _rate_limiter:
            _rate_limiter.on_success()
    except Exception as e:
        if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
            _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
        raise

    # S3: without output_file, today's in-band result, byte for byte.
    if output_file is None:
        return data

    return _write_node_export_archive(
        client,
        data,
        node_id=node_id,
        requested_output_file=output_file,
        path_resolution=path_resolution,
        archive_name=archive_name,
        archive_description=archive_description,
    )


# @beacon[
#   id=server@write_node_export_archive,
#   slice_labels=node-ops,
#   kind=ast,
#   comment=The output_file half of node.export: one pure cache read that builds the workflowy-nexus-archive document through the format authority, verifies it BEFORE the write (parse-back plus value-for-value comparison with the pinned view), writes it atomically through the ONE durable text writer, then reads the file back and demands byte identity. verified:true is Dan's signal that deleting the source is safe -- every refusal keeps the destination untouched, and a read-back mismatch reports the file UNVERIFIED (left in place, never trusted). No refresh, no Workflowy write, no cache/journal/epoch publication.,
# ]
def _write_node_export_archive(
    client,
    data: dict,
    *,
    node_id: str | None,
    requested_output_file: str,
    path_resolution,
    archive_name: str | None,
    archive_description: str | None,
) -> dict:
    """Build, verify, write and re-verify one workflowy-nexus-archive file.

    Pure cache read: no refresh, no Workflowy write, no cache, journal or
    epoch publication, no mutation of anything the pinned view owns.  A
    failure before the write leaves the destination untouched; a post-write
    read-back mismatch reports the file UNVERIFIED (it stays in place and
    is never grounds for deleting the source).
    """
    from datetime import timezone

    from .coherence.operation_cache import current_operation_cache

    unverified_prefix = (
        f"node.export: the archive for {requested_output_file} is UNVERIFIED; "
        "do not delete the source. "
    )

    # S8: provenance -- the pinned snapshot the selection was served from
    # (S7 succeeded without the internal refresh guard, so this snapshot
    # exists and its view IS the generation the records came from).
    snapshot = current_operation_cache(required=True)
    view = snapshot.view
    source_cache = {
        "epoch_number": view.epoch_number,
        "epoch_id": view.epoch_id,
        "adopted_sequence": view.adopted_sequence,
    }

    # S9: membership check -- a handle absent from the pinned view is a loud
    # error, never an empty archive.
    records = data["nodes"]
    if node_id is not None:
        present_ids = {record.get("id") for record in records}
        if node_id not in present_ids:
            raise NetworkError(
                f"nodes-export cache does not include requested node {node_id}; "
                "run system.cache.refresh "
                "(workflowy_refresh_nodes_export_cache) and retry. "
                "Nothing was written."
            )

    # S10-S11: the ordered document, built by the one format authority.
    exported_at = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    document = build_archive_document(
        records,
        nest=client._build_hierarchy,
        node_id=node_id,
        name=archive_name,
        description=archive_description,
        exported_at=exported_at,
        source_cache=source_cache,
    )

    # S12: serialize once; the same bytes are verified, written and read back.
    text = serialize_archive(document)
    try:
        payload = text.encode("utf-8")
    except UnicodeEncodeError as exc:
        raise ArchiveError(
            f"archive text is not encodable as strict UTF-8: {exc}; "
            "nothing was written"
        ) from exc

    # S13: pre-write verification -- the serialized text is parsed back by
    # the format authority's reader and every parsed record is compared with
    # the pinned view's record, value for value.  Any failure is loud and
    # nothing has been written.
    try:
        parsed = parse_archive(payload, nest=client._build_hierarchy)
    except ArchiveFormatError as exc:
        raise ArchiveVerificationError(
            unverified_prefix + f"pre-write parse failed: {exc}"
        ) from exc
    if parsed != document:
        raise ArchiveVerificationError(
            unverified_prefix
            + "the parsed document differs from the built document"
        )
    parsed_by_id = {record["id"]: record for record in parsed["nodes"]}
    source_by_id = {record["id"]: record for record in records}
    if len(parsed["nodes"]) != len(records) or parsed_by_id != source_by_id:
        raise ArchiveVerificationError(
            unverified_prefix
            + "the parsed records differ from the pinned view's records"
        )
    if node_id is not None and parsed["archive"]["root_ids"] != [node_id]:
        raise ArchiveVerificationError(
            unverified_prefix
            + f"root_ids {parsed['archive']['root_ids']!r} != [{node_id!r}]"
        )

    # S14: the one durable write -- atomic replace, never a partial file.
    atomic_write_text(path_resolution.resolved, text, sync_parent_dir=True)

    # S15: post-write verification -- the file on disk must be byte-identical
    # to the verified bytes.  On a mismatch the file stays in place, reported
    # as untrustworthy.
    written = Path(path_resolution.resolved).read_bytes()
    if written != payload:
        raise ArchiveVerificationError(
            unverified_prefix
            + "the file on disk differs from the verified bytes; it must not "
            "be trusted or used as grounds to delete the source; the file "
            "was left in place"
        )

    # S16: the acknowledgement -- small, and never the nodes.
    return {
        "success": True,
        "output_file": requested_output_file,
        "path_record": path_resolution.as_dict(),
        "node_id": node_id,
        "root_ids": document["archive"]["root_ids"],
        "node_count": document["archive"]["node_count"],
        "bytes_written": len(payload),
        "nodes_sha256": document["archive"]["nodes_sha256"],
        "format": ARCHIVE_FORMAT,
        "format_version": ARCHIVE_FORMAT_VERSION,
        "verified": True,
    }


# @beacon[
#   id=auto-beacon@workflowy_refresh_nodes_export_cache-4u9w,
#   role=⚡ workflowy_refresh_nodes_export_cache(),
#   slice_labels=ra-workflowy-cache,
#   kind=ast,
# ]
async def _system_cache_refresh_impl() -> dict:
    """Explicitly refresh the cached /nodes-export snapshot.

    S02: this is a REQUIRED full-refresh request — it routes through the
    account-scoped coherence refresh authority (kind ``system``), waits for
    the authoritative epoch result, and ignores the cache-refresh skip
    toggle unconditionally.  The result carries the legacy success/count
    fields plus additive coherence metadata (epoch, watermark, dedupe).
    """
    client = get_client()

    if _rate_limiter:
        await _rate_limiter.acquire()

    try:
        result = await client.refresh_nodes_export_cache(refresh_kind="system")
        if _rate_limiter:
            _rate_limiter.on_success()
        return result
    except Exception as e:  # noqa: BLE001
        return {"success": False, "error": str(e)}


# Tool: NEXUS PING (no-op health check; touches nothing)
# @beacon[
#   id=server@nexus_ping,
#   role=⚡ nexus_ping(),
#   slice_labels=nexus-loading-flow,
#   kind=ast,
#   comment=Pure-Python health/install validation with the immutable startup source identity and current daemon phase; no per-ping metadata scan cache read refresh API call or WebSocket activity.,
# ]
async def _system_ping_impl() -> dict:
    """Lightweight liveness and install-validation check.

    Returns a small payload describing the running MCP server process:
    package name, package version, on-disk install path of the loaded
    package, the Python interpreter that's running it, the process id,
    and the number of MCP tools currently registered on the FastMCP
    instance.

    No external systems are touched:
      - No Workflowy API call.
      - No /nodes-export cache read or refresh.
      - No per-ping filesystem/installer scan beyond resolving the loaded
        package's own ``__file__`` path; identity was captured at startup.
      - No WebSocket activity.

    Use cases:
      - Verify that a fresh ``pip install`` of workflowy-nexus-mcp-tools
        resolved correctly and the package is importable.
      - Verify that FastMCP successfully registered every ``@mcp.tool``
        decorator at startup (a non-zero ``registered_tool_count`` proves
        registration ran).
      - Verify which copy of the package is actually loaded when multiple
        installations exist on the same machine (e.g. comparing a fresh
        venv install against a long-standing editable install).
      - End-to-end smoke test that JSON-RPC dispatch is working between
        the MCP host/connector and this server process.
    """
    import os as _os
    import sys as _sys
    from pathlib import Path as _Path

    import workflowy_mcp as _wfm_pkg
    from .daemon_identity import installed_identity

    identity = installed_identity()
    controller = daemon_lifecycle.active_lifecycle()

    # Best-effort registered-tool count. FastMCP versions vary in how
    # tools are exposed on the instance; try a few known shapes and fall
    # back to None rather than raising.
    registered_tool_count: int | None = None
    try:
        tool_manager = getattr(mcp, "_tool_manager", None)
        if tool_manager is not None:
            tools_attr = getattr(tool_manager, "_tools", None)
            if tools_attr is None:
                tools_attr = getattr(tool_manager, "tools", None)
            if tools_attr is not None:
                try:
                    registered_tool_count = len(tools_attr)
                except TypeError:
                    registered_tool_count = None
        if registered_tool_count is None:
            # FastMCP >= some-version exposes list_tools() as an async helper.
            list_tools = getattr(mcp, "list_tools", None)
            if callable(list_tools):
                tools_list = await list_tools()
                try:
                    registered_tool_count = len(tools_list)
                except TypeError:
                    registered_tool_count = None
    except Exception:  # noqa: BLE001 - never let ping fail
        registered_tool_count = None

    try:
        package_path = str(_Path(_wfm_pkg.__file__).resolve().parent)
    except Exception:  # noqa: BLE001
        package_path = "<unknown>"

    return {
        "ok": True,
        "package_name": "workflowy_mcp",
        "package_version": getattr(_wfm_pkg, "__version__", "<unknown>"),
        "package_path": package_path,
        "python_executable": _sys.executable,
        "python_version": _sys.version.split()[0],
        "pid": _os.getpid(),
        "registered_tool_count": registered_tool_count,
        "package_commit": identity.commit,
        "package_commit_time": identity.commit_time,
        "daemon": controller.metadata() if controller is not None else None,
        "identity_warnings": [warning.payload() for warning in identity.warnings],
    }


# ---------------------------------------------------------------------------
# Archive Reads U3 — the archive inventory and mount verbs (§U3.2 D4–D5)
# ---------------------------------------------------------------------------


def _archives_inventory_row_text(entry) -> str:
    """One §5.12 compact inventory row (fields per §U3.2 D4)."""

    root_id = entry.root_ids[0] if entry.root_ids else ""
    root_display = root_id[:8] if root_id else "-"
    if entry.root_ap_id:
        root_display = f"{root_display} [ap:{entry.root_ap_id}]"
    planted = "top level"
    if entry.planted_parent_id:
        planted = f"{entry.planted_parent_id[:8]} {entry.planted_under_name or ''}".strip()
    source_parent = entry.source_parent_id[:8] if entry.source_parent_id else "-"
    mount_parent = entry.mount_parent_id[:8] if entry.mount_parent_id else "-"
    return (
        f"{entry.name} · {entry.state} · {entry.reason or '-'}"
        f" · name: {entry.archive_name or '-'}"
        f" · exported {entry.exported_at or '-'}"
        f" · scope {entry.scope or '-'}"
        f" · root {root_display}"
        f" · {entry.node_count} node(s), {entry.visible_count} visible"
        f" · planted under {planted}"
        f" · source parent {source_parent} · mount parent {mount_parent}"
    )


def _archives_inventory_row_dict(entry) -> dict:
    """One full-detail inventory row: exactly the §U3.2 D4 fields."""

    root_id = entry.root_ids[0] if entry.root_ids else None
    root_display = root_id[:8] if root_id else None
    if root_display and entry.root_ap_id:
        root_display = f"{root_display} [ap:{entry.root_ap_id}]"
    if entry.planted_parent_id:
        planted_under = (
            f"{entry.planted_parent_id[:8]} {entry.planted_under_name or ''}".strip()
        )
    else:
        planted_under = "top level"
    return {
        "file": entry.name,
        "state": entry.state,
        "reason": entry.reason,
        "archive_name": entry.archive_name,
        "exported_at": entry.exported_at,
        "scope": entry.scope,
        "root": root_display,
        "node_count": entry.node_count,
        "visible_count": entry.visible_count,
        "planted_under": planted_under,
        "source_parent_id": entry.source_parent_id,
        "mount_parent_id": entry.mount_parent_id,
    }


async def _archives_settings_pull_once() -> None:
    """The zero-wait settings read (§U3.2 D4): when a tab is connected,
    read the extension settings once (no grace wait) and remember the
    reported archive folder; with no tab, or on any failure, fall back to
    the remembered value silently.  Never raises, never waits."""

    import os as _os

    try:
        client = get_client()
        ws_conn, ws_queue = await get_ws_connection_with_grace_wait(max_wait_seconds=0.0)
        if not (ws_conn and ws_queue):
            return
        reply = await client.get_extension_settings(
            ws_connection=ws_conn,
            ws_queue=ws_queue,
            target_tab=None,
            tab_optional=True,
            timeout_s=float(_os.getenv("WORKFLOWY_GLIMPSE_WS_GRACE_S", "6.0")),
        )
        from .archive_store import remember_archive_folder_from_reply

        remember_archive_folder_from_reply(reply)
    except Exception:  # noqa: BLE001 - the pull is best-effort (E11)
        return


# @beacon[
#   id=nexus-archives@system-archives-list,
#   role=⚡ _system_archives_list_impl(detail),
#   slice_labels=nexus--archives,nexus--mcp-api,
#   kind=ast,
#   comment=system.archives.list (§U3.2 D4, §5.12): EVERY *.json in the archive folder as one row with exactly one state and its reason — active / orphaned / dormant / superseded / skipped (whole vault) / unreadable — via the ONE store inventory (which classifies per live generation and lists everything even when nothing is visible, unlike the overlay). One zero-wait settings read when a tab is connected (remembering the reported folder), else the remembered value; it NEVER waits for a tab. detail=compact (default): §5.12's one header line + one line per file; detail=full: the folder/folder_source/learned_at/files dict. The summary is §5.7 — the canonical doctrine.,
# ]
async def _system_archives_list_impl(detail: str = "compact") -> Any:
    """The archive inventory (``system.archives.list``)."""

    from .archive_store import (
        get_archive_store,
        read_remembered_archive_folder,
        remembered_archive_folder_learned_at,
    )
    from .archive_texts import archives_inventory_header

    if detail not in ("compact", "full", None):
        return make_error(
            family="system",
            operation="system.archives.list",
            code="invalid_enum_value",
            message="detail must be 'compact' or 'full'.",
            operation_spec=SYSTEM_REGISTRY.resolve("archives.list"),
        )
    await _archives_settings_pull_once()
    store = get_archive_store()
    entries = store.inventory()
    counts = {"total": len(entries)}
    for entry in entries:
        counts[entry.state] = counts.get(entry.state, 0) + 1
    folder = read_remembered_archive_folder()
    learned_at = remembered_archive_folder_learned_at()
    if detail == "full":
        return {
            "success": True,
            "folder": folder or None,
            "folder_source": "remembered (the GLIMPSE extension's Archive folder option)",
            "learned_at": learned_at,
            "files": [_archives_inventory_row_dict(entry) for entry in entries],
        }
    lines = [archives_inventory_header(folder, learned_at, counts)]
    for entry in entries:
        lines.append(_archives_inventory_row_text(entry))
    return "\n".join(lines)


def _archives_mount_error(message: str) -> dict:
    """§5.11's refusal envelope: code invalid_parameter_value, nothing
    written."""

    return make_error(
        family="system",
        operation="system.archives.mount",
        code="invalid_parameter_value",
        message=message,
        operation_spec=SYSTEM_REGISTRY.resolve("archives.mount"),
    )


# @beacon[
#   id=nexus-archives@system-archives-mount,
#   role=⚡ _system_archives_mount_impl(archive, parent_handle),
#   slice_labels=nexus--archives,nexus--mcp-api,
#   kind=ast,
#   comment=system.archives.mount (§U3.2 D5, §5.11): set or clear ONE archive's mount_parent_id — the parent its root is planted under when the parent it was exported from is gone. Resolves the parent LIVE first (the ONE shared resolver; a unique live AP-ID match and a live clean-prefix/exact UUID match always win — Chain-1 W3/F4: a shave is told from the resolution OUTCOME via uuid_resolution_was_shave, never from string inequality, so an AP-ID input is never misclassified), else through the store's active overlay (an archived parent is allowed); only an ACTUAL corrective UUID shave is eligible for the exact-archive exception (the store's exact_only lookup); refuses per §5.11 (no such file, unreadable, whole-vault, parent nowhere, parent inside the archive, mounting would close a cycle) with NOTHING written; otherwise the ONE sanctioned write — with_mount_parent (nodes and nodes_sha256 untouched) through the format authority, parse-back verified, written atomically, read back byte-identical or reported UNVERIFIED. Returns {success, archive, mount_parent_id, previous_mount_parent_id, verified: true}.,
# ]
async def _system_archives_mount_impl(
    archive: str, parent_handle: "str | None" = None
) -> dict:
    """Set or clear one archive's mount point (``system.archives.mount``)."""

    from .archive_context import _handle_lookup_kind, _snapshot_live_view
    from .archive_store import (
        get_archive_store,
        read_remembered_archive_folder,
    )
    from .archive_texts import (
        mount_cycle_text,
        mount_no_such_archive_text,
        mount_parent_inside_text,
        mount_parent_nowhere_text,
        mount_unreadable_text,
        mount_unverified_text,
        mount_vault_text,
    )
    from .client.api_client_nexus import resolve_uuid_or_anchor_point_handle

    if not isinstance(archive, str) or not archive.strip():
        return _archives_mount_error("archive must be a non-blank file name.")
    archive = archive.strip()

    store = get_archive_store()
    folder = read_remembered_archive_folder()
    target = store.mount_target(archive)
    if target is None:
        return _archives_mount_error(
            mount_no_such_archive_text(archive, folder or "(none configured)")
        )
    if target["scope"] == "vault":
        return _archives_mount_error(mount_vault_text(archive))
    if target["document"] is None:
        return _archives_mount_error(
            mount_unreadable_text(archive, str(target.get("reason") or "unreadable"))
        )

    parent_id: "str | None" = None
    if parent_handle is not None and str(parent_handle).strip():
        supplied = str(parent_handle).strip()
        # Live first (the ONE shared resolver over the operation's pinned
        # map), else the store's active overlay (an archived parent is
        # allowed) — in the Axiom-2 order: a live EXACT or clean-prefix
        # match always wins; an EXACT archived id beats a SHAVED live
        # match; only a total live miss falls through to the archive's
        # unique-prefix leg.  (The fallback gate is inert here — this verb
        # runs mode none — so the order is spelled out explicitly.)
        try:
            from .client.api_client_nexus import load_nodes_by_id_from_cache
            from .coherence.operation_cache import current_operation_cache

            live_nodes = load_nodes_by_id_from_cache(current_operation_cache())
        except Exception:  # noqa: BLE001 - fall through to the overlay leg
            live_nodes = {}
        resolved = resolve_uuid_or_anchor_point_handle(supplied, live_nodes)
        live_uuid = (
            str(resolved["resolved_uuid"]) if resolved.get("resolved_uuid") else None
        )
        shaved = False
        if live_uuid is not None:
            # Chain-1 W3 (F4): a shave is told from the RESOLUTION OUTCOME,
            # never from inequality between the supplied string and the
            # resolved UUID — an AP-ID match (a different domain) and a live
            # clean-prefix match are never shaves, so a unique live AP-ID
            # parent always wins over an archived duplicate (Axiom 1/G2).
            from .client.api_client_nexus import uuid_resolution_was_shave

            shaved = uuid_resolution_was_shave(supplied, resolved)
        kind = _handle_lookup_kind(supplied)
        if live_uuid is not None and not shaved:
            parent_id = live_uuid
        elif live_uuid is not None and shaved:
            # Axiom 2: an exact archived id outranks the shave.
            exact_hit, provenance = store.miss_lookup(
                supplied, kind, live_view=_snapshot_live_view(), exact_only=True
            )
            if exact_hit and isinstance(provenance, dict):
                parent_id = str(exact_hit)
            else:
                parent_id = live_uuid
        elif resolved.get("candidates"):
            return make_error(
                family="system",
                operation="system.archives.mount",
                code="invalid_parameter_value",
                message=(
                    f"archives.mount: parent {supplied!r} is ambiguous: "
                    f"{[row.get('uuid') for row in resolved['candidates']]!r}."
                ),
                operation_spec=SYSTEM_REGISTRY.resolve("archives.mount"),
            )
        else:
            # Total live miss: the archive leg (exact or unique prefix).
            uuid_hit, provenance = store.miss_lookup(
                supplied, kind, live_view=_snapshot_live_view()
            )
            if uuid_hit and isinstance(provenance, dict):
                parent_id = str(uuid_hit)
            else:
                return _archives_mount_error(
                    mount_parent_nowhere_text(supplied)
                )
        if parent_id is not None:
            holding = store.holding_archive_of(parent_id)
            if holding is not None and holding[0] == target["path"]:
                return _archives_mount_error(
                    mount_parent_inside_text(supplied, archive)
                )
            # Cycle check (§5.11): the target parent's own ancestor chain,
            # over live and archived planting edges, must never reach a
            # record of THIS archive.
            cycle_other = store.mount_cycle_check(target["path"], parent_id)
            if cycle_other is not None:
                return _archives_mount_error(
                    mount_cycle_text(archive, supplied, cycle_other)
                )

    outcome = store.write_mount_parent(archive, parent_id)
    if not outcome.get("verified"):
        return make_error(
            family="system",
            operation="system.archives.mount",
            code="operation_failed",
            message=mount_unverified_text(archive),
            operation_spec=SYSTEM_REGISTRY.resolve("archives.mount"),
        )
    return {
        "success": True,
        "archive": archive,
        "mount_parent_id": parent_id,
        "previous_mount_parent_id": outcome.get("previous_mount_parent_id"),
        "verified": True,
    }


# Tool: BROKER STATUS (observability; answered by the broker itself)
# @beacon[
#   id=server@workflowy_broker_status,
#   role=⚡ workflowy_broker_status(),
#   slice_labels=nexus--broker,
#   kind=ast,
#   comment=MCP tool wrapper for broker observability. Acquires the MCP<->broker connection (grace-wait, same as GLIMPSE) and issues the broker_status Direction-A read, which the broker answers directly from its live registries. Fails soft with a structured {success:false,error} when the broker is unreachable (never raises), since this is a diagnostic surface an agent may call precisely when something is wrong.,
# ]
async def _system_broker_status_impl() -> dict:
    """Return the GLIMPSE broker's live routing-registry snapshot.

    This is the observability surface whose ABSENCE made the single-tab
    ghost-endpoint routing bug hard to diagnose: it shows every browser
    connection, every endpoint (with liveness age + whether it is the default
    GLIMPSE tab), and every MCP client (with the primary-worker designation).
    The broker answers it directly from memory, so it is safe to call at any
    time and works even when no browser tab is connected.
    """
    client = get_client()
    ws_conn, ws_queue = await get_ws_connection_with_grace_wait()
    if not (ws_conn and ws_queue):
        return {
            "success": False,
            "error": (
                "No connection to the GLIMPSE broker (this MCP server is not "
                "currently attached). The broker may be down, or this server "
                "is mid-reconnect -- retry shortly."
            ),
        }
    try:
        snapshot = await client.get_broker_status(
            ws_connection=ws_conn,
            ws_queue=ws_queue,
        )
        result = {"success": True}
        result.update(snapshot)
        return result
    except Exception as e:  # noqa: BLE001
        return {"success": False, "error": str(e)}


# @beacon[
#   id=mcp-api@system-config-get,
#   role=⚡ _system_config_get_impl(target_tab),
#   slice_labels=nexus--mcp-api,nexus--config,
#   kind=ast,
#   comment=System-family public config read. Reuses the tab-agnostic extension-settings transport and the one slice-policy parser, then exposes canonical tags, Anchor Dock vocabulary/defaults, postfix words, global-never tags, the default Markdown folder and the Project Maps location pointer in one stable public shape. project_maps_location is the extension's trimmed pointer string, or null when unset/blank/absent (an older extension); nothing here resolves, validates or interprets it.,
# ]
async def _system_config_get_impl(target_tab: str | None = None) -> dict:
    """Return the consolidated public NEXUS configuration shape.

    ``project_maps_location`` is the user's Project Maps pointer as the tab
    reported it: the trimmed non-blank string, else ``None``. It is a pointer
    and nothing more — this read never resolves, validates or interprets it.
    """

    anchor_tags, canonical_tags, default_parent, reply = (
        await _resolve_note_session_config(target_tab)
    )
    operands = parse_slice_policy_config(reply)
    project_maps_location = reply.get("project_maps_location")
    if not isinstance(project_maps_location, str):
        project_maps_location = None
    else:
        project_maps_location = project_maps_location.strip() or None
    return {
        "canonical_tags": list(canonical_tags),
        "anchor_dock_tags": list(anchor_tags),
        "local_dock_postfixes": _local_anchor_postfixes_from_reply(reply),
        "favorite_dock_postfixes": _favorite_anchor_postfixes_from_reply(reply),
        "deprecated_dock_postfixes": _deprecated_anchor_postfixes_from_reply(reply),
        "slice_postfixes": {
            "expand": operands["auto_expand"],
            "suppress": operands["suppress"],
            "deprecated": operands["deprecated"],
        },
        "global_never_tags": list(operands["global_never_expand"]),
        "default_dock_parent_uuid": default_parent,
        "default_markdown_folder": reply.get("default_markdown_folder") or None,
        # Project Maps pointer (extension option). Pointer semantics only: no
        # resolution, validation, memory or refusal — unset/blank/absent -> null.
        "project_maps_location": project_maps_location,
    }


# @beacon[
#   id=mcp-api@build-system-registry,
#   role=ƒ build_system_registry(),
#   slice_labels=nexus--mcp-api,
#   kind=ast,
#   comment=Assembly point for the consolidated public system family and its sole dispatch schema and describe metadata; job.cancel documents cooperative Cartographer tasks, the additive cancellation_pending marker and parent-owned inline phase8 with no PID signalling. Thin handlers retain their existing internal implementations.,
# ]
def build_system_registry() -> OperationRegistry:
    """Build the six-operation public ``system`` family registry.

    Cartographer cancellation documentation describes the actual cooperative
    task lifetime, the additive pending marker and parent-owned inline phase8.
    """

    registry = OperationRegistry(
        "system",
        "Health, broker/config/cache access, and asynchronous job control."
        + _ARCHIVE_FAMILY_SENTENCE_SERVER,
        handle_grammar="job_id = an asynchronous NEXUS job identifier",
    )

    async def _ping(_params: dict[str, Any]) -> dict:
        return await _system_ping_impl()

    async def _broker_status(_params: dict[str, Any]) -> dict:
        return await _system_broker_status_impl()

    async def _cache_refresh(_params: dict[str, Any]) -> dict:
        return await _system_cache_refresh_impl()

    async def _config_get(params: dict[str, Any]) -> dict:
        return await _system_config_get_impl(params.get("target_tab"))

    async def _job_status(params: dict[str, Any]) -> dict:
        from .mcp_api_registry import OperationValidationError

        try:
            return await _system_job_status_impl(
                params.get("job_id"),
                **{key: params[key] for key in ("status", "kind", "limit", "view", "files", "file", "files_offset", "files_limit", "offset", "slice_offset") if key in params},
            )
        except OperationValidationError as exc:
            return make_error(
                family="system", operation="system.job.status", code=exc.code,
                message=exc.message, operation_spec=registry.resolve("job.status"),
            )

    async def _job_cancel(params: dict[str, Any]) -> dict:
        return await _system_job_cancel_impl(params["job_id"])

    async def _archives_list(params: dict[str, Any]) -> Any:
        return await _system_archives_list_impl(params.get("detail") or "compact")

    async def _archives_mount(params: dict[str, Any]) -> dict:
        return await _system_archives_mount_impl(
            params.get("archive"), params.get("parent_handle")
        )

    empty_schema = {
        "type": "object",
        "properties": {},
        "additionalProperties": False,
    }
    registry.register(
        OperationSpec(
            family="system",
            verb="ping",
            cache_backed=False,
            summary="Check MCP package and process health without external I/O.",
            side_effects=("pure_read",),
            async_mode="never",
            params_schema=empty_schema,
            returns={"type": "object", "description": "Package/process health record."},
            examples=({"call": {"verb": "ping", "params": {}}, "note": "No-op health check."},),
            related=("system.broker.status",),
            handler=_ping,
        )
    )
    registry.register(
        OperationSpec(
            family="system",
            verb="broker.status",
            cache_backed=False,
            summary="Read the broker's live routing and connection registries.",
            side_effects=("pure_read",),
            async_mode="never",
            params_schema=empty_schema,
            returns={"type": "object", "description": "Live broker observability snapshot."},
            examples=({"call": {"verb": "broker.status", "params": {}}, "note": "Works with zero browser tabs."},),
            related=("system.ping",),
            handler=_broker_status,
        )
    )
    registry.register(
        OperationSpec(
            family="system",
            verb="cache.refresh",
            cache_backed=False,
            summary="Refresh the server-local nodes-export cache snapshot.",
            side_effects=("local_state_mutation",),
            async_mode="never",
            params_schema=empty_schema,
            returns={"type": "object", "description": "Cache refresh result."},
            examples=({"call": {"verb": "cache.refresh", "params": {}}, "note": "Rewrites only server-local cache state."},),
            related=("system.job.status",),
            handler=_cache_refresh,
        )
    )
    registry.register(
        OperationSpec(
            family="system",
            verb="config.get",
            cache_backed=False,
            summary="Read canonical tags, Dock settings (incl. favorite_dock_postfixes and deprecated_dock_postfixes), postfixes, defaults, the default Markdown folder and the Project Maps location pointer (project_maps_location).",
            side_effects=("pure_read",),
            async_mode="never",
            params_schema={
                "type": "object",
                "properties": {"target_tab": {"type": "string"}},
                "additionalProperties": False,
            },
            returns={"type": "object", "description": "Consolidated public configuration."},
            examples=({"call": {"verb": "config.get", "params": {}}, "note": "Tab-agnostic shared config read."},),
            related=("system.broker.status",),
            handler=_config_get,
        )
    )
    registry.register(
        OperationSpec(
            family="system",
            verb="job.status",
            cache_backed=False,
            summary="List compact ACTIVE jobs by default, plus inactive counts. Filter by status/kind/limit (50 rows default, max 200; 32 KiB). job_id returns its summary; view='detail' reads complete evidence in pages, each at most 512 KiB.",
            side_effects=("pure_read",),
            async_mode="never",
            params_schema={
                "type": "object",
                "properties": {
                    "job_id": {"type": "string", "description": "One job's summary, including errors/refusal metadata; view='detail' returns complete paged evidence. Cannot combine with list filters."},
                    "status": {"type": "string", "default": "active", "description": "active (default), inactive, all, or an exact status such as failed/completed_with_warnings/running. Case-insensitive. Unknown/blank recorded statuses remain active."},
                    "kind": {"type": "string", "description": "Exact case-insensitive kind, e.g. CARTO_REFRESH or etch. Filters returned rows, not whole-inventory counts."},
                    "limit": {"type": "integer", "minimum": 1, "maximum": 200, "default": 50, "description": "Maximum rows across both lists; the 32-KiB UTF-8 output budget may return fewer. truncated/omitted disclose incomplete lists."},
                    "view": {"type": "string", "description": "summary (default, head only) or detail (complete evidence, paged). Unknown values warn and use summary."},
                    "files": {"type": "string", "description": "all or problems: summary plus complete file-row pages. Unknown values warn and use summary."},
                    "file": {"type": "string", "description": "One physical path's complete rows and receipts; takes precedence over files and view."},
                    "files_offset": {"type": "integer", "description": "Row cursor for files view; default 0."},
                    "files_limit": {"type": "integer", "description": "Rows requested per page; default 100. Byte budget may return fewer, never discard evidence."},
                    "offset": {"type": "integer", "description": "Unit cursor for detail/file view; default 0, continue with returned next_offset."},
                    "slice_offset": {"type": "integer", "description": "Character cursor inside a unit larger than one page; default 0."},
                },
                "additionalProperties": False,
            },
            returns={
                "type": "object",
                "description": (
                    "Compact in_memory_jobs/detached_jobs arrays; active-only unless explicitly filtered. "
                    "total, active_count, inactive_count and inactive_by_status describe ALL known records, "
                    "independent of filters/limit. matched counts filter matches; returned/omitted/truncated "
                    "describe list delivery. Newest-created/started first. Scalar rows only: no nested "
                    "progress, result, warning or log payloads. job_id returns a head-only summary by default; "
                    "view='detail' returns the original detailed record, losslessly paged. files/file select complete rows. "
                    "Every one-job reply stays within 512 KiB; truncated/message name the next cursor, previewed names "
                    "summary values whose complete content is in detail. Each evidence page carries its version. "
                    "No archival/deletion or cache mutation. Terminal status does NOT prove actual task completion "
                    "or region release. CARTO status vocabulary: "
                    "preparing/running (+ waiting for in-process bulk work), "
                    "cancelling (presentation only -- actual task completion remains stop truth), "
                    "and the terminals completed, completed_with_warnings (terminal; still triggers "
                    "the post-job cache refresh), failed, cancelled. An unrecognized status is "
                    "conservatively treated as active."
                ),
            },
            examples=(
                {"call": {"verb": "job.status", "params": {}}, "note": "Compact active jobs and counts of inactive jobs; never the full history."},
                {"call": {"verb": "job.status", "params": {"status": "failed", "limit": 10}}, "note": "Ten newest failed jobs, compact."},
                {"call": {"verb": "job.status", "params": {"kind": "CARTO_REFRESH"}}, "note": "Active Cartographer refreshes only."},
                {"call": {"verb": "job.status", "params": {"job_id": "JOB"}}, "note": "Read one job's cheap summary."},
                {"call": {"verb": "job.status", "params": {"job_id": "JOB", "view": "detail"}}, "note": "Read complete detail, following detail_page cursors and evidence version."},
            ),
            related=("system.job.cancel",),
            handler=_job_status,
            domain_error_codes=("invalid_parameter_value",),
        )
    )
    registry.register(
        OperationSpec(
            family="system",
            verb="job.cancel",
            cache_backed=False,
            summary="Request cancellation of one asynchronous job.",
            side_effects=("local_state_mutation",),
            async_mode="never",
            params_schema={
                "type": "object",
                "properties": {"job_id": {"type": "string"}},
                "required": ["job_id"],
                "additionalProperties": False,
            },
            returns={
                "type": "object",
                "description": (
                    "Request cooperative cancellation of one asynchronous job. Current Cartographer jobs run as daemon tasks: "
                    "cooperative and already_terminal mean the task has ended; kill_refused_in_process_job means cancellation "
                    "is still pending at a safe point, never a kill attempt. An acknowledgement is not proof of stop; poll "
                    "job.status. Cancelling a MARKDOWN_GENERATE job also stops its inline phase-8 refresh. Pending Cartographer "
                    "cancellation additionally carries cancellation_pending=true beside the retained "
                    "kill_refused_in_process_job outcome; no PID is signalled. Poll job.status until actual task completion."
                ),
            },
            examples=({"call": {"verb": "job.cancel", "params": {"job_id": "JOB"}}, "note": "Best-effort cancellation."},),
            related=("system.job.status",),
            handler=_job_cancel,
        )
    )
    registry.register(
        OperationSpec(
            family="system",
            verb="archives.list",
            cache_backed=True,
            summary=ARCHIVES_LIST_INDEX_SUMMARY,
            describe_suffix=" " + ARCHIVES_LIST_SUMMARY,
            side_effects=("pure_read",),
            async_mode="never",
            params_schema={
                "type": "object",
                "properties": {
                    "detail": {
                        "type": ["string", "null"],
                        "enum": ["compact", "full", None],
                        "description": (
                            "compact (default): §5.12's one header line plus one "
                            "line per file; full: the structured {folder, "
                            "folder_source, learned_at, files} dict with one row "
                            "per file."
                        ),
                    }
                },
                "additionalProperties": False,
            },
            returns={
                "description": (
                    "Every *.json file in the archive folder as exactly one row: "
                    "file, state (active · orphaned · dormant · superseded · "
                    "skipped · unreadable), reason, archive_name, exported_at, "
                    "scope, root (8-hex + AP-ID when the root name carries one), "
                    "node_count, visible_count, planted_under (8-hex + name, or "
                    "'top level'), source_parent_id, mount_parent_id. Works with "
                    "no tab connected (the remembered folder value; one zero-wait "
                    "settings read remembers a fresh value when a tab is up)."
                )
            },
            examples=(
                {"call": {"verb": "archives.list", "params": {}}},
                {"call": {"verb": "archives.list", "params": {"detail": "full"}}},
            ),
            related=("system.archives.mount", "node.export"),
            handler=_archives_list,
            domain_error_codes=(),
        )
    )
    registry.register(
        OperationSpec(
            family="system",
            verb="archives.mount",
            cache_backed=True,
            summary=ARCHIVES_MOUNT_SUMMARY,
            side_effects=("disk_mutation",),
            async_mode="never",
            params_schema={
                "type": "object",
                "properties": {
                    "archive": {
                        "type": "string",
                        "description": "The archive file name exactly as archives.list lists it.",
                    },
                    "parent_handle": {
                        "type": ["string", "null"],
                        "description": (
                            "exact UUID | its 8-hex first segment | unique longer "
                            "prefix | [ap:CORE] — resolved live first, else through "
                            "the active archives (an archived parent is allowed); "
                            "null clears the mount point."
                        ),
                    },
                },
                "required": ["archive"],
                "additionalProperties": False,
            },
            returns={
                "description": (
                    "{success, archive, mount_parent_id, previous_mount_parent_id, "
                    "verified: true} — the write touches only the archive block's "
                    "mount_parent_id (nodes and their SHA-256 untouched), is "
                    "parse-back verified before the write and read back "
                    "byte-identical after; every refusal writes nothing."
                )
            },
            examples=(
                {"call": {"verb": "archives.mount", "params": {"archive": "a.json", "parent_handle": "[ap:K7M2QF]"}}},
                {"call": {"verb": "archives.mount", "params": {"archive": "a.json", "parent_handle": None}}, "note": "Clear the mount point."},
            ),
            related=("system.archives.list",),
            handler=_archives_mount,
            domain_error_codes=("invalid_parameter_value",),
        )
    )
    return registry


