# @beacon[
#   id=auto-beacon@_glimpse_estate_entry_section-lb5w,
#   role=_glimpse_estate_entry_section,
#   slice_labels=saved-tabs,
#   kind=ast,
# ]
def _glimpse_estate_entry_section(rec: dict) -> str:
    """One entry's Markdown document section: heading + scope echo + body.

    A rendered entry gets ``# 📄 [N] display`` + a ONE-LINE compact-JSON
    ``render_scope`` echo (blockquote) + its document; a failed entry gets a
    loud ``# ⚠️ [N] display — ENTRY FAILED`` block quoting the error. The
    same section rides the assembled string, the structured dict's
    ``document`` field, and each per-entry disk file.
    """
    lines: list[str] = []
    if rec.get("ok"):
        lines.append(f"# 📄 [{rec.get('index')}] {rec.get('display')}")
        scope = rec.get("render_scope")
        if isinstance(scope, dict):
            echo = json.dumps(scope, sort_keys=True, separators=(",", ":"), default=str)
            lines.append(f"> render_scope: {echo}")
        doc = rec.get("document")
        if isinstance(doc, str) and doc.strip():
            lines.append(doc.rstrip("\n"))
        elif isinstance(doc, str):
            lines.append("_(empty render — nothing in scope)_")
    else:
        lines.append(
            f"# ⚠️ [{rec.get('index')}] {rec.get('display')} — ENTRY FAILED"
        )
        msg = str(rec.get("error") or "unknown error")
        quoted = "\n".join(
            (f"> {ln}" if ln else ">") for ln in ("error: " + msg).splitlines()
        )
        lines.append(quoted)
    return "\n\n".join(lines)


