def _estate_entry_from_simple_form(form, index, *, original=None):
    entry = original or EstateEntry(index=index, alias=form.alias)
    if not form.ok:
        return replace(entry, valid=False, invalid_reason=form.error_message, error_code=form.error_code)
    return replace(entry, valid=True, spec=form.spec,
                   group=form.text if form.form in {"named_group", "passthrough_group"} else None,
                   simple_form=None)


# @beacon[
#   id=simple-form@resolve-snapshot,
#   slice_labels=nexus--mcp-api,saved-tabs,
#   kind=ast,
#   comment=Pure simple-form identity interpretation over caller-injected cache/config operands. Reuses the existing node/group resolvers and Dock classifier, and the two pure decisions; returns a lowering or read_note intent, never acquires state or renders. Transport and note-read control flow stay per origin.,
# ]
def _resolve_simple_form_from_snapshot(form, nodes, groups, vocabulary, *, inside_note):
    """Resolve operands, not grammar; never parse a note or acquire a snapshot."""
    from .client.api_client_nexus import resolve_uuid_or_anchor_point_handle
    from nexus_map_codebase import split_name_and_tags

    def fail(code, message):
        return replace(form, ok=False, error_code=code, error_message=message), "error"

    if not form.ok:
        return form, "error"
    if form.form != "bare_handle" and form.root is None:
        return form, "ready"
    text = form.text if form.form == "bare_handle" else form.root
    outcome = resolve_uuid_or_anchor_point_handle(text, nodes)
    node_hits = ([{"uuid": outcome["resolved_uuid"]}] if outcome.get("resolved_uuid") else outcome.get("candidates", []))
    group_hits = []
    if form.form == "bare_handle":
        group, error = _resolve_slice_group_handle(groups, text)
        group_hits = [group] if group else (error or {}).get("colliding_ids", [])
        if not group_hits:
            # The existing handle front drops an ambiguous id-prefix miss
            # while trying names. Keep the kernel's candidates for the new
            # cross-domain ambiguity decision; no new matching algorithm.
            _index, id_error = _resolve_slice_group_id(groups, text)
            group_hits = (id_error or {}).get("colliding_ids", [])
    decision = resolve_bare_string_decision(text, node_hits=node_hits, group_hits=group_hits)
    if decision.error_code:
        if decision.error_code == "simple_form_unresolved":
            # Chain-1 W4 (F5, §4.7.2): a refusal-reason operation (an
            # output_file sink, a write, an export, a purge preview) whose
            # operand names a visible archived node fails with the exact
            # §5.2/§5.3 text and the record's provenance — the consumer
            # raises ArchivedNodeReadOnlyError from it, so an archived sink
            # request can never become an empty-success selection.  Reads
            # keep today's hint (the gate/re-run serves archived roots), and
            # no context (the WS drive) keeps today's text.
            from .archive_context import (
                ARCHIVE_REFUSAL_REASONS,
                archive_miss_hit,
                current_archive_context,
            )

            _ctx = current_archive_context()
            if _ctx is not None and _ctx.reason in ARCHIVE_REFUSAL_REASONS:
                _text, _prov, _uuid = archive_miss_hit(text)
                if _text is not None:
                    return replace(
                        form,
                        ok=False,
                        error_code="archived_node_read_only",
                        error_message=_text,
                        archive=dict(_prov or {}),
                    ), "error"
            # Archive Reads U2 (§5.4): an AP-shaped bare-handle miss ends
            # with the light hint.  The ONE sanctioned impurity in this pure
            # interpreter: a read-only store facts fetch (folder states),
            # never a snapshot acquisition; never raises.
            from .archive_context import ap_miss_hint

            _hint = ap_miss_hint(text)
            if _hint:
                return fail(
                    decision.error_code,
                    f"{decision.error_message}\n{_hint}",
                )
        return fail(decision.error_code, decision.error_message)
    if decision.role == "group":
        ready = normalize_simple_form({"group": decision.hit["id"]}, surface="estate_note")
        return replace(ready, alias=form.alias), "ready"
    uuid = decision.hit["uuid"]
    node = nodes.get(uuid)
    if node is None:
        return fail("simple_form_unresolved", f"node {uuid} is absent from the cache; use system.cache.refresh then check the handle; see describe")
    if form.form == "bare_handle" or form.requires_dock:
        base_tags, postfix_kwargs = vocabulary
        _, tags = split_name_and_tags(str(node.get("name") or node.get("nm") or ""))
        is_anchor = bool(classify_anchor_tags(tags, base_tags, **postfix_kwargs).get("is_anchor"))
        role = decide_node_role(is_anchor=is_anchor, note_parses_as_estate=None, inside_note=inside_note)
        if form.requires_dock and role.role != "dock":
            return fail("simple_form_unresolved", f"node {uuid} is not an Anchor Dock; use a formal subtree spec for a plain node; see describe")
        if role.error_code:
            return fail(role.error_code, role.error_message)
        if role.role == "read_note":
            return replace(form, root=uuid), "read_note"
        if form.form == "bare_handle":
            ready = normalize_simple_form({"dock": uuid}, surface="estate_note")
            return replace(ready, alias=form.alias), "ready"
    spec = dict(form.spec or {})
    if "root_uuid" in spec:
        spec["root_uuid"] = uuid
    elif "lightning" in spec:
        resolved_lightning = {**spec["lightning"], "root_uuids": [uuid]}
        if form.form == "node":
            # {node: H}: the handle is BOTH the symbol and the scope root —
            # replace both so the render is the resolved node alone.
            resolved_lightning["symbols"] = [uuid]
        spec["lightning"] = resolved_lightning
    lens = {**form.lens, "root_handle": uuid} if form.lens is not None else None
    return replace(form, spec=spec, lens=lens, root=uuid), "ready"


# @beacon[
#   id=saved-tabs@estate-entry-render,
#   slice_labels=nexus--mcp-api,nexus--md-preview,saved-tabs,glimpse-render,
#   kind=ast,
#   comment=ONE estate entry through the EXISTING server render funnel (no new render path): a named-group entry normalizes via normalize_from_glimpse_args(group_id=<handle>, match_scope='name') — a slice spec at the group's stored root with its saved default sort/policy, resolved by the SAME _resolve_slice_group_handle glimpse(group_handle=…) uses; a spec entry deserializes via RenderProjectionSpec.from_render_spec_blob (spec VERBATIM, focus included), rides the UUID prefix-grace, then the loud focus-intent-loss check (a saved selection that collapses to None aborts the entry rather than dumping the whole scope). Both go through the ONE override+guard seam (_apply_modal_view_overrides_and_guard → with_view_overrides) and _glimpse_dispatch_spec — which honors single-row AND mode='rows' covering-subtree focus via the shared Stage-2 tail, and NEVER runs the in-band Anchor-Dock raw-dump guard (every estate entry passes as allow_anchor_dock=true by construction). Returns a flat per-entry record; every failure shape (invalid entry, unresolvable group, root_not_in_cache, stale focus, guard rejection, funnel error, unexpected exception) is a LOUD record — the caller keeps rendering the others. Chain-1 r2 (F5/R2-W1): ArchivedNodeReadOnlyError is the one re-raised exception — an entry whose root names a visible archived node refuses the WHOLE sink call with the universal envelope, never an isolated failed row an assembly could write into a delivery-success file.,
# ]
async def _glimpse_estate_render_entry(
    entry: EstateEntry,
    *,
    ov_as_markdown: bool | None,
    ov_headings_only: bool | None,
    ov_sort_by: str | None,
    ov_sort_direction: str | None,
    ov_since: Any,
    ov_recent_by: str | None = None,
    ov_repository_view: bool | None = None,
    target_tab: str | None,
    cache_by_id: dict[str, dict[str, Any]],
    disk_only_markdown: bool,
) -> dict:
    """Funnel one estate entry; return its flat result record.

    Re-raises :class:`ArchivedNodeReadOnlyError` (Chain-1 r2, F5/R2-W1): the
    archive read-only refusal is the universal envelope's answer, never an
    isolated failed row the caller could assemble into a delivery-success
    file — every other failure shape stays a loud per-entry record.
    """
    from .archive_context import ArchivedNodeReadOnlyError

    rec: dict[str, Any] = {
        "index": entry.index,
        "display": entry.display_name,
        "alias": entry.alias,
        "title": entry.title,
        "ok": False,
        "as_markdown": None,
        "document": None,
        "result": None,
        "render_scope": None,
        "error": None,
        "error_extra": None,
        "node_count": None,
        "depth": None,
    }
    if not entry.valid:
        rec["error"] = f"invalid estate entry: {entry.invalid_reason}"
        if entry.error_code:
            rec["error"] = f"{entry.error_code}: {rec['error']}"
            rec["error_extra"] = {"code": entry.error_code}
        return rec
    try:
        if entry.is_group:
            # NAMED SLICE GROUP entry ([ap:ARDOF6] §E1 item 1): a slice spec
            # at the group's STORED root with its SAVED default sort/policy —
            # sort_by=None is the inherit sentinel; the handle itself rides
            # verbatim into _glimpse_slice_group_from_cache's resolution
            # (exact id → unique grp- prefix → full name → short name), the
            # SAME resolution glimpse(group_handle=…) uses. match_scope
            # 'name' mirrors the glimpse.run registry default for a
            # group_handle scope.
            spec = RenderProjectionSpec.normalize_from_glimpse_args(
                group_id=entry.group,
                match_scope="name",
            )
        else:
            blob = entry.spec if isinstance(entry.spec, dict) else {}
            spec = RenderProjectionSpec.from_render_spec_blob(blob)
            # UUID prefix-grace (the paste path's hallucination net), best
            # effort exactly as the render_spec blob path: a cache hiccup
            # never fails the entry — downstream helpers surface their own
            # loud cache-miss errors.
            if cache_by_id:
                try:
                    spec = _grace_resolve_spec_uuids(spec, cache_by_id)
                except Exception:  # noqa: BLE001
                    pass
            # LOUD focus intent-loss (the _glimpse_read_modal guard, per
            # entry): a saved selection that collapsed to None must never
            # silently fall through to a whole-scope render — that fallback
            # could dump megabytes into the agent conversation.
            if _estate_focus_intended(blob.get("focus")) and not (
                _estate_focus_survived(spec.focus)
            ):
                rec["error"] = (
                    "the entry's saved selection (focus) could not be "
                    "resolved server-side — it did not survive "
                    "deserialization/canonicalization — so this entry was "
                    "ABORTED rather than silently rendering its entire scope "
                    "(which could be very large). Re-export the entry from "
                    "the modal's ⌖ focus button, or refresh the nodes cache "
                    "if Workflowy was edited since the last refresh."
                )
                rec["error_extra"] = {"focus_intent_lost": True}
                return rec
        # Per-call view overrides through the ONE normalized seam
        # (with_view_overrides + the loud focus/since guards). Tri-state:
        # None = inherit the entry's own saved view.
        spec, ov_err = _apply_modal_view_overrides_and_guard(
            spec,
            as_markdown=ov_as_markdown,
            headings_only=ov_headings_only,
            sort_by=ov_sort_by,
            sort_direction=ov_sort_direction,
            since=ov_since,
            recent_by=ov_recent_by,
            # REPOSITORY VIEW (U1, §6.5): tri-state like headings_only; the
            # §3.4 backstop in the normalizer re-checks the merged spec, so
            # an entry whose saved blob carries a focus/full_uuids/timestamp
            # sort FAILS as a loud per-entry record (a ValueError here is
            # caught by this function's per-entry isolation handler).
            repository_view=ov_repository_view,
        )
        if ov_err is not None:
            rec["error"] = _estate_error_message(ov_err)
            rec["error_extra"] = _estate_extra_fields(
                ov_err, drop=("error", "success")
            )
            return rec
        rec["as_markdown"] = bool(spec.as_markdown)
        if disk_only_markdown and not spec.as_markdown:
            # The slice-group output_file guard's estate twin: never write a
            # wrong file — fail the entry loudly instead.
            rec["error"] = (
                "entry renders in full/UUID mode (as_markdown=false): estate "
                "disk writes are Markdown-only (the same restriction as the "
                "slice-group output_file guard). Pass as_markdown=true, or "
                "omit output_file to render in memory."
            )
            return rec
        res = await _glimpse_dispatch_spec(
            spec, output_file=None, target_tab=target_tab
        )
        if not isinstance(res, dict):
            rec["error"] = (
                f"entry render returned {type(res).__name__}, expected a "
                "result dict"
            )
            return rec
        # FAILURE, both shapes. (1) the ordinary success:false error payload.
        # (2) the Stage-2 STALE-FOCUS payload: success:true BUT an `error`
        # message + `focus_unresolved` marker + an EMPTY render (the shared
        # exact-or-error contract — the requested row does not exist in the
        # current forest and is never guessed). For the estate assembly that
        # entry did NOT render its saved view: it is a loud per-entry
        # failure, never an empty document.
        _res_error = res.get("error")
        if res.get("success") is False or _res_error or res.get("focus_unresolved"):
            rec["error"] = _estate_error_message(res) if _res_error else (
                "the entry's saved focus row could not be resolved "
                f"(focus_unresolved={res.get('focus_unresolved')!r})"
            )
            rec["error_extra"] = _estate_extra_fields(
                res,
                drop=(
                    "error", "success", "preview_markdown", "preview_text",
                    "preview_tree", "rows", "root", "children",
                    "node_count", "depth", "_source", "render_scope",
                    "since_applied",
                ),
            )
            return rec
        shaped = _shape_glimpse_family_return(
            res, output_file=None, headings_only=bool(spec.headings_only)
        )
        rec["ok"] = True
        _scope = res.get("render_scope")
        rec["render_scope"] = _scope if isinstance(_scope, dict) else None
        rec["node_count"] = res.get("node_count")
        rec["depth"] = res.get("depth")
        # REPOSITORY VIEW (§6.5): the record's document is the entry's CLEAN
        # document (the tail's D, §6.1) -- never the shaper's `> `-prefixed
        # screen string -- and the entry's counts ride the record for the
        # acknowledgement's rollup.
        if isinstance(res, dict) and isinstance(res.get("repository_view"), dict):
            rec["repository_view"] = dict(res.get("repository_view") or {})
            rec["document"] = str(res.get("document") or "")
        elif isinstance(shaped, str):
            rec["document"] = shaped
        elif isinstance(shaped, dict):
            rec["result"] = shaped
        else:
            rec["document"] = str(shaped)
        return rec
    except ArchivedNodeReadOnlyError:
        # Chain-1 r2 (F5, R2-W1): the archive read-only refusal is the
        # ANSWER to a sink aimed at a visible archived node — the universal
        # archived_node_read_only envelope (exact §5.3.2 text + provenance),
        # never a per-entry failed record inside a delivery-success file and
        # never a family-level generic failure.  Ordinary per-entry isolation
        # is unchanged for every other failure shape.
        raise
    except Exception as exc:  # noqa: BLE001 — per-entry isolation is the contract
        rec["error"] = f"{type(exc).__name__}: {exc}"
        return rec


# @beacon[
#   id=saved-tabs@estate-verb,
#   slice_labels=nexus--mcp-api,nexus--md-preview,saved-tabs,glimpse-render,
#   kind=ast,
#   comment=Estate OUTPUT origin: simple forms/full JSON directly or a Dock/estate handle, interpreted by the pure grammar and injected-snapshot resolver. Dock first (no note read), else ONE live _node_read_impl; entries never nest. Lowered entries use the same TWO-branch _glimpse_estate_render_entry and _glimpse_dispatch_spec. Existing alias/title headings, scope echoes, per-entry isolation, view overrides, output_file and reserved tabs semantics remain; no renderer, wire, cache writer or transport fork. Chain 1 r2 (WO [ap:4Q3LQV] W1): under repository_view the estate delivers the ONE coherence advisory authority's warning on its own reply -- the canonical line on the screen (text adapter on the document part, below the composed '> ' lines) and the structured key on the successful file acknowledgement -- while every file byte and assembled D stays clean; applicability rides the operation's captured status and is byte-identical when clean or with the flag off.,
# ]
async def _glimpse_estate_impl(
    *,
    handle: str | dict | None,
    mode: str | None = None,
    entries: list | None = None,
    output_file: str | None = None,
    as_markdown: bool | None = None,
    headings_only: bool | None = None,
    sort_by: str | None = None,
    sort_direction: str | None = None,
    since: str | None = None,
    recent_by: str | None = None,
    repository_view: bool | None = None,
    target_tab: str | None = None,
) -> Any:
    """Render an estate note, Dock handle, simple form or direct full JSON.

    ``glimpse(verb='estate')``. OUTPUT mode only; ``mode='tabs'`` is the
    reserved Tier-3 drive ([ap:DNMYMZ]) and is refused with a teaching error.
    Every entry rides the existing render funnel; see the beacon and
    :func:`_glimpse_estate_render_entry` for the contract. Returns the
    assembled Markdown string (all-Markdown render), a structured dict (any
    full/UUID entry, or the file-write ack), or a loud error payload.
    """
    # ── mode: exactly one implemented value ─────────────────────────────
    _mode = str(mode or "output").strip().lower()
    if _mode == "tabs":
        return {
            "success": False,
            "error": _ESTATE_TABS_RESERVED_ERROR,
            "estate_tabs_reserved": True,
        }
    if _mode != "output":
        return {
            "success": False,
            "error": (
                f"unknown estate mode {mode!r}; the only implemented mode is "
                "'output' (the default). mode='tabs' (the agent-triggered "
                "browser-tab drive) is RESERVED — Tier 3 of the Saved Tabs "
                "program ([ap:DNMYMZ]), not built."
            ),
        }
    if not isinstance(handle, (str, dict)) or (isinstance(handle, str) and not handle.strip()):
        return {
            "success": False,
            "error": (
                "glimpse estate requires 'handle': a non-empty group name, "
                "Dock/estate handle, simple-form object or full JSON string; see describe."
            ),
        }

    # ── per-call view overrides (tri-state; parsed once for every entry) ─
    _since_obj, _since_err = _since_from_edge_result(since)
    if _since_err:
        return {"success": False, "error": _since_err}
    # sort_direction is an override ONLY alongside sort_by (the run-path
    # rule: a direction with no sort_by is meaningless/undecidable).
    _ov_sort_direction = sort_direction if sort_by is not None else None
    # [ap:TVIIBN] 4d(a): the recency basis of a 'newest' item_count selection
    # rides the same tri-state channel as since (normalized here once).
    _ov_recent_by = recent_by if recent_by in ("created", "modified") else None

    # ── output_file resolution + classification + fail-fast pre-checks ───
    out_form: str | None = None
    _estate_path_res = None
    if output_file is not None:
        # Resolve the ARGUMENT first — before any entry renders (P1: a
        # refused estate argument fails before any side effect). The
        # classification + existence pre-checks and every derived per-entry
        # path apply to the RESOLVED string; the grammar and the never-mkdirs
        # rule are unchanged (§10). Refusals surface through the established
        # {success: false, error} dict (§6.7).
        try:
            _estate_path_res = resolve_tool_path(
                output_file, param="output_file", context="glimpse.estate",
                direction="write",
            )
        except ToolPathError as exc:
            return {"success": False, "error": str(exc)}
        out_form, _out_err = _glimpse_estate_output_form(_estate_path_res.resolved)
        if _out_err:
            return {"success": False, "error": _out_err}

    # One operation-owned map (CF-11: the SAME pinned source the run and
    # lens simple-form paths use — _anchor_cache_by_id — never a second
    # cache reader), also used for entry resolution and UUID grace.
    cache_by_id: dict[str, dict[str, Any]] = {}
    try:
        cache_by_id = _anchor_cache_by_id()
    except Exception:
        cache_by_id = {}
    groups = None
    vocabulary = None
    node_uuid = node_name = ""
    parsed = None
    form = normalize_simple_form(handle, surface="estate_call")
    if not form.ok:
        return _simple_form_failure(form)
    if form.form == "bare_handle" or form.root is not None:
        try:
            groups = (await _resolve_slice_group_config(target_tab))[0] if form.form == "bare_handle" else []
            vocabulary = await _read_anchor_dock_vocabulary(target_tab) if form.form == "bare_handle" or form.requires_dock else None
            form, role = _resolve_simple_form_from_snapshot(
                form, cache_by_id, groups, vocabulary, inside_note=False,
            )
        except Exception as exc:
            return {"success": False, "error": str(exc)}
        if not form.ok:
            # Chain-1 W4 (F5): the archived refusal must reach the caller as
            # the archived_node_read_only envelope (the exception mapper's
            # kernel code), never as a family failure dict with the refusal
            # buried in the message — and always before any sink work.
            if form.error_code == "archived_node_read_only":
                from .archive_context import ArchivedNodeReadOnlyError

                raise ArchivedNodeReadOnlyError(
                    form.error_message, extra=dict(form.archive or {})
                )
            return _simple_form_failure(form)
        if role != "read_note":
            parsed = [_estate_entry_from_simple_form(form, 1)]
    else:
        parsed, parse_err = parse_estate_payload(form.raw)
        if parse_err or not parsed:
            return {"success": False, "code": "simple_form_unresolved", "error": f"{parse_err}; see describe"}

    # ── 1) LIVE note read through the ONE node-read core ────────────────
    from .archive_context import ArchivedNodeReadOnlyError

    try:
        node = await _node_read_impl(handle, False) if parsed is None else None
    except ArchivedNodeReadOnlyError:
        # Chain-1 W4 (F5): the archive read-only refusal is the answer — the
        # universal envelope (code + provenance), never a wrapped dict that
        # reads like an ordinary read failure.
        raise
    except Exception as exc:  # noqa: BLE001 — actionable resolve/read errors
        return {
            "success": False,
            "error": (
                f"could not read the estate Anchor Point {handle!r}: {exc}"
            ),
        }
    if node is not None:
        node_uuid = str(getattr(node, "id", "") or "")
        node_name = str(getattr(node, "name", "") or "")
        note = _note_wire_to_semantic(getattr(node, "note", "") or "")
        parsed, parse_err = parse_estate_note(note)
        # QBCTWU U3-2 · the estate-vs-plain-node classification: a note is a
        # named estate only when every BARE-NAME line actually resolves to an
        # existing slice group — prose that fails the lookup makes this an
        # ordinary node (the skill's plain-node row), never a loud
        # unknown-group estate. Entries from legacy JSON payloads carry no
        # bare_name_line flag: a Saved-Tabs export stays an estate, its
        # unresolvable names failing as loud PER-ENTRY errors as before.
        note_is_estate = parsed is not None and parse_err is None
        if note_is_estate and groups is not None:
            for _entry in parsed:
                if _entry.valid and _entry.bare_name_line:
                    _group_match, _ = _resolve_slice_group_handle(groups, _entry.group)
                    if not _group_match:
                        note_is_estate = False
                        break
        role = decide_node_role(is_anchor=False, note_parses_as_estate=note_is_estate, inside_note=False)
        if role.error_code:
            return {"success": False, "code": role.error_code,
                    "error": f"{role.error_message} ({parse_err})"}
        if role.role == "node":
            # A bare handle that is neither a Dock nor an estate reads the
            # node on its own: ONE {"node": uuid} entry through the SAME
            # lowering the direct {node} form uses (render_nodes machinery).
            _ready = normalize_simple_form({"node": node_uuid}, surface="estate_note")
            parsed = [_estate_entry_from_simple_form(
                replace(_ready, alias=form.alias or node_name), 1,
            )]

    # ── 3) optional subset filter ────────────────────────────────────────
    selected, filter_err = _estate_apply_entries_filter(parsed, entries)
    if filter_err is not None or not selected:
        return {
            "success": False,
            "error": f"estate {handle!r}: "
            + (filter_err or "the entries filter selected no entry."),
        }

    # ── 5) render every selected entry, in payload order ────────────────
    records: list[dict] = []
    for entry in selected:
        if entry.simple_form is not None:
            try:
                pending = entry.simple_form
                if pending.form == "bare_handle" and groups is None:
                    groups, *_ = await _resolve_slice_group_config(target_tab)
                if (pending.form == "bare_handle" or pending.requires_dock) and vocabulary is None:
                    vocabulary = await _read_anchor_dock_vocabulary(target_tab)
                ready, _role = _resolve_simple_form_from_snapshot(
                    pending, cache_by_id, groups or [], vocabulary, inside_note=True,
                )
                if not ready.ok and ready.error_code == "archived_node_read_only":
                    # Chain-1 W4 (F5): an archived entry refuses the WHOLE
                    # call with the §5.2/§5.3 envelope before any render tail
                    # or sink work — never a per-entry failed record inside a
                    # delivery-success envelope, and never a file written
                    # without the archived entry.
                    raise ArchivedNodeReadOnlyError(
                        ready.error_message, extra=dict(ready.archive or {})
                    )
                entry = _estate_entry_from_simple_form(ready, entry.index, original=entry)
            except ArchivedNodeReadOnlyError:
                raise
            except Exception as exc:
                entry = replace(entry, valid=False, invalid_reason=str(exc))
            # REPOSITORY VIEW (§3.3/§6.5): a {node} parcel (or a bare handle
            # that lowered to the plain-node read) cannot render the commit
            # view -- a plain node is not mapped source -- so that entry
            # FAILS loudly while the others still render.
            if (
                repository_view
                and entry.valid
                and getattr(ready, "form", None) == "node"
            ):
                entry = replace(
                    entry,
                    valid=False,
                    invalid_reason=(
                        "repository_view=true cannot render a {node} parcel "
                        "(the node-alone read): a plain node is not mapped "
                        "source code, so there is no beacon-slice document "
                        "to clean. Use a slice, tag or symbols parcel for "
                        "this entry, or drop repository_view."
                    ),
                    error_code=_REPOSITORY_VIEW_REFUSAL_ERROR,
                )
        rec = await _glimpse_estate_render_entry(
            entry,
            ov_as_markdown=as_markdown,
            ov_headings_only=headings_only,
            ov_sort_by=sort_by,
            ov_sort_direction=_ov_sort_direction,
            ov_since=_since_obj,
            ov_recent_by=_ov_recent_by,
            ov_repository_view=repository_view,
            target_tab=target_tab,
            cache_by_id=cache_by_id,
            disk_only_markdown=out_form is not None,
        )
        records.append(rec)

    n_ok = sum(1 for r in records if r["ok"])
    n_failed = len(records) - n_ok
    estate_meta = {
        "handle": handle,
        "node_uuid": node_uuid,
        "node_name": node_name,
        "entry_count": len(parsed),
        "selected": len(selected),
        "rendered": n_ok,
        "failed": n_failed,
    }

    # REPOSITORY VIEW (§6.5): the summed counts + per-entry rows for the
    # acknowledgement, and the summed screen sentence's input.
    _rv_on = bool(repository_view)
    _rv_sum = {"left_out": 0, "ap_ids_removed": 0, "unresolved_items": 0}
    _rv_ack: dict[str, Any] | None = None
    if _rv_on:
        _rv_entry_rows: list[dict[str, Any]] = []
        for r in records:
            if r["ok"] and isinstance(r.get("repository_view"), dict):
                _rvd = r["repository_view"]
                _rv_sum["left_out"] += int(_rvd.get("left_out") or 0)
                _rv_sum["ap_ids_removed"] += int(_rvd.get("ap_ids_removed") or 0)
                _rv_sum["unresolved_items"] += int(_rvd.get("unresolved_items") or 0)
                _rv_entry_rows.append(
                    {
                        "index": r["index"],
                        "left_out": int(_rvd.get("left_out") or 0),
                        "ap_ids_removed": int(_rvd.get("ap_ids_removed") or 0),
                        "unresolved_items": int(_rvd.get("unresolved_items") or 0),
                    }
                )
        _rv_ack = dict(_rv_sum)
        _rv_ack["entries"] = _rv_entry_rows

    # ── 6) zero renders = the only top-level failure ────────────────────
    if n_ok == 0:
        return {
            "success": False,
            "error": (
                f"every entry of the estate failed to render "
                f"({n_failed} of {n_failed} attempted); no document was "
                "produced. The estate itself parsed cleanly — see the "
                "per-entry errors."
            ),
            "mode": _mode,
            "estate": estate_meta,
            "failed_entries": [
                {"index": r["index"], "display": r["display"], "error": r["error"],
                 **({"error_extra": r["error_extra"]} if (r.get("error_extra") or {}).get("code") in SIMPLE_FORM_ERROR_CODES else {})}
                for r in records
            ],
        }

    # ── 7) assemble ──────────────────────────────────────────────────────
    if _rv_on:
        # §6.5 assembly under the view: NO estate header, NO per-entry
        # sections, NO render_scope lines -- the non-empty entry documents
        # in payload order joined by '\n---\n\n'.
        _rv_docs = [str(r.get("document") or "") for r in records if r["ok"]]
        _rv_docs = [d for d in _rv_docs if d]
        assembled = "\n---\n\n".join(_rv_docs)
    else:
        header_bits = [
            "# 🏛️ ESTATE",
            node_name or "(untitled)",
            f"handle {handle}",
            (
                f"{len(records)} of {len(parsed)} entries"
                if len(records) != len(parsed)
                else f"{len(records)} entr{'y' if len(records) == 1 else 'ies'}"
            ),
            f"{n_ok} rendered" + (f" · {n_failed} FAILED" if n_failed else ""),
        ]
        header = " · ".join(header_bits)
        sections = [_glimpse_estate_entry_section(r) for r in records]
        assembled = header + "\n\n" + "\n\n---\n\n".join(sections) + "\n"

    # ── 8) output_file: disk is the deliverable, ack is compact ─────────
    if out_form is not None:
        written: list[dict] = []
        failed_entries: list[dict] = [
            {"index": r["index"], "display": r["display"], "error": r["error"],
             **({"error_extra": r["error_extra"]} if (r.get("error_extra") or {}).get("code") in SIMPLE_FORM_ERROR_CODES else {})}
            for r in records
            if not r["ok"]
        ]
        if out_form == "file":
            try:
                nbytes = _write_resolved_text_file(_estate_path_res.resolved, assembled)
            except Exception as exc:  # noqa: BLE001
                return {
                    "success": False,
                    "error": f"failed to write output_file {output_file!r}: {exc}",
                    "mode": _mode,
                    "estate": estate_meta,
                }
            written.append(
                {
                    "index": None,
                    "display": "(assembled estate document)",
                    # §6.6: output_files[].path carries the RESOLVED derived
                    # path (identical to the request when no translation).
                    "path": _estate_path_res.resolved,
                    "bytes_written": nbytes,
                }
            )
        else:
            for r in records:
                if not r["ok"]:
                    continue
                # Per-entry paths derive from the RESOLVED argument (one
                # translation, at the argument — never per entry).
                path = _glimpse_estate_entry_path(out_form, _estate_path_res.resolved, r)
                # §6.5: under the view a per-entry file holds EXACTLY that
                # entry's clean document (empty file when empty) -- never the
                # framed section.
                if _rv_on:
                    content = str(r.get("document") or "")
                else:
                    content = _glimpse_estate_entry_section(r) + "\n"
                try:
                    nbytes = _write_resolved_text_file(path, content)
                except Exception as exc:  # noqa: BLE001 — per-entry isolation
                    failed_entries.append(
                        {
                            "index": r["index"],
                            "display": r["display"],
                            "error": f"failed to write {path!r}: {exc}",
                        }
                    )
                    continue
                written.append(
                    {
                        "index": r["index"],
                        "display": r["display"],
                        "path": path,
                        "bytes_written": nbytes,
                    }
                )
            if not written:
                return {
                    "success": False,
                    "error": (
                        "no entry of the estate could be written to disk — "
                        "every write failed; see failed_entries."
                    ),
                    "mode": _mode,
                    "estate": estate_meta,
                    "failed_entries": failed_entries,
                }
        # REPOSITORY VIEW (Chain 1 r2, WO [ap:4Q3LQV] W1): under the view the
        # successful file acknowledgement carries the ONE advisory
        # authority's structured coherence_advisory when the operation's
        # captured status is hard-dirty -- the warning stays out of every
        # file byte (above) but must stay visible on the reply. The authority
        # decides applicability; clean runs are byte-identical (no key), and
        # with the flag off the ack is untouched (today's framing).
        _estate_ack: dict[str, Any] = {
            "success": True,
            "mode": _mode,
            "estate": estate_meta,
            "output_files": written,
            "failed_entries": failed_entries,
            # §6.1/§6.5: the estate ack carries the summed view counts and
            # the per-entry rows under the view.
            **({"repository_view": _rv_ack} if _rv_ack is not None else {}),
            # §6.6: ONE path_record for the consumed argument; the derived
            # per-entry paths ride output_files[].path in resolved form (P3).
            "path_record": _estate_path_res.as_dict(),
        }
        if _rv_on:
            from .coherence.read_advisory import apply_coherence_read_advisory

            return apply_coherence_read_advisory(_estate_ack)
        return _estate_ack

    # ── 9) in-memory result: ONE string when every rendered entry is
    # Markdown; a structured per-entry dict when any entry rendered in
    # full/UUID mode (a preview_tree cannot ride an assembled string). ──
    if _rv_on:
        # §6.5 in-memory: the document, with the summed `> Repository view:`
        # line and one `> Estate entry [N] failed: <error>` line per failed
        # entry above it -- the reply, never the document (A6).
        #
        # Chain 1 r2 (WO [ap:4Q3LQV] W1): under a captured hard-dirty
        # boundary the canonical coherence warning stays visible in the
        # screen reply -- through the ONE advisory authority's text adapter
        # on the document part (the same shape as the direct render tail:
        # the shaper's `> ` lines above the advised preview), never inside
        # any entry document or assembled D. Clean runs are byte-identical.
        from .coherence.read_advisory import apply_coherence_advisory_to_text

        _screen_lines: list[str] = []
        _rv_sentence = _repository_view_sentence({"repository_view": _rv_sum})
        if _rv_sentence:
            _screen_lines.append(f"> {_rv_sentence}")
        for r in records:
            if not r["ok"]:
                _screen_lines.append(
                    f"> Estate entry [{r['index']}] failed: {r['error']}"
                )
        if _screen_lines:
            return "\n".join(_screen_lines) + "\n" + apply_coherence_advisory_to_text(assembled)
        return apply_coherence_advisory_to_text(assembled)
    structured_needed = any(
        r["ok"] and r.get("document") is None for r in records
    )
    if structured_needed:
        return {
            "success": True,
            "mode": _mode,
            "estate": estate_meta,
            "entries": [
                {
                    "index": r["index"],
                    "alias": r["alias"],
                    "title": r["title"],
                    "display": r["display"],
                    "ok": r["ok"],
                    "as_markdown": r["as_markdown"],
                    "render_scope": r["render_scope"],
                    "document": r["document"],
                    "result": r["result"],
                    "node_count": r["node_count"],
                    "depth": r["depth"],
                    "error": r["error"],
                    "error_extra": r["error_extra"],
                }
                for r in records
            ],
        }
    return assembled


# Tool: GLIMPSE (Read Node Trees)
_GLIMPSE_LEGACY_TOOL_DECORATOR = _legacy_tool(
    name="workflowy_glimpse",
    description="⚠️⚠️ RAW-BYTES WARNING (read first): GLIMPSE output is a RENDERED view, NOT the raw node bytes. Text that looks like an HTML tag (a word wrapped in triangle brackets, e.g. `<token>`) is STRIPPED from the Markdown render — it is invisible in GLIMPSE output even though it EXISTS in the node and displays normally in the Workflowy main view. DO NOT assume the bytes you see in a GLIMPSE return match what you see in the Workflowy main view, and DO NOT compose note_search text for workflowy_edit_node from GLIMPSE output — a mismatched search string silently no-ops. For search-and-replace text, ALWAYS fetch the node with workflowy_read_node first; it returns the exact semantic bytes the Workflowy main view shows, and note_search matches against exactly those bytes. Load the currently-visible Workflowy subtree into context (no file intermediary). GLIMPSE command for direct context loading. Auto-resolves to whatever bullet the user is currently zoomed into in Workflowy — no UUID needed. Defaults to compact Markdown mode (as_markdown=True): a clean pseudo-document with Cartographer metadata stripped and no UUIDs shown. This Markdown rendering works excellently even for SOURCE-CODE Cartographer beacon slices (not just Markdown files): it roughly halves the token cost of the response versus the bracketed JSON form, and the prettified Markdown (file-break headers, one heading per function/class/constant with its full signature, slurped docstrings and comments as flowing prose, slice-label tags inline) materially improves the readability of source-code beacon slices. The only thing dropped is inline UUIDs — use read_text_snippet_by_symbol to read mapped source by function/class/beacon name when needed. Pass as_markdown=False for the bracketed preview_tree form with UUIDs inline (use only when you specifically need UUIDs for a structural op). Optional output_file writes the result to disk: single Markdown file when as_markdown=True (the default), JSON (structured node tree with UUIDs + companion Markdown view) when as_markdown=False. Optional target_tab selects WHICH Workflowy tab to GLIMPSE when several are open: pass a tab alias or an endpoint_id; resolved alias-first by exact whole-string match. The alias MAY contain spaces (a multi-word phrase such as 'my big project' is fine) — pass it verbatim, exactly as the user named the tab; it is never split into tokens. Omit it for the common single-tab case (auto-selected); with multiple tabs and no target_tab you get an actionable error listing the available tab aliases. For UUID-targeted reads of arbitrary subtrees, use workflowy_scry. Optional slice_group makes GLIMPSE UNIVERSAL: instead of reading the live Workflowy expansion state over the DOM, it projects a named F8 SLICE GROUP straight from the /nodes-export cache (NO human at the GUI, NO live expansion needed) and renders it through the exact same composer, so the output is structurally identical to a live-DOM GLIMPSE of that same expanded slice. Pass the slice group's id (prefix-tolerant, like other UUID args) OR its name; the group's stored Root UUID scopes the projection and its tag prefixes select membership. The only WebSocket touch in this mode is the tab-agnostic slice-group CONFIG read (not a DOM extraction). Use list_slice_groups to see available groups. Optional root_uuid takes an even simpler cache-only RAW-DUMP path: pass any bare Workflowy UUID (prefix-tolerant) and GLIMPSE projects the COMPLETE subtree beneath it from the /nodes-export cache — EVERY descendant, no slice/tag filtering, no expand/suppress/deprecated policy — rendered through the same composer, with NO live expansion state and no DOM read at all (the one WebSocket touch on this path is the Anchor-Dock guard's tab-agnostic config read: a bare-root_uuid dump rooted AT an Anchor Dock is refused with a peek/render teaching error unless allow_anchor_dock=true; output_file and push_to_modal are exempt). This is 'SCRY-as-Markdown': read everything under any UUID server-side. You MAY pass slice_group AND root_uuid TOGETHER: the group supplies its tags/policy but the projection is SCOPED TO your root_uuid (an OVERRIDE root replacing the group's stored default root) -- 'run my <group> lens, but rooted HERE' (e.g. point a lens at a descendant of a suppression node to spotlight what was suppressed; any existing node is a valid scope, no ancestor/containment relationship required). So the (slice_group, root_uuid) presence is the whole server-side truth table: root_uuid only = raw dump; slice_group only = slice at the group root; BOTH = slice at the override root. When both are omitted, GLIMPSE behaves exactly as before (live DOM). Optional headings_only=True emits ONLY heading/title text and drops every node's note body -- the token-slashing 'titles only' view (structure without content), honored in BOTH Markdown mode (drops note bodies) and full/UUID mode (drops the inline [note] suffix); it is orthogonal and applies to the live-DOM, slice_group, and root_uuid paths alike. Optional since shows only the RECENT TAIL. THREE forms: (A) a TIME WINDOW like since='1w' / '3d' / '12h' (units s|m|h|d|w; a bare number means days) keeps every branch whose date is within the window of the DATA'S LEADING EDGE (newest branch-date minus the window -- NOT wall-clock now, so 'last 1 week' on data whose newest item is 2 years old means the week ending at that 2-year-old edge); works on the live-DOM, slice_group, and root_uuid paths. (B) since='curated' is the SELF-MAINTAINING CURATION CURSOR and REQUIRES slice_group: the pivot is the most-recent node under the group's root that carries ANY of the group's tags (INCLUDING --deprecated/--suppress variants, since triaging a tag is itself curation), so the result is exactly the UNCURATED TAIL = everything added since the last curation pass; as you tag those nodes the high-water mark advances and the tail shrinks to empty. (C) an ITEM COUNT like since='last 10' (or 'last 10 items') keeps the LAST N LEAF nodes of the final render order -- the tail of whatever order is in effect (most-recent under an ascending chronological sort, earliest under descending, last-in-document-order when unsorted). Unlike (A) and (B), the item count is ORTHOGONAL to sort: it needs NO sort_by (it counts leaves in the current order) and works on every path (live-DOM, slice_group, root_uuid, modal). It counts LEAVES only; a subtree with K leaves consumes K of the count. `since` is applied LAST, after Phase 1/2/3 and the sort. Date forms (window/curated) use the SinceSpec object's own axis/direction (default created/asc), so they do NOT require a presentation sort_by at all; since='curated' still requires slice_group (to define 'curated'), and item-count remains sort-orthogonal. ⚠️ SLICE↔WORKFLOWY-GUI DIVERGENCE (matters ONLY if you try to reproduce a slice_group GLIMPSE in the docked Markdown modal AND sync it back to the live Workflowy pane): the slice_group render intentionally diverges from what Workflowy's own search box can reproduce, in TWO ways. (1) To make the live search box surface the slice, the server auto-populates it with EVERY tag variant it finds in the full descendant tree under the group's Root UUID — including tags that are one of the group's prefixes PLUS an arbitrary extra middle segment (so a personal variant of a slice tag still matches), each with its own deprecated-negation. This can EXPLODE the search string; there is a hard cutoff, so for a complex slice with many tag variants the GUI search may be REFUSED and you simply cannot reproduce that slice in the Workflowy search box (the server render/GLIMPSE itself is unaffected — only the GUI-sync shortcut). (2) The slice_group GLIMPSE (and the Markdown modal) HIDE the childless “zombie” root-contraction nodes left behind by a collapsed suppressed/deprecated subtree; the live Workflowy GUI CANNOT hide those (collapse hides a node's descendants but keeps the node itself), so the reproduced GUI view will still show them as collapsed bullets. Both divergences are by design and are surfaced in the modal UI; they never affect the correctness of the GLIMPSE output itself. Optional push_to_modal=True (SLICE-GROUP ONLY) does NOT return the slice to you; it COMMANDS the target Workflowy tab to render that slice group into its docked Markdown modal — the server-push equivalent of the human clicking the green APPLY button — honoring your sort_by/sort_direction (and since) as an explicit override so you can push a scope pre-sorted (e.g. by creation date). It works for ANY server-side scope: slice_group (push the named slice), root_uuid (push a RAW DUMP of that subtree -- the zero-token 'show me this anchor, in full' command), or BOTH (the group's lens scoped to an override root). It errors on a bare live-DOM GLIMPSE (neither scope -- nothing to project) and refuses render_spec='modal' + push (cross-tab copy pending); with a render_spec BLOB it IS honored (the resolved spec routes through the same push funnel; the blob's focus is dropped); returns a small ack, not content. Optional render_spec is the 'GLIMPSE exactly what I'm looking at in the docked Markdown modal' surface -- ONE argument doing double duty that, when present, fully specifies the render and short-circuits every other scope arg. Pass render_spec='modal' (the primary, one-call path) to have the server ask the target tab what its docked modal is CURRENTLY showing (its current scope + selected-row focus) and re-project that exact view server-side -- the agent supplies NO UUIDs at all, which eliminates focus-UUID hallucination at the source (requires the dock to be showing a cache-sourced render; else an actionable error). OR pass render_spec=<a full render-spec object, or a JSON string of one> (the fallback paste path): the dock's per-row 'copy GLIMPSE focus' button copies exactly this blob -- the current scope with the selected row folded in as its focus field -- so a human can hand it to the agent verbatim to reproduce that focused view without a round trip; the server deserializes it and applies UUID prefix-grace to every UUID it carries before the exact occurrence-match. (render_spec REPLACED the older bare focus triple argument: a row triple is simply the focus FIELD of a spec blob, so the blob subsumes it and the 'modal' path removes the need to type it at all.)"
)
# @beacon[
#   id=auto-beacon@glimpse-rxug,
#   role=glimpse(output_file, as_markdown: bool, target_tab, sort_by, sort_direction, slice_group, root_uuid, headings_only, render_spec, allow_anchor_dock),
#   slice_labels=nexus--md-preview,glimpse-render,live-dom,
#   kind=ast,
#   comment=GLIMPSE ingress: modal sentinel then simple/formal grammar and the existing spec/grace/view-override/push/render path. Threads include_rows only to the public shaper: successful in-memory Markdown can carry canonical rows and the SAME resolved projection spec beside the finalized legacy string. Absent/false and full/UUID/file/push/error returns stay unchanged. Raw recursive=False uses the ONE walker's max_depth=1; slice/live-DOM depth caps remain refused.,
# ]
async def _glimpse_run_impl(
    output_file: str | None = None,
    as_markdown: bool | None = None,
    target_tab: str | None = None,
    sort_by: str | None = None,
    sort_direction: str = "asc",
    slice_group: str | None = None,
    root_uuid: str | None = None,
    headings_only: bool | None = None,
    since: str | None = None,
    recent_by: str | None = None,
    push_to_modal: bool = False,
    match_scope: str = "name_and_note",
    descend_policy: str = "all",
    # [ap:EPR86W] part a: the depth leg of the traversal pair. True (default)
    # = the historical unbounded walk; False = a RAW-ROOT render of the scope
    # root + its DIRECT children only. Refused loudly for a slice-group scope
    # and on a live-DOM GLIMPSE (no server descent to bound) -- see the guard
    # below.
    recursive: bool = True,
    render_spec: str | dict[str, Any] | None = None,
    allow_anchor_dock: bool = False,
    ancestor_notes: bool = False,
    full_uuids: bool = False,
    # REPOSITORY VIEW (U1, MasterSpec §5.2): the registry passes the RAW
    # param (True / False / absent-None). The explicit group/root paths
    # forward bool(); the render_spec paths apply it through the ONE
    # override seam (tri-state None = inherit the blob's own value, which
    # is always False by §3.6).
    repository_view: bool | None = None,
    include_rows: bool = False,
) -> Any:
    """Load the currently-visible Workflowy subtree into agent context.

    RETURN CONTRACT (the GLIMPSE-family agent-facing shape, via
    ``_shape_glimpse_family_return``): in Markdown mode this returns the RAW
    Markdown STRING (real newlines, exactly like ``read_text_file`` -- no JSON
    envelope, no ``rows``) unless include_rows opts into the existing rows
    and resolved spec beside that exact Markdown; in full/UUID mode it returns the structured dict
    with ``preview_tree`` PLUS the useful metadata (node_count, depth,
    _source, render_scope, ...), minus only the redundant ``rows`` content
    twin; ``output_file`` writes and error/ack payloads return the structured
    dict unchanged. Hence the ``Any`` annotation (str | list | dict).

    GLIMPSE command - efficient context loading for agent analysis.

    Auto-resolves to whatever bullet the user is currently zoomed into in
    Workflowy. The Chrome/Electron extension finds the DOM element carrying
    CSS class ``project root`` (Workflowy's own marker for the zoomed-in
    node) and walks its subtree. No UUID is needed or accepted; this is by
    design — the agent should follow the user's natural zoom-in/zoom-out
    workflow rather than navigate by hardcoded UUIDs. If you need a
    UUID-targeted read of an arbitrary subtree (independent of the user's
    current zoom), use ``workflowy_scry`` instead.

    Args:
        output_file: Optional absolute path; if provided, write the GLIMPSE
            result to disk. The disk-write format is selected by as_markdown:
            - as_markdown=False: structured JSON export (WebSocket+API merge
              with has_hidden_children / children_status annotations,
              original_ids_seen ledger, full node tree) + a companion
              Markdown view written alongside as <output_file>.md.
            - as_markdown=True: single compact Markdown file written directly
              to output_file.
        as_markdown: Defaults to True. When True (the default), both the
            in-memory preview and the on-disk output (when output_file is
            provided) use the compact Markdown heading + note text form
            instead of the bracketed preview_tree / structured JSON form.
            Markdown mode also strips generated Cartographer metadata
            blocks (MD_PATH, AST_QUALNAME, BEACON blocks) from notes so the
            output reads as a clean pseudo-document.

            This is the preferred default even for SOURCE-CODE Cartographer
            slices — not just for Markdown files. Despite the name, the
            flag describes the OUTPUT FORMAT (render the result *as*
            Markdown), not the kind of thing being rendered, so it applies
            equally well to a slice of Python/JS/TS/Vue/SQL/shell source.
            Two concrete wins for source code:
              * Token cost: the Markdown form is dramatically cheaper than
                the bracketed JSON preview_tree — roughly half the tokens
                on a typical multi-file beacon slice — because it drops
                UUIDs, positional indices, and JSON scaffolding.
              * Readability: the prettified Markdown reads like a code
                outline. File boundaries are unmistakable (the per-file
                header + Path: + LINE COUNT: triad), each function / class /
                constant is its own heading carrying its full signature,
                slurped docstrings and adjacent comments render as flowing
                prose, and slice-label tags appear inline on the heading.
                This makes source-code beacon slices materially easier to
                navigate than the JSON form.
            The only thing dropped is inline UUIDs, and those are rarely
            needed (use read_text_snippet_by_symbol to read mapped source
            by function/class/beacon name; it resolves symbols even if they
            were not visible in the GLIMPSE).

            Pass as_markdown=False to get the bracketed preview_tree form,
            which preserves the metadata blocks and shows UUIDs inline —
            use it only when you specifically need a UUID for a structural
            operation (e.g. targeting an ETCH parent or a move_node).
        target_tab: Optional string naming WHICH Workflowy tab to
            GLIMPSE when more than one is connected to the broker. Accepts a
            human-set tab ALIAS OR an opaque endpoint_id; the broker resolves
            it ALIAS-FIRST (by exact, whole-string match), then falls back to
            endpoint_id. The alias may be a multi-word PHRASE containing
            spaces (e.g. "spine" or "my big project") — pass it verbatim,
            exactly as the user named the tab, including internal spaces; it
            is matched as a whole string, never split into tokens. Leave None
            for the common single-tab case (the broker auto-selects the only
            connected tab). With multiple tabs and no target_tab, the broker
            returns an actionable error listing the available tabs.
        sort_by: Optional Markdown-mode reorder of the rendered pseudo-
            document by node timestamp. "created" sorts by each LEAF's
            own creation time (an append-log view: the things you created, in
            creation order, each carried with its full ancestor path).
            "modified" sorts each root->leaf BRANCH by the most-recent edit
            time anywhere on that branch (a "what did I touch most recently"
            view). "none" is EXPLICIT natural document order. When a branch's
            ancestors are straddled in time by another branch, the shared
            ancestor (e.g. a file/heading) is re-emitted to preserve context —
            exactly like the natural file-leader repetition. Only affects
            as_markdown=True output; the bracketed UUID tree is never
            reordered. Identical sorting applies in the docked Markdown modal
            via its sort widget (shared server-side composer).
            DEFAULT / OMITTED (None) is CONTEXT-DEPENDENT (SGSORT, 2026): for a
            slice_group GLIMPSE (or slice_group push), omitting sort_by INHERITS
            that slice group's SAVED DEFAULT SORT (set per group in the widget /
            via create_slice_group / update_slice_group) — the server resolves
            it once the group config is in hand. Pass sort_by="none" to FORCE
            document order and override the saved default; pass
            "created"/"modified" for an explicit chronological override. For a
            live-DOM or bare root_uuid GLIMPSE (no slice group), there is no
            saved default, so omitting sort_by is plain natural document order
            (the historical behavior).
        sort_direction: "asc" (default; oldest/least-recent first) or "desc"
            (most-recent first). Ignored when sort_by is None.
        slice_group: Optional F8 slice-group id (prefix-tolerant) OR name.
            When provided, GLIMPSE takes its CACHE-ONLY path: it does NOT read
            the live Workflowy DOM/expansion state at all. Instead it reads the
            slice-group config (a tab-agnostic options read -- the only
            WebSocket touch), resolves the group's Root UUID + tag prefixes,
            projects the slice subtree directly from the /nodes-export cache,
            and renders it through the SAME composer the live-DOM path uses --
            so the output is structurally identical to a live-DOM GLIMPSE of
            that same expanded slice, with no human at the GUI. This makes
            session initialization replayable inside an automated agent loop.
            When None (the default), GLIMPSE behaves exactly as before (live
            DOM). target_tab/as_markdown/output_file/sort_by/sort_direction all
            still apply in slice_group mode.
        root_uuid: Optional Workflowy node handle -- a UUID (exact or a unique
            prefix) OR an [ap:CORE] anchor-point handle (NOT a source-code
            symbol; that is meaningless for a projection scope). When
            provided, GLIMPSE takes a pure CACHE-ONLY RAW-DUMP path: it projects
            the COMPLETE subtree beneath root_uuid straight from the
            /nodes-export cache -- EVERY descendant, with no slice membership
            filter and no expand/suppress/deprecated policy -- and renders it
            through the SAME composer the live-DOM path uses. This is
            "SCRY-as-Markdown": read everything under any UUID server-side, with
            NO live Workflowy expansion state and no DOM read at all (the one
            WebSocket touch on this path is the Anchor-Dock guard's tab-agnostic
            config read -- the historical 'no WebSocket at all' doctrine is
            retracted for config reads). The
            handle is resolved against the cache (exact UUID -> unique UUID
            prefix -> [ap:CORE] anchor-point handle; an ambiguous prefix or
            duplicated AP-ID returns a 'did you mean?' disambiguation; no match
            is a cache-miss error). This SAME UUID-or-AP-ID resolution applies
            to the raw-dump root, the slice-override root, AND a push root, so
            you can pass an anchor's [ap:CORE] handle anywhere a root_uuid is
            accepted. (slice_group is a DIFFERENT namespace -- a group id / name
            -- and does NOT accept an AP-ID; if you want a slice's lens rooted
            at an anchor, pass slice_group=<the lens> with root_uuid=[ap:CORE].)
            as_markdown/output_file/sort_by/sort_direction all still
            apply. ANCHOR-DOCK GUARD (2026): a bare-root_uuid raw dump whose
            resolved root IS an Anchor Dock is refused with an
            anchor_dock_root_detected teaching error (a full in-band Dock dump
            can be megabytes of agent context) -- use anchor.dock.peek /
            anchor.dock.render instead, or pass allow_anchor_dock=true.
            output_file writes and push_to_modal are exempt (out-of-band
            delivery); a slice_group+root_uuid override root renders a curated
            lens, not a raw dump, and is likewise NOT guarded. Passing BOTH
            slice_group AND root_uuid is the COMBINED mode:
            the group supplies its tags/policy but root_uuid OVERRIDES the
            group's stored default root as the projection scope ('run my
            <group> lens, but rooted HERE' -- e.g. spotlight a descendant of a
            suppression node). Any cache-present node is a valid override scope;
            there is DELIBERATELY no ancestor/containment requirement between
            the two roots. So the (slice_group, root_uuid) presence defines the
            whole server-side truth table: root_uuid only = raw dump;
            slice_group only = slice at the group root; BOTH = slice at the
            override root. When None (the default), GLIMPSE behaves as before
            (live DOM, unless slice_group is set).
        headings_only: Defaults to False. When True, emit ONLY heading/title
            text and DROP every node's note body -- the token-slashing
            "titles only" view (structure without content). Honored in BOTH
            output formats: in Markdown mode (as_markdown=True) it suppresses
            all note-body emission (and markdown-in-markdown embedding),
            leaving just the heading lines; in full/UUID mode
            (as_markdown=False) it drops the inline ``[note]`` suffix, leaving
            just the node name (+ UUID / preview_id / abs-path). Orthogonal to
            every other arg -- it applies to the live-DOM GLIMPSE, the
            slice_group cache path, and the root_uuid cache path alike.
        since: Optional RECENT-TAIL filter. Applied LAST -- after Phase 1/2/3
            membership+expansion AND after any timestamp sort -- so it filters
            exactly the final ordered branches. THREE forms. The FIRST TWO are
            branch-date pivots; SINCE↔SORT DECOUPLE (2026): the date pivot uses
            the ``since`` request's OWN axis/direction (default created/asc),
            NOT the presentation ``sort_by``, so a date-form ``since`` NO LONGER
            requires an active ``sort_by`` -- it works with a chronological sort
            OR with plain document order. (Curated still requires a
            ``slice_group`` to DEFINE 'curated', but not a presentation sort.)
            The THIRD form is an item count that is likewise sort-orthogonal:

            * Form A -- TIME WINDOW. A duration token: ``"1w"`` / ``"3d"`` /
              ``"12h"`` / ``"90m"`` / ``"45s"`` (units s|m|h|d|w); a BARE
              number means DAYS (``"7"`` == one week). The window is anchored
              to the DATA'S LEADING EDGE, not wall-clock now: ascending keeps
              branches with date > (newest branch-date - window). So "last 1
              week" on data whose newest item is 2 years old returns the week
              ENDING at that 2-year-old edge. Works on ALL three sources
              (live-DOM, slice_group, root_uuid). Needs a timestamp AXIS, which
              the SinceSpec always supplies -- NOT a presentation sort.

            * Form B -- ``"curated"`` (the self-maintaining CURATION CURSOR).
              REQUIRES ``slice_group`` (to define 'curated'); no presentation
              sort is required. The pivot is the branch-date
              of the MOST RECENT node under the group's root that carries ANY
              tag matching the group's prefixes -- INCLUDING ``--deprecated`` /
              ``--suppress`` variants, because deprecating/suppressing a tag
              is itself a curation act you should not re-encounter. The
              result is therefore the UNCURATED TAIL: everything created since
              the last curation pass. As you tag those nodes, the high-water
              mark advances and the tail shrinks toward empty. If nothing
              under the root is curated yet, the whole subtree is returned
              (all of it is "new since last curated"). Invalid (loud error)
              on the live-DOM and bare-root_uuid paths, which have no slice
              membership to define "curated".

            * Form C -- ITEM COUNT ([ap:TVIIBN] 4d(a)). ``"last N"`` /
              ``"newest N"`` (or ``"last N items"``), e.g. ``"last 10"``.
              SELECTS the N NEWEST leaf nodes by the recency basis
              (``recent_by``; else the presentation ``sort_by`` axis when it
              is a timestamp, else ``'modified'``) -- whatever the sort
              direction. It is ORTHOGONAL to sort: it needs NO ``sort_by``,
              the selected set is the same under ascending and descending,
              and it works on EVERY path (live-DOM, slice_group, root_uuid,
              and the docked modal). It counts LEAVES only -- a node with no
              visible children in the final tree -- so a subtree with K leaves
              consumes K of the count. N >= the leaf count returns everything
              unchanged. ``"bottom N"`` instead keeps the POSITIONAL tail of
              the current render order (the legacy ``"last N"`` behavior; an
              old wire blob without a selection field means this). A bare
              ``"last"`` with no N is a malformed item-count (loud error), NOT
              a time window.

            ``sort_direction`` only ORDERS the selected branches (Forms A/B/C)
            -- it never changes which branches a recency selection chose; the
            newest selection is direction-independent by rule. On the
            consolidated render verbs a ``sort_direction`` without an explicit
            timestamp ``sort_by`` is a loud ``sort_direction_without_sort_by``
            error. The response
        echoes a ``since_applied`` block -- ``{form:"window"|"curated",
        pivot_ts:N}`` for A/B or ``{form:"item_count", count:N,
        selection:"newest"|"bottom", basis:...}`` for C --
        and, when nothing survives, ``empty_window: true`` (a valid answer,
        e.g. once the curation cursor has caught up).
    ancestor_notes: Defaults to False. U6 TEACHING FLAG (ap:E03BN3, Dan's
        ruling): ancestor notes are SUPPRESSED ON CHRONOLOGICAL RENDERS --
        an explicit ``sort_by`` of created OR modified (either direction), or
        ANY ``recent`` selection (a date window like '1w', 'curated', or an
        item-count 'last N'/'newest N'/'bottom N') -- where
        every non-leaf of the final render forest (the root included when it
        is a non-leaf) renders HEADING-ONLY and leaf notes print. Member set,
        ordering and renders with no sort and no recent selection are
        untouched -- there, ancestor notes genuinely frame
        what follows and stay. ONE more default suppression: on a LENS render
        (a render_spec blob carrying lightning mode render_lens) the
        connective scaffolding above the lens's input roots renders
        heading-only by default EVEN IN DOCUMENT order -- input roots and
        their subtrees unaffected. Pass ``ancestor_notes: true`` -- the sole
        opt-out -- to include ancestor notes on a chronological render and to
        restore the lens scaffold notes. Applies to this tool's server-side cache scopes
        (group_handle / root_handle cells, push included); with ``render_spec``
        present, the spec blob's own value applies (the render_spec
        short-circuit ignores explicit scope args). There is deliberately NO
        knob to suppress ancestor notes in document order.
    push_to_modal: Defaults to False. When True, GLIMPSE does NOT return the
            rendered content to the agent; instead it COMMANDS the target
            Workflowy tab to render the requested server-side SCOPE straight
            into its docked Markdown modal -- the server-push equivalent of the
            human clicking the green APPLY button. The tab runs the exact same
            shared apply path (cache projection -> dock render -> live-GUI-sync
            watcher) a manual APPLY runs, so the result is identical. The
            AGENT-SUPPLIED sort_by/sort_direction (and since) are honored as an
            EXPLICIT override (the push never reads or mutates the tab's global
            dock sort), so you can push pre-sorted by creation date, etc.
            Works for ANY server-side scope, mirroring the truth table above:
            slice_group (push the named slice), root_uuid (push a RAW DUMP of
            that subtree -- the zero-token 'show me this anchor, in full'
            command that gives full human-readable visibility at NO agent-token
            cost, since the agent never ingests the content), or BOTH (the
            group's lens scoped to an override root). It is an error on a
            bare live-DOM GLIMPSE (neither scope -- nothing to project), and
            it is REFUSED loudly with render_spec='modal' (read one tab's
            dock then push it into another -- a cross-tab copy feature that
            is not built yet). With a render_spec BLOB it IS honored: the
            resolved spec routes through the SAME push funnel and its ack
            comes back (the blob's `focus` is dropped -- a push paints the
            full document). For a raw-dump push there is no slice search /
            expand-collapse plan, so
            NO live-GUI-sync watcher is installed (the modal render is complete
            by construction regardless). Returns a small ack (success + the
            scope pushed + the sort), not content.
        match_scope: SELECTION-stage scope knob. Controls WHERE slice-group
            tag MEMBERSHIP looks for a matching tag:
              * "name_and_note" (default -- prior behavior): a tag matches
                whether it lives in the node's NAME (title) or its NOTE body,
                matching how a pasted Workflowy tag-search behaves.
              * "name": a node is admitted to the slice ONLY if the matching
                tag lives in its NAME (title); tags living only in the note
                body do NOT pull the node into the slice.
            APPLICABILITY: this is a PREDICATE (search) concern, so it applies
            ONLY to the slice_group path (whose membership is tag-defined) --
            including a slice_group+root_uuid override and a slice_group push.
            It is NOT meaningful for a live-DOM GLIMPSE (no server-side
            predicate; the human's expansion IS the selection) nor for a bare
            root_uuid RAW DUMP (every descendant is included unconditionally),
            so passing match_scope="name" on either of those paths is a LOUD
            error rather than a silent no-op. It also governs the
            --expand/--suppress/--deprecated postfix OPERATION policy on this
            path (084 ruling): under "name" a family postfix counts only in
            the name's TRAILING tag region; under "name_and_note" it also
            counts in the note (Workflowy-search parity). The global
            never-expand tag (e.g. #wfy-suppress) counts only in the trailing
            tag region under EVERY scope.
            NOTE (documented divergence): with match_scope="name" the server
            render can differ slightly from what a pasted Workflowy search box
            would surface (Workflowy has no title-only tag mode); this is the
            accepted 'moored mode' light divergence -- press Refresh / re-sync
            when you want the live pane to match.
        render_spec: The 'GLIMPSE the docked Markdown modal' surface. ONE
            argument doing DOUBLE DUTY; when present it fully specifies the
            render and SHORT-CIRCUITS every other scope arg (slice_group /
            root_uuid / match_scope / descend_policy / sort / since /
            headings_only are all ignored -- the spec carries its own).
            push_to_modal is NOT one of the ignored args: with a spec BLOB it
            routes the resolved spec through the SAME push funnel an
            explicit-scope push uses (returning the push ack; the blob's
            focus is dropped -- a push paints the full document), and with
            'modal' it is refused loudly (cross-tab read-then-push copy is a
            pending feature).
              * render_spec="modal" (the PRIMARY, one-call path): 'GLIMPSE
                exactly what I'm looking at in the docked modal, right now.'
                The server sends ONE WebSocket query to the target tab, which
                answers with the scope + selected-row focus it is CURRENTLY
                showing (from its own server-adopted render state); the server
                then re-projects that scope server-side. The agent supplies NO
                UUIDs at all -- this is the whole point, eliminating focus-UUID
                hallucination at the source. Requires the dock to be showing a
                cache-sourced render (an applied slice / a pushed scope);
                otherwise it returns an actionable error.
              * render_spec=<blob> (a full render-spec object, OR a JSON string
                of one): the FALLBACK paste path. The dock's '\u2318 focus'
                button copies exactly this blob (the current scope + the
                selected row folded in as its `focus` field); a human can hand
                it to the agent to reproduce that focused view without a
                WebSocket round trip. The server deserializes it and applies
                UUID prefix-grace to every UUID it carries (root + the focus
                triple) before the exact occurrence-match, so a slightly-
                drifted pasted UUID still resolves.
            (render_spec REPLACED the older bare `focus` triple argument: a row
            triple is simply the `focus` FIELD of a spec blob, so the blob form
            subsumes it and the primary "modal" path removes the need to type
            it at all.)

            AGENT VIEW OVERRIDES over a render_spec (TRI-STATE). By default a
            render_spec render shows the agent EXACTLY what the human is
            looking at in the modal. But the agent MAY override the VIEW knobs
            of that view -- as_markdown / headings_only / sort_by /
            sort_direction / since -- and the override applies for BOTH the
            "modal" and pasted-blob forms. as_markdown / headings_only are
            TRI-STATE here: leave them unset (None) to inherit the modal's own
            view, or pass an explicit value to override. THE MOTIVATING USE
            CASE: after viewing a clicked modal row, re-call with
            render_spec="modal", as_markdown=False, headings_only=True to get a
            compact bracketed {UUID <-> title} table for EXACTLY the focused
            subtree -- the occurrence-exact handles you need to tag/edit those
            nodes. GUARDS (loud): when the modal view is FOCUSED on a clicked
            row, a sort override or a since override is REJECTED (sorting/
            windowing a single option-Y row is ill-defined -- re-root the modal
            at that subtree instead); since='curated' still needs a
            slice-group scope.

    Returns:
        When output_file is None: Minimal in-memory preview with only
            preview_tree (or preview_markdown when as_markdown=True) +
            basic stats (no full JSON node tree).
        When output_file is provided: Compact summary with the written file
            path(s) and stats.
    """
    # TRI-STATE view knobs (as_markdown / headings_only default to None at the
    # signature). For the render_spec path, None = 'inherit what the docked
    # modal is showing'; a value = an explicit agent override. For EVERY OTHER
    # path (live-DOM / slice_group / root_uuid / push), None must resolve to
    # the historical defaults (as_markdown=True, headings_only=False) so those
    # paths behave byte-for-byte as before. We compute the effective values
    # ONCE here and use them everywhere below; the render_spec block (which
    # runs first and returns) reads the RAW tri-state args instead, forwarding
    # them as ov_* overrides.
    #
    # sort_direction has a plain "asc" default (not None), so 'was it
    # explicitly set?' is undecidable on its own -- we treat it as an override
    # ONLY when sort_by was also supplied (a direction with no sort_by is
    # meaningless), which collapses the ambiguity cleanly for the render_spec
    # override.
    _sort_direction_explicit = sort_by is not None
    # Preserve the RAW tri-state values for the render_spec override path
    # (which needs None to mean 'inherit'); the effective coercion below is for
    # every other path.
    _ov_as_markdown = as_markdown
    _ov_headings_only = headings_only
    as_markdown = True if as_markdown is None else bool(as_markdown)
    headings_only = False if headings_only is None else bool(headings_only)

    _since_obj_for_guard, _since_error_for_guard = _since_from_edge_result(since)
    if _since_error_for_guard:
        return {"success": False, "error": _since_error_for_guard}

    if _since_obj_for_guard is not None:
        if _since_obj_for_guard.form == "curated" and not slice_group:
            return {
                "success": False,
                "error": (
                    "since='curated' (the new-since-last-curated curation cursor) "
                    "requires a slice_group -- it defines 'curated' as 'carries a "
                    "tag from this slice group'. It is meaningless on a live-DOM "
                    "or bare-root_uuid GLIMPSE. Pass slice_group=... with "
                    "since='curated', or use a time window (e.g. since='1w') or "
                    "an item count (e.g. since='last 10')."
                ),
            }

    # RENDER_SPEC dispatch (the 'GLIMPSE the docked modal' surface). This ONE
    # argument does DOUBLE DUTY and, when present, SHORT-CIRCUITS every other
    # scope arg below (it fully specifies the render on its own):
    #
    #   * render_spec="modal"  -> the PRIMARY, one-call 'GLIMPSE exactly what
    #     I'm looking at in the docked Markdown modal' path. The server issues
    #     ONE Direction-A WS query to the target tab (get_current_modal_render_
    #     spec); the tab answers with its OWN current dock scope + selected-row
    #     focus (from dockedSliceContext.render_spec + the selected row). The
    #     SERVER then deserializes + re-projects. The agent types ZERO UUIDs --
    #     which is the whole point: it eliminates focus-UUID hallucination at
    #     the source (the (b)-variant architecture). See _glimpse_read_modal.
    #
    #   * render_spec={...} (a dict) OR a JSON string of same -> the FALLBACK
    #     paste path: a full RenderProjectionSpec blob (scope + optional focus
    #     field), typically copied from the dock's '\u2318 focus' button and
    #     handed to the agent. The server deserializes it (from_render_spec_
    #     blob), applies UUID prefix-grace to every UUID it carries (root +
    #     focus triple), and re-projects. This is the ONLY path where the agent
    #     might carry UUIDs, so the grace step is the real safety net here.
    #
    # Both paths converge on the ONE RenderProjectionSpec object + the shared
    # _glimpse_dispatch_spec, so a modal read and a pasted blob render through
    # the exact same helpers as an explicit-arg GLIMPSE -- no second renderer,
    # no client-string round-trip through the server (the Python composer stays
    # the sole renderer). render_spec REPLACED the older bare `focus` triple
    # arg (a row triple is just the `focus` FIELD of a spec blob, so the dict
    # form subsumes it); there is intentionally exactly ONE new argument.
    if render_spec is not None and render_spec != "":
        # Sentinel string -> the WS modal-read path. The agent's TRI-STATE view
        # knobs (None = inherit what the modal shows) are forwarded as ov_*
        # overrides; _glimpse_read_modal applies them + the LOUD guards via the
        # ONE shared seam before dispatch.
        if isinstance(render_spec, str) and render_spec.strip().lower() == "modal":
            # MODAL READ + PUSH (read tab A's dock, push it into tab B) is a
            # cross-tab COPY FEATURE awaiting Dan's ruling (RECON ap:6RHNGJ
            # §8.2) -- NOT a bug fix. Refuse it loudly rather than silently
            # ignoring the flag (the pre-fix behavior returned the modal's
            # content render while pushing nothing: the same false success
            # the blob path had). Point at the push surfaces that DO work.
            if push_to_modal:
                return {
                    "success": False,
                    "error": (
                        "push_to_modal cannot be combined with "
                        "render_spec='modal': reading one tab's dock and "
                        "pushing it into another (a cross-tab copy) is a "
                        "feature that is not built yet. To push a scope into "
                        "a tab's modal, pass it explicitly -- group_handle=... "
                        "and/or root_handle=... with push_to_modal=true, or "
                        "render_spec=<a full spec blob> with "
                        "push_to_modal=true. To simply READ the docked "
                        "modal, omit push_to_modal."
                    ),
                }
            _mr = await _glimpse_read_modal(
                output_file=output_file,
                target_tab=target_tab,
                ov_as_markdown=_ov_as_markdown,
                ov_headings_only=_ov_headings_only,
                ov_sort_by=sort_by,
                ov_sort_direction=(
                    sort_direction if _sort_direction_explicit else None
                ),
                ov_since=_since_obj_for_guard,
                ov_recent_by=recent_by,
            )
            return _shape_glimpse_family_return(_mr, output_file=output_file, headings_only=headings_only, include_rows=include_rows)
        # New surface spellings are interpreted once, before the unchanged
        # blob/grace/override/render path. The modal sentinel stays first.
        form = normalize_simple_form(render_spec, surface="glimpse_run")
        if not form.ok:
            return _simple_form_failure(form)
        if form.form == "formal_array":
            return {"success": False, "code": "simple_form_wrong_surface",
                    "error": "render_spec is one view, not an array; use glimpse estate for multiple entries; see describe"}
        if form.form == "bare_handle" or form.root is not None:
            try:
                nodes = _anchor_cache_by_id()
                groups = (await _resolve_slice_group_config(target_tab))[0] if form.form == "bare_handle" else []
                vocabulary = await _read_anchor_dock_vocabulary(target_tab) if form.form == "bare_handle" or form.requires_dock else None
                form, role = _resolve_simple_form_from_snapshot(form, nodes, groups, vocabulary, inside_note=False)
                if not form.ok:
                    return _simple_form_failure(form)
                if role == "read_note":
                    node = await _node_read_impl(form.root, False)
                    entries, err = parse_estate_note(_note_wire_to_semantic(getattr(node, "note", "") or ""))
                    decision = decide_node_role(is_anchor=False, note_parses_as_estate=bool(entries) and err is None, inside_note=False)
                    return {"success": False, "code": decision.error_code or "simple_form_wrong_surface",
                            "error": decision.error_message or "render_spec is one view; use glimpse estate for an estate Anchor Point, never its first entry; see describe"}
                # REPOSITORY VIEW (Chain 1 r1, W1/F1, MasterSpec §3.3): a
                # {node} parcel (the node-alone read, lowered to the
                # render_symbols single-node scope) is REFUSED under the view
                # -- a plain-node read is not a beacon slice, so there is no
                # repository document to clean -- even when the named node
                # is a mapped entry the projection could render. A bare
                # plain-node handle never reaches a render on run (the
                # read_note refusal above speaks first), so the parcel form
                # is the one lowered shape to dispose here. Marker-gated so
                # the family wrapper honors the kernel code (A2).
                if repository_view and form.form == "node":
                    return {
                        "success": False,
                        "code": _REPOSITORY_VIEW_REFUSAL_ERROR,
                        "repository_view_refusal": True,
                        "error": (
                            "repository_view=true cannot render the {node} "
                            "parcel (the node-alone read): a plain-node read "
                            "is not a beacon slice, so there is no "
                            "repository document to clean. Use a tags, "
                            "symbols or subtree parcel for the commit file, "
                            "or drop repository_view."
                        ),
                    }
            except Exception as exc:
                return {"success": False, "error": str(exc)}
        _blob = form.spec or {}
        _spec = (RenderProjectionSpec.normalize_from_glimpse_args(group_id=form.text, match_scope="name")
                 if form.form in {"named_group", "passthrough_group"}
                 else RenderProjectionSpec.from_render_spec_blob(_blob))
        # UUID prefix-grace over the pasted spec's UUIDs (root + focus triple)
        # BEFORE the exact occurrence-match downstream -- the real hallucination
        # net for the paste path. Best-effort on a cache miss (downstream
        # helpers surface their own errors).
        try:
            _client = get_client()
            _all_nodes = _client._get_nodes_export_cache_nodes() or []
            _cache_by_id = {
                str(n["id"]): n for n in _all_nodes if isinstance(n, dict) and n.get("id")
            }
            _spec = _grace_resolve_spec_uuids(_spec, _cache_by_id)
        except Exception:
            pass
        # AGENT VIEW OVERRIDES + LOUD GUARDS -- the SAME shared seam the
        # "modal" path uses, so both render_spec sub-paths apply the tri-state
        # overrides and the focus/since guards identically. None = inherit the
        # pasted blob's own view knob.
        _spec, _paste_ov_err = _apply_modal_view_overrides_and_guard(
            _spec,
            as_markdown=_ov_as_markdown,
            headings_only=_ov_headings_only,
            sort_by=sort_by,
            sort_direction=(sort_direction if _sort_direction_explicit else None),
            since=_since_obj_for_guard,
            recent_by=recent_by,
            # REPOSITORY VIEW (U1, §5.2): the run-level flag applies to
            # render_spec specs through the ONE override seam (tri-state
            # None = inherit the blob's own value; its §3.4 backstop guard
            # re-checks the MERGED spec).
            repository_view=repository_view,
        )
        if _paste_ov_err is not None:
            return _paste_ov_err
        # PUSH-TO-MODAL ON THE BLOB PATH (R1, ap:8473VD; RECON ap:6RHNGJ
        # §6(i)): a pasted render_spec blob + push_to_modal routes the
        # RESOLVED spec through the ONE existing push funnel -- the SAME
        # _glimpse_push_slice_to_modal an explicit group_handle/root_handle
        # push uses -- and returns its ack (_source='push_to_modal'). Before
        # this routing existed, the block below returned the CONTENT render
        # without ever consulting the flag: the documented-contract violation
        # (false success -- no frame ever reached a tab). The funnel
        # re-resolves every scope against live config/cache (loud failures
        # stay loud), re-normalizes through normalize_from_glimpse_args and
        # emits its OWN wire blob: this is routing, not a second push path --
        # no new wire shape, no spec-format change. The per-kind field reads
        # mirror what _glimpse_dispatch_spec consumes below, so a blob push
        # admits exactly what a blob render admits:
        #   slice          -> slice_group only. root_uuid is NOT forwarded:
        #                     a plain 'slice' blob carries the group's stored
        #                     root as a RESOLVED ECHO (display/reuse), and the
        #                     render path ignores it the same way --
        #                     forwarding it would silently re-push the blob
        #                     as a slice_override pinned to a possibly stale
        #                     root instead of the group's LIVE stored root.
        #   slice_override -> slice_group + the override root_uuid.
        #   raw_root       -> root_uuid only.
        #   lightning_rod  -> root_uuid (the funnel enforces its own per-mode
        #                     root requirement) + the opaque lightning
        #                     selection, which the funnel re-validates and
        #                     re-canonicalizes.
        # `focus` is DELIBERATELY DROPPED: the funnel's normalization takes no
        # focus input, so a push paints the FULL document -- consistent with
        # canonical pushes and the import design (ap:HIH414 ruling 6). The
        # Anchor-Dock root guard needs no forwarding here: it guards the
        # in-band CONTENT raw-dump path only -- push (out-of-band delivery)
        # is exempt on the canonical path, and the blob render never ran it
        # either, so both admit a dock-rooted raw_root identically.
        # output_file is ignored on the push path (the ack IS the
        # deliverable), exactly as the canonical push dispatch below.
        if push_to_modal:
            _push_group: str | None = None
            _push_root: str | None = None
            _push_lightning: dict[str, Any] | None = None
            if _spec.kind in ("slice", "slice_override"):
                _push_group = str(_spec.group_id or "").strip() or None
                if _spec.kind == "slice_override":
                    _push_root = str(_spec.root_uuid or "").strip() or None
            elif _spec.kind == "raw_root":
                _push_root = str(_spec.root_uuid or "").strip() or None
            elif _spec.kind == "lightning_rod":
                _push_root = str(_spec.root_uuid or "").strip() or None
                _push_lightning = (
                    _spec.lightning if isinstance(_spec.lightning, dict) else None
                )
            _kind_pushable = (
                (_spec.kind in ("slice", "slice_override") and _push_group)
                or (_spec.kind == "raw_root" and _push_root)
                or (_spec.kind == "lightning_rod" and _push_lightning is not None)
            )
            if not _kind_pushable:
                # Degenerate blob: its resolved kind carries no pushable
                # scope. The SAME blob fails loudly as a render (the
                # dispatcher's no-root / no-selection errors below); fail
                # loudly here too -- BEFORE the funnel, whose caller contract
                # requires at least one scope present (a scope-less frame
                # would only fast-fail client-side after a pointless
                # round-trip).
                return {
                    "success": False,
                    "error": (
                        "push_to_modal with a render_spec blob requires a "
                        "pushable scope, but the resolved spec (kind "
                        f"{_spec.kind!r}) carries none: its group_id / "
                        "root_uuid / lightning selection is empty. Re-export "
                        "the blob from the dock's focus button, or push the "
                        "scope explicitly with group_handle=... and/or "
                        "root_handle=... plus push_to_modal=true."
                    ),
                }
            return await _glimpse_push_slice_to_modal(
                slice_group=_push_group,
                root_uuid=_push_root,
                lightning=_push_lightning,
                sort_by=_spec.sort_by,
                sort_direction=_spec.sort_direction,
                target_tab=target_tab,
                since=_spec.since,
                recent_by=getattr(_spec, "recent_by", None),
                match_scope=_spec.match_scope,
                headings_only=bool(_spec.headings_only),
                descend_policy=_spec.descend_policy,
                # U6: the blob's OWN flag rides the push (the render_spec
                # short-circuit ignores the explicit ancestor_notes arg, like
                # every other scope/view arg the blob carries).
                ancestor_notes=bool(_spec.ancestor_notes),
                # [ap:0M6VP8]: same for the heading-id form.
                full_uuids=bool(_spec.full_uuids),
            )
        _br = await _glimpse_dispatch_spec(
            _spec, output_file=output_file, target_tab=target_tab
        )
        return _shape_glimpse_family_return(_br, output_file=output_file, headings_only=headings_only, include_rows=include_rows)

    # SERVER-SIDE SCOPE MODEL (the (slice_group, root_uuid) truth table). The
    # PRESENCE of one or both of these two optional args is exactly what makes
    # GLIMPSE server-side (cache-projected) rather than client-side (live-DOM):
    #   * root_uuid ONLY          -> RAW DUMP of the whole subtree (member_all;
    #                                no slice tags, no Phase 2/3/4).
    #   * slice_group ONLY        -> slice projection scoped to the group's
    #                                stored default root, using its tags/policy.
    #   * slice_group + root_uuid -> slice projection using the group's
    #                                tags/policy but SCOPED TO root_uuid (the
    #                                override root REPLACES the group's default
    #                                root). This is the 'run my <group> lens,
    #                                but rooted HERE' mode -- e.g. spotlight a
    #                                descendant of a suppression node. There is
    #                                DELIBERATELY no ancestor/containment check
    #                                between the two roots; any cache-present
    #                                node is a valid scope (a feature, not a
    #                                constraint).
    #   * NEITHER                 -> live-DOM GLIMPSE (the original path).
    # So the two args are no longer mutually exclusive -- 'both' is a
    # first-class mode, not an error. (Dispatch below routes each cell.)

    # PUSH-TO-MODAL guard. push_to_modal does not return the slice to the agent;
    # it COMMANDS the target tab to render into its docked Markdown modal (the
    # server-push twin of the human APPLY button). It needs a SERVER-SIDE SCOPE
    # to project -- i.e. a slice_group and/or a root_uuid. A BARE live-DOM push
    # (neither arg) has nothing to project, so it remains an error. The three
    # cache-scoped cells above are ALL valid push targets (the modal's
    # cache-render handler resolves the same (slice_group, root_uuid) truth
    # table server-side, so a root-only raw dump and a slice+override both push
    # cleanly through the ONE shared apply path the APPLY button uses).
    if push_to_modal and not slice_group and not root_uuid:
        return {
            "success": False,
            "error": (
                "push_to_modal requires a server-side SCOPE to project into the "
                "docked modal: pass slice_group=... (a named F8 slice), "
                "root_uuid=... (a raw-dump of a subtree), or BOTH (a slice lens "
                "scoped to an override root). A bare live-DOM GLIMPSE has "
                "nothing to apply -- omit push_to_modal for the live-DOM read."
            ),
        }

    # match_scope GUARD (SELECTION-stage scope knob). It is a PREDICATE concern,
    # so it is meaningful ONLY where the server evaluates a tag-membership
    # predicate -- i.e. the slice_group path (bare, +override-root, or pushed).
    # It is NOT meaningful for a live-DOM GLIMPSE (the human's expansion is the
    # selection; no server predicate) nor for a bare root_uuid RAW DUMP (every
    # descendant is admitted unconditionally). Rather than silently ignore a
    # 'name' request on those paths (a confusing no-op), reject it loudly. The
    # default 'name_and_note' is always fine everywhere (it is a no-op that
    # preserves prior behavior), so only a non-default value is gated.
    _match_scope = str(match_scope or "name_and_note").strip().lower()
    if _match_scope not in ("name", "name_and_note"):
        return {
            "success": False,
            "error": (
                f"Unknown match_scope {match_scope!r}; use 'name' (slice "
                "membership matches tags in the node TITLE only) or "
                "'name_and_note' (default -- match tags in title AND note body)."
            ),
        }
    if _match_scope == "name" and not slice_group:
        return {
            "success": False,
            "error": (
                "match_scope='name' is only meaningful for a slice_group GLIMPSE "
                "(its membership is tag-defined, so restricting the match to "
                "node TITLES has an effect). A live-DOM GLIMPSE selects by the "
                "human's expansion (no server tag predicate), and a bare "
                "root_uuid RAW DUMP includes every descendant unconditionally, "
                "so 'name' would be a silent no-op there. Pass slice_group=... "
                "with match_scope='name', or omit match_scope."
            ),
        }

    # descend_policy GUARD (STOP-RECURSION traversal policy). This is a
    # TRAVERSAL knob (how deep to walk), ORTHOGONAL to match_scope (a predicate
    # knob) and to the slice expand/suppress/deprecated OPERATION policy. In
    # v1 the only non-default value is 'stop_at_child_anchors': while projecting
    # a subtree, STOP descending at any descendant that carries an anchor tag
    # (emit the child anchor as a visible leaf signpost, do not recurse into
    # it). It is a property of a RAW-ROOT (root_uuid) projection -- 'list the
    # anchor points under here without diving into sub-anchors' -- so it is
    # gated to the bare root_uuid path: it is NOT meaningful for a live-DOM
    # GLIMPSE (the human's expansion is the selection) nor for a slice_group
    # (whose shape is tag-defined + Phase-2 policy). Rejecting it loudly on
    # those paths avoids a confusing silent no-op. 'all' (default) is the
    # ordinary full descent and is always fine.
    _descend_policy = str(descend_policy or "all").strip().lower()
    if _descend_policy not in ("all", "stop_at_child_anchors"):
        return {
            "success": False,
            "error": (
                f"Unknown descend_policy {descend_policy!r}; use 'all' (default "
                "-- descend fully) or 'stop_at_child_anchors' (emit a child "
                "anchor as a visible leaf but do not recurse into it)."
            ),
        }
    if _descend_policy == "stop_at_child_anchors" and not (root_uuid or slice_group):
        return {
            "success": False,
            "error": (
                "descend_policy='stop_at_child_anchors' is only meaningful for "
                "a server-side cache projection (root_uuid raw dump, slice_group, "
                "or slice_group+root_uuid override). A live-DOM GLIMPSE walks "
                "the human's expansion, so there is no server descent to bound. "
                "Pass root_uuid=... and/or slice_group=..., or omit it."
            ),
        }

    # recursive GUARD ([ap:EPR86W] part a; the depth leg of the traversal
    # pair, same shape as the descend_policy guard above -- a knob that would
    # otherwise be a silent no-op is refused loudly). recursive=False means
    # "the scope root + its DIRECT children only", a RAW-ROOT traversal
    # policy: it is honoured on the bare root_uuid path (and threaded to the
    # push funnel), refused on a slice-group scope (membership is defined by
    # the predicate over the whole scope -- a depth cap would silently change
    # it; the ONE spec normalizer enforces the same refusal for blobs), and
    # refused on a live-DOM GLIMPSE (the human's expansion is the selection;
    # there is no server descent to cap). True (the default) is the
    # historical unbounded walk and is always fine. With render_spec present
    # this arg is ignored wholesale, like every other scope arg (the blob
    # carries its own recursive, and the normalizer's guard covers blobs).
    if not recursive and slice_group:
        return {
            "success": False,
            "error": (
                "recursive=False (render the scope root + its DIRECT children "
                "only) is a RAW-ROOT traversal policy and is not meaningful for "
                "a slice-group GLIMPSE: the slice's membership is defined by its "
                "tag predicate over the whole scope, so a depth cap would "
                "silently change which nodes render. Pass root_uuid=... alone "
                "for a depth-capped raw dump, or omit recursive."
            ),
        }
    if not recursive and not (root_uuid or slice_group):
        return {
            "success": False,
            "error": (
                "recursive=False is only meaningful for a server-side cache "
                "projection (a bare root_uuid raw dump). A live-DOM GLIMPSE "
                "walks the human's expansion, so there is no server descent to "
                "cap. Pass root_uuid=..., or omit recursive."
            ),
        }

    # PUSH-TO-MODAL dispatch (any server-side scope; guarded above so at least
    # one of slice_group / root_uuid is present). Instead of RETURNING the
    # rendered content, command the target tab to render this scope into its
    # docked Markdown modal (server-push twin of the APPLY button), forwarding
    # BOTH scope args (so the combined slice+override-root mode pushes too) and
    # the AGENT-SUPPLIED sort as an explicit override. Short-circuits before the
    # content-returning cache paths below. match_scope is forwarded so a pushed
    # slice honors title-only membership too (the tab's cache-render handler
    # threads it into the same Phase-1 predicate). For a raw-dump push it is the
    # harmless default (guarded above: 'name' requires a slice_group).
    if push_to_modal and (slice_group or root_uuid):
        return await _glimpse_push_slice_to_modal(
            slice_group=slice_group,
            root_uuid=root_uuid,
            sort_by=sort_by,
            sort_direction=sort_direction,
            target_tab=target_tab,
            since=_since_obj_for_guard,
            recent_by=recent_by,
            match_scope=_match_scope,
            # HEADINGS-ONLY forwarded EXPLICITLY from the GLIMPSE tool arg:
            # a server-initiated push carries its own headings_only in the
            # frame and NEVER inherits the tab's dock toggle.
            headings_only=headings_only,
            descend_policy=_descend_policy,
            # [ap:EPR86W] part a: the depth leg rides the pushed spec blob
            # (guarded above: False only ever reaches here on the raw-root
            # cell).
            recursive=recursive,
            # U6: the pushed spec carries the teaching flag on the wire blob,
            # so the tab's Apply render honors the same opt-out.
            ancestor_notes=ancestor_notes,
            # [ap:0M6VP8]: the pushed spec carries the heading-id form too.
            full_uuids=full_uuids,
        )

    # SLICE-GROUP (cache-only) path: when a slice_group is supplied, GLIMPSE
    # sources its input from the /nodes-export cache instead of the live DOM.
    # This is the universal-GLIMPSE branch -- same composer, no expansion state.
    # When root_uuid is ALSO supplied it is the OVERRIDE ROOT (the group's
    # tags/policy scoped to root_uuid instead of the group's stored default
    # root) -- the combined mode. root_uuid_override=None is a bare slice_group
    # at its own stored root.
    if slice_group:
        _sr = await _glimpse_slice_group_from_cache(
            slice_group=slice_group,
            as_markdown=as_markdown,
            output_file=output_file,
            sort_by=sort_by,
            sort_direction=sort_direction,
            target_tab=target_tab,
            headings_only=headings_only,
            since=_since_obj_for_guard,
            recent_by=recent_by,
            root_uuid_override=root_uuid,
            match_scope=_match_scope,
            descend_policy=_descend_policy,
            # FOCUS is no longer an explicit GLIMPSE arg: a focused (per-row)
            # render arrives via render_spec ('modal' or a pasted blob), which
            # short-circuits above through _glimpse_dispatch_spec. An
            # explicit-arg slice_group GLIMPSE always renders the WHOLE slice.
            focus=None,
            # U6 teaching flag (default False = the rule ships).
            ancestor_notes=ancestor_notes,
            # [ap:0M6VP8]: the heading-id form (short by default).
            full_uuids=full_uuids,
            # REPOSITORY VIEW (U1, §5.2): the explicit slice path forwards.
            repository_view=bool(repository_view),
        )
        return _shape_glimpse_family_return(_sr, output_file=output_file, headings_only=headings_only, include_rows=include_rows)

    # BARE-root_uuid (cache-only RAW DUMP) path: project the COMPLETE subtree
    # under root_uuid from the cache -- no membership filter, no Phase 2/3, and
    # no DOM read at all. The pure SCRY-as-Markdown capability. (The one
    # WebSocket touch on this path is the Anchor-Dock guard's tab-agnostic
    # config read, plus the descend_policy boundary config read below.)
    # (Reached only when slice_group is absent; with a slice_group the branch
    # above owns root_uuid as the override root.)
    if root_uuid:
        # ANCHOR-DOCK GUARD (in-band raw dumps only). Placed HERE at the tool
        # boundary so it covers EXACTLY this one cell: push_to_modal dispatch
        # (above) is exempt (content goes to the dock, not the context); a
        # slice_group+root_uuid override renders a curated lens (above); and
        # anchor.dock.render reaches _glimpse_root_uuid_from_cache DIRECTLY
        # (never through here), so the Dock preset can never self-reject.
        # output_file writes are exempt (content goes to disk, not context).
        # The guard's extension-settings config read is FIRST-CLASS (the
        # historical 'no WebSocket on the raw-dump path' doctrine is
        # retracted); a failed read raises loudly rather than silently
        # skipping the guard. It FAILS CLOSED on a cache miss
        # (root_not_in_cache) so an unclassifiable root is never projected.
        _anchor_vocabulary = None
        if not allow_anchor_dock and output_file is None:
            try:
                _guard_outcome = await _anchor_dock_root_guard(
                    root_uuid,
                    target_tab=target_tab,
                    tool_label="glimpse root_handle raw dump",
                )
            except (_AnchorDockRootDetected, _FullDumpRootCacheMiss) as exc:
                return {
                    "success": False,
                    "error": exc.message,
                    "code": exc.code,
                    "detail": exc.extra,
                }
            root_uuid = _guard_outcome["resolved"]
            # WELD: the guard's ONE vocabulary read is reused for the
            # descend_policy boundary below (no second WS round-trip).
            _anchor_vocabulary = _guard_outcome["anchor_vocabulary"]
        # descend_policy='stop_at_child_anchors': build the STOP-RECURSION
        # boundary predicate from the LIVE anchor tags. The vocabulary comes
        # from the guard's shared read above when it ran (ONE read per call);
        # otherwise (guard exempt by allow_anchor_dock/output_file) it is
        # read HERE. Either way it is done at the tool boundary (which owns
        # the WS grace-wait machinery) so _glimpse_root_uuid_from_cache stays
        # transport-free -- it just receives a pre-built predicate. The tags
        # come from the SAME vocabulary seam the anchor tools use, so 'what
        # is an anchor' cannot drift. Default descend_policy='all' skips the
        # boundary entirely.
        _boundary_predicate = None
        if _descend_policy == "stop_at_child_anchors":
            if _anchor_vocabulary is None:
                try:
                    _anchor_vocabulary = await _read_anchor_dock_vocabulary(
                        target_tab
                    )
                except Exception as e:  # noqa: BLE001
                    return {
                        "success": False,
                        "error": (
                            "descend_policy='stop_at_child_anchors' needs the live "
                            f"anchor-tag config, which could not be read ({e}). "
                            "Open Workflowy (with the GLIMPSE extension connected) "
                            "and retry, or omit descend_policy."
                        ),
                    }
            _boundary_predicate = build_anchor_boundary_predicate(
                _anchor_vocabulary[0],
                **_anchor_vocabulary[1],
            )
        _rr = await _glimpse_root_uuid_from_cache(
            root_uuid=root_uuid,
            as_markdown=as_markdown,
            output_file=output_file,
            sort_by=sort_by,
            sort_direction=sort_direction,
            headings_only=headings_only,
            since=_since_obj_for_guard,
            recent_by=recent_by,
            boundary_predicate=_boundary_predicate,
            # [ap:EPR86W] part a: the depth leg (False = root + direct
            # children only, via the ONE shared walker's max_depth gate).
            recursive=recursive,
            # FOCUS is no longer an explicit GLIMPSE arg (see the slice_group
            # branch above): a focused per-row render arrives via render_spec
            # and short-circuits at the top. A bare root_uuid GLIMPSE renders
            # the WHOLE subtree.
            focus=None,
            # U6 teaching flag (default False = the rule ships).
            ancestor_notes=ancestor_notes,
            # [ap:0M6VP8]: the heading-id form (short by default).
            full_uuids=full_uuids,
            # REPOSITORY VIEW (U1, §5.2): the explicit root path forwards.
            repository_view=bool(repository_view),
        )
        return _shape_glimpse_family_return(_rr, output_file=output_file, headings_only=headings_only, include_rows=include_rows)

    client = get_client()
    # Grace wait: if the Chrome extension's service worker is currently in
    # its idle-timeout window between dying and being rescued by the next
    # chrome.alarms fire (~30s cycle, ~0-2s typical reconnect latency once
    # alarm fires), wait up to 6s for the WebSocket to (re)connect before
    # falling back to the "WebSocket unavailable - use workflowy_scry"
    # error path. Reduces user-perceived dead-window from ~30s worst-case
    # to ~0s in nearly all real scenarios. The 6s ceiling is governed by
    # env var WORKFLOWY_GLIMPSE_WS_GRACE_S; default 6.0.
    import os as _os
    _grace_s = float(_os.getenv("WORKFLOWY_GLIMPSE_WS_GRACE_S", "6.0"))
    ws_conn, ws_queue = await get_ws_connection_with_grace_wait(
        max_wait_seconds=_grace_s,
    )

    # `since` for the LIVE-DOM path. The already-ingested SinceSpec object is
    # threaded straight through to the client method, which applies it via the ONE shared orchestrator
    # apply_since_to_forest (glimpse_since_policy) -- the SAME entry point the
    # cache tail + the modal handlers use. That orchestrator owns form-detection
    # + the per-form sort rule, so item-count ('last N', no sort needed) works
    # here identically to the cache paths, and the window form's data-leading-
    # edge pivot is computed inside. Form B (curated) can never reach here (the
    # glimpse() guard rejects since='curated' without a slice_group, and
    # slice_group takes the cache branch). Malformed tokens were already
    # rejected by the fail-fast classifier guard above, so we simply forward.
    if _rate_limiter:
        await _rate_limiter.acquire()

    try:
        # Auto-resolve current zoom in the extension; no node_id passed here.
        result = await client.workflowy_glimpse(
            output_file=output_file,
            as_markdown=as_markdown,
            target_tab=target_tab,
            sort_by=sort_by,
            sort_direction=sort_direction,
            headings_only=headings_only,
            since=_since_obj_for_guard,
            # [ap:TVIIBN] 4d(a): the 'newest' item_count selection's basis.
            recent_by=recent_by,
            # [ap:0M6VP8]: the live-DOM path honors the same heading-id form.
            full_uuids=full_uuids,
            _ws_connection=ws_conn,
            _ws_queue=ws_queue,
        )
        if _rate_limiter:
            _rate_limiter.on_success()
        
        # AGENT-FACING OUTPUT CONTRACT (the ONE finalizer, shared with every
        # other GLIMPSE-family return + lightning_rod): Markdown mode -> the
        # raw preview_markdown STRING (real newlines, like read_text_file);
        # full/UUID mode -> preview_tree + useful metadata, with rows stripped
        # (and root/children also stripped for headings_only UUID-harvest);
        # output_file / errors -> unchanged. This REPLACES the old hand-built mini-payload here so the
        # live-DOM path shapes identically to the cache/modal paths. (The
        # live-DOM result never carries `rows`; no new builder is introduced
        # for include_rows.) SCRY-to-disk (output_file is not None) still carries the
        # full JSON tree on disk only.
        return _shape_glimpse_family_return(result, output_file=output_file, headings_only=headings_only, include_rows=include_rows)
    except Exception as e:
        if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
            _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
        raise


@_GLIMPSE_LEGACY_TOOL_DECORATOR
# @beacon[
#   id=auto-beacon@glimpse-bikh,
#   role=glimpse,
#   slice_labels=glimpse-render,live-dom,
#   kind=ast,
# ]
async def glimpse(
    output_file: str | None = None,
    as_markdown: bool | None = None,
    target_tab: str | None = None,
    sort_by: str | None = None,
    sort_direction: str = "asc",
    slice_group: str | None = None,
    root_uuid: str | None = None,
    headings_only: bool | None = None,
    since: str | None = None,
    push_to_modal: bool = False,
    match_scope: str = "name_and_note",
    descend_policy: str = "all",
    render_spec: str | dict[str, Any] | None = None,
    allow_anchor_dock: bool = False,
) -> Any:
    """Legacy ``workflowy_glimpse`` wrapper over the single render authority."""

    return await _glimpse_run_impl(
        output_file=output_file,
        as_markdown=as_markdown,
        target_tab=target_tab,
        sort_by=sort_by,
        sort_direction=sort_direction,
        slice_group=slice_group,
        root_uuid=root_uuid,
        headings_only=headings_only,
        since=since,
        push_to_modal=push_to_modal,
        match_scope=match_scope,
        descend_policy=descend_policy,
        render_spec=render_spec,
        allow_anchor_dock=allow_anchor_dock,
    )


# @beacon[
#   id=note-sessions@_resolve_note_session_config,
#   slice_labels=nexus--config,nexus--anchors,
#   kind=ast,
#   comment=Server helper: acquire the live WS peer (grace wait) and fetch the target tab's extension settings, returning normalized (note_session_tags, global_tags, default_parent). Fails loudly if no tab is reachable. Shared by both note-session MCP tools. Archive Reads U3: the raw reply ALSO feeds remember_archive_folder_from_reply — the daemon's memory of the extension's archive_folder option, so archive reads never need a tab (the file write defers inside an augmented operation, Axiom 5/E36).,
# ]
async def _resolve_note_session_config(target_tab: str | None):
    """Resolve live note-session config from the target Workflowy tab.

    Acquires the WS peer (with the same grace-wait GLIMPSE uses) and issues a
    Direction-A ``get_extension_settings`` request. Returns a tuple of
    ``(note_session_tags, global_tags, default_parent, raw_reply)``. Raises a
    clear error when no tab is reachable, so the tools fail loudly rather than
    guessing (per spec).

    NOTE: the LOCAL-anchor postfix list is NOT a positional tuple element (to
    avoid an arity change across every existing unpack site); it rides in
    ``raw_reply`` under ``note_session_local_postfixes`` and is read via the
    shared :func:`_local_anchor_postfixes_from_reply` helper wherever the
    boundary predicate / listing needs it. The raw reply is the single source
    of all tab config, so this keeps one source of truth without a fragile
    multi-site tuple-widening.
    """
    import os as _os

    client = get_client()
    _grace_s = float(_os.getenv("WORKFLOWY_GLIMPSE_WS_GRACE_S", "6.0"))
    ws_conn, ws_queue = await get_ws_connection_with_grace_wait(max_wait_seconds=_grace_s)
    if not (ws_conn and ws_queue):
        raise RuntimeError(
            "No live Workflowy tab is connected to the GLIMPSE broker, so the "
            "note-session configuration cannot be read. Open Workflowy in the "
            "browser (with the GLIMPSE extension connected) and retry."
        )
    reply = await client.get_extension_settings(
        ws_connection=ws_conn,
        ws_queue=ws_queue,
        target_tab=target_tab,
        # Anchor / canonical-tag config is SHARED across all tabs (it lives in
        # chrome.storage.sync, mirrored identically into every tab), so this
        # read is TAB-AGNOSTIC: any connected tab returns the same answer.
        # tab_optional=True tells the broker to pick a tab deterministically
        # under multi-tab when no target/star is given, instead of erroring
        # with 'ambiguous_browser_target' — the friction this fixes. An
        # explicit target_tab (when passed) is still honored; the zero-tab
        # case still fails loudly. (GLIMPSE/extract_dom does NOT set this and
        # remains tab-specific.)
        tab_optional=True,
    )
    # Archive Reads U3 (§4.10): learn the extension's archive folder from
    # this reply — the daemon's memory, so archive reads never need a tab.
    # Never raises; the file write is deferred inside an augmented
    # operation (Axiom 5, E36).
    from .archive_store import remember_archive_folder_from_reply

    remember_archive_folder_from_reply(reply)
    note_session_tags = list(reply.get("note_session_tags") or [])
    global_tags = list(reply.get("global_tags") or [])
    default_parent = reply.get("default_note_sessions_parent") or None
    return note_session_tags, global_tags, default_parent, reply


# @beacon[
#   id=note-sessions@_local_anchor_postfixes_from_reply,
#   slice_labels=nexus--config,nexus--anchors,
#   kind=ast,
#   comment=Extract the configured LOCAL-anchor postfix word list from a get_extension_settings raw reply, defaulting to [DEFAULT_LOCAL_ANCHOR_POSTFIX] ('local') when absent/empty/malformed. The ONE server-side place the local-postfix default lives -- the Dock-favorites unit added the exact siblings _favorite_anchor_postfixes_from_reply / _deprecated_anchor_postfixes_from_reply and the ONE aggregator _anchor_postfix_kwargs_from_reply, so list_anchors and every classify/boundary call site read the full family vocabulary identically (no per-site defaulting, no drift). Rides in the raw reply (note_session_local_postfixes) rather than a widened _resolve_note_session_config tuple, to avoid an arity change across every existing unpack site.,
# ]
def _local_anchor_postfixes_from_reply(reply: dict | None) -> list[str]:
    """Return the configured local-anchor postfix words from a settings reply.

    Reads ``note_session_local_postfixes`` from the ``get_extension_settings``
    raw reply. Each entry is trimmed and a single leading ``#`` stripped;
    empty / non-string entries are dropped; order-preserving de-dup. Falls back
    to ``[DEFAULT_LOCAL_ANCHOR_POSTFIX]`` (``['local']``) when the field is
    absent, empty, or contains no usable word -- so ``local=True`` on
    ``create_anchor`` and the ``is_local`` listing filter always have a
    meaningful postfix even against an older tab that predates this setting.

    This is the SINGLE server-side home for the local-postfix default; both
    the listing filter and every boundary-predicate call site read through it
    so the locality vocabulary can never drift between them.
    """
    raw = (reply or {}).get("note_session_local_postfixes")
    out: list[str] = []
    seen: set[str] = set()
    if isinstance(raw, (list, tuple)):
        for w in raw:
            if not isinstance(w, str):
                continue
            t = w.strip()
            if t.startswith("#"):
                t = t[1:].strip()
            if t and t not in seen:
                seen.add(t)
                out.append(t)
    if not out:
        return [DEFAULT_LOCAL_ANCHOR_POSTFIX]
    return out


