# @beacon[
#   id=mcp-api@node-etch-impl,
#   role=⚡ _node_etch_impl(parent_handle, nodes, nodes_file, execution),
#   slice_labels=nexus--mcp-api,node-ops,
#   kind=ast,
#   comment=Canonical Node-family ETCH front. Selects the existing synchronous or asynchronous ETCH primitive, standardizes sync mutation acknowledgements, and converts async legacy job handles into the shared family job envelope without changing ETCH payload semantics.,
# ]
async def _node_etch_impl(
    parent_handle: str,
    nodes: list[dict] | str | None = None,
    nodes_file: str | None = None,
    execution: str = "sync",
) -> dict:
    """Run ETCH synchronously or start its existing background job."""

    if execution == "async":
        legacy = await _node_etch_async_impl(parent_handle, nodes, nodes_file)
        job_id = legacy.get("job_id") if isinstance(legacy, dict) else None
        if job_id:
            record = make_job_record(
                operation="node.etch",
                job_id=str(job_id),
                state=str(legacy.get("status") or "queued"),
                extra={"kind": legacy.get("kind") or "etch"},
            )
            # §6.6: the nodes_file path_record rides the job envelope's TOP
            # LEVEL, beside `job` (carried up by _node_etch_async_impl).
            if isinstance(legacy.get("path_record"), dict):
                record["path_record"] = legacy["path_record"]
            return record
        return make_mutation_ack(
            operation="node.etch", result=legacy, changed=False
        )

    legacy = await _node_etch_sync_impl(parent_handle, nodes, nodes_file)
    changed = bool(
        isinstance(legacy, dict)
        and int(legacy.get("nodes_created", 0) or 0) > 0
    )
    warnings = legacy.get("warnings") or () if isinstance(legacy, dict) else ()
    return make_mutation_ack(
        operation="node.etch",
        result=legacy,
        changed=changed,
        warnings=warnings,
    )


