class _S07OperationError(RuntimeError):
    """Typed S07 family failure converted through the registry contract."""

    def __init__(self, code: str, message: str, extra: Any = None) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.extra = extra


def _s07_error_result(
    registry: OperationRegistry, verb: str, exc: _S07OperationError
) -> dict[str, Any]:
    spec = registry.resolve(verb)
    return make_error(
        family=registry.family,
        operation=f"{registry.family}.{verb}",
        code=exc.code,
        message=exc.message,
        extra=exc.extra,
        operation_spec=spec,
    )


def _s07_lens_error_result(
    registry: OperationRegistry, verb: str, exc: LensSpecError
) -> dict[str, Any]:
    spec = registry.resolve(verb)
    return make_error(
        family=registry.family,
        operation=f"{registry.family}.{verb}",
        code=exc.code,
        message=exc.message,
        extra={"path": exc.path},
        operation_spec=spec,
    )


def _s07_mutation_ack(
    registry: OperationRegistry,
    verb: str,
    result: Mapping[str, Any],
    *,
    changed: bool,
) -> dict[str, Any]:
    """Preserve mutation detail while standardizing any declared failure code."""

    operation = f"{registry.family}.{verb}"
    ack = make_mutation_ack(
        operation=operation,
        result=result,
        changed=changed,
        warnings=_result_warnings(result),
    )
    code = str(result.get("code") or "")
    if not ack["success"] and code:
        spec = registry.resolve(verb)
        error_envelope = make_error(
            family=registry.family,
            operation=operation,
            code=code,
            message=str(result.get("error") or "Operation failed."),
            extra={"changed": changed, "resumable": True},
            operation_spec=spec,
        )
        ack["error"] = error_envelope["error"]
    return ack


def _require_top_level_merge_lens(raw: Any):
    from .lens_spec import MergeNode

    parsed = parse_lens_spec(raw)
    if not isinstance(parsed, MergeNode):
        raise LensSpecError(
            "invalid_lens_shape",
            "This operation requires a top-level kind='merge' LensSpec; use slice_group.render for a single-atom recipe.",
            "$",
        )
    return parsed


def _current_cache_by_id() -> dict[str, dict[str, Any]]:
    """The operation's pinned ``{uuid: node}`` map (S03 §8.1).

    Consumes the task-local operation snapshot EXPLICITLY (loud outside an
    operation boundary — a cache consumer without one is a migration bug).
    Borrows the immutable view's exact index (outer map AND node dicts are
    read-only by contract, Axiom 5), enabling identity-bound derived indexes.
    """
    from .client.api_client_nexus import load_nodes_by_id_from_cache
    from .coherence.operation_cache import current_operation_cache

    return load_nodes_by_id_from_cache(current_operation_cache())


def _walk_materialized_tree_ids(tree: Mapping[str, Any]) -> set[str]:
    ids: set[str] = set()

    def visit(node: Mapping[str, Any]) -> None:
        node_id = str(node.get("id") or "")
        if node_id:
            ids.add(node_id)
        for child in node.get("children") or ():
            if isinstance(child, Mapping):
                visit(child)

    visit(tree)
    return ids


def _s07_postfix_words(snapshot: "_LensStage0Snapshot") -> tuple[str, str, str]:
    return (
        str(snapshot.postfixes.get("auto_expand") or DEFAULT_AUTO_EXPAND_POSTFIX),
        str(snapshot.postfixes.get("suppress") or DEFAULT_SUPPRESS_POSTFIX),
        str(snapshot.postfixes.get("deprecated") or DEFAULT_DEPRECATED_POSTFIX),
    )


def _generated_group_identity(
    groups: list[dict[str, Any]], *, group_name: str, root_uuid: str, tag: str
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    same_name = [g for g in groups if str(g.get("name") or "") == group_name]
    exact = [
        g
        for g in same_name
        if str(g.get("root_uuid") or "") == root_uuid
        and [str(p).lstrip("#") for p in (g.get("prefixes") or ())] == [tag]
    ]
    incompatible = [g for g in same_name if g not in exact]
    summary = {
        "group_name": group_name,
        "exact_match_ids": [str(g.get("id") or "") for g in exact],
        "incompatible_same_name_ids": [
            str(g.get("id") or "") for g in incompatible
        ],
    }
    if len(exact) > 1 or incompatible:
        raise _S07OperationError(
            "generated_group_conflict",
            "Generated slice-group identity is ambiguous or conflicts with an existing same-name group.",
            summary,
        )
    return (exact[0] if exact else None), summary


def _merge_target_family_safety(
    *,
    groups: list[dict[str, Any]],
    parsed_lens: Any,
    tag: str,
    postfix_words: tuple[str, str, str],
    global_never: tuple[str, ...],
    exempt_group_id: str | None,
) -> None:
    from .lens_spec import TagsAtom

    compared: list[dict[str, str]] = []
    for group in groups:
        if exempt_group_id and str(group.get("id") or "") == exempt_group_id:
            continue
        for prefix in group.get("prefixes") or ():
            compared.append(
                {
                    "source": "persisted_group",
                    "owner": str(group.get("id") or ""),
                    "prefix": str(prefix).lstrip("#").strip(),
                }
            )
    for path, atom in iter_lens_atoms(parsed_lens):
        if isinstance(atom, TagsAtom):
            for prefix in atom.tags:
                compared.append(
                    {"source": "tags_atom", "owner": path, "prefix": str(prefix)}
                )
    collisions = []
    for row in compared:
        prefix = row["prefix"]
        if not prefix:
            continue
        if (
            slice_tag_variant_match(tag, prefix, postfix_words=postfix_words)
            is not None
            or slice_tag_variant_match(prefix, tag, postfix_words=postfix_words)
            is not None
        ):
            collisions.append(row)
    stems = normalize_global_never_stems(global_never)
    expand_form = f"{tag}{POSTFIX_SEP}{postfix_words[0]}"
    if tag in stems or expand_form in stems:
        collisions.append(
            {"source": "global_never", "owner": "config", "prefix": tag}
        )
    if collisions:
        raise _S07OperationError(
            "merge_tag_collision",
            "The target family overlaps an existing slice-group/tags-atom family or a global-never stem.",
            {"collisions": collisions},
        )


def _unpersistable_global_never_leaves(
    *,
    cache_by_id: Mapping[str, Mapping[str, Any]],
    leaf_ids: Iterable[str],
    root_uuid: str,
    global_never: Iterable[str],
) -> list[dict[str, str]]:
    from .f8_slice_policy import name_has_global_never_tag

    stems = normalize_global_never_stems(global_never)
    affected: list[dict[str, str]] = []
    for leaf_id in sorted(set(str(item) for item in leaf_ids)):
        current = leaf_id
        seen: set[str] = set()
        blocked = False
        while current and current not in seen:
            seen.add(current)
            if current == root_uuid:
                break
            node = cache_by_id.get(current)
            if node is None:
                break
            if name_has_global_never_tag(node.get("name"), stems):
                blocked = True
                break
            current = str(node.get("parent_id") or node.get("parentId") or "")
        if blocked:
            node = cache_by_id.get(leaf_id) or {}
            affected.append(
                {"uuid": leaf_id, "name": str(node.get("name") or "")}
            )
    return affected


# U7 ([ap:256S33] postcondition 2) — the ONE server-side serializer for the
# slice-group config read-modify-write. Every server RMW over the whole
# expand_groups array holds this lock from BEFORE its _resolve_slice_group_config
# read until the set_slice_groups ack returns, so two parallel tool calls
# serialize (the second reads only after the first's write completed) instead of
# interleaving read-read-write-write and silently dropping a field. The four —
# and ONLY four — sites: _slice_group_update_core, _slice_group_create_core,
# _slice_group_delete_impl, and _merge_persist_lens_impl's T2 identity-check +
# atomic create/reuse commit. Server-local by design (this process is the single
# slice-group policy owner); it is NOT a distributed lock and guards no data of
# its own — it is synchronization, not a third copy of the settings (the merge
# base is the durable chrome.storage.local state the tab answers from, per U7
# postcondition 1). Never re-entered: none of the four sites calls another while
# holding it (merge.persist commits through _write_slice_group_config directly,
# NOT through the create/update cores).
_SLICE_GROUP_CONFIG_LOCK: asyncio.Lock = asyncio.Lock()


async def _write_slice_group_config(
    groups: list[dict[str, Any]],
    active_group_id: str | None,
    target_tab: str | None,
) -> dict[str, Any]:
    ws_conn, ws_queue = await get_ws_connection_with_grace_wait(max_wait_seconds=6.0)
    if not (ws_conn and ws_queue):
        raise RuntimeError("No live Workflowy tab to persist slice-group configuration.")
    return await get_client().set_slice_groups(
        ws_connection=ws_conn,
        ws_queue=ws_queue,
        expand_groups=groups,
        active_group=active_group_id,
        target_tab=target_tab,
    )


# @beacon[
#   id=mcp-api@slice-group-delete-impl,
#   role=⚡ _slice_group_delete_impl(group_handle, target_tab),
#   slice_labels=nexus--mcp-api,nexus--config,slices,
#   kind=ast,
#   comment=Config-only Slice Group deletion. Resolves through the shared id/prefix/name resolver, clears active_group_id atomically when needed, persists once, and never touches Workflowy tags.,
# ]
async def _slice_group_delete_impl(
    group_handle: str, target_tab: str | None = None
) -> dict[str, Any]:
    # U7 ([ap:256S33]): RMW site 3/4 — serialized by _SLICE_GROUP_CONFIG_LOCK
    # from the config read until the write ack (see the lock's definition).
    async with _SLICE_GROUP_CONFIG_LOCK:
        groups, active_id, _postfixes, _global_never, _reply = (
            await _resolve_slice_group_config(target_tab)
        )
        chosen, error = _resolve_slice_group_handle(groups, group_handle)
        if error is not None or chosen is None:
            raise _S07OperationError(
                "group_resolution_failed",
                str((error or {}).get("error") or "Slice group did not resolve."),
                error,
            )
        deleted_id = str(chosen.get("id") or "")
        next_groups = [dict(group) for group in groups if str(group.get("id") or "") != deleted_id]
        active_cleared = bool(deleted_id and active_id == deleted_id)
        next_active = None if active_cleared else active_id
        ack = await _write_slice_group_config(next_groups, next_active, target_tab)
    return {
        "success": True,
        "deleted": _slice_group_public_view(dict(chosen), active_id),
        "active_cleared": active_cleared,
        "persisted_active_group_id": ack.get("active_group", next_active),
        "teaching": (
            "Only configuration was deleted; node tags remain. For cleanup after deletion, "
            "use tag.purge with the returned root and tag prefixes."
        ),
    }


def _merge_persist_report_failure(
    report: dict[str, Any], code: str, message: str
) -> dict[str, Any]:
    report.update({"success": False, "code": code, "error": message})
    return report


# @beacon[
#   id=mcp-api@merge-persist-lens-impl,
#   role=⚡ _merge_persist_lens_impl(params),
#   slice_labels=nexus--mcp-api,nexus--tags,nexus--config,slices,
#   kind=ast,
#   comment=Recursive LensSpec merge persistence orchestrator. Evaluates once against the immutable S06 T1 snapshot, materializes the authoritative tree, preflights reproducibility/identity/collisions, reuses the shipped plan-simulate-Q4-verify compiler, then performs a fresh T2 config identity check and atomic create/reuse update.,
# ]
async def _merge_persist_lens_impl(params: Mapping[str, Any]) -> dict[str, Any]:
    from .tag_purge_policy import normalize_base_tag_family

    parsed = _require_top_level_merge_lens(params["lens"])
    target_tab = params.get("target_tab")
    snapshot = await _build_lens_stage0_snapshot(
        target_tab, exclude_completed=RenderProjectionSpec().exclude_completed
    )
    postfix_words = _s07_postfix_words(snapshot)
    try:
        target_tag = normalize_base_tag_family(params["tag"], postfix_words)
    except ValueError as exc:
        raise _S07OperationError("merge_target_tag_invalid", str(exc)) from exc
    group_name = str(params.get("group_name") or target_tag).strip()
    if not group_name:
        raise _S07OperationError(
            "generated_group_conflict", "group_name must be non-empty."
        )
    description_supplied = "group_description" in params and params.get("group_description") is not None
    requested_description = (
        str(params.get("group_description") or "").strip()
        if description_supplied
        else None
    )
    make_active = bool(params.get("make_active", False))

    # Semantic tag-search default: a merge.persist lens selects slice members
    # to merge, so atoms that omit their own match_scope take the flipped
    # name-only default (trailing tag region via the core splitter), matching
    # slice_group.merge.render / slice_group.render. An explicit per-atom
    # match_scope (including 'name_and_note') still wins.
    evaluation = evaluate_lens(
        parsed, replace(snapshot.context, default_match_scope="name")
    )
    effective_leaf_ids = set(evaluation.effective_leaf_ids)
    if not effective_leaf_ids:
        raise _S07OperationError(
            "empty_selection_not_persistable",
            "The recursive merge selected no effective leaves; nothing was written.",
        )
    materialized = build_lens_result_tree(effective_leaf_ids, snapshot.context)
    if not isinstance(materialized, LensResultTree):
        raise _S07OperationError(
            "empty_selection_not_persistable", "The merge materialized as empty."
        )
    root_uuid = materialized.root_uuid
    expected_node_ids = _walk_materialized_tree_ids(materialized.tree)
    unpersistable = _unpersistable_global_never_leaves(
        cache_by_id=snapshot.cache_by_id,
        leaf_ids=effective_leaf_ids,
        root_uuid=root_uuid,
        global_never=snapshot.global_never,
    )
    if unpersistable:
        raise _S07OperationError(
            "unpersistable_leaves",
            "Some selected leaves cannot be reproduced by a generated slice group because a leaf-to-root-exclusive path carries a global-never tag.",
            {"affected": unpersistable[:80], "affected_count": len(unpersistable)},
        )

    groups_t1 = [dict(group) for group in snapshot.groups_cfg]
    exact_t1, identity_t1 = _generated_group_identity(
        groups_t1,
        group_name=group_name,
        root_uuid=root_uuid,
        tag=target_tag,
    )
    _merge_target_family_safety(
        groups=groups_t1,
        parsed_lens=parsed,
        tag=target_tag,
        postfix_words=postfix_words,
        global_never=snapshot.global_never,
        exempt_group_id=(str(exact_t1.get("id") or "") if exact_t1 else None),
    )

    cache_t1 = dict(snapshot.cache_by_id)
    plan = compute_merge_tag_plan(
        cache_t1,
        effective_leaf_ids,
        root_uuid,
        target_tag=target_tag,
        expand_postfix_word=postfix_words[0],
        global_never_expand_tags=snapshot.global_never,
        skip_completed=True,
    )
    if not plan.get("ok"):
        raise _S07OperationError(
            "merge_spine_blocked",
            str(plan.get("error") or "The merge tag plan could not cover the materialized tree."),
            {"spine_blockers": plan.get("spine_blockers") or []},
        )
    expand_nodes = list(plan.get("expand_nodes") or ())
    plain_nodes = list(plan.get("plain_nodes") or ())
    planned_node_forms = {node_id: "expand" for node_id in expand_nodes}
    planned_node_forms.update({node_id: "plain" for node_id in plain_nodes})
    collisions = find_tag_family_collisions(
        cache_t1,
        [root_uuid],
        target_tag,
        postfix_words=postfix_words,
        planned_node_forms=planned_node_forms,
        expand_form=f"{target_tag}{POSTFIX_SEP}{postfix_words[0]}",
        skip_completed=False,
    )
    if collisions.get("count"):
        raise _S07OperationError(
            "merge_tag_collision",
            "Existing target-family residue is noncongruent with the current plan, including completed/unplanned nodes. Remove or purge it, or uncomplete and retry.",
            collisions,
        )

    overlay = build_merge_overlay_cache(
        cache_t1, expand_nodes, plain_nodes, target_tag, postfix_words[0]
    )
    dry_run_ids = simulate_merge_projection(
        overlay,
        [root_uuid],
        target_tag,
        auto_expand_postfix=postfix_words[0],
        suppress_postfix=postfix_words[1],
        deprecated_postfix=postfix_words[2],
        global_never_expand_tags=snapshot.global_never,
        exclude_completed=snapshot.context.exclude_completed,
        match_scope="name_and_note",
    )
    if dry_run_ids is None or set(dry_run_ids) != expected_node_ids:
        raise _S07OperationError(
            "merge_spine_blocked",
            "Pre-mutation overlay simulation did not reproduce the authoritative materialized LensResultTree.",
            {
                "missing": sorted(expected_node_ids - set(dry_run_ids or ())),
                "unexpected": sorted(set(dry_run_ids or ()) - expected_node_ids),
            },
        )

    operations = [
        {
            "handle": node_id,
            "operation": "add",
            "tags": [f"{target_tag}{POSTFIX_SEP}{postfix_words[0]}"],
        }
        for node_id in expand_nodes
    ] + [
        {"handle": node_id, "operation": "add", "tags": [target_tag]}
        for node_id in plain_nodes
    ]
    mutation = await _tag_batch_impl(operations)
    changed = bool(mutation.get("nodes_changed"))
    report: dict[str, Any] = {
        "success": False,
        "lens": lens_spec_to_wire(evaluation.canonical_lens),
        "root_uuid": root_uuid,
        "merged_leaf_count": len(effective_leaf_ids),
        "expected_node_ids": sorted(expected_node_ids),
        "expand_tag": f"{target_tag}{POSTFIX_SEP}{postfix_words[0]}",
        "expand_nodes": expand_nodes,
        "plain_nodes": plain_nodes,
        "planned_op_count": len(operations),
        "timeout_seconds": 2.0 * len(operations),
        "mutation": mutation,
        "verification": {
            "dry_run": {"ran": True, "matched": True},
            "post_mutation": {"ran": False, "matched": False},
        },
        "identity": {"t1": identity_t1},
        "changed": changed,
        "warnings": list(evaluation.warnings),
    }
    if not mutation.get("success"):
        return _merge_persist_report_failure(
            report,
            "merge_verification_failed",
            "Tag mutation did not complete exactly; the run remains resumable from congruent residue.",
        )

    fresh_cache = _current_cache_by_id()
    verified = verify_merge_projection(
        fresh_cache,
        [root_uuid],
        target_tag,
        expected_node_ids,
        auto_expand_postfix=postfix_words[0],
        suppress_postfix=postfix_words[1],
        deprecated_postfix=postfix_words[2],
        global_never_expand_tags=snapshot.global_never,
        exclude_completed=snapshot.context.exclude_completed,
        match_scope="name_and_note",
    )
    report["verification"]["post_mutation"] = {"ran": True, **verified}
    if not verified.get("matched"):
        return _merge_persist_report_failure(
            report,
            "merge_verification_failed",
            "Fresh-cache post-mutation verification did not reproduce the authoritative materialized tree.",
        )

    try:
        # U7 ([ap:256S33]): RMW site 4/4 — the fresh T2 identity check + atomic
        # create/reuse commit is this orchestrator's config read-modify-write;
        # _SLICE_GROUP_CONFIG_LOCK serializes it against the other three sites
        # from the T2 read until the write ack. The T1 snapshot / lens
        # evaluation / tag mutation above stay OUTSIDE the lock (it is never
        # held across any other await chain).
        async with _SLICE_GROUP_CONFIG_LOCK:
            groups_t2, active_t2, pf_t2, gn_t2, _reply_t2 = (
                await _resolve_slice_group_config(target_tab)
            )
            t2_postfix_words = (
                str(pf_t2.get("auto_expand") or DEFAULT_AUTO_EXPAND_POSTFIX),
                str(pf_t2.get("suppress") or DEFAULT_SUPPRESS_POSTFIX),
                str(pf_t2.get("deprecated") or DEFAULT_DEPRECATED_POSTFIX),
            )
            if t2_postfix_words != postfix_words:
                raise _S07OperationError(
                    "generated_group_conflict",
                    "Slice postfix configuration changed between the T1 materialization and T2 commit; verified tags remain, but persistence was refused. Retry after reconciling the residue.",
                    {"t1_postfixes": postfix_words, "t2_postfixes": t2_postfix_words},
                )
            groups_t2 = [dict(group) for group in groups_t2]
            exact_t2, identity_t2 = _generated_group_identity(
                groups_t2,
                group_name=group_name,
                root_uuid=root_uuid,
                tag=target_tag,
            )
            report["identity"]["t2"] = identity_t2
            _merge_target_family_safety(
                groups=groups_t2,
                parsed_lens=parsed,
                tag=target_tag,
                postfix_words=postfix_words,
                global_never=tuple(gn_t2 or ()),
                exempt_group_id=(str(exact_t2.get("id") or "") if exact_t2 else None),
            )

            auto_description = (
                "Generated from recursive LensSpec: "
                + json.dumps(
                    lens_spec_to_wire(evaluation.canonical_lens),
                    sort_keys=True,
                    separators=(",", ":"),
                )
            )
            config_changed = False
            description_preserved = False
            if exact_t2 is None:
                import uuid as _uuid

                record = {
                    "id": _uuid.uuid4().hex,
                    "name": group_name,
                    "prefixes": [target_tag],
                    "root_uuid": root_uuid,
                    "description": (
                        requested_description
                        if description_supplied
                        else auto_description
                    ),
                    "default_sort_by": "none",
                    "default_sort_direction": "asc",
                }
                groups_t2.append(record)
                config_changed = True
            else:
                record = exact_t2
                if description_supplied:
                    if str(record.get("description") or "") != requested_description:
                        record["description"] = requested_description
                        config_changed = True
                else:
                    description_preserved = True
            next_active = active_t2
            if make_active and str(active_t2 or "") != str(record.get("id") or ""):
                next_active = str(record.get("id") or "")
                config_changed = True
            if config_changed:
                ack = await _write_slice_group_config(groups_t2, next_active, target_tab)
                persisted_groups = list(ack.get("expand_groups") or groups_t2)
                persisted_active = ack.get("active_group", next_active)
                record = next(
                    (
                        group
                        for group in persisted_groups
                        if str(group.get("id") or "") == str(record.get("id") or "")
                    ),
                    record,
                )
            else:
                persisted_groups = groups_t2
                persisted_active = active_t2
        changed = changed or config_changed
        report["slice_group"] = {
            "success": True,
            "created": exact_t2 is None,
            "reused": exact_t2 is not None,
            "description_preserved": description_preserved,
            "config_changed": config_changed,
            "record": _slice_group_public_view(record, persisted_active),
            "short_name_collisions": _short_name_collisions(
                persisted_groups,
                str(record.get("name") or group_name),
                exclude_id=str(record.get("id") or ""),
            ),
        }
    except _S07OperationError as exc:
        report["identity"]["t2_error"] = {
            "code": exc.code,
            "message": exc.message,
            "extra": exc.extra,
        }
        report["changed"] = changed
        return _merge_persist_report_failure(report, exc.code, exc.message)
    except Exception as exc:  # noqa: BLE001
        report["changed"] = changed
        return _merge_persist_report_failure(
            report,
            "generated_group_conflict",
            f"Verified tags remain, but the fresh T2 configuration commit failed: {exc}",
        )

    report["success"] = True
    report["changed"] = changed
    return report


# @beacon[
#   id=auto-beacon@_purge_preview_impl-mo1u,
#   role=_purge_preview_impl,
#   slice_labels=slices,
#   kind=ast,
# ]
async def _purge_preview_impl(
    *,
    family: str | None = None,
    root_handle: str | None = None,
    group_handle: str | None = None,
    target_tab: str | None = None,
) -> dict[str, Any]:
    from .tag_purge_policy import (
        find_purge_shared_use,
        normalize_base_tag_family,
        plan_tag_family_purge,
        purge_fingerprint,
    )

    snapshot = await _build_lens_stage0_snapshot(
        target_tab, exclude_completed=False
    )
    groups = [dict(group) for group in snapshot.groups_cfg]
    excluded_group_ids: tuple[str, ...] = ()
    selected_group: dict[str, Any] | None = None
    if group_handle is not None:
        selected_group, error = _resolve_slice_group_handle(groups, group_handle)
        if error is not None or selected_group is None:
            raise _S07OperationError(
                "group_resolution_failed",
                str((error or {}).get("error") or "Slice group did not resolve."),
                error,
            )
        raw_families = list(selected_group.get("prefixes") or ())
        if not raw_families:
            raise _S07OperationError(
                "group_resolution_failed", "The selected slice group has no tag prefixes."
            )
        root_handle = str(selected_group.get("root_uuid") or "").strip()
        if not root_handle:
            raise _S07OperationError(
                "root_resolution_failed", "The selected slice group has no stored root."
            )
        excluded_group_ids = (str(selected_group.get("id") or ""),)
    else:
        raw_families = [family]
    postfix_words = _s07_postfix_words(snapshot)
    try:
        families = [
            normalize_base_tag_family(item, postfix_words)
            for item in raw_families
        ]
    except ValueError as exc:
        raise _S07OperationError("purge_family_invalid", str(exc)) from exc
    try:
        resolve_root = (
            snapshot.context.resolve_inherited_root
            if selected_group is not None
            else snapshot.context.resolve_root
        )
        root_uuid = resolve_root(str(root_handle or ""))
    except Exception as exc:  # noqa: BLE001
        raise _S07OperationError("root_resolution_failed", str(exc)) from exc

    plan = plan_tag_family_purge(
        snapshot.cache_by_id, [root_uuid], families, postfix_words
    )
    shared_use = find_purge_shared_use(
        families,
        groups,
        excluded_group_ids=excluded_group_ids,
        live_postfixes=postfix_words,
    )
    scope = {
        "start_ids": [root_uuid],
        "group_id": (
            str(selected_group.get("id") or "") if selected_group else None
        ),
    }
    fingerprint = purge_fingerprint(
        scope,
        families,
        plan,
        shared_use,
        live_postfixes=postfix_words,
    )
    return {
        "success": True,
        "scope": scope,
        "families": families,
        "plan": plan,
        "report_only": plan["report_only"],
        "counts": plan["counts"],
        "shared_use": shared_use,
        "fingerprint": fingerprint,
        "postfix_words": list(postfix_words),
        "selected_group": (
            _slice_group_public_view(selected_group, snapshot.active_group_id)
            if selected_group
            else None
        ),
    }


# @beacon[
#   id=mcp-api@purge-apply-impl,
#   role=⚡ _purge_apply_impl(...),
#   slice_labels=nexus--mcp-api,nexus--tags,slices,
#   kind=ast,
#   comment=Shared low-level/group-aware purge apply orchestrator. Recomputes and fingerprint-gates the preview, refuses shared families by default, delegates exact removals to Q4, rebuilds the eager-patched cache, and verifies no mutable family occurrence remains.,
# ]
async def _purge_apply_impl(
    *,
    fingerprint: str,
    force_shared: bool,
    family: str | None = None,
    root_handle: str | None = None,
    group_handle: str | None = None,
    target_tab: str | None = None,
) -> dict[str, Any]:
    from .tag_purge_policy import plan_tag_family_purge

    preview = await _purge_preview_impl(
        family=family,
        root_handle=root_handle,
        group_handle=group_handle,
        target_tab=target_tab,
    )
    if str(fingerprint or "") != preview["fingerprint"]:
        raise _S07OperationError(
            "stale_purge_preview",
            "The purge scope, matching tags, report-only hits, plan, or shared-use state drifted; run purge.preview again.",
            {
                "expected_fingerprint": str(fingerprint or ""),
                "current_fingerprint": preview["fingerprint"],
            },
        )
    if preview["shared_use"] and not force_shared:
        raise _S07OperationError(
            "shared_family_collision",
            "Other persisted slice groups share this family. Re-preview and pass force_shared=true only if removing their node tags is intended.",
            {"shared_use": preview["shared_use"]},
        )

    ops = list(preview["plan"]["ops"])
    if not ops:
        return {
            "success": True,
            "changed": False,
            "preview": preview,
            "mutation": {"success": True, "results": [], "nodes_changed": []},
            "verification": {"ran": True, "matched": True, "residual": []},
        }
    mutation = await _tag_batch_impl(ops)
    changed = bool(mutation.get("nodes_changed"))
    fresh_cache = _current_cache_by_id()
    postfix_words = tuple(preview.get("postfix_words") or (
        DEFAULT_AUTO_EXPAND_POSTFIX,
        DEFAULT_SUPPRESS_POSTFIX,
        DEFAULT_DEPRECATED_POSTFIX,
    ))
    residual_plan = plan_tag_family_purge(
        fresh_cache,
        preview["scope"]["start_ids"],
        preview["families"],
        postfix_words,
    )
    residual = residual_plan["mutable"]
    success = bool(mutation.get("success")) and not residual
    result = {
        "success": success,
        "changed": changed,
        "preview": preview,
        "mutation": mutation,
        "verification": {
            "ran": True,
            "matched": not residual,
            "residual": residual[:80],
            "residual_count": len(residual),
        },
    }
    if residual:
        result["code"] = "purge_verification_failed"
        result["error"] = (
            "Fresh-cache purge verification found residual trailing-name family tags; "
            "committed writes remain and the operation is resumable by re-previewing."
        )
    elif not mutation.get("success"):
        result["code"] = "purge_verification_failed"
        result["error"] = (
            "The Q4 mutation ledger did not complete exactly; committed writes remain and "
            "the operation is resumable by re-previewing."
        )
    return result


# @beacon[
#   id=mcp-api@build-tag-registry,
#   role=ƒ build_tag_registry(),
#   slice_labels=nexus--mcp-api,nexus--tags,
#   kind=ast,
#   comment=Assembly point for the consolidated public Tag family. Six operations preserve surgical single-node primitives, the complete batch ledger, and the fingerprint-gated purge workflow while the registry owns canonical verbs, aliases, schemas, effects, and describe output.,
# ]
def build_tag_registry() -> OperationRegistry:
    """Build tag verbs with declared per-item collisions and describe-only retry advice."""

    registry = OperationRegistry(
        "tag",
        "Workflowy-side tag mutation and batch curation operations.",
        handle_grammar=(
            "node_handle = exact UUID | its 8-hex first segment | unique "
            "longer prefix | [ap:CORE]; source "
            "symbols remain an undocumented transition compatibility only"
        ),
    )

    async def _add(params: dict[str, Any]) -> dict:
        result = await _tag_add_impl(params["node_handle"], params["tags"])
        changed = bool(
            isinstance(result, dict)
            and result.get("success", True)
            and not result.get("no_op")
        )
        return make_mutation_ack(
            operation="tag.add",
            result=result,
            changed=changed,
            warnings=_result_warnings(result),
        )

    async def _remove(params: dict[str, Any]) -> dict:
        result = await _tag_remove_impl(params["node_handle"], params["tags"])
        changed = bool(
            isinstance(result, dict)
            and result.get("success", True)
            and not result.get("no_op")
        )
        return make_mutation_ack(
            operation="tag.remove",
            result=result,
            changed=changed,
            warnings=_result_warnings(result),
        )

    async def _rename(params: dict[str, Any]) -> dict:
        result = await _tag_rename_impl(
            params["node_handle"], params["old_tag"], params["new_tag"]
        )
        changed = bool(
            isinstance(result, dict)
            and result.get("success", True)
            and not result.get("no_op")
        )
        return make_mutation_ack(
            operation="tag.rename",
            result=result,
            changed=changed,
            warnings=_result_warnings(result),
        )

    async def _batch(params: dict[str, Any]) -> dict:
        result = await _tag_batch_impl(params["operations"])
        changed = bool(isinstance(result, dict) and result.get("nodes_changed"))
        return make_mutation_ack(
            operation="tag.batch",
            result=result,
            changed=changed,
            warnings=_result_warnings(result),
        )

    async def _purge_preview(params: dict[str, Any]) -> dict:
        try:
            return await _purge_preview_impl(
                family=params["family"],
                root_handle=params["root_handle"],
                target_tab=params.get("target_tab"),
            )
        except _S07OperationError as exc:
            return _s07_error_result(registry, "purge.preview", exc)

    async def _run_purge_apply(params: dict[str, Any]) -> dict:
        try:
            result = await _purge_apply_impl(
                family=params["family"],
                root_handle=params["root_handle"],
                fingerprint=params["fingerprint"],
                force_shared=bool(params.get("force_shared", False)),
                target_tab=params.get("target_tab"),
            )
        except _S07OperationError as exc:
            return _s07_error_result(registry, "purge.apply", exc)
        return _s07_mutation_ack(
            registry,
            "purge.apply",
            result,
            changed=bool(result.get("changed")),
        )

    async def _purge_apply(params: dict[str, Any]) -> dict:
        if params.get("execution", "sync") == "async":
            legacy = await _start_background_job(
                "tag-purge",
                dict(params),
                lambda _job_id: _run_purge_apply(
                    {**params, "execution": "sync"}
                ),
            )
            return make_job_record(
                operation="tag.purge.apply",
                job_id=str(legacy["job_id"]),
                state=str(legacy.get("status") or "started"),
                extra={"kind": legacy.get("kind") or "tag-purge"},
            )
        return await _run_purge_apply(params)

    node_handle_property = {
        "type": "string",
        "description": "exact UUID | its 8-hex first segment | unique longer prefix | [ap:CORE]",
    }
    tags_property = {
        "type": ["string", "array"],
        "items": {"type": "string"},
    }
    registry.register(
        OperationSpec(
            family="tag",
            verb="add",
            cache_backed=True,
            summary="Add one or more trailing-name tags to one Workflowy node.",
            side_effects=("workflowy_mutation",),
            async_mode="never",
            params_schema={
                "type": "object",
                "properties": {
                    "node_handle": node_handle_property,
                    "tags": tags_property,
                },
                "required": ["node_handle", "tags"],
                "additionalProperties": False,
            },
            returns={"description": "Standardized acknowledgement with full surgical tag result."},
            examples=({"call": {"verb": "add", "params": {"node_handle": "UUID", "tags": ["topic-a"]}}},),
            related=("tag.remove", "tag.batch"),
            handler=_add,
            param_aliases={"node_id": "node_handle", "tag": "tags"},
            domain_error_codes=("mutation_serialization_timeout", "mutation_serialization_conflict", "mutation_region_error", ConcurrentEditDetectedError.code),
            describe_suffix=_N02_UPDATE_DESCRIBE_SUFFIX,
        )
    )
    registry.register(
        OperationSpec(
            family="tag",
            verb="remove",
            cache_backed=True,
            summary="Remove one or more trailing-name tags from one Workflowy node.",
            side_effects=("workflowy_mutation",),
            async_mode="never",
            params_schema={
                "type": "object",
                "properties": {
                    "node_handle": node_handle_property,
                    "tags": tags_property,
                },
                "required": ["node_handle", "tags"],
                "additionalProperties": False,
            },
            returns={"description": "Standardized acknowledgement with full surgical tag result."},
            examples=({"call": {"verb": "remove", "params": {"node_handle": "UUID", "tags": "topic-a"}}},),
            related=("tag.add", "tag.batch"),
            handler=_remove,
            param_aliases={"node_id": "node_handle", "tag": "tags"},
            domain_error_codes=("mutation_serialization_timeout", "mutation_serialization_conflict", "mutation_region_error", ConcurrentEditDetectedError.code),
            describe_suffix=_N02_UPDATE_DESCRIBE_SUFFIX,
        )
    )
    registry.register(
        OperationSpec(
            family="tag",
            verb="rename",
            cache_backed=True,
            summary="Rename one trailing-name tag on one Workflowy node.",
            side_effects=("workflowy_mutation",),
            async_mode="never",
            params_schema={
                "type": "object",
                "properties": {
                    "node_handle": node_handle_property,
                    "old_tag": {"type": "string"},
                    "new_tag": {"type": "string"},
                },
                "required": ["node_handle", "old_tag", "new_tag"],
                "additionalProperties": False,
            },
            returns={"description": "Standardized acknowledgement with full per-node rename result."},
            examples=({"call": {"verb": "rename", "params": {"node_handle": "UUID", "old_tag": "topic-a", "new_tag": "topic-b"}}},),
            related=("tag.add", "tag.remove"),
            handler=_rename,
            param_aliases={"node_id": "node_handle"},
            domain_error_codes=("mutation_serialization_timeout", "mutation_serialization_conflict", "mutation_region_error", ConcurrentEditDetectedError.code),
            describe_suffix=_N02_UPDATE_DESCRIBE_SUFFIX,
        )
    )
    registry.register(
        OperationSpec(
            family="tag",
            verb="batch",
            cache_backed=True,
            summary=(
                "Batch add/remove/rename Workflowy #tags in one call. "
                "operations=[{handle, operation:'add'|'remove', tags:[...]}] "
                "or {handle, operation:'rename', old_tag, new_tag}; handle = "
                "UUID, unique prefix, or [ap:CORE]. All-or-none: one "
                "unresolved handle aborts with zero mutations."
            ),
            side_effects=("workflowy_mutation",),
            async_mode="never",
            params_schema={
                "type": "object",
                "properties": {"operations": {"type": "array"}},
                "required": ["operations"],
                "additionalProperties": False,
            },
            returns={"description": "Standardized acknowledgement with the complete Q4 ledger under detail."},
            examples=({"call": {"verb": "batch", "params": {"operations": [{"handle": "UUID", "operation": "add", "tags": ["topic-a"]}]}}},),
            related=("tag.add", "tag.remove", "tag.rename"),
            handler=_batch,
            domain_error_codes=("mutation_serialization_timeout", "mutation_serialization_conflict", "mutation_region_error", ConcurrentEditDetectedError.code),
            describe_suffix=_N02_UPDATE_DESCRIBE_SUFFIX + " Per-item conflicts stay on the error row and other items continue.",
        )
    )
    purge_codes = (
        "purge_family_invalid",
        "stale_purge_preview",
        "shared_family_collision",
        "purge_verification_failed",
        "root_resolution_failed",
    )
    registry.register(
        OperationSpec(
            family="tag", verb="purge.preview",
            cache_backed=True,
            summary="Preview exact trailing-name removals for one tag family under a root.",
            side_effects=("pure_read",), async_mode="never",
            params_schema={"type":"object","properties":{"family":{"type":"string"},"root_handle":node_handle_property,"target_tab":{"type":["string","null"]}},"required":["family","root_handle"],"additionalProperties":False},
            returns={"description":"Deterministic purge plan, report-only hits, shared-use rows, and consent fingerprint."},
            examples=({"call":{"verb":"purge.preview","params":{"family":"topic-a","root_handle":"UUID"}}},),
            related=("tag.purge.apply","slice_group.purge.preview"), handler=_purge_preview,
            param_aliases={"root_uuid":"root_handle"},
            domain_error_codes=purge_codes,
        )
    )
    registry.register(
        OperationSpec(
            family="tag", verb="purge.apply",
            cache_backed=True,
            summary="Apply a fingerprint-gated verified tag-family cleanup plan.",
            side_effects=("workflowy_mutation","local_state_mutation"), async_mode="optional",
            params_schema={"type":"object","properties":{"family":{"type":"string"},"root_handle":node_handle_property,"fingerprint":{"type":"string"},"force_shared":{"type":"boolean"},"execution":{"type":"string","enum":["sync","async"]},"target_tab":{"type":["string","null"]}},"required":["family","root_handle","fingerprint"],"additionalProperties":False},
            returns={"description":"Job envelope or standardized acknowledgement preserving the full Q4 ledger and verification."},
            examples=({"call":{"verb":"purge.apply","params":{"family":"topic-a","root_handle":"UUID","fingerprint":"sha256"}}},),
            related=("tag.purge.preview",), handler=_purge_apply,
            param_aliases={"root_uuid":"root_handle"},
            domain_error_codes=purge_codes + ("mutation_serialization_timeout", "mutation_serialization_conflict", "mutation_region_error"),
        )
    )
    return registry


# ---------------------------------------------------------------------------
# Consolidated public Anchor family (S03): Anchor Docks + Anchor Points.
# ---------------------------------------------------------------------------

class _AnchorOperationError(RuntimeError):
    """Typed family error converted to the registry's declared error envelope."""

    def __init__(self, code: str, message: str, extra: Any = None) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.extra = extra


_ANCHOR_AP_ID_ALLOCATION_LOCK = asyncio.Lock()
_ANCHOR_AP_ID_RESERVED_CORES: set[str] = set()
_ANCHOR_AP_ID_ALLOCATED_CORES: set[str] = set()
# NOTE: _ANCHOR_AP_ID_LEADING_RE moved to api_client_nexus.py (SINGLE HOME,
# next to the other AP-ID grammar) so the protected-name composer, the
# leading-AP splitter, and this assignment-side detector all share one regex.


def _anchor_cache_by_id() -> dict[str, dict[str, Any]]:
    """The operation's pinned ``{uuid: node}`` map for anchor tooling (S03 §8.1).

    Same contract as :func:`_current_cache_by_id`: the explicit task-local
    operation snapshot, borrowed read-only view index and immutable nodes.
    """
    from .client.api_client_nexus import load_nodes_by_id_from_cache
    from .coherence.operation_cache import current_operation_cache

    return load_nodes_by_id_from_cache(current_operation_cache())


class _AnchorDockRootDetected(RuntimeError):
    """Typed guard failure: an in-band full-dump root IS an Anchor Dock.

    Raised by :func:`_anchor_dock_root_guard`; converted at each public
    family boundary (``node.scry`` catches it into the declared registry
    envelope via the shared ``_error`` seam; the glimpse bare-root branch
    converts it into that path's standard ``success: False`` payload).
    """

    def __init__(self, code: str, message: str, extra: Any = None) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.extra = extra


class _FullDumpRootCacheMiss(RuntimeError):
    """Typed guard failure: an in-band full-dump root is NOT in the cache.

    Raised by :func:`_anchor_dock_root_guard` when the (possibly resolved)
    root is absent from the local /nodes-export snapshot -- the guard cannot
    classify it, and an in-band full dump of an UNCLASSIFIABLE root is
    refused (it could be an Anchor Dock). Converted at the same family
    boundaries as :class:`_AnchorDockRootDetected`.
    """

    def __init__(self, code: str, message: str, extra: Any = None) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.extra = extra


# @beacon[
#   id=auto-beacon@_read_anchor_dock_vocabulary-v52q,
#   role=_read_anchor_dock_vocabulary,
#   slice_labels=nexus--anchors,
#   kind=ast,
# ]
async def _read_anchor_dock_vocabulary(
    target_tab: str | None,
) -> tuple[list[str], dict[str, list[str]]]:
    """One shared read of the live Anchor Dock tag vocabulary.

    Returns ``(base_tags, postfix_kwargs)`` from the tab-agnostic
    extension-settings read, where ``postfix_kwargs`` is the THREE-key dict
    from :func:`_anchor_postfix_kwargs_from_reply` (``local_postfixes`` /
    ``favorite_postfixes`` / ``deprecated_postfixes``) ready to splat into
    ``classify_anchor_tags`` / ``build_anchor_boundary_predicate``. Loud on
    transport failure (per the retracted no-WebSocket doctrine: config
    vocabulary reads are first-class). The Anchor-Dock root guard and the
    ``stop_at_child_anchors`` boundary predicate share ONE read per operation
    through this seam.
    """
    base_tags, _global_tags, _default_parent, reply = (
        await _resolve_note_session_config(target_tab)
    )
    return base_tags, _anchor_postfix_kwargs_from_reply(reply)


# @beacon[
#   id=mcp-api@anchor-dock-root-guard,
#   role=⚡ _anchor_dock_root_guard(root_handle, target_tab, tool_label, anchor_vocabulary),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Shared Anchor-Dock root guard behind the two IN-BAND full-dump returns (node.scry and the bare-root_handle glimpse raw dump). Resolves the handle (UUID / unique prefix / [ap:CORE]) and classifies the root node's NAME tags against ONE welded snapshot (the resolver's echoed cache map + ONE live Dock-vocabulary read, optionally injected so the stop_at_child_anchors boundary shares it). Verdicts: root IS an Anchor Dock (global or local) -> raise _AnchorDockRootDetected with a peek/render teaching message; root ABSENT from the cache -> raise _FullDumpRootCacheMiss (FAIL CLOSED -- an unclassifiable in-band full-dump root is refused, never allowed to fall through to the API subtree fetch; the message points at system.cache.refresh); otherwise return {resolved, anchor_vocabulary} so the caller's downstream resolution and boundary predicate reuse the same operands. The live extension-settings WS read is FIRST-CLASS (the historical 'scry never touches the WebSocket' doctrine is retracted: node CONTENTS come from the cache/API, the Dock-tag VOCABULARY from the tab; a failed config read is loud, never a silent skip). Out-of-band deliveries (output_file, push_to_modal) are exempt by caller placement, never by this helper; allow_anchor_dock=true skips the guard wholesale at each caller.,
# ]
async def _anchor_dock_root_guard(
    root_handle: str,
    *,
    target_tab: str | None,
    tool_label: str,
    anchor_vocabulary: tuple[list[str], dict[str, list[str]]] | None = None,
) -> dict[str, Any]:
    """Resolve + Anchor-Dock-classify an in-band full-dump root handle.

    Shared guard behind ``node.scry`` and the bare-root ``glimpse`` raw dump
    -- the two IN-BAND full-subtree returns. An Anchor Dock root makes those
    calls return the ENTIRE Dock subtree in-band (potentially megabytes of
    agent context) when ``anchor.dock.peek`` / ``anchor.dock.render`` is
    almost always the right tool.

    Returns ``{"resolved": <uuid>, "anchor_vocabulary": (base_tags,
    postfix_kwargs)}`` on a pass: ``resolved`` is the adopted UUID (a unique
    prefix / ``[ap:CORE]`` handle exact-hits downstream), and the vocabulary
    is the ONE live read this guard performed (reusable by the caller, e.g.
    the ``stop_at_child_anchors`` boundary predicate). The cache map used for
    classification is the SAME map the handle resolver loaded (one welded
    snapshot -- no second load).

    Raises:
        _AnchorDockRootDetected: the resolved root carries a configured
            Anchor Dock tag (global OR local).
        _FullDumpRootCacheMiss: the root is absent from the local
            /nodes-export snapshot. FAIL CLOSED: an unclassifiable in-band
            full-dump root is refused (it could be an Anchor Dock) rather
            than allowed through to the API subtree fetch. No config read
            is spent on this path (nothing to classify).
        RuntimeError: the live anchor-tag config could not be read. The
            extension-settings WebSocket read is FIRST-CLASS here -- the
            historical 'scry never touches the WebSocket' doctrine is
            retracted: node CONTENTS come from the cache/API (never the
            DOM), but the Dock-tag VOCABULARY comes from the tab, and
            without it 'what is an Anchor Dock' is unknowable, so this
            fails loudly rather than silently skipping the guard.
    """
    resolved, nodes_by_id = await _resolve_generic_node_handle_with_cache(
        root_handle, label=f"{tool_label} (root_handle)", required=False
    )
    node = nodes_by_id.get(resolved)
    if node is None:
        # Absent from the local snapshot: nothing to classify. FAIL CLOSED --
        # the scry client would otherwise fall through to a live API subtree
        # fetch and could return an entire Anchor Dock in-band (the original
        # 2MB-class failure mode, precisely during cache staleness). No
        # config read is spent: there is no node to classify.
        from .archive_context import ap_miss_hint

        _hint = ap_miss_hint(root_handle)
        raise _FullDumpRootCacheMiss(
            "root_not_in_cache",
            (
                f"{tool_label}: root {root_handle!r} is absent from the local "
                "/nodes-export snapshot, so the Anchor-Dock guard cannot "
                "classify it -- an in-band full dump of an UNCLASSIFIABLE root "
                "is refused (it could be an Anchor Dock). If you recently "
                "created or retagged this node, call "
                "system(verb='cache.refresh') and retry; if it is still "
                "absent after a fresh refresh, the root does not exist in "
                "this vault -- check the UUID / unique prefix / [ap:CORE] "
                "handle. To bypass the guard entirely, pass "
                "allow_anchor_dock=true."
                + (f"\n{_hint}" if _hint else "")
            ),
            extra={
                "root_handle": root_handle,
                "remedy": "system.cache.refresh",
                "override_param": "allow_anchor_dock",
            },
        )
    if anchor_vocabulary is None:
        anchor_vocabulary = await _read_anchor_dock_vocabulary(target_tab)
    base_tags, postfix_kwargs = anchor_vocabulary
    from nexus_map_codebase import split_name_and_tags  # type: ignore[import-not-found]

    plain_name, name_tags = split_name_and_tags(
        str(node.get("name") or node.get("nm") or "")
    )
    verdict = classify_anchor_tags(
        name_tags,
        base_tags,
        **postfix_kwargs,
    )
    if not verdict.get("is_anchor"):
        return {"resolved": resolved, "anchor_vocabulary": anchor_vocabulary}
    dock_name = str(plain_name or "").strip() or "(untitled)"
    matched_tag = (
        f"#{verdict['matched_tag']}" if verdict.get("matched_tag") else None
    )
    raise _AnchorDockRootDetected(
        "anchor_dock_root_detected",
        (
            f"{tool_label}: the requested root is the Anchor Dock "
            f"'{dock_name}' ({resolved}"
            + (f", matched {matched_tag}" if matched_tag else "")
            + "). A full in-band dump of an Anchor Dock returns its ENTIRE "
            "subtree -- potentially megabytes of agent context. Prefer "
            "anchor.dock.peek (compact direct-child inventory; child Docks "
            "signposted) or anchor.dock.render (bounded full read that stops "
            "at child Docks). To proceed anyway, re-call with "
            "allow_anchor_dock=true (out-of-band deliveries such as "
            "output_file writes are exempt by design)."
        ),
        extra={
            "dock_uuid": resolved,
            "dock_name": dock_name,
            "matched_tag": matched_tag,
            "suggested_operations": ["anchor.dock.peek", "anchor.dock.render"],
            "override_param": "allow_anchor_dock",
        },
    )


def _anchor_leading_ap_core(name: Any) -> str | None:
    # Delegates to the ONE shared leading-AP splitter (same grammar the
    # protected-name composer uses), so 'does this name carry an AP-ID' can
    # never drift between assignment, resolution, and the rename guard.
    return _split_leading_ap_handle(str(name or ""))["core"]


# @beacon[
#   id=mcp-api@generate-ap-core,
#   role=ƒ generate_ap_core(existing_check, tries=8),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Pure six-character uppercase-base36 AP-ID generator. Retries against an injected collision predicate and fails loudly after the bounded attempt budget; allocation locking and reservation live in the caller.,
# ]
def generate_ap_core(existing_check: Callable[[str], bool], tries: int = 8) -> str:
    """Generate one collision-checked six-character uppercase base36 AP core."""

    import secrets
    import string

    alphabet = string.ascii_uppercase + string.digits
    for _ in range(max(1, int(tries))):
        core = "".join(secrets.choice(alphabet) for _ in range(6))
        if not existing_check(core):
            return core
    raise _AnchorOperationError(
        "ap_id_allocation_exhausted",
        f"Could not allocate a unique AP-ID after {tries} attempts; retry.",
    )


# @beacon[
#   id=auto-beacon@_anchor_reserve_ap_core-z0d0,
#   role=_anchor_reserve_ap_core,
#   slice_labels=nexus--anchors,
#   kind=ast,
# ]
async def _anchor_reserve_ap_core(
    requested: str,
    *,
    nodes_by_id: dict[str, dict[str, Any]],
) -> str:
    """Reserve an explicit/automatic AP core against cache + process-local state.

    S04 §7.4: this is a cache-derived GLOBAL UNIQUENESS proof (the
    collision scan asserts the core is absent from the whole cache) — it
    REFUSES under the hard barrier via the shared identity-proof gate
    before any reservation work.  Ordinary AP-ID 0/1/N resolution is a
    cache-backed read and is NOT gated (it carries the read advisory).
    """

    from .client.api_client_nexus import (
        _normalize_ap_id_input,
        resolve_uuid_from_anchor_point,
    )
    from .coherence.admission import require_cache_identity_proof

    await require_cache_identity_proof(
        _admission_coherence_paths, operation="anchor AP-ID uniqueness proof"
    )

    # Archive Reads (§4.9, Axiom 11): read the archived cores ONCE, before
    # the lock.  Allocation runs in write operations, so it reads the store,
    # never the snapshot.  A core any readable archive carries -- whatever
    # its state -- is taken (an unreachable folder contributes only what it
    # can read, E42).
    from .archive_store import get_archive_store
    from .archive_texts import ap_core_collision_text

    archived_cores = get_archive_store().all_ap_cores()

    async with _ANCHOR_AP_ID_ALLOCATION_LOCK:
        def _exists(core: str) -> bool:
            if (
                core in _ANCHOR_AP_ID_RESERVED_CORES
                or core in _ANCHOR_AP_ID_ALLOCATED_CORES
            ):
                return True
            if core in archived_cores:
                return True
            outcome = resolve_uuid_from_anchor_point(
                core, nodes_by_id, universe="live"
            )
            return int(outcome.get("match_count", 0) or 0) > 0

        if str(requested or "").strip().lower() == "auto":
            core = generate_ap_core(_exists)
        else:
            core = _normalize_ap_id_input(str(requested or ""))
            if not core:
                raise _AnchorOperationError(
                    "invalid_parameter_combination",
                    "ap_id must be null, 'auto', or a valid [ap:CORE] handle.",
                )
            if core in archived_cores:
                raise _AnchorOperationError(
                    "ap_id_collision",
                    ap_core_collision_text(core, archived_cores[core]),
                )
            if _exists(core):
                raise _AnchorOperationError(
                    "ap_id_collision",
                    f"AP-ID [ap:{core}] is already present or reserved; choose another.",
                )
        _ANCHOR_AP_ID_RESERVED_CORES.add(core)
        return core


# @beacon[
#   id=auto-beacon@_anchor_finish_ap_reservation-0864,
#   role=_anchor_finish_ap_reservation,
#   slice_labels=nexus--anchors,
#   kind=ast,
# ]
async def _anchor_finish_ap_reservation(core: str, *, committed: bool) -> None:
    async with _ANCHOR_AP_ID_ALLOCATION_LOCK:
        _ANCHOR_AP_ID_RESERVED_CORES.discard(core)
        if committed:
            _ANCHOR_AP_ID_ALLOCATED_CORES.add(core)


def _anchor_result_warnings(result: Any) -> tuple[Any, ...]:
    if not isinstance(result, dict):
        return ()
    raw = result.get("warnings") or ()
    items = list(raw) if isinstance(raw, (list, tuple)) else [raw]
    mapped = result.get("mapped_subtree_warning")
    if mapped and mapped not in items:
        items.append(mapped)
    return tuple(items)


# ---------------------------------------------------------------------------
# COMPACT INVENTORY VIEWS -- output-side progressive disclosure (2026).
# The three INVENTORY operations (anchor.dock.list / anchor.dock.peek /
# slice_group.list) return one raw-text inventory string under
# detail='compact' -- THE DEFAULT AT EVERY SURFACE: the consolidated registry
# handlers, the impls, AND the legacy list_anchors / list_slice_groups
# delegates (Dan, 2026: single-user system; the byte-compat guard for legacy
# surfaces is deliberately waived). detail='full' is the explicit escape
# hatch everywhere, byte-for-byte the established payloads. These are
# inventory SERIALIZERS, not document renderers: they never enter
# RenderProjectionSpec / Stage 1 / Stage 2 / the Markdown composer, and they
# stay pure_read. Shared PURE interpretation lives in
# _normalize_inventory_view (boundary knobs) plus the api_client_nexus
# primitives (_short_handle_prefix / _middle_ellipsis) and the
# f8_slice_policy nested-display builder; the three domain serializers and
# their transports stay per-origin (Stage-0 doctrine).
# ---------------------------------------------------------------------------


def _normalize_inventory_view(
    detail: Any,
    max_chars: Any,
) -> tuple[str | None, int | None, tuple[str, str] | None]:
    """Shared boundary normalizer for the compact-inventory view knobs.

    Validates the two knobs every compact inventory operation carries:
    ``detail`` (exact, case-sensitive ``'compact'``|``'full'`` -- the family
    ``describe(detail=...)`` idiom) and ``max_chars`` (an integer ``>= 0``;
    ``0`` disables truncation; ``None`` maps to the public default, which is
    UNLIMITED -- Dan's ruling [ap:WG3QTR], 2026-09-16: an inventory never
    truncates a node name by default; middle-elision is an explicit opt-in
    via the public ``max_name_chars`` knob).
    Returns ``(detail, max_chars, error)`` where ``error`` is ``None`` or a
    ``(code, message)`` pair the caller wraps in its own family error type.
    Deliberately NOT an orchestrator: each inventory operation keeps its own
    transport/data path (Stage-0 doctrine -- share pure interpretation only).
    """
    if not isinstance(detail, str) or detail not in ("compact", "full"):
        return None, None, (
            "invalid_enum_value",
            "detail must be 'compact' or 'full' (exact, case-sensitive).",
        )
    if max_chars is None:
        return detail, 0, None
    if isinstance(max_chars, bool) or (
        not isinstance(max_chars, int)
        and not (isinstance(max_chars, float) and max_chars.is_integer())
    ):
        return None, None, (
            "invalid_parameter_type",
            "max_chars must be an integer >= 0 (0 disables truncation).",
        )
    max_chars = int(max_chars)
    if max_chars < 0:
        return None, None, (
            "invalid_parameter_combination",
            "max_chars must be >= 0 (0 disables truncation).",
        )
    return detail, max_chars, None


def _dock_peek_description_excerpt(root_note: Any) -> str | None:
    """The Dock's one-line description text: metadata-stripped, whitespace-collapsed.

    THE single definition of the peek description-excerpt text (CF-MST-015):
    the compact serializer budgets it (default 256 chars via the shared
    ``_middle_ellipsis`` -- node NAMES stay unlimited per the WG3QTR ruling)
    and ``detail='full'`` carries the same text untruncated as
    ``description``. Returns None when nothing would be displayed. Pure.
    """
    excerpt = WorkFlowyClient._strip_cartographer_metadata_from_note_for_preview(
        str(root_note or "")
    )
    one_line = " ".join(str(excerpt).split())
    return one_line or None


# @beacon[
#   id=mcp-api@render-dock-peek-raw-text,
#   role=ƒ _render_dock_peek_raw_text(dock_name, root_note, rows, show_ids, show_counts, show_description, max_chars, max_description_chars, root_metrics, recursive, descend_policy, selection, sort, root_uuid, uuid_prefix_collisions, parent_handles),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Pure compact Dock-peek serializer. One globally padded AP-only column over visible rows; blank for missing APs, no column if none. Names are shown in full (trailing #tags included) -- max_chars is an opt-in middle-ellipsis budget, 0/None = unlimited. The Dock's own '> …' description excerpt is budgeted SEPARATELY (max_description_chars, default 256, CF-MST-015; the name budget never touches it and show_description=false still suppresses it entirely). Only the trimmed body indents (four spaces per real node depth) and only while the rows are the plain document-order walk: a recent-N selection or a timestamp sort renders FLAT (a timestamp order is not a tree order), and UTAERZ shows the nesting per row there instead -- one ' ← in ‹parent handle›' hint (the parent's [ap:CORE], else its short UUID) on every row whose parent is not the peeked Dock (parent_handles is the impl's precomputed map; depth stays in the JSON). The header names the selection/order, including 'N completed hidden' whenever the default completed-exclusion removed rows (recency views AND the plain inventory alike, U6/J11); under a recent-N selection [ap:TVIIBN] 4e adds ONE explicit rule line directly below the header (describe_dock_peek_recency_rule, the peek-side twin of the render verbs' _recency_header_sentence): sort_direction only orders the selected rows, it never changes which rows were chosen. Row handles ([ap:0M6VP8] peek half): rows without an AP-ID show a bracketed short UUID handle in the body by default; show_ids=true adds it to every row; both route through the ONE shortener unique_short_uuid_prefix over the caller's uuid_prefix_collisions index (CF-22/O3), never a second shortener. Four source metrics and Dock/favorite/local/completed flags (marker order ⚓ ⭐ Ⓛ ✓; ⭐ only on a Dock row) with a policy-aware legend. No acquisition, source mutation, document rendering or traversal decisions.,
# ]
def _render_dock_peek_raw_text(
    *,
    dock_name: str,
    root_note: str,
    rows: list[dict[str, Any]],
    show_ids: bool = False,
    show_counts: bool = True,
    show_description: bool = True,
    max_chars: int | None = 0,
    max_description_chars: int | None = 256,
    root_metrics: dict[str, int] | None = None,
    recursive: bool = False,
    descend_policy: str = "stop_at_child_anchors",
    selection: dict[str, Any] | None = None,
    sort: dict[str, Any] | None = None,
    root_uuid: str | None = None,
    uuid_prefix_collisions: dict[str, list[str]] | None = None,
    parent_handles: dict[str, str] | None = None,
) -> str:
    """Keep one AP-only column left; indent only the trimmed body by node depth."""
    from .dock_peek_metrics import (
        DOCK_PEEK_RECENCY_BASES,
        describe_dock_peek_recency_rule,
        describe_dock_peek_selection,
        format_dock_peek_metrics,
    )

    count = len(rows)
    crosses_docks = descend_policy == "all"
    recursive_note = "includes nested Docks" if crosses_docks else "stops at nested Docks"
    selection = selection or {}
    sort = sort or {}
    recent_active = selection.get("recent") is not None
    timestamp_order = sort.get("by") in DOCK_PEEK_RECENCY_BASES
    # A recent-N selection or a timestamp order is not a tree order: flat rows.
    flat = recent_active or timestamp_order
    selection_phrase = describe_dock_peek_selection(selection, sort, recursive=recursive)
    if recent_active:
        child_noun = selection_phrase
        if recursive:
            child_noun += f" (recursive; {recursive_note}; flat, parent shown per row)"
        count_prefix = ""
    else:
        child_noun = f"rows (recursive; {recursive_note})" if recursive else ("child" if count == 1 else "children")
        if timestamp_order:
            child_noun += f" · {selection_phrase}"
            if recursive:
                child_noun += " · flat, parent shown per row"
        elif selection_phrase:
            # Document order: selection_phrase is exactly " · N completed
            # hidden" when the default exclusion removed rows ("" otherwise).
            child_noun += selection_phrase
        count_prefix = f"{count} "
    id_note = (
        "AP-IDs aligned left · [xxxxxxxx] short UUID handle on every row"
        if show_ids
        else "AP-IDs aligned left · [xxxxxxxx] short UUID handle on rows without an AP-ID"
    )
    root_suffix = format_dock_peek_metrics(root_metrics) if show_counts and root_metrics is not None else ""
    header = (
        f"{_middle_ellipsis(dock_name, max_chars)}{root_suffix} — {count_prefix}{child_noun} · "
        f"{id_note} · detail='full' for JSON"
    )
    lines: list[str] = [header]
    if recent_active:
        # [ap:TVIIBN] 4e: ONE explicit rule line right under the header when a
        # recent-N selection is active -- sort_direction only orders the
        # selected rows, it never changes which rows were chosen.
        lines.append(describe_dock_peek_recency_rule(selection, sort))
    if show_description:
        # CF-MST-015: the description excerpt carries its OWN default budget
        # (256 chars, middle-ellipsis); the name budget (max_chars, default
        # unlimited per WG3QTR) never applies to it.
        one_line = _dock_peek_description_excerpt(root_note)
        if one_line:
            lines.append(f"> {_middle_ellipsis(one_line, max_description_chars)}")
    dock_key = "⚓ Dock" if crosses_docks else "⚓ Dock (recursion stops here)"
    lines.append(f"Key: {dock_key} · ⭐ favorite Dock · Ⓛ local Dock · ✓ completed")
    if show_counts:
        lines.append(
            "Metrics: ▸ direct children · desc all descendants · self title+note UTF-8 size "
            "· tree self+all descendants; includes completed/suppressed content and content "
            "behind Dock signposts. Snapshot facts, not live verification."
        )
    lines.append("")
    if not rows:
        lines.append("(no descendants)" if recursive else "(no direct children)")
        return "\n".join(lines)

    id_strings: list[str] = []
    names: list[str] = []
    for row in rows:
        name = str(row.get("name") or "").strip()
        ap_id = str(row.get("ap_id") or "").strip()
        id_strings.append(ap_id)
        if ap_id:
            # One AP grammar, one AP display. Padding goes AFTER the closing
            # bracket so the citation remains an intact resolver token.
            parts = _split_leading_ap_handle(name)
            if parts.get("core"):
                regions = [
                    region.strip()
                    for region in (
                        parts.get("decoration") or "",
                        parts.get("title") or "",
                    )
                    if region and region.strip()
                ]
                name = " ".join(regions)
        names.append(name.strip())
    # One width across ALL displayed rows, independent of group/depth. No
    # AP anywhere means no column or separator; missing APs otherwise pad blank.
    width = max(len(value) for value in id_strings)
    for row, id_str, name in zip(rows, id_strings, names):
        suffix = format_dock_peek_metrics(row) if show_counts else ""
        # Compact marker order (§6.8): ⚓ then ⭐ (only when is_dock) then Ⓛ then ✓.
        if row.get("is_dock"):
            suffix += " ⚓"
            if row.get("is_favorite_dock"):
                suffix += " ⭐"
        if row.get("is_local_dock"):
            suffix += " Ⓛ"
        if row.get("completed"):
            suffix += " ✓"
        name = _middle_ellipsis(name, max_chars)
        # UTAERZ: a flat view (recent-N or timestamp order) is not a tree
        # order, so nesting is shown per row instead: a short parent hint on
        # every row whose parent is not the peeked Dock itself. Document
        # order keeps the indentation and never adds hints.
        if flat:
            parent_id = row.get("parent_id")
            if parent_id and root_uuid and parent_id != root_uuid:
                hint = (parent_handles or {}).get(parent_id)
                if hint:
                    name = f"{name} ← in {hint}"
        indent = "    " * int(row.get("depth") or 0) if (recursive and not flat) else ""
        ap_column = id_str.ljust(width) + " " if width else ""
        # [ap:0M6VP8] peek half: a usable handle on EVERY row. Default: the
        # short UUID handle only on rows without an AP-ID (those rows would
        # otherwise have no handle at all); show_ids=true adds it to every
        # row. One shortener, 4g's unique_short_uuid_prefix (CF-22/O3), so a
        # peek handle pastes back and resolves exactly like a rendered heading.
        if show_ids or not id_str:
            short = unique_short_uuid_prefix(row.get("uuid"), uuid_prefix_collisions)
            uuid_prefix = f"[{short}] " if short else ""
        else:
            uuid_prefix = ""
        lines.append(f"{ap_column}{indent}{uuid_prefix}{name}{suffix}")
    return "\n".join(lines)


# @beacon[
#   id=mcp-api@render-slice-group-inventory-raw-text,
#   role=ƒ _render_slice_group_inventory_raw_text(records, show_tags, max_chars),
#   slice_labels=nexus--mcp-api,nexus--config,
#   kind=ast,
#   comment=Pure compact serializer for slice_group.list: one raw-text nested outline of the persisted slice groups. Rows come from build_slice_group_display_items -- the exact Python twin of the client's buildNestedDisplayItems (auto-vivified synthetic categories, the lowest-indexed canonical expander owning descendants, duplicate expander rows marked ' ⚠ duplicate category', null-index-last case-insensitive ordering, every category expanded). Category rows are bare '▾ name' (organizational; no ID, and hidden category-group tags are never exposed); leaf rows are '[<bare 8-hex group prefix>] short-name — up to 4 #tags (+N more) ✅' (✅ on the active group only). The header counts every stored record and ends detail='full' for JSON. Pure; no I/O.,
# ]
def _render_slice_group_inventory_raw_text(
    records: list[dict[str, Any]],
    *,
    show_tags: bool = True,
    max_chars: int = 256,
) -> str:
    """Serialize persisted slice-group records as the compact nested outline."""
    header = (
        f"Slice Groups — {len(records)} · [xxxxxxxx] = bare 8-char "
        "group-handle prefix ('grp-' elided) · short names resolve · "
        "▾ = category · ✅ = active · detail='full' for JSON"
    )
    lines: list[str] = [header, ""]
    rows = build_slice_group_display_items(records)
    if not rows:
        lines.append("(none)")
        return "\n".join(lines)
    for row in rows:
        indent = "  " * int(row.get("depth") or 0)
        if row["kind"] == "expander":
            marker = " ⚠ duplicate category" if row.get("duplicate") else ""
            lines.append(f"{indent}▾ {row['name']}{marker}")
            continue
        record = row.get("group") or {}
        gid = _short_handle_prefix(record.get("id"), key_prefix="grp-")
        name = _middle_ellipsis(row.get("name"), max_chars)
        line = f"{indent}[{gid}] {name}"
        if show_tags:
            tags = [str(tag) for tag in (record.get("tags") or [])]
            shown = tags[:4]
            tag_text = " ".join(f"#{tag}" for tag in shown)
            extra = len(tags) - len(shown)
            if extra > 0:
                tag_text += f" +{extra} more"
            if tag_text:
                line += f" — {tag_text}"
        if record.get("active"):
            line += " ✅"
        lines.append(line)
    return "\n".join(lines)


# @beacon[
#   id=mcp-api@anchor-dock-list,
#   role=⚡ _anchor_dock_list_impl(include_local, target_tab, detail, max_chars, favorites_only, max_description_chars, show_description),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Anchor Dock inventory front. detail='compact' (THE default everywhere -- consolidated registry, impl, and the legacy list_anchors delegate) returns ONE raw-text inventory string from one _list_anchors_internal(tree_view=True) acquisition, serialized by the ONE shared _render_anchor_tree_raw_text compact mode; detail='full' is the explicit escape hatch returning the established structured payload (rows gain is_favorite; the favorites echo keys ride along). favorites_only defaults TRUE HERE (the public shortlist default; _list_anchors_internal and the legacy tool stay False): the ⭐ favorites shortlist with the zero-favorites fallback, compact header counts taken from the echoed shown_global_count/shown_local_count so the arithmetic is correct under favorites. Row descriptions ([ap:YLHDIN] part 2): every compact row carries the Dock's FIRST description line as a ' — excerpt' tail (show_description=true default; max_description_chars budgets it, default 120, 0 hides; the same metadata-stripped text the structured rows carry). An inventory serializer, never a document render: no RenderProjectionSpec, no Stage 1/2, no composer.,
# ]
async def _anchor_dock_list_impl(
    include_local: bool = False,
    target_tab: str | None = None,
    *,
    detail: str = "compact",
    max_chars: int | None = None,
    favorites_only: bool = True,
    max_description_chars: int | None = 120,
    show_description: bool = True,
) -> Any:
    """Return the configured Anchor Dock inventory in Workflowy visual order.

    ``detail='compact'`` (the default everywhere -- consolidated registry,
    impl, and the legacy ``list_anchors`` delegate alike) returns one raw-text
    inventory string from the SAME single acquisition path -- one
    ``_list_anchors_internal(tree_view=True)`` call, serialized by the ONE
    shared ``_render_anchor_tree_raw_text`` compact mode. ``detail='full'``
    is the explicit escape hatch returning the established structured payload.
    ``favorites_only`` defaults TRUE (the public shortlist default, §6.5.2):
    only ⭐ favorite Docks (plus, with ``include_local``, local Docks reachable
    from a favorite through local Docks only); zero favorites in the vault
    falls back to the full list with a header saying so. Compact rows carry
    the Dock's FIRST description line as a `` — excerpt`` tail (TODO
    [ap:YLHDIN] part 2): ``show_description`` (default true) and
    ``max_description_chars`` (default 120; 0 hides) shape it. This is an
    inventory serializer, never a document render.
    """
    detail, max_chars, view_error = _normalize_inventory_view(detail, max_chars)
    if view_error:
        code, message = view_error
        raise _AnchorOperationError(code, message)
    # Archive Reads U3 (§U3.2 D3): dock.list's scope is the whole vault —
    # the §5.5 footer then counts every active/orphaned archive.
    from .archive_context import note_archive_scope_vault

    note_archive_scope_vault()
    if detail == "compact":
        result = await _list_anchors_internal(
            target_tab=target_tab,
            show_local_anchors=bool(include_local),
            tree_view=True,
            include_raw_text=False,
            favorites_only=bool(favorites_only),
        )
        if not isinstance(result, dict) or not result.get("success"):
            return result
        # §6.5.5: the compact header counts come from the ECHOED shown counts
        # in ALL modes -- numerically identical to today's
        # session_count − local_anchor_count arithmetic when favorites_only
        # is not effective, and correct under favorites (where the old
        # arithmetic would be wrong: shown locals include starred locals even
        # with include_local=False, and hidden globals are not session_count).
        shown_global_count = int(result.get("shown_global_count") or 0)
        shown_local_count = int(result.get("shown_local_count") or 0)
        return _render_anchor_tree_raw_text(
            result.get("anchor_tree"),
            global_count=shown_global_count,
            local_count=shown_local_count,
            show_local=bool(include_local),
            compact=True,
            max_chars=max_chars,
            max_description_chars=max_description_chars,
            show_description=show_description,
            favorites_only=bool(result.get("favorites_only")),
            favorites_fallback=bool(result.get("favorites_fallback")),
            favorite_count=int(result.get("favorite_count") or 0),
            total_dock_count=result.get("total_dock_count"),
            favorite_tag_hint=result.get("favorite_tag_hint"),
        )
    result = await _list_anchors_internal(
        target_tab=target_tab,
        show_local_anchors=bool(include_local),
        favorites_only=bool(favorites_only),
    )
    if not isinstance(result, dict) or not result.get("success"):
        return result
    docks: list[dict[str, Any]] = []
    for row in result.get("sessions") or []:
        if not isinstance(row, dict):
            continue
        dock = dict(row)
        dock["dock_handle"] = row.get("id")
        dock["topic"] = row.get("name")
        dock["is_local"] = bool(row.get("is_local", False))
        # §6.5.2: full rows carry is_favorite (copied from the session row).
        dock["is_favorite"] = bool(row.get("is_favorite", False))
        docks.append(dock)
    result["docks"] = docks
    result["dock_count"] = len(docks)
    return result


# @beacon[
#   id=mcp-api@anchor-dock-create,
#   role=⚡ _anchor_dock_create_impl(topic, description, parent_handle, local, extra_tags, target_tab, favorite),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Resolve explicit or configured parent and hold its child list plus any authored leading AP core through client.create_note_session; description stays optional and the existing single-create tag/config authority is unchanged.,
# ]
async def _anchor_dock_create_impl(
    topic: str,
    description: str = "",
    parent_handle: str | None = None,
    local: bool = False,
    extra_tags: list[str] | str | None = None,
    target_tab: str | None = None,
    *,
    favorite: bool = False,
) -> dict:
    """Create a Dock under parent-child-list plus authored-core ownership."""

    client = get_client()
    cfg_tags, _global_tags, default_parent, reply = (
        await _resolve_note_session_config(target_tab)
    )
    postfix_kwargs = _anchor_postfix_kwargs_from_reply(reply)
    resolved_parent = str(parent_handle or "").strip() or str(default_parent or "").strip()
    if not resolved_parent:
        raise RuntimeError(
            "No parent_handle was supplied and no default Anchor Dock parent is configured."
        )
    resolved_parent = await _resolve_mutation_region_handle(
        resolved_parent, label="anchor.dock.create (parent_handle)", role="parent",
    )
    explicit_cores = _explicit_ap_cores_from_payload([{"name": topic}])
    async with mutation_region_locks(
        client=client, operation_label="anchor.dock.create",
        region_factory=lambda snapshot: (
            *_mutation_parent_regions(resolved_parent, snapshot=snapshot),
            *(build_region_ap_core(core) for core in explicit_cores),
        ),
    ):
        session_tags = list(cfg_tags[:1])
        if not session_tags:
            raise RuntimeError("No Anchor Dock tag is configured on the target tab.")
        if "note session" in str(topic or "").lower():
            raise ValueError(
                "topic must not contain the words 'note session'; the Dock tag supplies identity."
            )
        if isinstance(extra_tags, str):
            extra_tags = [extra_tags]
        local_postfix = (
            postfix_kwargs["local_postfixes"][0] if local else None
        )
        favorite_postfix = (
            postfix_kwargs["favorite_postfixes"][0] if favorite else None
        )
        return await client.create_note_session(
            parent_uuid=resolved_parent,
            description=topic,
            detail=description,
            session_tags=session_tags,
            extra_tags=list(extra_tags or []),
            local_postfix=local_postfix,
            favorite_postfix=favorite_postfix,
        )


# @beacon[
#   id=mcp-api@anchor-dock-update,
#   role=⚡ _anchor_dock_update_impl(dock_handle, topic, description, local, target_tab, favorite, families),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Exact-node ownership precedes the one live Dock GET through a covered inner edit; the protected-name composer preserves AP tags and emoji, local/favorite transforms change only the selected family's attributes, ambiguity refuses before writes and the same snapshot determines both verdict and write.,
# ]
async def _anchor_dock_update_impl(
    dock_handle: str,
    topic: str | None = None,
    description: str | None = None,
    local: bool | None = None,
    target_tab: str | None = None,
    *,
    favorite: bool | None = None,
    families: str | list[str] | None = None,
    replace_emoji: bool = False,
) -> dict:
    """Update a Dock under exact ownership before its one live snapshot.

    ``local`` / ``favorite`` set (True) or unset (False) exactly ONE attribute
    each; every other attribute, every other family's tags, every
    ``--deprecated`` tag and every unrelated tag ride through byte-for-byte.
    Unsetting the LAST attribute leaves the bare base tag -- Dock identity is
    never deleted by an attribute change (I7). ``families`` names the Dock
    family (base tag, one string or a list) the attribute write targets; it is
    required when the node carries proper tags from more than one family and
    must name families actually present on the node. A ``topic`` rename
    preserves the Dock's existing leading emoji run (the caller need not pass
    an emoji; a supplied topic run wins explicitly);
    ``replace_emoji=True`` hands the run to the supplied topic wholesale
    (its run replaces the existing one; its absence clears the run).
    """

    if topic is None and description is None and local is None and favorite is None:
        raise ValueError(
            "anchor.dock.update requires topic, description, local and/or favorite."
        )
    if topic is not None and "note session" in topic.lower():
        raise ValueError(
            "topic must not contain the words 'note session'; the Dock tag supplies identity."
        )

    # ---- families: pure shape validation BEFORE any I/O (§6.6.1/§6.6.3) ----
    normalized_families: list[str] | None = None
    if families is not None:
        if local is None and favorite is None:
            raise _AnchorOperationError(
                "invalid_parameter_combination",
                "families only applies together with local and/or favorite; "
                "it selects the Dock family an ATTRIBUTE write targets.",
            )
        raw_families = [families] if isinstance(families, str) else families
        if not isinstance(raw_families, (list, tuple)) or not raw_families:
            raise _AnchorOperationError(
                "invalid_parameter_combination",
                "families must be one family base tag (string) or a non-empty "
                "list of them.",
            )
        normalized_families = []
        for entry in raw_families:
            if not isinstance(entry, str):
                raise _AnchorOperationError(
                    "invalid_parameter_combination",
                    f"families entries must be strings; got {entry!r}.",
                )
            fam = entry.strip()
            if fam.startswith("#"):
                fam = fam[1:].strip()
            if not fam:
                raise _AnchorOperationError(
                    "invalid_parameter_combination",
                    "families entries must be non-empty family base tags.",
                )
            if fam not in normalized_families:
                normalized_families.append(fam)  # de-dup, keep given order

    base_tags, _global_tags, _default_parent, reply = (
        await _resolve_note_session_config(target_tab)
    )
    postfix_kwargs = _anchor_postfix_kwargs_from_reply(reply)
    resolved = await _resolve_mutation_region_handle(
        dock_handle, label="anchor.dock.update (dock_handle)"
    )
    async with mutation_region_locks(
        client=get_client(), operation_label="anchor.dock.update",
        region_factory=lambda snapshot: (build_region_exact_node(resolved, cache_by_id=snapshot.nodes_by_id),),
    ):
        nodes_by_id = _anchor_cache_by_id()
        node = nodes_by_id.get(resolved)
        if not node:
            raise RuntimeError(
                f"Anchor Dock {resolved} is absent from the nodes-export cache; refresh and retry."
            )

        map_verdict = _classify_node_map_state(resolved, nodes_by_id)
        if map_verdict.get("state") == "folder":
            raise RuntimeError(
                "Refused: an Anchor Dock cannot be updated at/under a Cartographer FOLDER node."
            )

        # ONE-SNAPSHOT RULE (protected-name policy): the topic title, the leading
        # [ap:] handle, AND the tag list the locality transform rewrites ALL come
        # from the SAME authoritative live GET -- never a cache/live mix (a stale
        # cache tag set must not overwrite a tag the user just added in the GUI).
        # The raw GET name is decoded ONE non-cascading entity layer so the
        # re-composed name re-encodes exactly once on write.
        client = get_client()
        if _rate_limiter:
            await _rate_limiter.acquire()
        try:
            live_node = await client.get_node(resolved)
            if _rate_limiter:
                _rate_limiter.on_success()
        except Exception as e:
            if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
                _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
            raise
        current_name = _semantic_name_for_tag_merge(live_node.name or "")
        base_name, name_tags = _resolve_split_name_and_tags(current_name)
        # Anchor-hood revalidated against the LIVE tags (cache drift fails safely).
        verdict = classify_anchor_tags(
            name_tags, base_tags, **postfix_kwargs
        )
        if not verdict.get("is_anchor"):
            raise RuntimeError(f"Node {resolved} is not an Anchor Dock; refusing to update it.")

        # ---- Family selection (§6.6.3) — on the LIVE tags, before any write ----
        # present = the families that have at least one PROPER tag on the node
        # (a family present only via --deprecated is NOT "on the node").
        present = list(verdict.get("matched_bases") or ())
        targets: list[str] = []
        if local is not None or favorite is not None:
            if normalized_families is None:
                if len(present) == 1:
                    targets = [present[0]]
                else:
                    # NEVER pick base_tags[0]: two or more families on the node is
                    # a choice only the caller may make.
                    raise _AnchorOperationError(
                        "dock_families_ambiguous",
                        (
                            f"Dock carries tags from {len(present)} families "
                            f"({', '.join('#' + fam for fam in present)}); pass "
                            "families='‹one›' or families=[…] to say which to update"
                        ),
                        extra={"families_present": present},
                    )
            else:
                for fam in normalized_families:
                    if fam not in present:
                        raise _AnchorOperationError(
                            "dock_family_not_on_node",
                            (
                                f"family #{fam} has no proper Dock tag on this node; "
                                f"present: {', '.join('#' + f for f in present) or '(none)'} "
                                "(a family carried only via a --deprecated tag does not count)"
                            ),
                            extra={"requested": fam, "families_present": present},
                        )
                    targets.append(fam)

        # The NARROW dedicated tag channel: this transform is the ONLY tag rewrite
        # anchor.dock.update may perform. Per targeted family it removes ONLY that
        # family's PROPER tags and re-inserts one canonical tag per remaining
        # attribute at the first removed position (§6.6.4). Left in place,
        # untouched and in position: --deprecated tags of the family,
        # unknown-postfix tags (#F--expand), every tag of every other family,
        # every unrelated tag. The named anti-pattern -- "remove every recognised
        # form, insert one canonical tag" -- is exactly what this is NOT.
        def _attribute_transform(tags: list[str]) -> list[str]:
            working = list(tags)
            for fam in targets:
                # 1. Collect the family's PROPER tags (ALL occurrences, duplicates
                #    included): (index, attribute, postfix).
                found: list[tuple[int, str | None, str]] = []
                for idx, tag in enumerate(working):
                    m = match_anchor_tag(str(tag), fam, **postfix_kwargs)
                    if m is None or m["attribute"] == "deprecated":
                        continue
                    found.append((idx, m["attribute"], m["postfix"]))
                first_index = found[0][0] if found else None
                # existing_word[a] = the postfix of the FIRST proper tag carrying a.
                existing_word: dict[str, str] = {}
                # 2. attrs asserted by the proper tags (a bare base asserts none).
                attrs: set[str] = set()
                for _idx, attr, word in found:
                    if attr is not None:
                        attrs.add(attr)
                        existing_word.setdefault(attr, word)
                # 3. Apply the requested set/unset, ONE attribute at a time.
                if local is not None:
                    attrs = (attrs | {"local"}) if local else (attrs - {"local"})
                if favorite is not None:
                    attrs = (attrs | {"favorite"}) if favorite else (attrs - {"favorite"})
                # 4. Remove every proper tag of THIS family; everything else stays
                #    in place, untouched and in position.
                remove_idx = {idx for idx, _attr, _word in found}
                kept = [tag for idx, tag in enumerate(working) if idx not in remove_idx]
                insert_at = (
                    len(kept)
                    if first_index is None
                    else sum(
                        1 for idx in range(len(working))
                        if idx < first_index and idx not in remove_idx
                    )
                )
                # 5. Build the canonical block: bare base when no attribute
                #    remains (identity is never deleted, I7); else one tag per
                #    attribute in the FIXED order local, favorite, preserving the
                #    word already on the node and falling back to the FIRST
                #    configured word for a newly-set attribute.
                block: list[str] = []
                if not attrs:
                    block = [f"#{fam}"]
                else:
                    for attr in ("local", "favorite"):
                        if attr not in attrs:
                            continue
                        if attr in existing_word:
                            word = existing_word[attr]
                        elif attr == "local":
                            word = postfix_kwargs["local_postfixes"][0]
                        else:
                            word = postfix_kwargs["favorite_postfixes"][0]
                        block.append(f"#{fam}{POSTFIX_SEP}{word}")
                # 6. Insert the block at the first removed position (append if none).
                kept[insert_at:insert_at] = block
                working = kept
            return working

        tag_transform = (
            _attribute_transform if (local is not None or favorite is not None) else None
        )
        if topic is None and local is None and favorite is None:
            # Description-only update: the name is NOT being edited, so do NOT
            # recompose it. Recomposing would normalize the trailing region
            # (trident / presentation markup peeled, canonical tag re-join) and
            # could make name_changed True while the core is invoked with
            # name=None -- misreporting a rename that never happened.
            final_name = current_name
            final_tags = name_tags
            name_changed = False
        else:
            # The ONE protected-name composer validates the topic (supplied trailing
            # #tags or an added/changed leading [ap:] handle are loud errors) and
            # composes: preserved AP-ID + new topic + (transformed) tags. NOTE: when
            # locality is omitted, a topic rename now re-joins the trailing tag region
            # in canonical bare-token form (single-spaced, presentation markup
            # stripped) -- the SAME normalization the tag tools already apply;
            # Workflowy re-renders pill/underline styling on display.
            composed = _compose_protected_name(
                current_semantic_name=current_name,
                requested_name=topic,
                tag_transform=tag_transform,
                replace_leading_emoji=replace_emoji,
            )
            final_name = composed["name"]
            final_tags = composed["tags"]
            name_changed = final_name != current_name
        note_changed = description is not None
        if not name_changed and not note_changed:
            no_op_verdict = classify_anchor_tags(final_tags, base_tags, **postfix_kwargs)
            return {
                "success": True,
                "node_id": resolved,
                "no_op": True,
                "old_name": current_name,
                "new_name": current_name,
                "local": bool(no_op_verdict.get("is_local")),
                "favorite": bool(no_op_verdict.get("is_favorite")),
                "attributes": sorted(no_op_verdict.get("attributes") or ()),
                "families_updated": list(targets),
                "tags": final_tags,
                "warnings": [],
            }

        await _node_edit_core(
            resolved,
            name=topic if name_changed else None,
            note=description if description is not None else None,
            _tag_transform=tag_transform if name_changed else None,
            _replace_leading_emoji=replace_emoji,
            _current_node=live_node,
        )
        # §6.6.5: recompute the classifier verdict on the FINAL tags and echo it.
        final_verdict = classify_anchor_tags(final_tags, base_tags, **postfix_kwargs)
        result: dict[str, Any] = {
            "success": True,
            "node_id": resolved,
            "no_op": False,
            "old_name": current_name,
            "new_name": final_name,
            "renamed": name_changed,
            "description_updated": description is not None,
            "local": bool(final_verdict.get("is_local")),
            "favorite": bool(final_verdict.get("is_favorite")),
            "attributes": sorted(final_verdict.get("attributes") or ()),
            "families_updated": list(targets),
            "tags": final_tags,
            "warnings": [],
        }
        if map_verdict.get("state") in ("file", "inside_file"):
            warning = (
                "This Anchor Dock lives in a Cartographer-mapped Markdown subtree "
                f"({map_verdict.get('file_path')}). Run F12+3 to persist the Workflowy edit."
            )
            result["mapped_subtree_warning"] = warning
            result["warnings"].append(warning)
        return result


# @beacon[
#   id=mcp-api@anchor-dock-promote,
#   role=⚡ _anchor_dock_promote_impl(node_handle, local, target_tab, favorite),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
# ]
async def _anchor_dock_promote_impl(
    node_handle: str,
    local: bool = False,
    target_tab: str | None = None,
    *,
    favorite: bool = False,
) -> dict:
    """Promote an existing safe node into an Anchor Dock without touching children."""

    from nexus_map_codebase import split_name_and_tags  # type: ignore[import-not-found]

    base_tags, _global_tags, _default_parent, reply = (
        await _resolve_note_session_config(target_tab)
    )
    postfix_kwargs = _anchor_postfix_kwargs_from_reply(reply)
    resolved = await _resolve_generic_node_handle(
        node_handle, label="anchor.dock.promote (node_handle)"
    )
    nodes_by_id = _anchor_cache_by_id()
    node = nodes_by_id.get(resolved)
    if not node:
        raise RuntimeError(f"Node {resolved} is absent from the nodes-export cache.")
    _base, tags = split_name_and_tags(str(node.get("name") or node.get("nm") or ""))
    verdict = classify_anchor_tags(tags, base_tags, **postfix_kwargs)
    if verdict.get("is_anchor"):
        # Already a Dock → no-op EVEN IF favorite=true was passed: adding an
        # attribute to an existing Dock is dock.update's job (§6.7).
        warning = "already an Anchor Dock"
        if favorite:
            warning += "; use dock.update(favorite=true) to add an attribute"
        return {
            "success": True,
            "node_id": resolved,
            "no_op": True,
            "warnings": [warning],
        }
    map_verdict = _classify_node_map_state(resolved, nodes_by_id)
    guard_error = _anchor_target_guard_error(map_verdict)
    if guard_error:
        raise RuntimeError(guard_error)
    first_base = str((base_tags or [""])[0]).strip().lstrip("#")
    if not first_base:
        raise RuntimeError("No Anchor Dock tag is configured on the target tab.")
    # ONE tag per attribute (never stacked), local BEFORE favorite; the bare
    # base when neither attribute is requested. ONE _tag_add_impl call (it
    # accepts a list) so a failure leaves either nothing or the complete set.
    tags_to_add: list[str] = []
    if local:
        tags_to_add.append(
            f"#{first_base}{POSTFIX_SEP}{postfix_kwargs['local_postfixes'][0]}"
        )
    if favorite:
        tags_to_add.append(
            f"#{first_base}{POSTFIX_SEP}{postfix_kwargs['favorite_postfixes'][0]}"
        )
    if not tags_to_add:
        tags_to_add = [f"#{first_base}"]
    result = await _tag_add_impl(resolved, tags_to_add)
    if isinstance(result, dict):
        result.setdefault("warnings", [])
        if map_verdict.get("state") in ("file", "inside_file"):
            warning = (
                "This Anchor Dock was promoted inside a mapped Markdown subtree; "
                "run F12+3 to persist it."
            )
            result["warnings"].append(warning)
            result["mapped_subtree_warning"] = warning
    return result


# @beacon[
#   id=mcp-api@anchor-dock-demote,
#   role=⚡ _anchor_dock_demote_impl(dock_handle, target_tab),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
# ]
async def _anchor_dock_demote_impl(
    dock_handle: str,
    target_tab: str | None = None,
) -> dict:
    """Remove every recognized Dock tag while preserving the node and subtree."""

    from nexus_map_codebase import split_name_and_tags  # type: ignore[import-not-found]

    base_tags, _global_tags, _default_parent, reply = (
        await _resolve_note_session_config(target_tab)
    )
    postfix_kwargs = _anchor_postfix_kwargs_from_reply(reply)
    resolved = await _resolve_generic_node_handle(
        dock_handle, label="anchor.dock.demote (dock_handle)"
    )
    nodes_by_id = _anchor_cache_by_id()
    node = nodes_by_id.get(resolved)
    if not node:
        raise RuntimeError(f"Anchor Dock {resolved} is absent from the nodes-export cache.")
    _base, name_tags = split_name_and_tags(
        str(node.get("name") or node.get("nm") or "")
    )
    verdict = classify_anchor_tags(
        name_tags, base_tags, **postfix_kwargs
    )
    if not verdict.get("is_anchor"):
        warning = "not an Anchor Dock"
        return {
            "success": True,
            "node_id": resolved,
            "no_op": True,
            "warnings": [warning],
        }
    remove_tags: list[str] = []
    for actual in name_tags:
        body = str(actual).strip().lstrip("#")
        if any(
            match_anchor_tag(
                body,
                str(base).strip().lstrip("#"),
                **postfix_kwargs,
            )
            is not None
            for base in base_tags
        ):
            remove_tags.append(actual)
    result = await _tag_remove_impl(resolved, remove_tags)
    if isinstance(result, dict):
        result["dock_tags_removed"] = remove_tags
        result["subtree_preserved"] = True
    return result


# @beacon[
#   id=mcp-api@anchor-dock-get-description,
#   role=⚡ _anchor_dock_get_description_impl(dock_handle, target_tab),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=anchor.dock.get_description: Dock-checked preset over the ONE point metadata header. Counts direct child Docks with the same parent-key precedence and boundary predicate without a discarded size aggregate; forwards its fresh vocabulary to _anchor_point_read_impl and reads the full unguarded note. Non-Docks and no-tab reads keep their existing loud errors.
#   Forwards its one fresh vocabulary read into the shared point header; exact-view metrics are reused.,
# ]
async def _anchor_dock_get_description_impl(
    dock_handle: str,
    target_tab: str | None = None,
) -> str:
    """Return one Anchor Dock's description under the ONE metadata header.

    TODO [ap:YLHDIN] part 1 (Dan's "get description"): the cheap one-shot
    bootstrap read -- name + metadata (the ``anchor.point.read`` header,
    plus one ``child docks: N`` line) + the FULL description (the note).
    A thin Dock-checked preset over ``_anchor_point_read_impl``: the header
    is composed there and nowhere else. Direct child-Dock counting needs no
    subtree metrics; the point header computes its own displayed totals.
    """
    resolved, nodes_by_id = await _resolve_generic_node_handle_with_cache(
        dock_handle, label="anchor.dock.get_description (dock_handle)"
    )
    if not nodes_by_id or resolved not in nodes_by_id:
        raise RuntimeError(
            f"anchor.dock.get_description: node {resolved} is absent from the "
            "cached /nodes-export snapshot; call system.cache.refresh and retry."
        )
    base_tags, _global_tags, _default_parent, reply = (
        await _resolve_note_session_config(target_tab)
    )
    postfix_kwargs = _anchor_postfix_kwargs_from_reply(reply)
    node = nodes_by_id[resolved]
    from nexus_map_codebase import split_name_and_tags  # type: ignore[import-not-found]

    _base, name_tags = split_name_and_tags(
        str(node.get("name") or node.get("nm") or "")
    )
    verdict = classify_anchor_tags(name_tags, base_tags, **postfix_kwargs)
    if not verdict.get("is_anchor"):
        raise _AnchorOperationError(
            "not_an_anchor_dock",
            f"Node {resolved} is not an Anchor Dock; "
            "anchor.dock.get_description reads Docks -- use anchor.point.read "
            "for any node.",
        )
    from .f8_slice_policy import build_anchor_boundary_predicate

    boundary = build_anchor_boundary_predicate(base_tags, **postfix_kwargs)
    child_dock_count = sum(
        1
        for child in nodes_by_id.values()
        if str(child.get("parent_id") if "parent_id" in child else child.get("parentId")) == resolved
        and boundary(child)
    )
    # THE one metadata header (anchor.point.read's), with the ONE Dock-only
    # line spliced under the name/metrics line; the note rides unguarded.
    return await _anchor_point_read_impl(
        resolved,
        target_tab=target_tab,
        extra_header_lines=(f"child docks: {child_dock_count}",),
        _anchor_vocabulary=(base_tags, postfix_kwargs),
    )


# @beacon[
#   id=mcp-api@anchor-dock-peek,
#   role=⚡ _anchor_dock_peek_impl(dock_handle, target_tab, detail, show_ids, show_counts, show_description, max_chars, recursive, descend_policy, recent, recent_by, sort_by, sort_direction, include_completed),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Dock-peek read-only inventory front: existing one config read/resolver/pinned map and owned source-metrics index. Direct children remain default; recursive=true uses real node depth and stops at nested Docks unless descend_policy='all' explicitly opens them (global and local alike). Rows carry the FULL node name verbatim (trailing #tags included; title/tags split alongside), the item's own created_at/modified_at, and parent_id (UTAERZ: the walked parent, so the flat recent/timestamp compact view shows a per-row ' ← in ‹parent handle›' hint for rows whose parent is not the peeked Dock; document order keeps indentation and no hints). Row handles ([ap:0M6VP8] peek half): rows without an AP-ID show a bracketed short UUID handle in the body by default; show_ids=true adds it to every row -- both through the ONE shortener unique_short_uuid_prefix over a build_uuid_prefix_collisions index built once per call from the same pinned cache map (CF-22/O3; parent hints use the same authority, the parent's [ap:CORE] when it carries one). recent=N selects the N newest walked rows on recent_by (default modified) and sort_by/sort_direction order the whole inventory -- one pure policy (apply_dock_peek_recency) applied between the walk and BOTH renderers so compact and detail='full' select identical items; neither knob given = document order, unchanged. Completed rows are marked but HIDDEN by default on EVERY view -- recency, timestamp sort, and the plain document-order inventory alike (U6/J11; include_completed=true opts back in) -- the filter lives solely inside the policy. detail='full' additionally carries the Dock's untruncated one-line 'description'; the compact '> …' excerpt budgets it at 256 chars. Totals always cover the full subtree. No new live reads, mutation claims, cache publication, renderer or broker path.,
#   Counts topology sizes and collisions now reuse immutable exact-view indexes rather than rebuilding per call.,
# ]
async def _anchor_dock_peek_impl(
    dock_handle: str,
    target_tab: str | None = None,
    *,
    detail: str = "compact",
    show_ids: bool = False,
    show_counts: bool = True,
    show_description: bool = True,
    max_chars: int | None = None,
    recursive: bool = False,
    descend_policy: str = "stop_at_child_anchors",
    recent: int | None = None,
    recent_by: str | None = None,
    sort_by: str | None = None,
    sort_direction: str | None = None,
    include_completed: bool = False,
) -> Any:
    """Peek real node depth; nested Docks stop recursion unless policy is all.

    Direct children remain the default. Source metrics cover the full
    underlying subtree regardless of display policy. The existing one config
    read, resolver and pinned map remain the sole acquisition path.

    ``recent=N`` keeps the N newest rows by ``recent_by`` (``created`` |
    ``modified``, default ``modified`` -- the item's OWN timestamp) and
    implies ``sort_by=recent_by`` unless overridden; the presentation is
    ascending (oldest first) like every default -- ``sort_direction='desc'``
    (newest first) is an explicit opt-in, never implied.     ``sort_by`` alone
    reorders the whole inventory (same ascending default); neither given =
    document order. Completed rows are hidden by
    default on EVERY view -- they neither consume ``recent`` slots nor
    appear in a timestamp sort nor appear in the plain document-order
    inventory (U6/J11) -- unless ``include_completed=true`` lists them
    again with their ✓ marker. With ``recursive=true``
    the selection is taken from every walked row (``descend_policy``
    respected) and the output is flat in timestamp order -- ``depth`` and
    ``parent_id`` stay as data (the flat compact view shows the parent per
    row: ``← in ‹handle›``), ancestors are never injected or counted.
    """
    if not isinstance(recursive, bool):
        raise _AnchorOperationError("invalid_parameter_combination", "recursive must be a boolean")
    if descend_policy not in ("all", "stop_at_child_anchors"):
        raise _AnchorOperationError(
            "invalid_parameter_combination", "descend_policy must be 'all' or 'stop_at_child_anchors'",
        )
    detail, max_chars, view_error = _normalize_inventory_view(detail, max_chars)
    if view_error:
        code, message = view_error
        raise _AnchorOperationError(code, message)
    from .dock_peek_metrics import (
        DOCK_PEEK_RECENCY_BASES,
        DOCK_PEEK_SORT_DIRECTIONS,
        DOCK_PEEK_SORT_KEYS,
        apply_dock_peek_recency,
        node_timestamp,
    )

    if recent is not None:
        if isinstance(recent, bool) or not (
            isinstance(recent, int)
            or (isinstance(recent, float) and recent.is_integer())
        ):
            raise _AnchorOperationError(
                "invalid_parameter_type", "recent must be a positive integer (the N most recent items).",
            )
        recent = int(recent)
        if recent < 1:
            raise _AnchorOperationError(
                "invalid_parameter_combination", "recent must be >= 1 (the N most recent items).",
            )
    if recent_by is not None:
        if recent_by not in DOCK_PEEK_RECENCY_BASES:
            raise _AnchorOperationError(
                "invalid_enum_value", "recent_by must be 'created' or 'modified'.",
            )
        if recent is None:
            raise _AnchorOperationError(
                "invalid_parameter_combination",
                "recent_by only applies together with recent=N; to order the whole "
                "inventory use sort_by='created'|'modified' instead.",
            )
    if sort_by is not None and sort_by not in DOCK_PEEK_SORT_KEYS:
        raise _AnchorOperationError(
            "invalid_enum_value", "sort_by must be 'none', 'created' or 'modified'.",
        )
    if sort_direction is not None and sort_direction not in DOCK_PEEK_SORT_DIRECTIONS:
        raise _AnchorOperationError(
            "invalid_enum_value", "sort_direction must be 'asc' or 'desc'.",
        )
    if not isinstance(include_completed, bool):
        raise _AnchorOperationError(
            "invalid_parameter_type", "include_completed must be a boolean.",
        )

    from nexus_map_codebase import split_name_and_tags  # type: ignore[import-not-found]

    base_tags, _global_tags, _default_parent, reply = (
        await _resolve_note_session_config(target_tab)
    )
    postfix_kwargs = _anchor_postfix_kwargs_from_reply(reply)
    resolved = await _resolve_generic_node_handle(
        dock_handle, label="anchor.dock.peek (dock_handle)"
    )
    # Archive Reads U3 (§U3.2 D3): the §5.5 footer's scope basis.
    from .archive_context import note_archive_scope

    note_archive_scope([str(resolved)])
    nodes_by_id = _anchor_cache_by_id()
    root = nodes_by_id.get(resolved)
    if not root:
        raise RuntimeError(f"Anchor Dock {resolved} is absent from the cache.")
    _root_base, root_tags = split_name_and_tags(
        str(root.get("name") or root.get("nm") or "")
    )
    root_verdict = classify_anchor_tags(
        root_tags, base_tags, **postfix_kwargs
    )
    if not root_verdict.get("is_anchor"):
        raise RuntimeError(f"Node {resolved} is not an Anchor Dock.")

    from .dock_peek_metrics import build_dock_peek_index
    from .f8_slice_policy import _node_is_completed

    # Owned ID lists/scalars only; never annotate or sort source nodes.
    children_by_parent, metrics = build_dock_peek_index(nodes_by_id, resolved)
    rows: list[dict[str, Any]] = []
    # UTAERZ: each walked row carries its parent_id so the flat (recent /
    # timestamp) compact view can show a per-row parent hint; the JSON keeps
    # it as data on every view.
    pending = [(child_id, 0, resolved) for child_id in reversed(children_by_parent.get(resolved, ()))]
    while pending:
        child_id, depth, parent_id = pending.pop()
        child = nodes_by_id[child_id]
        raw_name = str(child.get("name") or child.get("nm") or "")
        plain_name, child_tags = split_name_and_tags(raw_name)
        child_verdict = classify_anchor_tags(
            child_tags, base_tags, **postfix_kwargs
        )
        child_metrics = metrics[child_id]
        rows.append(
            {
                "uuid": child_id,
                "parent_id": parent_id,
                "ap_id": (
                    f"[ap:{_anchor_leading_ap_core(raw_name)}]"
                    if _anchor_leading_ap_core(raw_name)
                    else None
                ),
                # WG3QTR: the FULL name verbatim, trailing #tags included.
                # title/tags are the split for callers that want it.
                "name": raw_name,
                "title": plain_name,
                "tags": [str(tag) for tag in child_tags],
                "is_dock": bool(child_verdict.get("is_anchor")),
                "is_local_dock": bool(child_verdict.get("is_local")),
                "is_favorite_dock": bool(child_verdict.get("is_favorite")),
                "has_children": child_metrics["child_count"] > 0,
                **child_metrics,
                "depth": depth,
                "completed": _node_is_completed(child),
                "created_at": node_timestamp(child, "created"),
                "modified_at": node_timestamp(child, "modified"),
            }
        )
        if recursive and (descend_policy == "all" or not child_verdict.get("is_anchor")):
            pending.extend(
                (descendant, depth + 1, child_id)
                for descendant in reversed(children_by_parent.get(child_id, ()))
            )
    # SKWSXO: ONE recency policy between the walk and BOTH renderers, so the
    # compact text and the full JSON select exactly the same items.
    # CF-MST-016 + U6/J11: the completed-exclusion for EVERY peek view
    # (recency, timestamp sort, and the plain document-order inventory)
    # lives inside that policy, the ONE place in peek where a completed
    # row can be filtered.
    rows, selection, sort = apply_dock_peek_recency(
        rows,
        recent=recent,
        recent_by=recent_by,
        sort_by=sort_by,
        sort_direction=sort_direction,
        include_completed=include_completed,
    )
    # [ap:0M6VP8] peek half + UTAERZ parent hints: one collision index over
    # the SAME pinned cache map the handles resolve against (4g's precedent:
    # built once per call beside the child counts), so a displayed short
    # handle pastes back and resolves uniquely. Parent handles are computed
    # only for the parents actually displayed (the parent's [ap:CORE] when
    # it carries one, else its short UUID).
    uuid_prefix_collisions = build_uuid_prefix_collisions(nodes_by_id)
    parent_handles: dict[str, str] = {}
    for row in rows:
        hint_parent = row.get("parent_id")
        if (
            not hint_parent
            or hint_parent == resolved
            or hint_parent in parent_handles
            or hint_parent not in nodes_by_id
        ):
            continue
        parent_node = nodes_by_id[hint_parent]
        parent_name = str(parent_node.get("name") or parent_node.get("nm") or "")
        parent_core = _anchor_leading_ap_core(parent_name)
        if parent_core:
            parent_handles[hint_parent] = f"[ap:{parent_core}]"
        else:
            parent_handles[hint_parent] = f"[{unique_short_uuid_prefix(hint_parent, uuid_prefix_collisions)}]"
    root_note = str(root.get("note") or root.get("no") or "")
    if detail == "full":
        return {
            "success": True,
            "dock_handle": resolved,
            # CF-MST-015: the compact '> …' excerpt is budgeted (256 default);
            # the full payload carries the same text untruncated.
            "description": _dock_peek_description_excerpt(root_note),
            "count": len(rows),
            "rows": rows,
            "recursive": recursive,
            "descend_policy": descend_policy,
            "root_metrics": dict(metrics[resolved]),
            "selection": selection,
            "sort": sort,
        }
    return _render_dock_peek_raw_text(
        dock_name=str(root.get("name") or root.get("nm") or ""),
        root_note=root_note,
        rows=rows,
        show_ids=bool(show_ids),
        show_counts=bool(show_counts),
        show_description=bool(show_description),
        max_chars=max_chars,
        root_metrics=metrics[resolved],
        recursive=recursive,
        descend_policy=descend_policy,
        selection=selection,
        sort=sort,
        root_uuid=resolved,
        uuid_prefix_collisions=uuid_prefix_collisions,
        parent_handles=parent_handles,
    )


def _anchor_scope_documents(
    tree: dict[str, Any],
    line_matcher: Callable[[str], list[tuple[int, int]]],
    match_scope: str,
) -> list[tuple[str, str, str] | tuple[str, str, str, str]]:
    """Preorder documents for the anchor.search grep over a scope tree.

    Every in-scope node from the ONE Stage-1 walk (root first, priority
    order) becomes a document for the ONE formatter, which selects the hits
    -- a scope grep has no node-level predicate, so selection happens in the
    formatter over these documents (node.search's own model). Under
    ``match_scope='name_and_note'`` the document carries the note plus a
    ``(title match)`` marker whenever the TITLE matches -- the formatter
    drops the marker when note lines also hit, so a title-only match still
    appears (D6). Under ``'name'`` only title-matching nodes are documents,
    each carrying NO note, so the shared formatter cannot leak note rows.
    NOT ``_sift_grep_documents``: that producer keeps exactly the nodes a
    node-level predicate already admitted; this one has no predicate to
    apply. Pure; no I/O.
    """
    documents: list[tuple[str, str, str] | tuple[str, str, str, str]] = []
    stack: list[dict[str, Any]] = [tree]
    while stack:
        node = stack.pop()
        if not isinstance(node, dict):
            continue
        stack.extend(
            reversed([child for child in (node.get("children") or []) if isinstance(child, dict)])
        )  # preorder: parents before children
        node_id = str(node.get("id") or "")
        if not node_id:
            continue
        name = str(node.get("name") or "")
        note = str(node.get("note") or "")
        title_hit = bool(line_matcher(name))
        if match_scope == "name":
            if title_hit:
                documents.append((node_id, name, "", "(title match)"))
            continue
        if title_hit:
            documents.append((node_id, name, note, "(title match)"))
        else:
            documents.append((node_id, name, note))
    return documents


# @beacon[
#   id=anchors@point-search,
#   slice_labels=nexus--anchors,node-ops,nexus--mcp-api,
#   kind=ast,
#   comment=anchor.search: a node.search-shaped grep scoped to ONE Anchor Dock's subtree. Acquisition is dock.peek's own pattern -- the ONE note-session config read (the live Dock vocabulary; loud with no tab, like dock.peek), the generic handle resolver, the pinned operation cache -- then the ONE generic Stage-1 walk build_selected_subtree_from_cache with member_all=True, the shared build_anchor_boundary_predicate (descend_policy='stop_at_child_anchors' default stops at child Docks; each child Dock's own name/note is still searched as a signpost; 'all' enters them) and exclude_completed (completed nodes hidden by default, root exempt -- node.search's own default; include_completed opts back in). Documents from _anchor_scope_documents feed the ONE shared grep tail (_note_grep_plan + _note_grep_report + note_lines.search_note_documents): query machinery identical to node.search (literal or is_regex line-local, context_lines/context_width/match_width, matched-LINE offset/max_matches paging with the all-caps banner). _note_grep_plan delegates grep values/defaults/bounds AND the [ap:O3MDOY] match controls (sort_by/sort_direction/recent/recent_by/max_nodes -- node-level: recent keeps the N newest matching nodes, hidden ones counted in the footer; max_nodes caps matching nodes) to _normalize_note_grep_params; the registry takes the ONE schema fragment _note_grep_properties + _search_match_controls_properties, shared with node.search/sift/render_search. lightning_rod.render_search's tier 'context' ([ap:2EG7TD], landed) calls both owners too. match_scope ('name_and_note' default, sift's vocabulary) picks WHAT the query reads: name_and_note = note lines plus the TITLE (a title-only match renders its header row with the D6 '(title match)' marker -- the formatter drops the marker when note lines also hit); 'name' = title rows only (the document carries no note, so the shared formatter cannot leak note rows). No second formatter, second matcher, second walk, second vocabulary reader or second ranking idiom exists.,
# ]
async def _anchor_search_impl(
    dock_handle: str,
    target_tab: str | None = None,
    *,
    query: str,
    name_filter: str | None = None,
    is_regex: bool = False,
    case_sensitive: bool = False,
    context_lines: int = 2,
    max_matches: int = 50,
    offset: int = 0,
    include_completed: bool = False,
    context_width: int | None = 160,
    match_width: int | None = 1000,
    match_scope: str = "name_and_note",
    descend_policy: str = "stop_at_child_anchors",
    sort_by: str | None = None,
    sort_direction: str | None = None,
    recent: int | str | None = None,
    recent_by: str | None = None,
    max_nodes: int | None = None,
) -> str:
    """Grep name+note lines inside one Anchor Dock's subtree.

    Scope is dock.peek's: the Dock itself and its whole subtree, descending
    stops at child Docks by default (each child Dock's own name and note are
    searched as a signpost; its descendants are not) --
    ``descend_policy='all'`` enters child Docks. The report is
    ``node.search``'s: grouped UUID/title headers, 1-based note-line
    numbers, ``>`` hit markers beside context, the width crops, the
    pagination footer, and the all-caps banner on multi-page results. A node
    whose TITLE matches but whose note has no matching line still appears,
    as its header row marked ``(title match)``. Completed nodes are hidden
    by default (the root is exempt; ``include_completed`` searches them).
    Requires a connected Workflowy tab for the Dock vocabulary -- the same
    one-read dependency as dock.peek. The query is line-local literal or
    regex -- the ONE matcher node.search uses, no smart/Boolean grammar.
    """
    from .f8_slice_policy import (
        build_anchor_boundary_predicate, build_selected_subtree_from_cache,
    )
    from nexus_map_codebase import split_name_and_tags  # type: ignore[import-not-found]

    if not isinstance(dock_handle, str) or not dock_handle.strip():
        raise _AnchorOperationError("invalid_parameter_type", "dock_handle must be a non-blank string")
    for name, value in (
        ("is_regex", is_regex), ("case_sensitive", case_sensitive),
        ("include_completed", include_completed),
    ):
        if not isinstance(value, bool):
            raise _AnchorOperationError("invalid_parameter_type", f"{name} must be a boolean")
    if match_scope not in ("name", "name_and_note"):
        raise _AnchorOperationError(
            "invalid_enum_value", "match_scope must be 'name' or 'name_and_note'",
        )
    if descend_policy not in ("all", "stop_at_child_anchors"):
        raise _AnchorOperationError(
            "invalid_parameter_combination", "descend_policy must be 'all' or 'stop_at_child_anchors'",
        )
    matches, accepts_name, controls = _note_grep_plan(
        query, is_regex=is_regex, case_sensitive=case_sensitive,
        name_filter=name_filter, context_lines=context_lines,
        max_matches=max_matches, offset=offset,
        context_width=context_width, match_width=match_width,
        sort_by=sort_by, sort_direction=sort_direction,
        recent=recent, recent_by=recent_by, max_nodes=max_nodes,
    )

    # dock.peek's own acquisition: ONE config read (the live Dock
    # vocabulary), the generic resolver, the pinned operation cache.
    base_tags, _global_tags, _default_parent, reply = (
        await _resolve_note_session_config(target_tab)
    )
    postfix_kwargs = _anchor_postfix_kwargs_from_reply(reply)
    resolved = await _resolve_generic_node_handle(
        dock_handle, label="anchor.search (dock_handle)"
    )
    # Archive Reads U3 (§U3.2 D3): the §5.5 footer's scope basis.
    from .archive_context import note_archive_scope

    note_archive_scope([str(resolved)])
    nodes_by_id = _anchor_cache_by_id()
    root = nodes_by_id.get(resolved)
    if not root:
        raise RuntimeError(f"Anchor Dock {resolved} is absent from the cache.")
    _root_base, root_tags = split_name_and_tags(
        str(root.get("name") or root.get("nm") or "")
    )
    root_verdict = classify_anchor_tags(root_tags, base_tags, **postfix_kwargs)
    if not root_verdict.get("is_anchor"):
        raise RuntimeError(f"Node {resolved} is not an Anchor Dock.")

    boundary = (
        build_anchor_boundary_predicate(base_tags, **postfix_kwargs)
        if descend_policy == "stop_at_child_anchors"
        else None
    )
    tree = build_selected_subtree_from_cache(
        nodes_by_id, resolved, lambda _node: True,
        exclude_completed=not include_completed,
        boundary_predicate=boundary,
    )
    if tree is None:
        # The root vanished from the pinned snapshot between resolution and
        # the walk; fail closed the same way the pre-walk check does.
        raise RuntimeError(f"Anchor Dock {resolved} is absent from the cache.")

    documents = _anchor_scope_documents(tree, matches, match_scope)
    if include_completed:
        source = (
            "Source: pinned operation cache (Anchor Dock subtree, including completed nodes;"
            " descending stops at child Docks -- each child Dock's own name/note is searched, its"
            " descendants are not; descend_policy='all' enters them)."
        )
    else:
        source = (
            "Source: pinned operation cache (Anchor Dock subtree; descending stops at child"
            " Docks -- each child Dock's own name/note is searched, its descendants are not"
            " (descend_policy='all' enters them); completed nodes hidden by default --"
            " include_completed=true searches them too)."
        )
    return _note_grep_report(
        matches, accepts_name, documents, context_lines=context_lines,
        max_matches=max_matches, offset=offset, header_line=source,
        context_width=context_width, match_width=match_width,
        controls=controls, nodes_by_id=nodes_by_id,
    )


# @beacon[
#   id=mcp-api@anchor-dock-render,
#   role=⚡ _anchor_dock_render_impl(dock_handle, sort_by, sort_direction, recent, headings_only, as_markdown, output_file, push_to_modal, target_tab),
#   slice_labels=nexus--mcp-api,nexus--md-preview,nexus--anchors,
#   kind=ast,
#   comment=Named Dock raw-root preset using existing root projection/modal-push paths and SinceSpec recent edge. The shared render tail hands its SAME resolved spec to the registry shaper for include_rows; this impl adds no row construction or mode. Traversal matches dock.peek names/values (render defaults recursive=True and stop_at_child_anchors); recursive=False renders Dock plus direct children via the ONE walker's max_depth=1, boundary moot; push/file behavior is unchanged.,
# ]
async def _anchor_dock_render_impl(
    dock_handle: str,
    *,
    sort_by: str | None = None,
    sort_direction: str = "asc",
    recent: str | None = None,
    # [ap:TVIIBN] 4d(a): recency basis of a 'newest' item_count selection.
    recent_by: str | None = None,
    headings_only: bool = False,
    as_markdown: bool = True,
    output_file: str | None = None,
    push_to_modal: bool = False,
    target_tab: str | None = None,
    # [ap:EPR86W] part a: the traversal pair, named and valued EXACTLY like
    # dock.peek's (the defaults differ by design: render keeps today's
    # behavior -- recursive=True, stop_at_child_anchors). recursive=False
    # renders the Dock's own heading and note plus each DIRECT child's
    # heading and note, and nothing deeper -- child Docks and plain nodes
    # alike; descend_policy is then moot, exactly as on peek.
    recursive: bool = True,
    descend_policy: str = "stop_at_child_anchors",
    # U6 (ap:E03BN3) teaching flag: default False = the rule ships (a
    # chronological dock.render -- sort_by created/modified in either direction,
    # or ANY recent selection -- a date window, 'curated', or an item-count
    # 'last N'/'newest N'/'bottom N' -- renders every non-leaf ancestor
    # heading-only, the excerpt order staying document order unless sorted);
    # True is the sole opt-out restoring ancestor note bodies.
    ancestor_notes: bool = False,
    # [ap:0M6VP8] part a: the heading-id form (short resolver-compatible
    # handle by default; full_uuids=True prints full UUIDs).
    full_uuids: bool = False,
) -> dict:
    """Dock raw-root preset; the shared tail hands its resolved spec to shaping.

    The registry's include_rows switch affects only the public shaper, never
    this projection, traversal boundary, file write or modal-push path.
    """

    resolved = await _resolve_generic_node_handle(
        dock_handle, label="anchor.dock.render (dock_handle)"
    )
    # Archive Reads U3 (§U3.2 D3): the §5.5 footer's scope basis.
    from .archive_context import note_archive_scope

    note_archive_scope([str(resolved)])
    anchor_tags, _global_tags, _default_parent, reply = (
        await _resolve_note_session_config(target_tab)
    )
    from nexus_map_codebase import split_name_and_tags  # type: ignore[import-not-found]

    root_node = _anchor_cache_by_id().get(resolved)
    if not root_node:
        raise RuntimeError(f"Anchor Dock {resolved} is absent from the nodes-export cache.")
    _base, root_tags = split_name_and_tags(
        str(root_node.get("name") or root_node.get("nm") or "")
    )
    if not classify_anchor_tags(
        root_tags,
        anchor_tags,
        **_anchor_postfix_kwargs_from_reply(reply),
    ).get("is_anchor"):
        raise RuntimeError(f"Node {resolved} is not an Anchor Dock.")
    boundary = build_anchor_boundary_predicate(
        anchor_tags,
        **_anchor_postfix_kwargs_from_reply(reply),
    ) if descend_policy == "stop_at_child_anchors" else None
    # [ap:EPR86W] part a: descend_policy takes exactly dock.peek's values
    # (the registry schema enforces the enum; the impl re-checks so direct
    # callers fail loudly too).
    if descend_policy not in ("all", "stop_at_child_anchors"):
        raise _AnchorOperationError(
            "invalid_parameter_value",
            f"Unknown descend_policy {descend_policy!r}; use "
            "'stop_at_child_anchors' (default -- emit a child Dock as a "
            "visible leaf but do not recurse into it) or 'all'.",
        )
    since_obj, since_error = _since_from_edge_result(recent)
    if since_error:
        raise ValueError(since_error)
    if push_to_modal and output_file is not None:
        raise _AnchorOperationError(
            "invalid_parameter_combination",
            "anchor.dock.render cannot combine push_to_modal with output_file.",
        )
    if push_to_modal:
        return await _glimpse_push_slice_to_modal(
            root_uuid=resolved,
            sort_by=sort_by,
            sort_direction=sort_direction,
            target_tab=target_tab,
            since=since_obj,
            recent_by=recent_by,
            match_scope="name_and_note",
            headings_only=headings_only,
            descend_policy=descend_policy,
            recursive=recursive,
            ancestor_notes=ancestor_notes,
            full_uuids=full_uuids,
        )
    return await _glimpse_root_uuid_from_cache(
        root_uuid=resolved,
        as_markdown=as_markdown,
        output_file=output_file,
        sort_by=sort_by,
        sort_direction=sort_direction,
        headings_only=headings_only,
        since=since_obj,
        recent_by=recent_by,
        boundary_predicate=boundary,
        # [ap:EPR86W] part a: the depth leg. Under recursive=False the
        # boundary predicate above is moot (the walker's depth gate stops the
        # descent at depth 1 first), exactly as on dock.peek -- passing both
        # is harmless and keeps the spec echo faithful.
        recursive=recursive,
        focus=None,
        ancestor_notes=ancestor_notes,
        full_uuids=full_uuids,
    )


# @beacon[
#   id=mcp-api@anchor-point-capture,
#   role=⚡ _anchor_point_capture_impl(parent_handle, nodes, tags, target_tab, note_file, content, name, ap_id),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Freeze the selected payload and derive literal cores before auto injection; hold child_set(resolved parent) plus explicit cores through guarded capture and tags, with same-plane subtree(new root) recursion holds and exact-node fresh-root tagging; existing AP reserve/finish order is unchanged.,
# ]
async def _anchor_point_capture_impl(
    parent_handle: str,
    nodes: list[dict] | str | None = None,
    tags: list[str] | str | None = None,
    target_tab: str | None = None,
    note_file: str | None = None,
    content: str | None = None,
    name: str | None = None,
    ap_id: str | None = None,
) -> dict:
    """Capture under C(parent)+explicit cores, with fresh recursion/tag windows."""

    from .client.api_client_etch import parse_etch_nodes_payload

    supplied = sum(value is not None for value in (nodes, note_file, content))
    if supplied != 1:
        raise _AnchorOperationError(
            "invalid_parameter_combination",
            "point.capture requires exactly one of nodes, note_file, or content.",
        )
    if nodes is not None and name is not None:
        raise _AnchorOperationError(
            "invalid_parameter_combination",
            "name is invalid with nodes because the forest carries its own names.",
        )
    if content is not None and name is None:
        raise _AnchorOperationError(
            "invalid_parameter_combination",
            "content requires name.",
        )

    payload, note_meta, content_meta, note_path_record = _prepare_anchor_capture_payload(
        nodes, note_file, content, name,
    )
    explicit_cores = _explicit_ap_cores_from_payload(payload)
    if ap_id is not None and str(ap_id).strip().lower() != "auto":
        explicit_cores = tuple(sorted({*explicit_cores, normalize_ap_core(ap_id)}))

    reserved_core: str | None = None
    if ap_id is not None:
        forest, _strategy, parse_error = parse_etch_nodes_payload(payload)
        if parse_error or not isinstance(forest, list):
            raise _AnchorOperationError(
                "invalid_parameter_combination",
                f"point.capture could not normalize the ETCH payload: {parse_error}",
            )
        if len(forest) != 1:
            raise _AnchorOperationError(
                "invalid_parameter_combination",
                "ap_id is valid only for a single-root capture.",
            )
        root = forest[0]
        existing = _anchor_leading_ap_core(
            root.get("name") if isinstance(root, dict) else ""
        )
        if existing:
            raise _AnchorOperationError(
                "invalid_parameter_combination",
                f"The capture payload already carries [ap:{existing}]; ap_id cannot replace or duplicate it.",
            )
        nodes_by_id = _anchor_cache_by_id()
        reserved_core = await _anchor_reserve_ap_core(
            str(ap_id), nodes_by_id=nodes_by_id
        )
        if not isinstance(root, dict):
            await _anchor_finish_ap_reservation(reserved_core, committed=False)
            raise _AnchorOperationError(
                "invalid_parameter_combination",
                "The single capture root must be an object with a name.",
            )
        root = dict(root)
        root["name"] = f"[ap:{reserved_core}] {str(root.get('name') or '').strip()}".rstrip()
        payload = [root]

    if isinstance(tags, str):
        tags = [tags]
    want_tags = [str(tag) for tag in (tags or []) if str(tag or "").strip()]
    auto_expand_postfix: str | None = None
    postfix_words: list[str] | None = None
    try:
        if want_tags:
            _groups, _active, postfixes, _never, _raw = (
                await _resolve_slice_group_config(target_tab)
            )
            auto_expand_postfix = postfixes.get("auto_expand") or "expand"
            postfix_words = [
                word
                for word in (
                    postfixes.get("auto_expand"),
                    postfixes.get("suppress"),
                    postfixes.get("deprecated"),
                )
                if word
            ]
    except Exception:
        if reserved_core is not None:
            await _anchor_finish_ap_reservation(reserved_core, committed=False)
        raise

    committed = False
    try:
        client = get_client()
        resolved_parent = await _resolve_mutation_region_handle(
            parent_handle, label="anchor.point.capture (parent_handle)", role="parent",
        )
        async with mutation_region_locks(
            client=client, operation_label="anchor.point.capture",
            region_factory=lambda snapshot: (
                *_mutation_parent_regions(resolved_parent, snapshot=snapshot),
                *(build_region_ap_core(core) for core in explicit_cores),
            ),
        ):
            result = await client.add_to_anchor(
                parent_uuid=resolved_parent,
                nodes=payload,
                tags=want_tags,
                auto_expand_postfix=auto_expand_postfix,
                postfix_words=postfix_words,
                fresh_root_hold=lambda root: mutation_region_locks(
                    client=client, operation_label="anchor.point.capture:fresh-root",
                    region_factory=lambda snapshot: (build_region_subtree(root, cache_by_id=snapshot.nodes_by_id),),
                ),
            )
            if isinstance(result, dict) and note_meta is not None:
                result.setdefault("_source", {})["note_file"] = note_meta
            if isinstance(result, dict) and content_meta is not None:
                result.setdefault("_source", {})["content"] = content_meta
            if isinstance(result, dict) and note_path_record is not None:
                result["path_record"] = note_path_record
            committed = bool(isinstance(result, dict) and result.get("success"))
            if reserved_core is not None and isinstance(result, dict):
                root_ids = list(result.get("root_node_ids") or [])
                result["ap_id"] = f"[ap:{reserved_core}]"
                result["uuid"] = root_ids[0] if root_ids else None
            return result
    finally:
        if reserved_core is not None:
            await _anchor_finish_ap_reservation(
                reserved_core, committed=committed
            )


# @beacon[
#   id=mcp-api@anchor-point-extract,
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Hold exact(source), destination child_set and explicit cores before one original basis read; acknowledged captures precede the checked injected-basis source rewrite. A detected collision preserves every capture and typed recovery ledger, distinguishing an unsent rewrite from an already-sent one.,
# ]
async def _anchor_point_extract_impl(
    node_handle: str, parent_handle: str, *,
    start_line: int | None = None, end_line: int | None = None,
    name: str | None = None, ranges: list[dict] | None = None,
    ap_id: str | None = "auto", tags: list[str] | str | None = None,
    target_tab: str | None = None,
) -> dict[str, Any]:
    """Hold source/destination/cores; retain captures and typed source-conflict recovery.

    Range identities are 1-based inclusive against ONE fresh source note.
    Capture verification is the capture authority's explicit success flag plus
    one created root ID, not truthiness of a result dict. HTTP verification,
    pacing, encoding, cache publication and AP-ID reservations stay downstream.
    This is not a transaction: concurrent GUI edits are not CAS-protected.
    """
    from .note_lines import normalize_extract_ranges, plan_note_extraction

    batch, normalized = normalize_extract_ranges(
        start_line=start_line, end_line=end_line, name=name, ranges=ranges, ap_id=ap_id,
    )
    resolved_source = await _resolve_mutation_region_handle(
        node_handle, label="anchor.point.extract (node_handle)",
    )
    resolved_parent = await _resolve_mutation_region_handle(
        parent_handle, label="anchor.point.extract (parent_handle)", role="parent",
    )
    explicit_cores = set(_explicit_ap_cores_from_payload([{"name": item["name"]} for item in normalized]))
    explicit_cores.update(
        normalize_ap_core(item["ap_id"]) for item in normalized
        if item["ap_id"] is not None and str(item["ap_id"]).strip().lower() != "auto"
    )
    explicit_cores = tuple(sorted(explicit_cores))
    async with mutation_region_locks(
        client=get_client(), operation_label="anchor.point.extract",
        region_factory=lambda snapshot: (
            build_region_exact_node(resolved_source, cache_by_id=snapshot.nodes_by_id),
            *_mutation_parent_regions(resolved_parent, snapshot=snapshot),
            *(build_region_ap_core(core) for core in explicit_cores),
        ),
    ):
        # This already uses the generic UUID/prefix/AP-ID resolver and ONE live GET.
        current = await _node_read_impl(resolved_source, as_raw_node=False)
        source_id = str(current.id)
        planned, replacement, counts = plan_note_extraction(
            _note_wire_to_semantic(current.note or ""), normalized,
        )
        rows = [
            {
                "name": item["name"], "start_line": item["start_line"], "end_line": item["end_line"],
                "line_count": item["line_count"], "char_count": item["char_count"],
                "requested_ap_id": item["ap_id"], "uuid": None, "ap_id": None,
                "status": "not_attempted",
            }
            for item in planned
        ]
        warnings: list[Any] = []
        verified_ids: set[str] = set()

        def failure(phase: str, cause: Any, *, exception: Exception | None = None) -> dict:
            # A failed POST/readback is NOT proof that the POST didn't commit.
            # Never tell an agent to blindly replay the original line deletion.
            untouched = phase == "capture"
            recovery = (
                "The source note was not written by extraction. Inspect the destination "
                "parent and the per-range ledger before retrying: captures may already "
                "exist (including a failed capture whose transport outcome is unknown). "
                "Keep them and re-read before removing source text with node.edit, or "
                "complete unwanted new points. Do not blindly repeat the batch."
                if untouched else
                "All captures were acknowledged before the source update, but its outcome "
                "is unknown (an update can commit before readback fails). Use node.read "
                "on the source and inspect the created points before any retry or cleanup. "
                "Never repeat the original line deletion without re-reading."
            )
            source = {
                "uuid": source_id, "lines_before": counts["lines_before"],
                "lines_after": counts["lines_before"] if untouched else None,
                "deleted_line_count": 0 if untouched else None,
                "note_state": "not_written_by_extract" if untouched else "unknown",
                "planned_deleted_line_count": counts["deleted_line_count"],
            }
            if isinstance(exception, ConcurrentEditDetectedError):
                no_send = exception.detected_at == "preflight" and exception.previously_sent is None
                recovery = (
                    "The source rewrite was not sent for this attempt; the source changed. "
                    if no_send else
                    "The source rewrite was sent, or an earlier attempt may have sent it; the observed source differs. "
                ) + (
                    "All captures were acknowledged and remain in place. Inspect the created points, "
                    "re-read the source and recompute before retrying; never replay the original line numbers."
                )
                source.update(lines_after=None, deleted_line_count=0 if no_send else None,
                              note_state="not_written_by_extract" if no_send else "unknown")
            ledger = {
                "source": source, "parent_handle": parent_handle,
                "extracted": rows if batch else rows[0], "warnings": warnings,
                "partial_failure": {"phase": phase, "ranges": rows, "cause": cause, "recovery": recovery},
            }
            spec = ANCHOR_REGISTRY.resolve("point.extract")
            # Reuse the ONE mapper: a mid-operation hard-barrier refusal retains
            # its universal code/recovery metadata, with the partial ledger added.
            mapped = _mcp_exception_mapper(spec, exception) if exception is not None else None
            if mapped is not None:
                mapped["error"].setdefault("extra", {})["extraction"] = ledger
                return mapped
            return make_error(
                family="anchor", operation="anchor.point.extract",
                code="partial_failure_source_unchanged" if untouched else "partial_failure_source_unknown",
                message=recovery, extra=ledger, operation_spec=spec,
            )

        for item, row in zip(planned, rows):
            try:
                result = await _anchor_point_capture_impl(
                    resolved_parent, content=item["content"], name=item["name"],
                    ap_id=item["ap_id"], tags=tags, target_tab=target_tab,
                )
            except Exception as exc:
                row["status"] = "capture_outcome_unknown"
                cause = {"exception_type": type(exc).__name__, "message": str(exc)}
                if isinstance(exc, _AnchorOperationError):
                    cause.update(code=exc.code, extra=exc.extra)
                row["capture_error"] = cause
                return failure("capture", cause, exception=exc)
            # Retain the capture authority's full result (including warnings/tags)
            # even on failure; never launder success:false through a mutation ack.
            row["capture_result"] = result
            roots = result.get("root_node_ids") if isinstance(result, dict) else None
            root_id = roots[0] if isinstance(roots, (list, tuple)) and len(roots) == 1 else None
            if isinstance(result, dict):
                row["ap_id"] = result.get("ap_id")
                warnings.extend(_anchor_result_warnings(result))
            if isinstance(root_id, str) and root_id.strip():
                row["uuid"] = root_id
            valid = (
                isinstance(result, dict) and result.get("success") is True
                and isinstance(root_id, str) and bool(root_id.strip())
                and root_id != source_id and root_id not in verified_ids
                and (result.get("uuid") is None or result.get("uuid") == root_id)
            )
            if not valid:
                row["status"] = "capture_unverified"
                return failure("capture", result)
            row["status"] = "created_verified"
            verified_ids.add(root_id)

        # The sole deletion gate: EVERY capture above was acknowledged. Exact
        # whole-note replacement through the existing core; no direct client/cache
        # write or second basis read. UPDATE owns final/read-back checks; the
        # core retains encoding/redaction and the original pre-capture basis.
        try:
            edited = await _node_edit_core(source_id, note=replacement, _current_node=current)
            if not isinstance(edited, WorkFlowyNode) or str(edited.id) != source_id:
                raise RuntimeError("Source edit did not return the expected node acknowledgement")
        except Exception as exc:
            return failure(
                "source_update", {"exception_type": type(exc).__name__, "message": str(exc)},
                exception=exc,
            )
        return {
            "success": True, "operation": "anchor.point.extract", "changed": True,
            "extracted": rows if batch else rows[0],
            "source": {"uuid": source_id, **counts},
            "partial_failure": None, "warnings": warnings,
        }


# @beacon[
#   id=mcp-api@anchor-point-assign-id,
#   role=⚡ _anchor_point_assign_id_impl(node_handle, ap_id),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Hold exact(target) and an explicitly requested AP core before live read; auto allocation adds no core region and existing reserve/finish order stays inside the hold; the covered edit preserves title and tags through the narrow assignment channel.,
# ]
async def _anchor_point_assign_id_impl(
    node_handle: str,
    ap_id: str = "auto",
) -> dict:
    """Assign under E(target)+explicit A(core), leaving auto reservation unchanged."""

    resolved = await _resolve_mutation_region_handle(
        node_handle, label="anchor.point.assign_id (node_handle)"
    )
    explicit_core = normalize_ap_core(ap_id) if str(ap_id).strip().lower() != "auto" else None
    async with mutation_region_locks(
        client=get_client(), operation_label="anchor.point.assign_id",
        region_factory=lambda snapshot: (
            build_region_exact_node(resolved, cache_by_id=snapshot.nodes_by_id),
            *((build_region_ap_core(explicit_core),) if explicit_core is not None else ()),
        ),
    ):
        node = await _node_read_impl(resolved, as_raw_node=False)
        current_name = str(getattr(node, "name", "") or "")
        existing = _anchor_leading_ap_core(current_name)
        if existing:
            raise _AnchorOperationError(
                "ap_id_exists",
                f"Node {resolved} already carries [ap:{existing}]; refusing to replace it.",
            )
        core = await _anchor_reserve_ap_core(
            ap_id, nodes_by_id=_anchor_cache_by_id()
        )
        committed = False
        try:
            # The NARROW dedicated AP channel: the reserved core is assigned by the
            # shared edit core through _compose_protected_name's assign leg -- the
            # existing title and trailing tags are preserved automatically (and
            # the wire-form name is decoded one entity layer first). This is NOT
            # a generic infrastructure bypass: the channel can only ADD the one
            # reserved core to an AP-less node.
            new_name = _compose_protected_name(
                current_semantic_name=_semantic_name_for_tag_merge(current_name),
                assign_ap_core=core,
            )["name"]
            await _node_edit_core(resolved, _assign_ap_core=core, _current_node=node)
            committed = True
            return {
                "success": True,
                "node_id": resolved,
                "uuid": resolved,
                "ap_id": f"[ap:{core}]",
                "old_name": current_name,
                "new_name": new_name,
            }
        finally:
            await _anchor_finish_ap_reservation(core, committed=committed)


# @beacon[
#   id=mcp-api@anchor-point-remove-id,
#   role=⚡ _anchor_point_remove_id_impl(node_handle),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Exact-node ownership spans AP-handle resolution's subsequent one live read and covered _remove_ap_id edit; preserve title decoration tags and entity semantics, keep AP-less no-op and citation warning, and never release the removed core for immediate reuse.,
# ]
async def _anchor_point_remove_id_impl(node_handle: str) -> dict:
    """Remove one leading AP-ID under exact-node ownership before live read.

    Removal invalidates existing citations to the AP-ID. The operation is
    idempotent: an AP-less node returns ``no_op=True`` without an API write.
    """

    resolved = await _resolve_mutation_region_handle(
        node_handle, label="anchor.point.remove_id (node_handle)"
    )
    async with mutation_region_locks(
        client=get_client(), operation_label="anchor.point.remove_id",
        region_factory=lambda snapshot: (build_region_exact_node(resolved, cache_by_id=snapshot.nodes_by_id),),
    ):
        # A live structured read is authoritative and also allows the caller to
        # target the node BY the AP-ID being removed: resolution completes first,
        # then this exact node snapshot is injected into the shared edit core.
        node = await _node_read_impl(resolved, as_raw_node=False)
        current_name = str(getattr(node, "name", "") or "")
        existing = _anchor_leading_ap_core(current_name)
        if existing is None:
            return {
                "success": True,
                "node_id": resolved,
                "uuid": resolved,
                "no_op": True,
                "removed_ap_id": None,
                "old_name": current_name,
                "new_name": current_name,
                "warnings": [],
            }

        current_semantic_name = _semantic_name_for_tag_merge(current_name)
        composed = _compose_protected_name(
            current_semantic_name=current_semantic_name,
            remove_ap_id=True,
        )
        await _node_edit_core(
            resolved,
            _remove_ap_id=True,
            _current_node=node,
        )
        removed = f"[ap:{existing}]"
        warning = (
            f"Removed {removed}. Existing citations or stored references to this "
            "AP-ID will no longer resolve to this node."
        )
        # Tombstone the removed core in the process-local allocation ledger even
        # when it predated this process. Otherwise an immediate explicit
        # assign_id of the same core to another node could silently retarget old
        # citations. (The ledger is process-local; the public warning remains the
        # durable statement that removal invalidates citation stability.)
        _ANCHOR_AP_ID_ALLOCATED_CORES.add(existing)
        return {
            "success": True,
            "node_id": resolved,
            "uuid": resolved,
            "no_op": False,
            "removed_ap_id": removed,
            "old_name": current_name,
            "new_name": composed["name"],
            "warnings": [warning],
        }


# @beacon[
#   id=mcp-api@anchor-point-resolve,
#   role=⚡ _anchor_point_resolve_impl(ap_id),
#   slice_labels=nexus--mcp-api,nexus--anchors,handle-resolution,
#   kind=ast,
#   comment=anchor.point.resolve: the AP-ID-first identity resolve ([ap:CZ95R6]) through the ONE shared resolve_node_identity_record (prefer='anchor_point': the AP leg runs first, the UUID leg only on unresolved fall-through, so a UUID / 8-hex handle resolves here too and a bare base36 core that is also hex stays AP-domain first). Established 0/1/N shape preserved for the live consumers (success/match_count/candidates/resolved_ap_id), now with the unified identifier vocabulary {short, uuid, ap_id} at the top level on a unique match and per candidate row ('no anchor point available' when a node carries none). Never needed before an ordinary call: every handle parameter accepts an AP-ID directly.,
# ]
async def _anchor_point_resolve_impl(ap_id: str) -> dict:
    """Resolve an AP-ID — or a UUID / its 8-hex segment — to the unified identity record."""

    from .client.api_client_nexus import resolve_node_identity_record

    return await resolve_node_identity_record(
        str(ap_id or ""),
        prefer="anchor_point",
        nodes_by_id=_anchor_cache_by_id(),
    )


# @beacon[
#   id=mcp-api@anchor-point-read,
#   role=⚡ _anchor_point_read_impl(node_handle, offset, limit, with_line_numbers, view, target_tab, extra_header_lines),
#   slice_labels=nexus--mcp-api,nexus--anchors,node-ops,
#   kind=ast,
#   comment=anchor.point.read: the shared live note decoder and guard with numbered rows and one metadata header. Walks the ancestor chain for the path but composes metrics only at the target whose totals are displayed. Peek markers dates handle windows defaults and visible no-tab degradation stay unchanged; extra_header_lines and injected fresh Dock vocabulary serve get_description through this same composer.,
#   The Dock getter injects its fresh vocabulary; standalone reads still acquire settings on every call.,
# ]
async def _anchor_point_read_impl(
    node_handle: str,
    *,
    offset: int | None = None,
    limit: int | None = None,
    with_line_numbers: bool = True,
    view: SnippetViewOptions | None = None,
    target_tab: str | None = None,
    extra_header_lines: tuple[str, ...] | None = None,
    _anchor_vocabulary: tuple[list[str], dict[str, list[str]]] | None = None,
) -> str:
    """Read one Anchor Point (any node) with its metadata header.

    The Anchor-family read: the same guard, flag set and live decoder as
    ``node.read`` (one shared implementation), a numbered-rows default, and
    a metadata header answering *what is this and where is it* from the
    pinned operation cache before the live note body.

    ``extra_header_lines`` (internal channel, anchor.dock.get_description
    only) splices additional lines directly under the header's first
    (name + metrics) line — the ONE header composer serves both verbs.
    The Dock getter supplies its already-read vocabulary; standalone reads
    still probe the tab and acquire fresh vocabulary on every invocation.
    The full chain supplies path names; only the target row needs source sizes.
    """
    offset = validate_note_read_lines(offset, limit, with_line_numbers)
    windowed = offset > 0 or limit is not None

    # Resolution AND metadata weld to the SAME pinned operation snapshot (the
    # resolver echoes the map it actually used) — the _node_ancestors pattern.
    resolved, nodes_by_id = await _resolve_generic_node_handle_with_cache(
        node_handle, label="anchor.point.read (node_handle)"
    )
    if not nodes_by_id or resolved not in nodes_by_id:
        raise RuntimeError(
            f"anchor.point.read: node {resolved} is absent from the cached "
            "/nodes-export snapshot; call system.cache.refresh and retry."
        )

    # Dock-marker vocabulary: probe for a live peer WITHOUT the grace wait (a
    # tab-less read must not stall), then the ONE established Direction-A
    # config read. Any failure degrades visibly — the read itself never
    # refuses (Dan, 2026-10-01); ✓ and the mapped markers need no tab.
    anchor_base_tags: list[str] | None = None
    anchor_postfix_kwargs: dict[str, list[str]] | None = None
    markers_note: str | None = None
    ws_conn, ws_queue = get_ws_connection()
    if not (ws_conn and ws_queue):
        markers_note = "dock markers unavailable: no Workflowy tab connected"
    elif _anchor_vocabulary is not None:
        anchor_base_tags, anchor_postfix_kwargs = _anchor_vocabulary
    else:
        try:
            base_tags, _global_tags, _default_parent, settings_reply = (
                await _resolve_note_session_config(target_tab)
            )
            anchor_base_tags = list(base_tags)
            anchor_postfix_kwargs = _anchor_postfix_kwargs_from_reply(settings_reply)
        except Exception as exc:  # noqa: BLE001 -- degrade, never refuse the read
            markers_note = (
                "dock markers unavailable"
                f" ({exc.__class__.__name__}): no Workflowy tab connected"
            )

    from .ancestor_path import build_ancestor_path_document, walk_ancestor_chain
    from .dock_peek_metrics import format_dock_peek_metrics, node_timestamp

    chain = walk_ancestor_chain(resolved, nodes_by_id)
    document = build_ancestor_path_document(
        chain[-1:],
        nodes_by_id,
        target_uuid=resolved,
        uuids="none",
        markers=True,
        metrics=True,
        anchor_base_tags=anchor_base_tags,
        anchor_postfix_kwargs=anchor_postfix_kwargs,
    )
    row = document["path"][-1]
    source_node = nodes_by_id[resolved]

    suffix = ""
    if row["is_dock"]:
        suffix += " ⚓"
        if row["is_favorite_dock"]:
            suffix += " ⭐"
    if row["is_local_dock"]:
        suffix += " Ⓛ"
    if row["completed"]:
        suffix += " ✓"
    if row["map_state"] == "folder":
        suffix += " 🗺️"
    elif row["map_state"] == "file":
        suffix += " 📄"
    created = node_timestamp(source_node, "created")
    modified = node_timestamp(source_node, "modified")
    header_lines = [
        str(row["name"]) + suffix + format_dock_peek_metrics(row["metrics"]),
        (
            f"created {created if created is not None else '-'}"
            f" · modified {modified if modified is not None else '-'}"
            f" · {resolved[:8]}"
        ),
        (
            "path: " + " › ".join(entry["name"] for entry in chain[:-1])
            if len(chain) > 1
            else "path: (document root)"
        ),
    ]
    if extra_header_lines:
        # anchor.dock.get_description's Dock-only lines sit directly under the
        # name/metrics line — Dock metadata belongs beside the source metrics.
        header_lines[1:1] = list(extra_header_lines)
    if markers_note:
        header_lines.append(markers_note)
    header = "\n".join(header_lines)

    # Both fronts call the same fetch/decode and pure body renderer; only
    # this metadata header replaces node.read's name banner.
    _node, note = await _read_live_node_note(resolved)
    body = render_note_body(note, offset, limit, with_line_numbers, view, windowed)
    return header + "\n\n" + body


# Seconds to wait before the ONE re-touch when a touch does not land in a
# strictly later server second than the previous one (timestamps are whole
# seconds; the write governor spaces POSTs ~1 s apart, so ties are rare).
# Module attribute so tests can shorten it; the sleeper is likewise a module
# attribute so tests can observe it without real waiting.
_ANCHOR_TOUCH_TIE_SLEEP_SECONDS = 1.1
_anchor_touch_sleep = asyncio.sleep


def _touch_content_fingerprint(node: Any) -> dict[str, Any]:
    """Preserve content using the shared wire projection, plus structural fields.

    Harmless name/note presentation cannot defeat a successful N02 check;
    position, completion and layout preservation keep their existing authority.
    """
    data = getattr(node, "data", None)
    return {
        "name": _canonical_update_value("name", getattr(node, "name", None)),
        "note": _canonical_update_value("note", getattr(node, "note", None)),
        "parent_id": getattr(node, "parent_id", None),
        "priority": getattr(node, "priority", None),
        "completedAt": getattr(node, "completedAt", None),
        "layoutMode": data.get("layoutMode") if isinstance(data, dict) else None,
    }


def _touch_order_ok(
    before_ts: int | None, after_ts: int | None, last_after: int | None
) -> bool:
    """Pure: did this touch land strictly later than both its own pre-write
    timestamp and the previously touched item (the one that must display
    BELOW it in a newest-modified-first view)?"""
    if not isinstance(after_ts, int):
        return False
    if isinstance(before_ts, int) and after_ts <= before_ts:
        return False
    if isinstance(last_after, int) and after_ts <= last_after:
        return False
    return True


# @beacon[
#   id=mcp-api@anchor-point-touch,
#   role=⚡ _anchor_point_touch_impl(handles, allow_docks, target_tab),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Reverse-order touches retain per-item ownership and original live bases; name echoes compare final/returned text while layout echoes do not. Known no-send collisions continue per item, sent or tie-stage collisions stop with a typed full ledger, and no conflict reaches another tie re-touch.,
# ]
async def _anchor_point_touch_impl(
    handles: list[str],
    *,
    allow_docks: bool = False,
    target_tab: str | None = None,
) -> dict[str, Any]:
    """Touch in reverse order; preserve typed no-send/sent collisions without re-touch.

    Returns the complete ledger (one row per input handle, input order) or,
    for a mid-batch typed coherence refusal, the universal error envelope
    with the partial ledger under ``error.extra.touch``. Batch-level input
    refusals raise :class:`_AnchorOperationError` (zero writes).
    """
    import time as _time

    from .coherence.errors import CoherenceBarrierActiveError

    # ---- Input validation (batch REFUSE: zero writes) -----------------------
    if not isinstance(allow_docks, bool):
        raise _AnchorOperationError("invalid_parameter_type", "allow_docks must be a boolean.")
    if not isinstance(handles, list):
        raise _AnchorOperationError(
            "invalid_parameter_type",
            "handles must be an ordered list of node handles (UUID / unique prefix / [ap:CORE]).",
        )
    if not handles:
        raise _AnchorOperationError(
            "invalid_parameter_value",
            "handles must contain at least one handle; the first handle is the highest priority "
            "(newest modified afterwards).",
        )
    cleaned: list[str] = []
    for index, raw in enumerate(handles):
        if not isinstance(raw, str) or not raw.strip():
            raise _AnchorOperationError(
                "invalid_parameter_type",
                f"handles[{index}] must be a non-empty string handle; got {raw!r}.",
            )
        cleaned.append(raw.strip())
    seen_literal: dict[str, int] = {}
    literal_duplicates: list[str] = []
    for value in cleaned:
        key = value.lower()
        seen_literal[key] = seen_literal.get(key, 0) + 1
        if seen_literal[key] == 2:
            literal_duplicates.append(value)
    if literal_duplicates:
        raise _AnchorOperationError(
            "duplicate_handles",
            "handles must not repeat: a node can hold only one position in the order. "
            f"Duplicated: {literal_duplicates}. No write was made.",
            extra={"duplicates": literal_duplicates},
        )

    # ---- Ledger scaffolding (one row per input handle, INPUT order) --------
    rows: list[dict[str, Any]] = [
        {
            "handle": handle,
            "uuid": None,
            "ap_id": None,
            "name": None,
            "status": "not_run",
            "modified_before": None,
            "modified_after": None,
            "reason": None,
        }
        for handle in cleaned
    ]
    warnings: list[str] = []

    # ---- Preflight A: resolve every handle (per-item SKIP on failure) -------
    from .archive_context import ArchivedNodeReadOnlyError

    nodes_by_id = _anchor_cache_by_id()
    uuid_owner: dict[str, int] = {}
    for index, row in enumerate(rows):
        try:
            resolved = await _resolve_generic_node_handle(
                row["handle"], label=f"anchor.point.touch (handles[{index}])"
            )
        except ArchivedNodeReadOnlyError as exc:
            # Archive Reads U2 (§5.2.4): an archived item is a SKIPPED row
            # with the §5.2.1 story; the batch continues in order.
            row["status"] = "skipped"
            row["reason"] = "archived_node"
            row["detail"] = str(exc)
            row["archive"] = dict(exc.extra or {})
            continue
        except RuntimeError as exc:
            row["status"] = "skipped"
            row["reason"] = "unresolvable_handle"
            row["detail"] = str(exc)
            continue
        row["uuid"] = str(resolved)
        if row["uuid"] in uuid_owner:
            first = uuid_owner[row["uuid"]]
            raise _AnchorOperationError(
                "duplicate_handles",
                f"handles[{first}] ({rows[first]['handle']!r}) and handles[{index}] "
                f"({row['handle']!r}) resolve to the same node {row['uuid']}; a node can hold "
                "only one position in the order. No write was made.",
                extra={"uuid": row["uuid"], "handles": [rows[first]["handle"], row["handle"]]},
            )
        uuid_owner[row["uuid"]] = index

    # ---- Preflight B: safe scope from the pinned cache (per-item SKIP) ------
    from nexus_map_codebase import split_name_and_tags  # type: ignore[import-not-found]

    anchor_vocabulary: tuple[list[str], list[str]] | None = None
    for row in rows:
        if row["uuid"] is None:
            continue
        cached = nodes_by_id.get(row["uuid"])
        if cached is None:
            row["status"] = "skipped"
            row["reason"] = "not_in_cache"
            row["detail"] = (
                "absent from the local /nodes-export snapshot, so its map state and Dock "
                "status cannot be classified; system.cache.refresh once and retry."
            )
            continue
        cached_name = str(cached.get("name") or cached.get("nm") or "")
        row["name"] = _semantic_name_for_tag_merge(cached_name)
        core = _anchor_leading_ap_core(cached_name)
        row["ap_id"] = f"[ap:{core}]" if core else None
        verdict = _classify_node_map_state(row["uuid"], nodes_by_id)
        if verdict.get("state") != "unmapped":
            row["status"] = "skipped"
            row["reason"] = "mapped_node_refused"
            row["detail"] = (
                f"Cartographer-mapped material (state={verdict.get('state')}, "
                f"path={verdict.get('path_value')!r}); disk is truth and mapped "
                "modifiedAt has other consumers -- touch is refused there."
            )
            continue
        if not allow_docks:
            if anchor_vocabulary is None:
                anchor_vocabulary = await _read_anchor_dock_vocabulary(target_tab)
            base_tags, postfix_kwargs = anchor_vocabulary
            _plain, name_tags = split_name_and_tags(cached_name)
            dock_verdict = classify_anchor_tags(
                name_tags, base_tags, **postfix_kwargs
            )
            if dock_verdict.get("is_anchor"):
                row["status"] = "skipped"
                row["reason"] = "anchor_dock_refused"
                row["detail"] = (
                    "the node is an Anchor Dock root (matched "
                    f"#{dock_verdict.get('matched_tag')}); touch its Points instead, or pass "
                    "allow_docks=true to touch the Dock itself."
                )
                continue
        row["status"] = "eligible"

    # ---- Execution: REVERSE input order, one governed write per item -------
    started = _time.monotonic()
    last_after: int | None = None
    stopped = False
    stop_reason: str | None = None
    mapped_refusal: dict[str, Any] | None = None

    def _finish() -> dict[str, Any]:
        for row in rows:
            if row["status"] == "eligible":
                row["status"] = "not_run"
                row["reason"] = row.get("reason") or "batch_stopped"
        touched = [r for r in rows if r["status"] == "touched"]
        counts = {
            "requested": len(rows),
            "touched": len(touched),
            "skipped": sum(1 for r in rows if r["status"] == "skipped"),
            "failed": sum(1 for r in rows if r["status"] == "failed"),
            "not_run": sum(1 for r in rows if r["status"] == "not_run"),
        }
        order_established = bool(touched) and all(
            r.get("order_verified") is True for r in touched
        )
        success = counts["touched"] == counts["requested"] and counts["requested"] > 0
        any_fail = counts["skipped"] + counts["failed"] + counts["not_run"] > 0
        if touched and not order_established:
            warnings.append(
                "The stored timestamps could not establish a strict order for every touched "
                "item (see rows with order_verified=false); all touched items are at the top, "
                "but their relative order among tied rows is not guaranteed."
            )
        if stopped:
            warnings.append(
                f"Batch STOPPED ({stop_reason}); rows marked not_run were never written. "
                "Because touches run in reverse input order, the not_run rows are the "
                "HIGHER-priority handles -- re-read live state before re-running."
            )
        return {
            "success": success,
            "operation": "anchor.point.touch",
            "changed": bool(touched),
            "partial_success": bool(touched) and any_fail and success is False,
            "order_convention": "handles[0] = highest priority = newest modified afterwards",
            "established_order": [r["uuid"] for r in touched],
            "results": rows,
            "summary": {
                **counts,
                "order_established": order_established,
                "stopped": stopped,
                "stop_reason": stop_reason,
                "elapsed_seconds": round(_time.monotonic() - started, 3),
                "writes": sum(int(r.get("writes") or 0) for r in rows),
            },
            "warnings": warnings,
        }

    async def _one_touch(row: dict[str, Any], current: Any) -> Any:
        row["writes"] = int(row.get("writes") or 0) + 1
        return await _node_edit_core(row["uuid"], _touch=True, _current_node=current)

    for row in reversed(rows):
        if row["status"] != "eligible":
            continue
        # U01 §6.3 seam: {node} per item — after that item's resolution
        # (preflight A), BEFORE its live GET; the core's _touch-channel
        # acquisition no-ops (§6.5). §6.7: this item's waits ride its row.
        wait_mark = _mutation_wait_mark()
        try:
            async with mutation_region_locks(
                client=get_client(), operation_label="anchor.point.touch:item",
                region_factory=lambda snapshot: (build_region_exact_node(row["uuid"], cache_by_id=snapshot.nodes_by_id),),
            ):
                # Live GET: authoritative pre-write snapshot (timestamp + mechanism +
                # the preservation fingerprint). Injected into the write so the touch
                # costs ONE governed POST plus UPDATE's final preflight and
                # existing post-write GET (layout-only echoes omit preflight).
                try:
                    before = await _node_read_impl(row["uuid"], as_raw_node=False)
                except Exception as exc:  # noqa: BLE001 -- no write was attempted
                    row["status"] = "failed"
                    row["reason"] = "pre_read_failed"
                    row["detail"] = f"{type(exc).__name__}: {exc}"
                    continue
                before_ts = getattr(before, "modifiedAt", None)
                row["modified_before"] = before_ts
                row["mechanism"] = _touch_mechanism_for(before)
                fingerprint_before = _touch_content_fingerprint(before)

                try:
                    after = await _one_touch(row, before)
                except ConcurrentEditDetectedError as exc:
                    row.update(status="failed", reason=ConcurrentEditDetectedError.code, detail=str(exc),
                               error_code=ConcurrentEditDetectedError.code, retry_after=exc.retry_after,
                               extra=_mutation_refusal_extra(exc))
                    if exc.detected_at == "preflight" and exc.previously_sent is None:
                        row["writes"] -= 1
                        continue
                    stopped, stop_reason = True, ConcurrentEditDetectedError.code
                    mapped_refusal = _mcp_exception_mapper(ANCHOR_REGISTRY.resolve("point.touch"), exc)
                    break
                except CoherenceBarrierActiveError as exc:
                    row["status"] = "failed"
                    row["reason"] = "coherence_barrier_active"
                    row["detail"] = str(exc)
                    stopped, stop_reason = True, "coherence_barrier_active"
                    spec = ANCHOR_REGISTRY.resolve("point.touch")
                    mapped_refusal = _mcp_exception_mapper(spec, exc)
                    break
                except (MutationSerializationTimeoutError, MutationSerializationConflictError, MutationRegionError):
                    raise  # This nested admission made no write; the item catch continues.
                except Exception as exc:  # noqa: BLE001 -- outcome UNKNOWN: never re-send
                    row["status"] = "failed"
                    row["reason"] = "write_outcome_unknown"
                    row["detail"] = (
                        f"{type(exc).__name__}: {exc}. The POST may or may not have committed; "
                        "the batch stopped and nothing was re-sent."
                    )
                    stopped, stop_reason = True, "write_outcome_unknown"
                    break

                retried = False
                after_ts = getattr(after, "modifiedAt", None)
                if not _touch_order_ok(before_ts, after_ts, last_after):
                    # Tie / same-second landing: wait for the next wall-clock second
                    # and re-touch this item exactly once.
                    retried = True
                    await _anchor_touch_sleep(_ANCHOR_TOUCH_TIE_SLEEP_SECONDS)
                    try:
                        after = await _one_touch(row, after)
                    except ConcurrentEditDetectedError as exc:
                        row.update(status="failed", reason=ConcurrentEditDetectedError.code,
                                   detail=f"The first touch was sent; re-touch: {exc}",
                                   modified_after=after_ts, retried=True,
                                   error_code=ConcurrentEditDetectedError.code, retry_after=exc.retry_after,
                                   extra=_mutation_refusal_extra(exc))
                        if exc.detected_at == "preflight" and exc.previously_sent is None:
                            row["writes"] -= 1
                        stopped, stop_reason = True, ConcurrentEditDetectedError.code
                        mapped_refusal = _mcp_exception_mapper(ANCHOR_REGISTRY.resolve("point.touch"), exc)
                        break
                    except CoherenceBarrierActiveError as exc:
                        row["status"] = "failed"
                        row["reason"] = "coherence_barrier_active"
                        row["detail"] = str(exc)
                        row["modified_after"] = after_ts
                        stopped, stop_reason = True, "coherence_barrier_active"
                        spec = ANCHOR_REGISTRY.resolve("point.touch")
                        mapped_refusal = _mcp_exception_mapper(spec, exc)
                        break
                    except (MutationSerializationTimeoutError, MutationSerializationConflictError, MutationRegionError):
                        raise
                    except Exception as exc:  # noqa: BLE001
                        row["status"] = "failed"
                        row["reason"] = "write_outcome_unknown"
                        row["modified_after"] = after_ts
                        row["detail"] = (
                            f"re-touch: {type(exc).__name__}: {exc}. The first touch committed "
                            f"(modifiedAt {after_ts}); the re-touch outcome is unknown. Stopped."
                        )
                        stopped, stop_reason = True, "write_outcome_unknown"
                        break
                    after_ts = getattr(after, "modifiedAt", None)

                row["modified_after"] = after_ts
                row["retried"] = retried

                fingerprint_after = _touch_content_fingerprint(after)
                changed_fields = sorted(
                    key for key in fingerprint_before if fingerprint_before[key] != fingerprint_after[key]
                )
                if changed_fields:
                    row["status"] = "failed"
                    row["reason"] = "content_changed"
                    row["detail"] = (
                        f"fields differ after the touch: {changed_fields}. Either the write altered "
                        "content (a defect -- report it) or the node was edited concurrently. Stopped."
                    )
                    row["changed_fields"] = changed_fields
                    stopped, stop_reason = True, "content_changed"
                    break

                if _touch_order_ok(before_ts, after_ts, last_after):
                    row["status"] = "touched"
                    row["order_verified"] = True
                    row["reason"] = None
                    last_after = after_ts
                    continue
                if not isinstance(after_ts, int) or (isinstance(before_ts, int) and after_ts <= before_ts):
                    # The server did not advance modifiedAt even after a spaced
                    # re-touch: the mechanism is not working -- stop, do not hammer.
                    row["status"] = "failed"
                    row["reason"] = "timestamp_not_advanced"
                    row["detail"] = (
                        f"modifiedAt {before_ts} -> {after_ts} after two spaced writes; the API "
                        "did not advance the timestamp. Stopped rather than retrying further."
                    )
                    stopped, stop_reason = True, "timestamp_not_advanced"
                    break
                # Advanced past its own pre-write value but tied with the previous
                # item: the item IS at the top; only the intra-batch order is unproven.
                row["status"] = "touched"
                row["order_verified"] = False
                row["reason"] = "tie_unresolved"
                last_after = after_ts
        except (MutationSerializationTimeoutError, MutationSerializationConflictError, MutationRegionError) as exc:
            # CF-04: recorded ON the item as timed-out-before-any-write —
            # never write_outcome_unknown, and it never stops the batch (I7).
            row["status"] = "failed"
            row["reason"] = exc.code
            row["detail"] = str(exc)
            row["error_code"] = exc.code
            row["retry_after"] = exc.retry_after
            row["extra"] = _mutation_refusal_extra(exc)
            continue
        finally:
            _item_serialization = _mutation_serialization_field(since=wait_mark)
            if _item_serialization is not None:
                row["serialization"] = _item_serialization

    ledger = _finish()
    if mapped_refusal is not None:
        mapped_refusal["error"].setdefault("extra", {})["touch"] = ledger
        return mapped_refusal
    return ledger


# ---------------------------------------------------------------------------
# anchor.point.promote -- batch move-with-provenance (mode: move) and
# promote-as-COPY with fresh AP-IDs (mode: derivative). Contract [ap:ZZEFM2].
# ---------------------------------------------------------------------------

# Orphaned Cartographer metadata on line 1 of a note (F12+4 residue whose
# mapped ancestor is gone). The ancestor walk (_classify_node_map_state) is
# the real test; the first-line prefixes live in the ONE managed-metadata
# registry (managed_metadata.py, [ap:BNNUZ4]) -- see
# _promote_mapped_metadata_reason below, which delegates to it.
_PROMOTE_MODES: tuple[str, ...] = ("move", "derivative")
# Fixed prefixes on purpose: provenance stays grep-able (node.search /
# lightning_rod.render_search for '↩ moved from' lists every promoted item;
# '↩ derived from' distinguishes copies).
_PROMOTE_MOVE_TRAIL_PREFIX = "↩ moved from"
_PROMOTE_DERIVATIVE_TRAIL_PREFIX = "↩ derived from"
_PROMOTE_MAPPED_REFUSAL_TEXT = (
    "mapped source/Markdown node -- disk is truth; move it in the file and refresh."
)


def _promote_today() -> str:
    """The trail-line date (UTC, YYYY-MM-DD). Module attribute so tests pin it."""
    from datetime import timezone as _timezone

    return datetime.now(_timezone.utc).date().isoformat()


def _promote_normalize_tags(tags: Any, *, where: str) -> list[str]:
    """Pure: normalize a tags argument to a de-duplicated '#tag' list.

    Accepts a string, a list of strings, or None. Leading '#' is optional on
    input; the output always carries it (the protected-name composer's tag
    vocabulary). Raises :class:`_AnchorOperationError` on a malformed value.
    """
    if tags is None:
        return []
    if isinstance(tags, str):
        tags = [tags]
    if not isinstance(tags, list):
        raise _AnchorOperationError(
            "invalid_parameter_type", f"{where}: tags must be a string or a list of strings."
        )
    out: list[str] = []
    for index, raw in enumerate(tags):
        if not isinstance(raw, str) or not raw.strip():
            raise _AnchorOperationError(
                "invalid_parameter_type",
                f"{where}: tags[{index}] must be a non-empty string; got {raw!r}.",
            )
        cleaned = raw.strip()
        if any(ch.isspace() for ch in cleaned):
            raise _AnchorOperationError(
                "invalid_parameter_value",
                f"{where}: tags[{index}] {raw!r} contains whitespace; pass one tag per item.",
            )
        tag = cleaned if cleaned.startswith("#") else f"#{cleaned}"
        if tag == "#":
            raise _AnchorOperationError(
                "invalid_parameter_value", f"{where}: tags[{index}] is an empty tag."
            )
        if tag not in out:
            out.append(tag)
    return out


# @beacon[
#   id=auto-beacon@normalize_promote_items-275c,
#   role=normalize_promote_items,
#   slice_labels=nexus--anchors,
#   kind=ast,
# ]
def normalize_promote_items(
    *,
    items: Any = None,
    handles: Any = None,
    destination: Any = None,
    tags: Any = None,
    mode: Any = None,
    children: Any = None,
) -> list[dict[str, Any]]:
    """Pure: normalize the two ``anchor.point.promote`` grammars to one item list.

    Granular: ``items=[{handle, destination, tags?, mode?, children?}]``.
    Shorthand: ``handles=[...]`` + ``destination`` (+ ``tags?``, ``mode?``,
    ``children?`` applied to every handle). Exactly one grammar per call.
    ``validate_params`` does not inspect nested item objects, so every shape
    error is raised HERE (before any resolution or write) as an
    :class:`_AnchorOperationError` with a kernel/declared code. Returns
    ``[{handle, destination, tags: ['#x', ...], mode, children}]`` with
    ``mode`` defaulted to ``'move'`` and ``children`` to ``True``.
    """
    if items is not None and handles is not None:
        raise _AnchorOperationError(
            "invalid_parameter_combination",
            "Pass EITHER items=[{handle, destination, ...}] OR handles=[...] + destination, not both.",
        )
    if items is None and handles is None:
        raise _AnchorOperationError(
            "invalid_parameter_combination",
            "point.promote requires items=[{handle, destination, tags?, mode?, children?}] "
            "or the shorthand handles=[...] + destination (+ tags?, mode?, children?).",
        )

    def _mode(value: Any, where: str) -> str:
        if value is None:
            return "move"
        if not isinstance(value, str) or value.strip().lower() not in _PROMOTE_MODES:
            raise _AnchorOperationError(
                "invalid_parameter_value",
                f"{where}: mode must be one of {list(_PROMOTE_MODES)}; got {value!r}.",
            )
        return value.strip().lower()

    def _children(value: Any, where: str) -> bool:
        if value is None:
            return True
        if not isinstance(value, bool):
            raise _AnchorOperationError(
                "invalid_parameter_type", f"{where}: children must be a boolean."
            )
        return value

    def _handle(value: Any, where: str) -> str:
        if not isinstance(value, str) or not value.strip():
            raise _AnchorOperationError(
                "invalid_parameter_type",
                f"{where}: handle must be a non-empty string (UUID / unique prefix / [ap:CORE]); got {value!r}.",
            )
        return value.strip()

    def _destination(value: Any, where: str) -> str:
        if not isinstance(value, str) or not value.strip():
            raise _AnchorOperationError(
                "invalid_parameter_type",
                f"{where}: destination must be a non-empty string handle (a Dock or any safe node); got {value!r}.",
            )
        return value.strip()

    normalized: list[dict[str, Any]] = []
    if handles is not None:
        if not isinstance(handles, list) or not handles:
            raise _AnchorOperationError(
                "invalid_parameter_value",
                "handles must be a non-empty list of node handles.",
            )
        dest = _destination(destination, "shorthand")
        shared_tags = _promote_normalize_tags(tags, where="shorthand")
        shared_mode = _mode(mode, "shorthand")
        shared_children = _children(children, "shorthand")
        for index, raw in enumerate(handles):
            normalized.append({
                "handle": _handle(raw, f"handles[{index}]"),
                "destination": dest,
                "tags": list(shared_tags),
                "mode": shared_mode,
                "children": shared_children,
            })
        return normalized

    # Granular grammar: the top-level shorthand fields must not leak in.
    leaked = [
        key for key, value in (
            ("destination", destination), ("tags", tags), ("mode", mode), ("children", children)
        ) if value is not None
    ]
    if leaked:
        raise _AnchorOperationError(
            "invalid_parameter_combination",
            f"{leaked} belong to the shorthand grammar (handles=[...]); with items=[...] "
            "put destination/tags/mode/children on each item.",
        )
    if not isinstance(items, list) or not items:
        raise _AnchorOperationError(
            "invalid_parameter_value",
            "items must be a non-empty list of {handle, destination, tags?, mode?, children?} objects.",
        )
    allowed = {"handle", "destination", "tags", "mode", "children"}
    for index, item in enumerate(items):
        where = f"items[{index}]"
        if not isinstance(item, dict):
            raise _AnchorOperationError(
                "invalid_parameter_type",
                f"{where} must be an object {{handle, destination, tags?, mode?, children?}}; got {type(item).__name__}.",
            )
        unknown = sorted(set(item) - allowed)
        if unknown:
            raise _AnchorOperationError(
                "invalid_parameter_value",
                f"{where} has unknown key(s) {unknown}; allowed: {sorted(allowed)}.",
            )
        if "handle" not in item or "destination" not in item:
            raise _AnchorOperationError(
                "invalid_parameter_value", f"{where} requires both handle and destination."
            )
        normalized.append({
            "handle": _handle(item.get("handle"), where),
            "destination": _destination(item.get("destination"), where),
            "tags": _promote_normalize_tags(item.get("tags"), where=where),
            "mode": _mode(item.get("mode"), where),
            "children": _children(item.get("children"), where),
        })
    return normalized


def _promote_node_parent(node: Mapping[str, Any] | None) -> str | None:
    if not isinstance(node, Mapping):
        return None
    parent = node.get("parent_id") if "parent_id" in node else node.get("parentId")
    return str(parent) if parent else None


def _promote_title(nodes_by_id: Mapping[str, Any], node_id: str | None) -> str:
    """Pure: a node's tag-stripped semantic title from the pinned cache."""
    from nexus_map_codebase import split_name_and_tags  # type: ignore[import-not-found]

    if node_id is None:
        return "(root)"
    node = nodes_by_id.get(node_id)
    if not isinstance(node, Mapping):
        return "(unknown)"
    raw = str(node.get("name") or node.get("nm") or "")
    base, _tags = split_name_and_tags(_semantic_name_for_tag_merge(raw))
    parts = _split_leading_ap_handle(base)
    title = f"{parts['decoration']}{parts['title']}".strip()
    return title or "(untitled)"


# @beacon[
#   id=auto-beacon@nearest_anchor_dock_ancestor-8b8e,
#   role=nearest_anchor_dock_ancestor,
#   slice_labels=nexus--anchors,
#   kind=ast,
# ]
def nearest_anchor_dock_ancestor(
    nodes_by_id: Mapping[str, Any],
    node_id: str,
    base_tags: "Iterable[str]",
    local_postfixes: "Iterable[str]",
    *,
    favorite_postfixes: "Iterable[str] | None" = None,
    deprecated_postfixes: "Iterable[str] | None" = None,
) -> dict[str, Any]:
    """Pure: the promote ORIGIN of ``node_id`` from the pinned cache.

    Walks ``parent_id`` upward from the node's PARENT (the node's own
    Dock-hood is irrelevant) and returns the first ancestor whose NAME tags
    classify as an Anchor Dock (bare / local / favorite form, via the ONE
    :func:`classify_anchor_tags` authority; a ``--deprecated``-only node is
    NOT a Dock and is skipped). When no ancestor is a Dock the
    immediate parent is the origin. Cycle-guarded and hop-capped like
    :func:`_classify_node_map_state`. Returns
    ``{"uuid", "title", "is_dock", "is_local"}``; ``uuid`` is None for a
    root-level node (title ``'(root)'``).
    """
    from nexus_map_codebase import split_name_and_tags  # type: ignore[import-not-found]

    bases = list(base_tags or [])
    postfixes = list(local_postfixes or [])
    parent = _promote_node_parent(nodes_by_id.get(node_id))
    cur = parent
    visited: set[str] = set()
    hops = 0
    while cur and cur not in visited and hops < 512:
        visited.add(cur)
        node = nodes_by_id.get(cur)
        if not isinstance(node, Mapping):
            break
        raw = str(node.get("name") or node.get("nm") or "")
        _base, name_tags = split_name_and_tags(raw)
        verdict = classify_anchor_tags(
            name_tags,
            bases,
            local_postfixes=postfixes,
            favorite_postfixes=favorite_postfixes,
            deprecated_postfixes=deprecated_postfixes,
        )
        if verdict.get("is_anchor"):
            return {
                "uuid": cur,
                "title": _promote_title(nodes_by_id, cur),
                "is_dock": True,
                "is_local": bool(verdict.get("is_local")),
            }
        cur = _promote_node_parent(node)
        hops += 1
    return {
        "uuid": parent,
        "title": _promote_title(nodes_by_id, parent),
        "is_dock": False,
        "is_local": False,
    }


def _promote_origin_label(origin: Mapping[str, Any]) -> str:
    """``title (uuid8)`` -- the inert, human-readable origin record."""
    uuid = origin.get("uuid")
    short = _short_handle_prefix(uuid) if uuid else "root"
    return f"{origin.get('title') or '(untitled)'} ({short})"


# @beacon[
#   id=auto-beacon@_promote_trail_line-4byr,
#   role=_promote_trail_line,
#   slice_labels=nexus--anchors,
#   kind=ast,
# ]
def _promote_trail_line(
    origin: Mapping[str, Any], *, mode: str, date: str,
    source_uuid: str | None = None, source_ap_id: str | None = None,
) -> str:
    """Pure: the one fixed-prefix provenance line for a move or a derivative."""
    if mode == "derivative":
        source = f"{source_ap_id} {_short_handle_prefix(source_uuid)}" if source_ap_id else _short_handle_prefix(source_uuid)
        return (
            f"{_PROMOTE_DERIVATIVE_TRAIL_PREFIX} {_promote_origin_label(origin)} · {date} · source {source}"
        )
    return f"{_PROMOTE_MOVE_TRAIL_PREFIX} {_promote_origin_label(origin)} · {date}"


def _promote_prepend_trail(trail_line: str, old_note: str) -> str:
    """Pure: trail line on top, one blank line, then the existing note (newest
    on top; a node moved three times shows three lines). An empty note gets
    the trail line alone -- no dangling blank lines."""
    old = old_note or ""
    return f"{trail_line}\n\n{old}" if old.strip() else trail_line


def _promote_mapped_metadata_reason(note_wire: Any) -> str | None:
    """Pure: the content check -- does the decoded note's first line carry
    orphaned Cartographer metadata? Returns the offending prefix or None.

    Delegates to the ONE managed-metadata registry (managed_metadata.py,
    [ap:BNNUZ4]); the returned prefix text and this refusal's detail text are
    byte-identical to the retired inline regex.
    """
    from .managed_metadata import first_refuse_guard_hit
    from .note_lines import split_note_lines

    lines = split_note_lines(_note_wire_to_semantic(str(note_wire or "")))
    return first_refuse_guard_hit(lines[0] if lines else "")


def _promote_is_within(nodes_by_id: Mapping[str, Any], node_id: str, ancestor_id: str) -> bool:
    """Pure: is ``node_id`` equal to or beneath ``ancestor_id`` (cycle check)?"""
    cur: str | None = node_id
    visited: set[str] = set()
    hops = 0
    while cur and cur not in visited and hops < 512:
        if cur == ancestor_id:
            return True
        visited.add(cur)
        cur = _promote_node_parent(nodes_by_id.get(cur))
        hops += 1
    return False


def _promote_enumerate_subtree(
    nodes_by_id: Mapping[str, Any], root_id: str, *, children: bool, include_completed: bool,
) -> list[dict[str, Any]]:
    """Pure: the derivative copy's source node list in document order.

    Uses the metrics owner's priority-ordered topology without byte sizing;
    reachable cycles keep the same loud error, even behind completed nodes.
    ``children=False`` yields the root alone.
    Completed descendants are skipped (with their subtrees) unless
    ``include_completed``; the root is always included. Each entry is
    ``{"uuid", "parent", "depth", "completed"}``.
    """
    from .dock_peek_metrics import _build_ordered_children
    from .f8_slice_policy import _node_is_completed

    if root_id not in nodes_by_id:
        raise ValueError(f"Dock peek metrics root {root_id!r} is absent from the snapshot")
    ordered = _build_ordered_children(nodes_by_id)
    out: list[dict[str, Any]] = [{
        "uuid": root_id, "parent": None, "depth": 0,
        "completed": _node_is_completed(nodes_by_id.get(root_id) or {}),
    }]
    seen = {root_id}
    stack = [(child, root_id, 1, not children) for child in reversed(ordered.get(root_id, ()))]
    while stack:
        node_id, parent, depth, excluded = stack.pop()
        if node_id in seen:
            raise ValueError(f"Cycle in Dock peek source topology at {node_id!r}")
        seen.add(node_id)
        node = nodes_by_id.get(node_id)
        if node is None:
            continue
        completed = _node_is_completed(node)
        excluded = excluded or (completed and not include_completed)
        if not excluded:
            out.append({"uuid": node_id, "parent": parent, "depth": depth, "completed": completed})
        stack.extend((child, node_id, depth + 1, excluded) for child in reversed(ordered.get(node_id, ())))
    return out


def _promote_layout_mode(node: Mapping[str, Any]) -> str | None:
    data = node.get("data")
    mode = data.get("layoutMode") if isinstance(data, Mapping) else None
    return mode if isinstance(mode, str) and mode in _TOUCH_ECHO_LAYOUT_MODES else None


# @beacon[
#   id=mcp-api@anchor-point-promote,
#   role=⚡ _anchor_point_promote_impl(items, handles, destination, tags, mode, children, include_completed, target_tab),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Per-item move keeps source and parent-list ownership; its post-move live basis checks the trail/tags stage only. Known no-send collisions continue and sent-content uncertainty stops with the typed ledger. Derivative uses topology-only enumeration and frontier counting without discarded metrics; destination ownership ETCH re-completion provenance and managed-metadata policy stay unchanged.,
# ]
async def _anchor_point_promote_impl(
    *,
    items: Any = None,
    handles: Any = None,
    destination: Any = None,
    tags: Any = None,
    mode: Any = None,
    children: Any = None,
    include_completed: bool = False,
    target_tab: str | None = None,
) -> dict[str, Any]:
    """Promote per item; retain acknowledged moves and typed trail/tags collisions.

    MOVE owns exact(source) and both proof-current parent child lists.
    Derivative owns C(destination); generated cores stay allocator-owned.
    Its source enumeration and completed frontier count use topology, not sizes.
    ETCH protects fresh-root recursion (VA5ZZO), and only a requested
    re-completion phase additionally owns S(acknowledged copy root) (HG2R5B).

    Returns the complete ledger (one row per input item, input order) or, for
    a mid-batch typed coherence refusal, the universal error envelope with
    the partial ledger under ``error.extra.promote``. Batch-level input
    refusals raise :class:`_AnchorOperationError` (zero writes).
    """
    import time as _time

    from .coherence.errors import CoherenceBarrierActiveError
    from .managed_metadata import detect_trail_skip_metadata
    from .models.requests import NodeListRequest

    # ---- Input validation (batch REFUSE: zero writes) -----------------------
    if not isinstance(include_completed, bool):
        raise _AnchorOperationError(
            "invalid_parameter_type", "include_completed must be a boolean."
        )
    normalized = normalize_promote_items(
        items=items, handles=handles, destination=destination, tags=tags,
        mode=mode, children=children,
    )
    seen_literal: dict[str, int] = {}
    literal_duplicates: list[str] = []
    for item in normalized:
        key = item["handle"].lower()
        seen_literal[key] = seen_literal.get(key, 0) + 1
        if seen_literal[key] == 2:
            literal_duplicates.append(item["handle"])
    if literal_duplicates:
        raise _AnchorOperationError(
            "duplicate_handles",
            "handles must not repeat within one call (a node is promoted once). "
            f"Duplicated: {literal_duplicates}. No write was made.",
            extra={"duplicates": literal_duplicates},
        )

    # ---- Ledger scaffolding (one row per item, INPUT order) -----------------
    rows: list[dict[str, Any]] = [
        {
            "handle": item["handle"],
            "uuid": None,
            "ap_id": None,
            "mode": item["mode"],
            "from": None,
            "to": None,
            "trail_line": None,
            "tags_applied": [],
            "status": "not_run",
            "reason": None,
            "info": None,
        }
        for item in normalized
    ]
    warnings: list[str] = []
    today = _promote_today()

    # ---- Preflight A: resolve handle + destination against ONE pinned map ---
    from .archive_context import ArchivedNodeReadOnlyError, archive_miss_hit

    nodes_by_id = _anchor_cache_by_id()
    uuid_owner: dict[str, int] = {}
    for index, (row, item) in enumerate(zip(rows, normalized)):
        try:
            resolved = await _resolve_generic_node_handle(
                item["handle"], label=f"anchor.point.promote (items[{index}].handle)"
            )
        except ArchivedNodeReadOnlyError:
            # Archive Reads U2 (Axiom 6, G8, E32): an ARCHIVED source.
            #   move  -> a SKIPPED row with the §5.2.1 + how-to-copy story;
            #   derivative -> the ONE sanctioned copy: the source rides the
            #   archive file's verbatim records (no overlay is ever
            #   installed; the file is untouched).
            _text, _prov, _arch_uuid = archive_miss_hit(
                item["handle"],
                copy_hint="promote_move" if item["mode"] == "move" else None,
            )
            if item["mode"] == "move":
                row["status"] = "skipped"
                row["reason"] = "archived_node"
                row["detail"] = _text or str("archived node")
                row["archive"] = dict(_prov or {})
                continue
            item["archived_source"] = {
                "file": (_prov or {}).get("archive_file") or "",
                "uuid": str(_arch_uuid or ""),
                "provenance": dict(_prov or {}),
            }
            row["uuid"] = str(_arch_uuid or "")
            uuid_owner[row["uuid"]] = index
            # The destination resolves exactly as for a live source (the
            # archived-destination refusal below applies here too).
            try:
                dest_uuid = await _resolve_generic_node_handle(
                    item["destination"],
                    label=f"anchor.point.promote (items[{index}].destination)",
                    role="destination",
                )
            except ArchivedNodeReadOnlyError as exc:
                row["status"] = "skipped"
                row["reason"] = "archived_node"
                row["detail"] = str(exc)
                row["archive"] = dict(exc.extra or {})
                continue
            except RuntimeError as exc:
                row["status"] = "skipped"
                row["reason"] = "unresolvable_destination"
                row["detail"] = str(exc)
                continue
            item["dest_uuid"] = str(dest_uuid)
            continue
        except RuntimeError as exc:
            row["status"] = "skipped"
            row["reason"] = "unresolvable_handle"
            row["detail"] = str(exc)
            continue
        row["uuid"] = str(resolved)
        if row["uuid"] in uuid_owner:
            first = uuid_owner[row["uuid"]]
            raise _AnchorOperationError(
                "duplicate_handles",
                f"items[{first}] ({rows[first]['handle']!r}) and items[{index}] "
                f"({row['handle']!r}) resolve to the same node {row['uuid']}; a node is "
                "promoted once per call. No write was made.",
                extra={"uuid": row["uuid"], "handles": [rows[first]["handle"], row["handle"]]},
            )
        uuid_owner[row["uuid"]] = index
        try:
            dest_uuid = await _resolve_generic_node_handle(
                item["destination"],
                label=f"anchor.point.promote (items[{index}].destination)",
                role="destination",
            )
        except ArchivedNodeReadOnlyError as exc:
            # Archive Reads U2 (§5.2.3): an archived DESTINATION refuses
            # with the parent/destination story, as a skipped row.
            row["status"] = "skipped"
            row["reason"] = "archived_node"
            row["detail"] = str(exc)
            row["archive"] = dict(exc.extra or {})
            continue
        except RuntimeError as exc:
            row["status"] = "skipped"
            row["reason"] = "unresolvable_destination"
            row["detail"] = str(exc)
            continue
        item["dest_uuid"] = str(dest_uuid)

    # ---- Preflight B: cache presence, mapped-node refusals, cycle check -----
    for index, (row, item) in enumerate(zip(rows, normalized)):
        if row["status"] != "not_run" or row["uuid"] is None:
            continue
        src = row["uuid"]
        dest = item["dest_uuid"]
        if item.get("archived_source") is not None:
            # Archive Reads U2 (Axiom 6): the archived source has no live
            # map state by definition — only the LIVE destination is
            # checked here.  The map-state and metadata-content refusals
            # are about preserving live mapped material; the archive's
            # verbatim records carry none.
            dest_cached = nodes_by_id.get(dest)
            if dest_cached is None:
                row["status"] = "skipped"
                row["reason"] = "not_in_cache"
                row["detail"] = (
                    "the destination node is absent from the local /nodes-export snapshot, so its "
                    "map state cannot be classified; system.cache.refresh once and retry."
                )
                continue
            item["dest_uuid"] = str(dest)
            row["to"] = {"uuid": dest, "title": _promote_title(nodes_by_id, dest)}
            row["status"] = "eligible"
            continue
        cached = nodes_by_id.get(src)
        dest_cached = nodes_by_id.get(dest)
        if cached is None or dest_cached is None:
            row["status"] = "skipped"
            row["reason"] = "not_in_cache"
            missing = "source" if cached is None else "destination"
            row["detail"] = (
                f"the {missing} node is absent from the local /nodes-export snapshot, so its "
                "map state cannot be classified; system.cache.refresh once and retry."
            )
            continue
        cached_name = str(cached.get("name") or cached.get("nm") or "")
        core = _anchor_leading_ap_core(cached_name)
        row["ap_id"] = f"[ap:{core}]" if core else None
        row["to"] = {"uuid": dest, "title": _promote_title(nodes_by_id, dest)}
        # Structural check, both directions (the real test).
        for label, node_id in (("source", src), ("destination", dest)):
            verdict = _classify_node_map_state(node_id, nodes_by_id)
            if verdict.get("state") != "unmapped":
                row["status"] = "skipped"
                row["reason"] = "mapped_node_refused"
                row["detail"] = (
                    f"{label} is Cartographer-mapped material (state={verdict.get('state')}, "
                    f"path={verdict.get('path_value')!r}): {_PROMOTE_MAPPED_REFUSAL_TEXT}"
                )
                break
        if row["status"] == "skipped":
            continue
        # Content check, both directions (belt and suspenders for orphaned metadata).
        for label, node in (("source", cached), ("destination", dest_cached)):
            prefix = _promote_mapped_metadata_reason(node.get("note") or node.get("no"))
            if prefix:
                row["status"] = "skipped"
                row["reason"] = "mapped_node_refused"
                row["detail"] = (
                    f"{label} note begins with orphaned Cartographer metadata ({prefix!r}): "
                    f"{_PROMOTE_MAPPED_REFUSAL_TEXT}"
                )
                break
        if row["status"] == "skipped":
            continue
        # Cycle: the destination is the source itself or inside its subtree.
        if _promote_is_within(nodes_by_id, dest, src):
            raise _AnchorOperationError(
                "promote_cycle_refused",
                f"items[{index}]: destination {dest} is the source node {src} or lies inside "
                "its own subtree; moving or copying there would nest the node under itself. "
                "No write was made.",
                extra={"handle": row["handle"], "uuid": src, "destination": dest},
            )
        row["status"] = "eligible"

    # ---- Origin: ONE Dock-vocabulary read per batch (only if anything runs) --
    if any(row["status"] == "eligible" for row in rows):
        base_tags, postfix_kwargs = await _read_anchor_dock_vocabulary(target_tab)
        for row, item in zip(rows, normalized):
            if row["status"] != "eligible":
                continue
            if item.get("archived_source") is not None:
                # Archive Reads U2 (§U2.4): an archived derivative's origin
                # is the ARCHIVE itself; its trail line is composed in
                # _run_derivative from the file's provenance.
                continue
            origin = nearest_anchor_dock_ancestor(nodes_by_id, row["uuid"], base_tags, **postfix_kwargs)
            row["from"] = origin
            row["trail_line"] = _promote_trail_line(
                origin, mode=row["mode"], date=today,
                source_uuid=row["uuid"], source_ap_id=row["ap_id"],
            )

    # ---- Execution (input order; per-item mode) ------------------------------
    started = _time.monotonic()
    stopped = False
    stop_reason: str | None = None
    mapped_refusal: dict[str, Any] | None = None
    client = get_client()

    def _finish() -> dict[str, Any]:
        for row in rows:
            if row["status"] == "eligible":
                row["status"] = "not_run"
                row["reason"] = row.get("reason") or "batch_stopped"
        promoted = [r for r in rows if r["status"] == "promoted"]
        counts = {
            "requested": len(rows),
            "promoted": len(promoted),
            "moved": sum(1 for r in promoted if r["mode"] == "move"),
            "copied": sum(1 for r in promoted if r["mode"] == "derivative"),
            "skipped": sum(1 for r in rows if r["status"] == "skipped"),
            "failed": sum(1 for r in rows if r["status"] == "failed"),
            "not_run": sum(1 for r in rows if r["status"] == "not_run"),
        }
        changed = bool(promoted) or any(
            r["status"] == "failed"
            and (r.get("moved") or int((r.get("copy") or {}).get("nodes_created") or 0) > 0)
            for r in rows
        )
        success = counts["promoted"] == counts["requested"] and counts["requested"] > 0
        any_fail = counts["skipped"] + counts["failed"] + counts["not_run"] > 0
        if stopped:
            warnings.append(
                f"Batch STOPPED ({stop_reason}); rows marked not_run were never written. "
                "Read live state (node.read / dock.peek) before re-running; retry only "
                "skipped/not_run rows after addressing their reasons."
            )
        return {
            "success": success,
            "operation": "anchor.point.promote",
            "changed": changed,
            "partial_success": bool(promoted) and any_fail and success is False,
            "results": rows,
            "summary": {
                **counts,
                "stopped": stopped,
                "stop_reason": stop_reason,
                "elapsed_seconds": round(_time.monotonic() - started, 3),
                "writes": sum(int(r.get("writes") or 0) for r in rows),
            },
            "warnings": warnings,
        }

    def _add_tags_transform(want: list[str]):
        def _transform(current: list[str]) -> list[str]:
            return list(current) + [tag for tag in want if tag not in current]
        return _transform

    async def _run_move(row: dict[str, Any], item: dict[str, Any]) -> None:
        nonlocal stopped, stop_reason, mapped_refusal
        src, dest = row["uuid"], item["dest_uuid"]
        row["moved"] = False
        row["trail_written"] = False
        try:
            row["writes"] = int(row.get("writes") or 0) + 1
            ok = await _node_move_impl(src, dest, position="bottom")
        except CoherenceBarrierActiveError as exc:
            row["status"], row["reason"], row["detail"] = "failed", "coherence_barrier_active", str(exc)
            stopped, stop_reason = True, "coherence_barrier_active"
            mapped_refusal = _mcp_exception_mapper(ANCHOR_REGISTRY.resolve("point.promote"), exc)
            return
        except (MutationSerializationTimeoutError, MutationSerializationConflictError, MutationRegionError):
            raise
        except Exception as exc:  # noqa: BLE001 -- outcome UNKNOWN: never re-send
            row["status"], row["reason"] = "failed", "write_outcome_unknown"
            row["detail"] = (
                f"move: {type(exc).__name__}: {exc}. The move may or may not have committed; "
                "the batch stopped and nothing was re-sent."
            )
            stopped, stop_reason = True, "write_outcome_unknown"
            return
        if not ok:
            row["status"], row["reason"] = "failed", "move_rejected"
            row["detail"] = "the move endpoint did not return status ok; the node was not moved."
            return
        row["moved"] = True
        # Live GET: the authoritative post-move snapshot (note bytes + name for
        # the protected-name composer); injected so the trail write costs ONE
        # governed POST.
        try:
            live = await _node_read_impl(src, as_raw_node=False)
        except Exception as exc:  # noqa: BLE001 -- no write attempted; not ambiguous
            row["status"], row["reason"] = "failed", "trail_read_failed"
            row["detail"] = (
                f"moved, but the live read before the trail write failed ({type(exc).__name__}: "
                f"{exc}); the trail line was NOT written. Re-running this item writes it."
            )
            return
        old_note = _note_wire_to_semantic(getattr(live, "note", None) or "")
        # Managed metadata ([ap:BNNUZ4]): a note carrying a recognised block
        # (program_interface YAML, estate payloads, manifests, snapshot nodes,
        # …) still moves, but the trail line is NOT written -- the system must
        # never prepend prose to its own machine-readable blocks. The computed
        # would-be line stays in the ledger row (row["trail_line"]); the row's
        # info field names the kind. Detection rides the LIVE note (the text
        # this write would have prepended to), decoded above.
        managed_kind = detect_trail_skip_metadata(
            old_note,
            name=_semantic_name_for_tag_merge(str(getattr(live, "name", "") or "")),
        )
        new_note = None if managed_kind else _promote_prepend_trail(row["trail_line"], old_note)
        want = list(item["tags"])
        if managed_kind is None or want:
            try:
                row["writes"] = int(row.get("writes") or 0) + 1
                await _node_edit_core(
                    src, note=new_note,
                    _tag_transform=_add_tags_transform(want) if want else None,
                    _current_node=live,
                )
            except ConcurrentEditDetectedError as exc:
                row.update(status="failed", reason=ConcurrentEditDetectedError.code, detail=str(exc),
                           error_code=ConcurrentEditDetectedError.code, retry_after=exc.retry_after,
                           extra=_mutation_refusal_extra(exc))
                if exc.detected_at == "preflight" and exc.previously_sent is None:
                    row["writes"] -= 1
                    return  # Move stands; this known content-stage failure continues per item.
                stopped, stop_reason = True, ConcurrentEditDetectedError.code
                mapped_refusal = _mcp_exception_mapper(ANCHOR_REGISTRY.resolve("point.promote"), exc)
                return
            except CoherenceBarrierActiveError as exc:
                row["status"], row["reason"], row["detail"] = "failed", "coherence_barrier_active", str(exc)
                stopped, stop_reason = True, "coherence_barrier_active"
                mapped_refusal = _mcp_exception_mapper(ANCHOR_REGISTRY.resolve("point.promote"), exc)
                return
            except (MutationSerializationTimeoutError, MutationSerializationConflictError, MutationRegionError):
                raise
            except Exception as exc:  # noqa: BLE001 -- outcome UNKNOWN: never re-send
                row["status"], row["reason"] = "failed", "write_outcome_unknown"
                row["detail"] = (
                    f"moved; trail/tags write: {type(exc).__name__}: {exc}. The note update may or "
                    "may not have committed; the batch stopped and nothing was re-sent."
                )
                stopped, stop_reason = True, "write_outcome_unknown"
                return
            if managed_kind is None:
                row["trail_written"] = True
        if managed_kind is not None:
            row["info"] = f"trail line skipped: the note carries managed metadata ({managed_kind})"
        row["tags_applied"] = want
        row["status"], row["reason"] = "promoted", None

    async def _recomplete_copies(
        row: dict[str, Any], copy_root: str, plan: list[dict[str, Any]],
    ) -> None:
        """include_completed: re-complete copied nodes whose SOURCE was completed.

        ETCH cannot create completed nodes and returns only root ids, so the
        copies are located by ONE live list_nodes read per copied parent that
        has children, matched by document order (ETCH appends in order). A
        count mismatch skips that parent with a warning -- never a guess."""
        wanted = [entry for entry in plan if entry["completed"]]
        if not wanted:
            return
        source_to_copy: dict[str, str] = {plan[0]["uuid"]: copy_root}
        # Children of each source node, in plan order.
        children_of: dict[str, list[str]] = {}
        for entry in plan[1:]:
            children_of.setdefault(entry["parent"], []).append(entry["uuid"])
        queue = [plan[0]["uuid"]]
        located_failures: list[str] = []
        while queue:
            source_parent = queue.pop(0)
            kids = children_of.get(source_parent)
            if not kids:
                continue
            copy_parent = source_to_copy.get(source_parent)
            if copy_parent is None:
                located_failures.extend(kids)
                continue
            try:
                listed, _total = await client.list_nodes(NodeListRequest(parentId=copy_parent))
            except Exception as exc:  # noqa: BLE001 -- read failure; nothing written
                warnings.append(
                    f"{row['handle']}: could not list the copy's children under {copy_parent} "
                    f"({type(exc).__name__}); completion state not reproduced beneath it."
                )
                located_failures.extend(kids)
                continue
            listed = sorted(
                listed, key=lambda n: (0, float(n.priority)) if isinstance(n.priority, (int, float)) else (1, 0.0)
            )
            if len(listed) != len(kids):
                warnings.append(
                    f"{row['handle']}: copy parent {copy_parent} lists {len(listed)} children, "
                    f"expected {len(kids)}; completion state not reproduced beneath it."
                )
                located_failures.extend(kids)
                continue
            for source_child, copy_child in zip(kids, listed):
                source_to_copy[source_child] = str(copy_child.id)
                queue.append(source_child)
        recompleted = 0
        for entry in wanted:
            copy_uuid = source_to_copy.get(entry["uuid"])
            if copy_uuid is None:
                continue
            # The copy is absent from the PINNED snapshot (created after the
            # pin), so the handle resolver cannot see it: complete through the
            # client's own governed funnel with the exact UUID ETCH/list_nodes
            # returned (the same authority _node_set_completion_impl calls).
            row["writes"] = int(row.get("writes") or 0) + 1
            if _rate_limiter:
                await _rate_limiter.acquire()
            try:
                await client.complete_node(copy_uuid)
                if _rate_limiter:
                    _rate_limiter.on_success()
            except Exception as exc:
                if _rate_limiter and exc.__class__.__name__ == "RateLimitError":
                    _rate_limiter.on_rate_limit(getattr(exc, "retry_after", None))
                raise
            recompleted += 1
        row["copy"]["completion"] = {
            "requested": len(wanted), "recompleted": recompleted,
            "unlocated": len(wanted) - recompleted,
        }
        if recompleted < len(wanted):
            warnings.append(
                f"{row['handle']}: {len(wanted) - recompleted} completed source node(s) could not be "
                "located in the copy and remain un-completed there."
            )

    async def _run_derivative(row: dict[str, Any], item: dict[str, Any]) -> None:
        nonlocal stopped, stop_reason, mapped_refusal
        src, dest = row["uuid"], item["dest_uuid"]
        archived = item.get("archived_source")
        source_map: Any = nodes_by_id
        if archived is not None:
            # Archive Reads U2 (Axiom 6, G8): the ONE sanctioned copy that
            # READS archived content.  The plan is the archive file's
            # verbatim records (original names, parents, priorities — no
            # 📦, no marker); the operation is never augmented (a write
            # carries no overlay) and the archive file is untouched.
            from .archive_store import get_archive_store

            verbatim = get_archive_store().verbatim_subtree_records(
                archived["file"], archived["uuid"]
            )
            if not verbatim:
                row["status"], row["reason"], row["detail"] = (
                    "failed",
                    "archived_source_unavailable",
                    (
                        "the archive file's records for this handle are no longer "
                        "visible (the file changed, is shadowed, or its root is "
                        "live again); system(verb='archives.list') shows the states."
                    ),
                )
                return
            source_map = {str(rec.get("id")): rec for rec in verbatim}
            from .f8_slice_policy import _node_is_completed

            # The trail line names the ARCHIVE as the origin (§U2.4).
            import os as _os

            _prov = archived["provenance"]
            row["trail_line"] = (
                f"{_PROMOTE_DERIVATIVE_TRAIL_PREFIX} "
                f"archive \"{_prov.get('archive_name') or archived['file']}\" "
                f"({_os.path.basename(str(_prov.get('archive_file') or ''))}, "
                f"exported {_prov.get('exported_at')}) · {today} · "
                f"source {_short_handle_prefix(src)}"
            )
            plan: "list[dict[str, Any]]" = [
                {"uuid": str(rec.get("id")), "parent": None, "depth": 0,
                 "completed": _node_is_completed(rec)}
                for rec in [verbatim[0]]
            ]
            if item["children"]:
                by_parent: "dict[Any, list[dict[str, Any]]]" = {}
                for rec in verbatim[1:]:
                    parent = rec.get("parent_id") or rec.get("parentId")
                    by_parent.setdefault(parent, []).append(rec)
                stack = [(rec, verbatim[0].get("id"), 1) for rec in reversed(by_parent.get(verbatim[0].get("id"), []))]
                while stack:
                    rec, parent_id, depth = stack.pop()
                    completed = _node_is_completed(rec)
                    if completed and not include_completed:
                        continue
                    plan.append({
                        "uuid": str(rec.get("id")), "parent": str(parent_id),
                        "depth": depth, "completed": completed,
                    })
                    stack.extend(
                        (kid, rec.get("id"), depth + 1)
                        for kid in reversed(by_parent.get(rec.get("id"), []))
                    )
        else:
            try:
                plan = _promote_enumerate_subtree(
                    nodes_by_id, src, children=item["children"], include_completed=include_completed
                )
            except ValueError as exc:
                row["status"], row["reason"], row["detail"] = "failed", "subtree_enumeration_failed", str(exc)
                return
        # Reserve a fresh core for the root and for EVERY AP-bearing descendant
        # BEFORE the create, so the payload never carries an old core.
        reserved: dict[str, str] = {}
        committed = False
        try:
            for entry in plan:
                node = source_map[entry["uuid"]]
                raw_name = str(node.get("name") or node.get("nm") or "")
                if entry["depth"] == 0 or _anchor_leading_ap_core(raw_name):
                    reserved[entry["uuid"]] = await _anchor_reserve_ap_core("auto", nodes_by_id=nodes_by_id)
        except _AnchorOperationError as exc:
            for core in reserved.values():
                await _anchor_finish_ap_reservation(core, committed=False)
            row["status"], row["reason"], row["detail"] = "failed", exc.code, exc.message
            return
        except Exception:
            for core in reserved.values():
                await _anchor_finish_ap_reservation(core, committed=False)
            raise
        try:
            # Build the ETCH forest from DECODED cache text (ETCH encodes once).
            forest_index: dict[str, dict[str, Any]] = {}
            want = list(item["tags"])
            for entry in plan:
                node = source_map[entry["uuid"]]
                raw_name_text = str(node.get("name") or node.get("nm") or "")
                raw_note_text = str(node.get("note") or node.get("no") or "")
                if archived is not None:
                    # Archive Reads U2 (§4.6, E7): archive text is
                    # CACHE-SEMANTIC — served verbatim, never re-decoded
                    # through the wire-to-semantic layer.
                    semantic = raw_name_text
                    note = raw_note_text
                else:
                    semantic = _semantic_name_for_tag_merge(raw_name_text)
                    note = _note_wire_to_semantic(raw_note_text)
                parts = _split_leading_ap_handle(semantic)
                new_core = reserved.get(entry["uuid"])
                if new_core:
                    name = f"{parts['decoration']}[ap:{new_core}] {parts['title']}".strip()
                else:
                    name = semantic
                if entry["depth"] == 0:
                    # Managed metadata ([ap:BNNUZ4]): the COPY still lands, but
                    # the '↩ derived from …' line is NOT baked into its note
                    # when the source root's note (which the copy preserves)
                    # carries a recognised managed block. The row's info field
                    # names the kind; row["trail_line"] keeps the would-be line.
                    managed_kind = detect_trail_skip_metadata(note, name=semantic)
                    if managed_kind is not None:
                        row["info"] = (
                            "derived-from line skipped: the note carries managed "
                            f"metadata ({managed_kind})"
                        )
                    else:
                        note = _promote_prepend_trail(row["trail_line"], note)
                    if want:
                        name = _compose_protected_name(
                            current_semantic_name=name, tag_transform=_add_tags_transform(want)
                        )["name"]
                payload: dict[str, Any] = {"name": name, "children": []}
                if note:
                    payload["note"] = note
                layout = _promote_layout_mode(node)
                if layout:
                    payload["layout_mode"] = layout
                forest_index[entry["uuid"]] = payload
                if entry["parent"] is not None:
                    forest_index[entry["parent"]]["children"].append(payload)
            for payload in forest_index.values():
                if not payload["children"]:
                    payload.pop("children")
            root_payload = forest_index[src]
            row["copy"] = {
                "uuid": None, "ap_id": f"[ap:{reserved[src]}]", "expected_nodes": len(plan),
                "nodes_created": 0, "children_copied": item["children"],
                "completed_skipped": None if include_completed else 0,
            }
            if not include_completed:
                if archived is not None:
                    # Archive Reads U2: the verbatim plan already excluded
                    # completed descendants; count them from the records.
                    row["copy"]["completed_skipped"] = (
                        sum(
                            1
                            for rec in verbatim[1:]
                            if _node_is_completed(rec)
                        )
                        if item["children"]
                        else 0
                    )
                else:
                    copied = {entry["uuid"] for entry in plan}
                    row["copy"]["completed_skipped"] = sum(
                        1 for child_id, child in nodes_by_id.items()
                        if str(child.get("parent_id") if "parent_id" in child else child.get("parentId")) in copied
                        and str(child_id) not in copied
                    ) if item["children"] else 0
            try:
                row["writes"] = int(row.get("writes") or 0) + len(plan)
                result = await _node_etch_sync_impl(dest, nodes=[root_payload], _explicit_ap_cores=())
            except CoherenceBarrierActiveError as exc:
                row["status"], row["reason"], row["detail"] = "failed", "coherence_barrier_active", str(exc)
                stopped, stop_reason = True, "coherence_barrier_active"
                mapped_refusal = _mcp_exception_mapper(ANCHOR_REGISTRY.resolve("point.promote"), exc)
                return
            except (MutationSerializationTimeoutError, MutationSerializationConflictError, MutationRegionError):
                raise
            except Exception as exc:  # noqa: BLE001 -- outcome UNKNOWN: never re-send
                row["status"], row["reason"] = "failed", "write_outcome_unknown"
                row["detail"] = (
                    f"copy: {type(exc).__name__}: {exc}. Some nodes may have been created under the "
                    "destination; inspect it (dock.peek) before retrying. The batch stopped."
                )
                stopped, stop_reason = True, "write_outcome_unknown"
                return
            created = int((result or {}).get("nodes_created") or 0) if isinstance(result, dict) else 0
            root_ids = list((result or {}).get("root_node_ids") or []) if isinstance(result, dict) else []
            errors = list((result or {}).get("errors") or []) if isinstance(result, dict) else ["no result"]
            row["copy"]["nodes_created"] = created
            row["copy"]["uuid"] = root_ids[0] if root_ids else None
            committed = created > 0
            if errors or not (isinstance(result, dict) and result.get("success")) or created != len(plan) or len(root_ids) != 1:
                row["status"], row["reason"] = "failed", "copy_incomplete"
                row["detail"] = (
                    f"ETCH created {created} of {len(plan)} node(s) (root {row['copy']['uuid']}); "
                    f"errors: {errors}. The source is untouched; inspect the destination and "
                    "clean up the partial copy before retrying."
                )
                return
            row["tags_applied"] = want
            if include_completed and any(entry["completed"] for entry in plan):
                try:
                    # The acknowledged root is fresh; one same-plane subtree
                    # covers every direct complete_node call, for this phase only.
                    copy_root = root_ids[0]
                    async with mutation_region_locks(
                        client=client, operation_label="anchor.point.promote:recomplete",
                        region_factory=lambda snapshot: (build_region_subtree(copy_root, cache_by_id=snapshot.nodes_by_id),),
                    ):
                        await _recomplete_copies(row, copy_root, plan)
                except CoherenceBarrierActiveError as exc:
                    row["status"], row["reason"], row["detail"] = "failed", "coherence_barrier_active", str(exc)
                    stopped, stop_reason = True, "coherence_barrier_active"
                    mapped_refusal = _mcp_exception_mapper(ANCHOR_REGISTRY.resolve("point.promote"), exc)
                    return
                except (MutationSerializationTimeoutError, MutationSerializationConflictError, MutationRegionError):
                    raise
                except Exception as exc:  # noqa: BLE001 -- a completion write's outcome is unknown
                    row["status"], row["reason"] = "failed", "write_outcome_unknown"
                    row["detail"] = (
                        f"copy created ({row['copy']['uuid']}); re-completing copied nodes: "
                        f"{type(exc).__name__}: {exc}. The batch stopped and nothing was re-sent."
                    )
                    stopped, stop_reason = True, "write_outcome_unknown"
                    return
            row["status"], row["reason"] = "promoted", None
        finally:
            for core in reserved.values():
                await _anchor_finish_ap_reservation(core, committed=committed)

    for row, item in zip(rows, normalized):
        if stopped:
            break
        if row["status"] != "eligible":
            continue
        # The pinned map above is a stable CONTENT plan, never the parentage
        # proof. Every item factory derives its old parent from its argument.
        def item_regions(snapshot):
            destination_regions = _mutation_parent_regions(str(item["dest_uuid"]), snapshot=snapshot)
            if row["mode"] == "derivative":
                return destination_regions
            return (
                build_region_exact_node(str(row["uuid"]), cache_by_id=snapshot.nodes_by_id),
                *_mutation_parent_regions(_pinned_parent_id_for_lock(str(row["uuid"]), snapshot=snapshot), snapshot=snapshot),
                *destination_regions,
            )
        # §6.7 per-item wait attribution (snapshot around the item's writes).
        wait_mark = _mutation_wait_mark()
        try:
            try:
                async with mutation_region_locks(
                    client=client, operation_label="anchor.point.promote:item", region_factory=item_regions,
                ):
                    if row["mode"] == "derivative":
                        await _run_derivative(row, item)
                    else:
                        await _run_move(row, item)
            except (MutationSerializationTimeoutError, MutationSerializationConflictError, MutationRegionError) as exc:
                # CF-04: recorded ON the item as timed-out-before-any-write —
                # never write_outcome_unknown, and it never stops the batch (I7).
                row["status"], row["reason"] = "failed", exc.code
                row["detail"] = str(exc)
                row["error_code"] = exc.code
                row["retry_after"] = exc.retry_after
                row["extra"] = _mutation_refusal_extra(exc)
                continue
        finally:
            item_serialization = _mutation_serialization_field(since=wait_mark)
            if item_serialization is not None:
                row["serialization"] = item_serialization

    ledger = _finish()
    if mapped_refusal is not None:
        mapped_refusal["error"].setdefault("extra", {})["promote"] = ledger
        return mapped_refusal
    return ledger


# @beacon[
#   id=mcp-api@build-anchor-registry,
#   role=ƒ build_anchor_registry(),
#   slice_labels=nexus--mcp-api,nexus--anchors,
#   kind=ast,
#   comment=Assembly point for the public Anchor family: Dock/Point primitives, verified range extraction, peek/render presets, Dock grep and AP-ID allocation. Only dock.render registers include_rows (Boolean default false) and threads it to the ONE public shaper; the shared tail supplies canonical rows/resolved spec without changing the Dock projection or legacy modes. Registry remains the sole dispatch/describe/schema/effects authority.,
# ]
def build_anchor_registry() -> OperationRegistry:
    """Anchor verbs with described text-stage collisions; dock.render alone offers rows."""

    registry = OperationRegistry(
        "anchor",
        (
            "Anchor Dock containers and Anchor Point capture/citation operations. "
            "Dock tags are a family: #‹base› (Dock), #‹base›--local (local), "
            "#‹base›--fav (favorite, ⭐); dock.list defaults to favorites_only=true "
            "(full list when nothing is starred, or favorites_only=false); "
            "#‹base›--deprecated is in the family but is NOT a Dock. "
            "Anchor Points are ordinary Workflowy nodes: anchor.point.read "
            "reads one with a metadata header (AP-ID, title, tags, "
            "⚓/⭐/Ⓛ/✓ markers, ▸N sizes, created/modified, path) and the "
            "shared read guard — numbered line windows "
            "(offset/limit/with_line_numbers) by default, head+tail clamped "
            "like node.read; node.search for line-numbered grep, and "
            "node.edit for note edits. anchor.search greps ONE Dock's "
            "subtree with node.search's machinery and report -- descending "
            "stops at child Docks unless descend_policy='all'. "
            "Use point.extract to move one or several note-line ranges into new "
            "citable points, with all captures acknowledged before source deletion. "
            "A Dock doubles as an ad-hoc to-do list: dock.peek recent=N, "
            "recent_by='created' shows arrivals; recent_by='modified' (default) "
            "shows current attention -- what was worked on or touched most "
            "recently; peek views hide completed items by default, the plain "
            "inventory included (include_completed=true shows them). To choose that view, anchor.point.touch an ordered working set "
            "(first handle = highest priority = newest afterwards; ~1 s per "
            "item) and dock.peek recent=N brings the set back without moving "
            "bullets -- ascending (oldest first) by default, so add "
            "sort_direction='desc' to read it in priority order. Names are "
            "shown in full, tags included. dock.get_description reads one "
            "Dock's description: the anchor.point.read metadata header plus "
            "a 'child docks: N' line, then the full note. Curation pass: "
            "capture everything into a session Dock, then anchor.point.promote the "
            "durable items into their topic Docks in one batch -- each moved node "
            "gains a grep-able '↩ moved from <origin> (<uuid8>) · <date>' trail line "
            "(node.search for it lists every promoted item); mode='derivative' "
            "leaves the source untouched and lands a COPY with fresh AP-IDs ('↩ "
            "derived from …') -- the way to lift reusable knowledge out of sealed "
            "records. Bad items are skipped, good items always land."
            " A note carrying managed metadata (program_interface YAML, "
            "estate payloads, manifests, snapshot/ledger names -- the ONE "
            "inventory in managed_metadata.py) still moves/copies but gains "
            "NO trail line; the result row's info field says so."
            + _ARCHIVE_FAMILY_SENTENCE_SERVER
        ),
        handle_grammar=(
            "dock_handle/node_handle/parent_handle = exact UUID | its 8-hex "
            "first segment | unique longer prefix | "
            "[ap:CORE]; AP-ID resolution is exact whole-core and source symbols are not accepted"
        ),
    )

    def _error(verb: str, exc: "_AnchorOperationError | ProtectedNameViolation") -> dict:
        spec = registry.resolve(verb)
        return make_error(
            family="anchor",
            operation=f"anchor.{verb}",
            code=exc.code,
            message=exc.message,
            extra=exc.extra,
            operation_spec=spec,
        )

    async def _list(params: dict[str, Any]) -> Any:
        # Compact-inventory default flip: the consolidated surface defaults
        # detail to 'compact'; 'full' is the explicit escape hatch.
        detail = params.get("detail") or "compact"
        compact_only = [
            key
            for key in ("show_description", "max_description_chars")
            if key in params
        ]
        if params.get("max_name_chars") is not None:
            compact_only.append("max_name_chars")
        if detail == "full" and compact_only:
            return _error(
                "dock.list",
                _AnchorOperationError(
                    "invalid_parameter_combination",
                    f"{', '.join(compact_only)} are compact-mode knobs; "
                    "omit them or pass detail='compact'.",
                ),
            )
        try:
            # favorites_only is forwarded ONLY when the key is present;
            # otherwise the kwarg is omitted so the impl's default (True) is
            # the single authority (§6.5.3).
            list_kwargs: dict[str, Any] = {}
            if "favorites_only" in params:
                list_kwargs["favorites_only"] = params["favorites_only"]
            return await _anchor_dock_list_impl(
                params.get("include_local", False),
                params.get("target_tab"),
                detail=detail,
                max_chars=params.get("max_name_chars"),
                max_description_chars=params.get("max_description_chars"),
                show_description=params.get("show_description", True),
                **list_kwargs,
            )
        except _AnchorOperationError as exc:
            return _error("dock.list", exc)

