    async def _peek(params: dict[str, Any]) -> Any:
        # Compact-inventory default flip: the consolidated surface defaults
        # detail to 'compact'; 'full' is the explicit escape hatch.
        detail = params.get("detail") or "compact"
        compact_only = [
            key
            for key in ("show_ids", "show_counts", "show_description")
            if key in params
        ]
        if params.get("max_name_chars") is not None:
            compact_only.append("max_name_chars")
        if detail == "full" and compact_only:
            return _error(
                "dock.peek",
                _AnchorOperationError(
                    "invalid_parameter_combination",
                    f"{', '.join(compact_only)} are compact-mode knobs; omit them or pass detail='compact'.",
                ),
            )
        try:
            return await _anchor_dock_peek_impl(
                params["dock_handle"],
                params.get("target_tab"),
                detail=detail,
                show_ids=params.get("show_ids", False),
                show_counts=params.get("show_counts", True),
                show_description=params.get("show_description", True),
                max_chars=params.get("max_name_chars"),
                recursive=params.get("recursive", False),
                descend_policy=params.get("descend_policy", "stop_at_child_anchors"),
                recent=params.get("recent"),
                recent_by=params.get("recent_by"),
                sort_by=params.get("sort_by"),
                sort_direction=params.get("sort_direction"),
                include_completed=params.get("include_completed", False),
            )
        except _AnchorOperationError as exc:
            return _error("dock.peek", exc)

    async def _render(params: dict[str, Any]) -> Any:
        # [ap:TVIIBN] 4d(a): the public sort_direction rule (loud, never a
        # silent no-op) -- checked on the RAW params before any live work.
        _sd_msg = _render_sort_direction_message(params)
        if _sd_msg:
            return _error(
                "dock.render",
                _AnchorOperationError(_SORT_DIRECTION_WITHOUT_SORT_BY_ERROR, _sd_msg),
            )
        try:
            result = await _anchor_dock_render_impl(
                params["dock_handle"],
                sort_by=params.get("sort_by"),
                sort_direction=params.get("sort_direction", "asc"),
                recent=params.get("recent"),
                recent_by=params.get("recent_by"),
                headings_only=params.get("headings_only", False),
                as_markdown=params.get("as_markdown", True),
                output_file=params.get("output_file"),
                push_to_modal=params.get("push_to_modal", False),
                target_tab=params.get("target_tab"),
                # [ap:EPR86W] part a: the traversal pair, dock.peek's names
                # and values; render's defaults (recursive true,
                # stop_at_child_anchors) live in the impl signature.
                recursive=bool(params.get("recursive", True)),
                descend_policy=params.get("descend_policy", "stop_at_child_anchors"),
                ancestor_notes=bool(params.get("ancestor_notes", False)),
                full_uuids=bool(params.get("full_uuids", False)),
            )
        except _AnchorOperationError as exc:
            return _error("dock.render", exc)
        # Same agent-facing shaping the GLIMPSE family applies: Markdown mode
        # (the default) returns the rendered string raw; output_file returns
        # the write summary; as_markdown=False returns the structured dict.
        # include_rows wraps only successful in-memory Markdown, using the
        # SAME resolved raw-root spec supplied privately by the shared tail.
        return _shape_glimpse_family_return(
            result,
            output_file=params.get("output_file"),
            headings_only=params.get("headings_only", False),
            include_rows=params.get("include_rows", False),
        )

