    async def _touch(params: dict[str, Any]) -> dict:
        try:
            ledger = await _anchor_point_touch_impl(
                params["handles"],
                allow_docks=params.get("allow_docks", False),
                target_tab=params.get("target_tab"),
            )
        except _AnchorOperationError as exc:
            return _error("point.touch", exc)
        if isinstance(ledger, dict) and "error" in ledger and ledger.get("success") is False:
            # Mid-batch typed coherence refusal: universal envelope, ledger
            # under error.extra.touch (extract parity).
            return ledger
        ack = make_mutation_ack(
            operation="anchor.point.touch",
            result=ledger,
            changed=bool(ledger.get("changed")),
            warnings=ledger.get("warnings") or (),
        )
        ack["partial_success"] = bool(ledger.get("partial_success"))
        return ack

