        try:
            ledger = await _anchor_point_promote_impl(
                items=params.get("items"),
                handles=params.get("handles"),
                destination=params.get("destination"),
                tags=params.get("tags"),
                mode=params.get("mode"),
                children=params.get("children"),
                include_completed=params.get("include_completed", False),
                target_tab=params.get("target_tab"),
            )
        except _AnchorOperationError as exc:
            return _error("point.promote", exc)
        if isinstance(ledger, dict) and "error" in ledger and ledger.get("success") is False:
            # Mid-batch typed coherence refusal: universal envelope, ledger
            # under error.extra.promote (touch/extract parity).
            return ledger
        ack = make_mutation_ack(
            operation="anchor.point.promote",
            result=ledger,
            changed=bool(ledger.get("changed")),
            warnings=ledger.get("warnings") or (),
        )
        ack["partial_success"] = bool(ledger.get("partial_success"))
        return ack

