            params_schema={"type":"object","properties":{"lens":{"type":["object","string"],"description":"Top-level recursive LensSpec merge. Operations are union, intersection, and ordered difference (first input minus every later input; result is always a subset of the first input). For a true symmetric difference, compose: difference(union(A,B), intersection(A,B))."},"tag":{"type":"string","description":"Exactly one base target family; optional leading #; no live operation-postfix tail."},"group_name":{"type":["string","null"],"description":"Generated group name; defaults to the normalized base tag."},"group_description":{"type":["string","null"],"description":"Explicit description; when omitted, new groups get a recipe summary and exact reuse preserves the existing description."},"make_active":{"type":"boolean"},"execution":{"type":"string","enum":["sync","async"]},"target_tab":string_null},"required":["lens","tag"],"additionalProperties":False},
            returns={"description":"Job envelope or standardized acknowledgement with complete plan, Q4 ledger, verification, and T1/T2 identity reports."},
