# @beacon[
#   id=mcp-api@render-family-result-or-error,
#   role=_render_family_result_or_error(registry, verb, result),
#   slice_labels=nexus--mcp-api,glimpse-render,
#   kind=ast,
#   comment=Shared render-family error boundary. Successes pass through byte-identically; success:false retains the whole payload under error.extra.legacy_result and honors a string code only when that operation declares it, otherwise the historical family failure code. No changed execution/admission path.,
# ]
def _render_family_result_or_error(
    registry: OperationRegistry, verb: str, result: Any
) -> Any:
    """Standardize expected legacy render failures without touching success."""

    if not isinstance(result, dict) or result.get("success") is not False:
        return result
    spec = registry.resolve(verb)
    code = (
        "glimpse_request_failed"
        if registry.family == "glimpse"
        else "lightning_request_failed"
    )
    legacy_error = result.get("error")
    declared = result.get("code")
    # REPOSITORY VIEW (U1, §3.3): THE VIEW'S OWN refusal is honored with its
    # exact kernel-owned code (make_error accepts kernel codes regardless of
    # the operation's declaration). Marker-gated on purpose (A2): every
    # other handler result -- including the pre-existing refusals that
    # already declare this same string -- keeps today's envelope exactly.
    if isinstance(declared, str) and (
        (spec is not None and declared in spec.domain_error_codes)
        or (
            declared == _REPOSITORY_VIEW_REFUSAL_ERROR
            and result.get("repository_view_refusal") is True
        )
    ):
        code = declared
    if isinstance(legacy_error, dict):
        message = str(legacy_error.get("message") or legacy_error)
    else:
        message = str(legacy_error or f"{registry.family}.{verb} request failed")
    return make_error(
        family=registry.family,
        operation=f"{registry.family}.{verb}",
        code=code,
        message=message,
        extra={"legacy_result": result},
        operation_spec=spec,
    )


