# @beacon[
#   id=coherence@mcp-operation-boundary,
#   slice_labels=ra-coherence,ra-workflowy-cache,mci-cache-seams,
#   kind=ast,
#   comment=MCP cache-backed handler boundary factory: lifecycle operation accounting spans the same ONE cache adoption through final reset and reuses this task's admitted token; cache-free specs never enter this factory and no active controller means pass-through.,
# ]
def _mcp_operation_boundary(canonical_name: str):
    """S03 §7.1: the ONE local-capture boundary per cache-backed public op.

    Injected into :func:`dispatch_operation` by every family front; the
    dispatch kernel wraps only the handler invocation of a ``cache_backed``
    spec in it.  Cache-free operations never touch this factory.
    Lifetime accounting is outside the existing adoption/reset, not another
    cache boundary or a new mutation/region authority.
    """

    from .coherence.operation_cache import cache_operation_boundary

    client = get_client()
    @asynccontextmanager
    async def accounted():
        async with daemon_lifecycle.operation_accounting(canonical_name), cache_operation_boundary(client, canonical_name) as snapshot:
            yield snapshot
    return accounted()


# @beacon[
#   id=mcp-api@coherence-dispatch-hooks,
#   role=S04 coherence dispatch hooks,
#   slice_labels=nexus--mcp-api,ra-coherence,
#   kind=ast,
#   comment=S04 MCP dispatch hooks injected into every family front: result finalizer applies the ONE standardized hard-barrier read advisory to cache-backed read-safe non-render-family results (render families are covered at their internal cache-render seams, which also covers modal delivery); mutation admission classifies each spec and runs the fresh LOCKED hard-stop gate only for refuse-class operations, returning the universal coherence_barrier_active envelope; the exception mapper keeps typed coherence refusals from collapsing into operation_failed. 23db916f: the finalizer ALSO drains the per-operation handle-correction echo state first (handle_corrections) and applies it to EVERY family -- one 'resolved: <short> <name> (corrected from <supplied>)' line prefixed to string results, a top-level resolved_corrections list on dict results -- BEFORE the advisory, so a prefixed result reads advisory -> correction line -> body; the render-family and cache-back guards govern only the advisory, never the echo.,
# ]
def _apply_handle_correction_echo(result: Any) -> Any:
    """23db916f: surface this operation's recorded handle-correction records.

    A string result gains one short ``resolved: ‹short› ‹name› (corrected
    from ‹supplied›)`` line per correction, prefixed ABOVE the body (and
    below the coherence advisory, which this finalizer applies after it). A
    dict result gains a top-level ``resolved_corrections`` list. Operations
    that recorded nothing — the common case — and results of any other shape
    are returned byte-identically.
    """

    corrections = drain_handle_corrections()
    if not corrections:
        return result
    if isinstance(result, str):
        prefix = "".join(
            format_handle_correction_line(correction) + "\n"
            for correction in corrections
        )
        return prefix + result
    if isinstance(result, dict):
        existing = result.get("resolved_corrections")
        merged = list(existing) if isinstance(existing, list) else []
        merged.extend(corrections)
        return {**result, "resolved_corrections": merged}
    return result


def _apply_archive_banner(result: Any) -> Any:
    """Archive Reads U2 (§5.1): drain this operation's archive-answered
    handles into the result, as the finalizer's LAST step so the banner is
    the FIRST line of the output — above the coherence read advisory and
    above every ``resolved:`` correction line.

    A string result gains the banner line(s), each followed by ``\\n``,
    prefixed above everything else (one line per archive file that answered
    at least one handle, in first-answered order).  A dict result gains
    ``archive_warning`` (the lines joined by ``\\n``) and ``archived`` (the
    answered handles, in first-answered order, each with ``handle, uuid,
    archive_file, archive_name, exported_at, archive_root``).  A pydantic
    MODEL result (Chain-1 W1: the archived structured ``node.read``) is
    delivered as its own field mapping plus the same two keys.  No archive
    answered, no context, or any other result shape: byte-identical return.
    """

    from .archive_context import current_archive_context
    from .archive_texts import banner_line

    context = current_archive_context()
    if context is None or context.state is None:
        return result
    served = context.state.served
    if not served:
        return result
    lines: "list[str]" = []
    seen_files: "set[str]" = set()
    for entry in served:
        if entry.archive_file in seen_files:
            continue
        seen_files.add(entry.archive_file)
        lines.append(banner_line(entry.archive_file, entry.exported_at))
    if isinstance(result, str):
        return "".join(line + "\n" for line in lines) + result
    if isinstance(result, dict):
        return {
            **result,
            "archive_warning": "\n".join(lines),
            "archived": [
                {
                    "handle": entry.handle,
                    "uuid": entry.uuid,
                    "archive_file": entry.archive_file,
                    "archive_name": entry.archive_name,
                    "exported_at": entry.exported_at,
                    "archive_root": entry.archive_root,
                }
                for entry in served
            ],
        }
    # Chain-1 W1 (F1): an archive-answered STRUCTURED read (node.read with
    # as_raw_node=false delivers a WorkFlowyNode model) must carry the
    # warning and the provenance too — the emoji alone proves nothing (E30).
    # The model is delivered as its own field mapping plus the same two keys
    # a dict result gains, so the archived structured result keeps the
    # node's shape and gains the §5.1 story; a LIVE structured read (nothing
    # served, the common case) never reaches this branch and keeps the
    # model object byte-identically.
    if isinstance(result, BaseModel):
        payload = result.model_dump(mode="json", by_alias=True)
        payload["archive_warning"] = "\n".join(lines)
        payload["archived"] = [
            {
                "handle": entry.handle,
                "uuid": entry.uuid,
                "archive_file": entry.archive_file,
                "archive_name": entry.archive_name,
                "exported_at": entry.exported_at,
                "archive_root": entry.archive_root,
            }
            for entry in served
        ]
        return payload
    return result


# The 16 verbs that carry ``include_archives`` in their schema (§U3.2 D1).
# The §5.5 footer is THEIR success-shape signal when the flag is off.
_ARCHIVE_FLAG_VERBS = frozenset(
    {
        "node.search",
        "node.scry",
        "anchor.search",
        "anchor.dock.peek",
        "anchor.dock.render",
        "anchor.dock.list",
        "slice_group.render",
        "slice_group.sift",
        "slice_group.merge.render",
        "glimpse.run",
        "glimpse.estate",
        "lightning_rod.gather",
        "lightning_rod.render_tags",
        "lightning_rod.render_search",
        "lightning_rod.render_nodes",
        "lightning_rod.render_symbols",
    }
)


def _archive_left_out_count(overlay: Any, state: Any) -> int:
    """§5.5's ``{n}``: the active/orphaned archives "under this scope".

    Chain basis (E16): an archive counts when its planted-parent chain
    (the planted parent and every ancestor, live or archived — precomputed
    per overlay as ``planted_chains``) contains one of the operation's
    recorded scope roots.  Vault-wide scope (``anchor.dock.list``): every
    active/orphaned archive.  An orphan (no planted parent) therefore only
    ever counts for a vault-wide scope.
    """

    active_states = ("active", "orphaned")
    if getattr(state, "vault_scope", False):
        return sum(
            1 for entry in overlay.files if entry.state in active_states
        )
    roots = set(state.scope_roots)
    if not roots:
        return 0
    count = 0
    for entry in overlay.files:
        if entry.state not in active_states:
            continue
        chain = overlay.planted_chains.get(entry.path) or frozenset()
        if roots & set(chain):
            count += 1
    return count


def _apply_archive_footer(spec: Any, result: Any) -> Any:
    """Archive Reads U3 (§5.5): the "left out" footer.

    Composed when the operation ran in ``fallback`` mode (the flag was off
    — never after an include run, where nothing was left out), the verb is
    one of the 16 flag verbs, and the result is a SUCCESS: ``{n}`` counts
    the active/orphaned archives planted under the operation's recorded
    scope roots (E16), from the overlay for the operation's live view.
    String results gain ``\\n`` + the footer as the LAST line; dict results
    gain a top-level ``archives_left_out: {"count", "line"}``.  Every other
    shape, ``n == 0``, or no overlay: byte-identical return.
    """

    from .archive_context import ARCHIVE_MODE_FALLBACK, current_archive_context
    from .archive_store import get_archive_store
    from .archive_texts import archives_left_out_footer
    from .coherence.operation_cache import current_operation_cache

    if getattr(spec, "canonical_name", "") not in _ARCHIVE_FLAG_VERBS:
        return result
    context = current_archive_context()
    if context is None or context.mode != ARCHIVE_MODE_FALLBACK:
        return result
    if isinstance(result, dict) and (
        result.get("success") is False or "error" in result
    ):
        return result
    try:
        snapshot = current_operation_cache()
        overlay = get_archive_store().overlay_for(snapshot.view)
    except Exception:  # noqa: BLE001 - the footer never raises
        return result
    if overlay is None:
        return result
    count = _archive_left_out_count(overlay, context.state)
    if count <= 0:
        return result
    line = archives_left_out_footer(count)
    if isinstance(result, str):
        return result + "\n" + line
    if isinstance(result, dict):
        return {**result, "archives_left_out": {"count": count, "line": line}}
    return result


# @beacon[
#   id=mcp-api@mcp-operation-result-finalizer,
#   role=_mcp_operation_result_finalizer(spec, result),
#   slice_labels=nexus--mcp-api,ra-coherence,
#   kind=ast,
#   comment=S04 §7.5 MCP result finalizer + Archive Reads U2 banner order + U3 footer: the coherence layers run first (handle-correction echo, then the ONE hard-barrier read advisory on cache-backed read-safe non-render results), then the archive steps — the §5.5 FOOTER first (fallback-mode success of one of the 16 flag verbs: \n + the line as the LAST string line, archives_left_out on dicts, counted from the overlay's precomputed planted chains), and the ARCHIVE BANNER drains LAST (§5.1), applied as the finalizer's final step so the ⚠️⚠️⚠️ ARCHIVED NODE line is the FIRST line of the result, above the advisory and above every resolved: correction line, on EVERY family (the two render families included: their internal seams advise, the banner still drains here). Strings gain the banner line(s) (one per archive file that answered, first-answered order) prefixed above the body; dicts gain archive_warning + archived; a PYDANTIC MODEL result (Chain-1 W1/F1: the archived structured node.read) is delivered as its own by-alias field mapping plus the same two keys, so an archive-answered structured read can never escape the warning; operations where no archive answered and nothing was left out are byte-identical.,
# ]
def _mcp_operation_result_finalizer(spec: Any, result: Any) -> Any:
    """S04 §7.5: the MCP read-advisory finalizer (post-handler, in-boundary).

    The two render families (glimpse, lightning_rod) are advised at their
    internal cache-render seams — which also covers modal delivery and
    output-file writing — so the live-DOM GLIMPSE (a pure live read) is
    never mis-advised.  Mutation results, error envelopes, and cache-free
    operations are untouched by the advisory.  The advisory consumes ONLY the
    operation's captured boundary status (H4) and is byte-identical when clean.

    U01 §6.7 mutation branch: a mutation result whose task WAITED on a
    contended node lock says so — top-level ``serialization:
    {waited_seconds, waited_on}`` on dict results (every make_mutation_ack
    result and every batch reply). String results (node.edit's note-edit
    report) are left byte-identical here; that path carries the field inside
    its JSON metadata header, emitted where the report metadata is built in
    _node_edit_core. Absent when uncontended — the uncontended wire shape is
    byte-identical to before this unit (§10). The wait record lives on this
    task's MUTATION_LOCK_STATE and the finalizer runs in-boundary on the same
    task, so it sees exactly this operation's waits.

    23db916f handle-correction echo: applied FIRST, to every family (the two
    render families' coherence-advisory skip below is untouched), so a
    shaved-prefix correction is visible on read, render and mutation results
    alike — one ``resolved: …`` line on strings, ``resolved_corrections`` on
    dicts — and never on an exact match.

    Archive Reads U2 (§5.1): the archive banner drains LAST, so the
    ``⚠️⚠️⚠️ ARCHIVED NODE`` line is the FIRST line of any result an archive
    answered — above the advisory and above every correction line — on every
    family; operations where no archive answered are byte-identical.
    """

    result = _apply_handle_correction_echo(result)

    if spec.family in ("glimpse", "lightning_rod"):
        return _apply_archive_banner(_apply_archive_footer(spec, result))
    if not spec.cache_backed:
        return _apply_archive_banner(_apply_archive_footer(spec, result))
    if set(spec.side_effects) - {"pure_read", "render", "modal_push", "artifact_write"}:
        if "workflowy_mutation" in spec.side_effects and isinstance(result, dict):
            serialization = _mutation_serialization_field()
            if serialization is not None and "serialization" not in result:
                result = {**result, "serialization": serialization}
        return _apply_archive_banner(_apply_archive_footer(spec, result))
    from .coherence.read_advisory import apply_coherence_read_advisory

    return _apply_archive_banner(
        _apply_archive_footer(spec, apply_coherence_read_advisory(result))
    )


async def _mcp_mutation_admission(spec: Any) -> Any:
    """S04 §7.2: the MCP hard-stop mutation-admission gate.

    Classification is lock-free; only refuse-class operations pay the fresh
    LOCKED hard-stop read (§7.6).  Returns None to proceed, or the
    universal ``coherence_barrier_active`` refusal envelope.
    """

    from .coherence.admission import (
        ADMISSION_CLASS_REFUSE_HARD_DIRT,
        mutation_admission_class,
        require_coherence_mutation_admission,
    )
    from .coherence.errors import CoherenceBarrierActiveError

    if (
        mutation_admission_class(
            spec.canonical_name, spec.side_effects, spec.cache_backed
        )
        != ADMISSION_CLASS_REFUSE_HARD_DIRT
    ):
        return None
    try:
        await require_coherence_mutation_admission(
            _admission_coherence_paths, operation=spec.canonical_name
        )
    except CoherenceBarrierActiveError as exc:
        return _coherence_refusal_envelope(spec, exc)
    return None


def _coherence_refusal_envelope(spec: Any, exc: Any) -> dict:
    """The §7.1 universal hard-barrier refusal envelope for one operation."""

    return make_error(
        family=spec.family,
        operation=spec.canonical_name,
        code="coherence_barrier_active",
        message=str(exc),
        extra=exc.refusal_extra(),
        operation_spec=spec,
    )


def _mcp_exception_mapper(spec: Any, exc: BaseException) -> Any:
    """Map typed coherence/plane refusals and live collisions without laundering."""

    from .coherence.errors import CoherenceBarrierActiveError

    if isinstance(exc, CoherenceBarrierActiveError):
        return _coherence_refusal_envelope(spec, exc)
    if isinstance(exc, ConcurrentEditDetectedError):
        return make_error(
            family=spec.family, operation=spec.canonical_name,
            code=ConcurrentEditDetectedError.code, message=str(exc),
            extra=_mutation_refusal_extra(exc), operation_spec=spec,
        )
    # U01 §5/§6.6 (A4): the bounded-wait refusal rides the SAME make_error
    # envelope as every other domain error — never a bespoke dict in an impl.
    # Consumers read error.code and error.extra.retry_after; the code is
    # declared in every affected verb's domain_error_codes (an undeclared
    # code would raise OperationSpecError right here — the mechanical check).
    if isinstance(exc, (MutationSerializationTimeoutError, MutationSerializationConflictError, MutationRegionError)):
        return make_error(
            family=spec.family,
            operation=spec.canonical_name,
            code=exc.code,
            message=str(exc),
            extra=_mutation_refusal_extra(exc),
            operation_spec=spec,
        )
    # Archive Reads U2 (§4.7.3): the archive read-only refusal rides the
    # SAME universal envelope — code archived_node_read_only, the exact
    # §5.2–§5.3 text, the record's provenance in error.extra.
    from .archive_context import ArchivedNodeReadOnlyError

    if isinstance(exc, ArchivedNodeReadOnlyError):
        return make_error(
            family=spec.family,
            operation=spec.canonical_name,
            code=ArchivedNodeReadOnlyError.code,
            message=str(exc),
            extra=dict(exc.extra or {}),
            operation_spec=spec,
        )
    return None


# ---------------------------------------------------------------------------
# Archive Reads (U1/U2) — the per-operation archive decision and the invoker
# ---------------------------------------------------------------------------

# U2 (§U2.2 deliverable 1): the automatic fallback is ON — a read operation
# runs mode ``fallback`` and the §4.5 re-run serves archive-answered handles.
# ``include`` arises only when the params carry ``include_archives: true``,
# which no schema allows until Unit 3 (tests call the invoker directly).
_ARCHIVE_FALLBACK_ENABLED = True

# §1.4: the read-operation deny list (never archive-served).
_ARCHIVE_READ_DENY_LIST = frozenset(
    {"node.export", "tag.purge.preview", "slice_group.purge.preview"}
)

_ARCHIVE_READ_SAFE_EFFECTS = frozenset(
    {"pure_read", "render", "modal_push", "artifact_write"}
)


class _ArchiveFlagRefusal(ValueError):
    """§5.9: a refused ``include_archives`` combination.

    Raised by :func:`_archive_mode_for` BEFORE any handler work; the
    invoker shapes it into the universal ``invalid_parameter_combination``
    envelope (a kernel-owned code, so no per-verb domain-code change).
    """


def _archive_flag_refusal_text(
    canonical: str, params: dict[str, Any]
) -> "str | None":
    """The §5.9 refusal message for one flag combination, or None.

    ``output_file`` is checked before ``push_to_modal`` (the order §5.9
    lists them in); ``glimpse.run`` refuses when no server-side scope is
    present.  Only ever called with ``include_archives`` true.
    """

    from .archive_texts import (
        flag_needs_scope_refusal_text,
        flag_output_file_refusal_text,
        flag_push_to_modal_refusal_text,
    )

    if params.get("output_file") not in (None, ""):
        return flag_output_file_refusal_text()
    if params.get("push_to_modal") is True:
        return flag_push_to_modal_refusal_text()
    # REPOSITORY VIEW (U1, MasterSpec §3.3): the one §3.3 refusal that must
    # fire BEFORE the archive invoker consumes ``include_archives`` (handlers
    # never see the flag), shaped into the same universal envelope here.
    if params.get("repository_view") and params.get("include_archives") is True:
        return (
            "repository_view=true renders a stable document from live mapped "
            "source, so include_archives=true (planting archived subtrees "
            "into the render) cannot combine with it. Drop include_archives."
        )
    if canonical == "glimpse.run" and not (
        params.get("root_handle")
        or params.get("group_handle")
        or params.get("render_spec")
    ):
        return flag_needs_scope_refusal_text()
    return None


def _archive_mode_for(spec: Any, params: Any) -> "tuple[str, str | None]":
    """The per-operation archive decision (§4.3.2) — computed once per call,
    before the handler runs.

    ``read`` = cache_backed, declared side effects read-safe, family not
    beacon/system, canonical name not on the deny list (§1.4).  ``sink`` =
    a non-blank ``output_file`` or ``push_to_modal: true``.  Returns
    ``(mode, reason)``: ``include`` (flag, reads only), ``fallback`` (a
    read without a sink), or ``none`` with the reason why (write ·
    export · purge_preview · beacon · system · sink).

    U3 (§5.9): a refused ``include_archives`` combination raises
    :class:`_ArchiveFlagRefusal` BEFORE any handler work — flag with
    ``output_file``, flag with ``push_to_modal``, or ``glimpse.run`` with
    the flag and no server-side scope.  The invoker shapes the raise into
    the universal ``invalid_parameter_combination`` envelope.
    """
    family = getattr(spec, "family", "")
    canonical = getattr(spec, "canonical_name", "")
    if family == "beacon":
        return "none", "beacon"
    if family == "system":
        return "none", "system"
    if canonical == "node.export":
        return "none", "export"
    if canonical in ("tag.purge.preview", "slice_group.purge.preview"):
        return "none", "purge_preview"
    if not getattr(spec, "cache_backed", False):
        return "none", "write"
    if set(getattr(spec, "side_effects", ()) or ()) - _ARCHIVE_READ_SAFE_EFFECTS:
        return "none", "write"
    if params.get("include_archives") is True:
        # §5.9 — the refused combinations are checked FIRST, before the
        # include decision ("refused first if sink", §4.3.2).  Only reads
        # carry schemas with the flag, so reaching here means a read.
        refusal = _archive_flag_refusal_text(canonical, params)
        if refusal is not None:
            raise _ArchiveFlagRefusal(refusal)
        return "include", "flag"
    if (params.get("output_file") not in (None, "")) or (
        params.get("push_to_modal") is True
    ):
        return "none", "sink"
    if _ARCHIVE_FALLBACK_ENABLED:
        return "fallback", None
    return "none", None


# @beacon[
#   id=nexus-archives@mcp-archive-operation-invoker,
#   role=⚡ _mcp_archive_operation_invoker(spec, normalized_params, invoke),
#   slice_labels=nexus--archives,nexus--mcp-api,
#   kind=ast,
#   comment=THE injected operation_invoker every family front passes to dispatch_operation (§4.3): classifies the operation ONCE per call with _archive_mode_for (include on include_archives:true for reads; fallback for reads — ON since U2 (_ARCHIVE_FALLBACK_ENABLED); none with reason write/export/purge_preview/beacon/system/sink otherwise; U3 §5.9: a refused flag combination — with output_file, with push_to_modal, or glimpse.run with no server-side scope — raises BEFORE any handler work and returns the universal invalid_parameter_combination envelope), consumes the flag so handlers never see it, and runs the handler inside archive_operation_scope — include installs the augmented snapshot when the store has a visible record (byte-identical when none), fallback/none run on the live view carrying the decision for the gate and the miss texts. A fallback run whose gate requested it re-runs the handler EXACTLY once, augmented, reason 'automatic', corrections reset, first outcome (return or exception) discarded (§4.5).,
# ]
async def _mcp_archive_operation_invoker(
    spec: Any, normalized_params: dict, invoke: Any
) -> Any:
    """The injected ``operation_invoker`` (§4.3.2–§4.3.3, §4.5).

    Consumes ``include_archives`` (handlers never see it), classifies the
    operation once, and runs the handler inside an
    :func:`archive_operation_scope` context: ``include`` installs the
    augmented snapshot when the store has a visible record (byte-identical
    when it has none); ``fallback`` and ``none`` run on the live view with
    the decision carried for the gate and the miss texts.  A ``fallback``
    run whose gate requested a re-run runs the handler EXACTLY once more,
    augmented, and returns only the second outcome (§4.5).
    """
    from .archive_context import (
        ARCHIVE_MODE_FALLBACK,
        ARCHIVE_MODE_INCLUDE,
        ARCHIVE_MODE_NONE,
        ArchiveOperationContext,
        ArchiveOperationState,
    )
    from .archive_store import get_archive_store
    from .coherence.operation_cache import (
        archive_operation_scope,
        current_operation_cache,
    )

    if not getattr(spec, "cache_backed", False):
        # No snapshot exists for a non-cache_backed spec: just invoke.
        return await invoke()

    try:
        mode, reason = _archive_mode_for(spec, normalized_params)
    except _ArchiveFlagRefusal as exc:
        # §5.9: the refused combination shapes the universal envelope and
        # returns BEFORE any handler work (no boundary work, no handler,
        # no finalizer — the refusal is a validation outcome).
        return make_error(
            family=spec.family,
            operation=spec.canonical_name,
            code="invalid_parameter_combination",
            message=str(exc),
            operation_spec=spec,
        )
    # The flag is consumed here; handlers never see it (Unit 3 adds it to
    # the schemas).
    normalized_params.pop("include_archives", None)

    if mode == ARCHIVE_MODE_INCLUDE:
        snapshot = current_operation_cache()
        overlay = get_archive_store().overlay_for(snapshot.view)
        if overlay is None:
            # Nothing visible: run exactly as mode none/reason flag —
            # byte-identical, no footer either (§4.3.3).
            context = ArchiveOperationContext(
                mode=ARCHIVE_MODE_NONE,
                reason="flag",
                overlay=None,
                state=ArchiveOperationState(),
                operation=spec.canonical_name,
            )
            with archive_operation_scope(context):
                return await invoke()
        context = ArchiveOperationContext(
            mode=ARCHIVE_MODE_INCLUDE,
            reason="flag",
            overlay=overlay,
            state=ArchiveOperationState(),
            operation=spec.canonical_name,
        )
        with archive_operation_scope(context, view=overlay.augmented_view):
            return await invoke()

    if mode == ARCHIVE_MODE_FALLBACK:
        state = ArchiveOperationState()
        context = ArchiveOperationContext(
            mode=ARCHIVE_MODE_FALLBACK,
            reason=reason,
            overlay=None,
            state=state,
            operation=spec.canonical_name,
        )
        first_outcome: Any = None
        first_error: "BaseException | None" = None
        try:
            with archive_operation_scope(context):
                first_outcome = await invoke()
        except Exception as exc:  # noqa: BLE001 - the re-run decision comes first
            first_error = exc
        if not state.rerun_requested:
            if first_error is not None:
                raise first_error
            return first_outcome
        snapshot = current_operation_cache()
        overlay = get_archive_store().overlay_for(snapshot.view)
        if overlay is None:
            # The archive vanished between the gate and now: the first
            # outcome stands unchanged (§4.5 step 1).
            if first_error is not None:
                raise first_error
            return first_outcome
        from .handle_corrections import reset_handle_corrections

        reset_handle_corrections()
        rerun_context = ArchiveOperationContext(
            mode=ARCHIVE_MODE_INCLUDE,
            reason="automatic",
            overlay=overlay,
            state=ArchiveOperationState(),
            operation=spec.canonical_name,
        )
        with archive_operation_scope(rerun_context, view=overlay.augmented_view):
            return await invoke()

    context = ArchiveOperationContext(
        mode=ARCHIVE_MODE_NONE,
        reason=reason,
        overlay=None,
        state=ArchiveOperationState(),
        operation=spec.canonical_name,
    )
    with archive_operation_scope(context):
        return await invoke()


# @beacon[
#   id=mcp-api@glimpse-family-tool,
#   role=glimpse_family_tool(verb, params),
#   slice_labels=nexus--mcp-api,live-dom,
#   kind=ast,
#   comment=UNREGISTERED S09 progressive-disclosure wrapper. This is the only family allowed to normalize an absent or blank verb to run, preserving both bare live-DOM GLIMPSE and verb-less params-only calls without weakening the strict shared dispatcher.,
# ]
async def glimpse_family_tool(
    verb: Any = None, params: dict | str | None = None
) -> Any:
    """Dispatch progressive-disclosure GLIMPSE; unregistered until S10."""

    route = "run" if verb is None or (isinstance(verb, str) and not verb.strip()) else verb
    return await dispatch_operation(
        GLIMPSE_REGISTRY,
        route,
        params,
        error_logger=log_event,
        operation_boundary=_mcp_operation_boundary,
        mutation_admission=_mcp_mutation_admission,
        exception_mapper=_mcp_exception_mapper,
        result_finalizer=_mcp_operation_result_finalizer,
        operation_invoker=_mcp_archive_operation_invoker,
    )


# @beacon[
#   id=mcp-api@lightning-rod-family-tool,
#   role=lightning_rod_family_tool(verb, params),
#   slice_labels=nexus--mcp-api,
#   kind=ast,
#   comment=UNREGISTERED S09 render-only progressive-disclosure wrapper. Missing and unknown-operation teaching appends the registry-owned relocation summary so retired mutation names point to tag.batch and beacon.tags.ensure/remove without registering hidden operations.,
# ]
async def lightning_rod_family_tool(
    verb: Any = None, params: dict | str | None = None
) -> Any:
    """Dispatch render-only Lightning Rod; unregistered until S10."""

    result = await dispatch_operation(
        LIGHTNING_ROD_REGISTRY,
        verb,
        params,
        error_logger=log_event,
        operation_boundary=_mcp_operation_boundary,
        mutation_admission=_mcp_mutation_admission,
        exception_mapper=_mcp_exception_mapper,
        result_finalizer=_mcp_operation_result_finalizer,
        operation_invoker=_mcp_archive_operation_invoker,
    )
    if not isinstance(result, dict) or result.get("success") is not False:
        return result
    error = result.get("error")
    if not isinstance(error, dict) or error.get("code") not in {
        "missing_verb",
        "unknown_operation",
    }:
        return result
    updated = dict(result)
    updated_error = dict(error)
    updated_error["message"] = (
        str(updated_error.get("message") or "")
        + "\n"
        + LIGHTNING_ROD_REGISTRY.family_summary
    )
    updated["error"] = updated_error
    return updated


