# @beacon[
#   id=auto-beacon@_read_text_snippet_result_impl-x7qa,
#   role=⚡ _read_text_snippet_result_impl(input_str: str, context: int),
#   slice_labels=nexus-md-header-path,ra-snippet-range,ra-reconcile,ra-read-text-snippet,handle-resolution,nexus--mcp-api,
#   kind=ast,
#   comment=One snippet-resolution body preserves true unresolved UUID fallback and lazy symbol-only suppression, but a Layer-4 typed extraction failure after successful identity resolution propagates file/id/candidates directly with no UUID-text symbol search or additional suppress-list read.,
# ]
async def _read_text_snippet_result_impl(
    input_str: str,
    context: int,
    *,
    explicit_uuid: bool = False,
) -> dict[str, Any]:
    """Shared resolution body for beacon.snippet and the legacy snippet tools.

    Routing:
    - explicit_uuid=False (read_text_snippet, auto mode): UUID-looking input
      goes to beacon_get_code_snippet; non-UUID-looking input is treated as a
      symbol and routed through read_text_snippet_by_symbol.
    - explicit_uuid=True (read_text_snippet_by_uuid): input is treated as a
      UUID first (via beacon_get_code_snippet, which includes prefix
      hallucination-tolerance). NEW: if that UUID resolution FAILS, we FALL
      BACK to the SAME symbol resolver used by the auto path, so an agent that
      accidentally passes a symbol name to the by-uuid tool (a mistake that
      became more likely as the agent instructions were trimmed) still gets a
      snippet. Only if the symbol fallback ALSO finds nothing do we raise --
      and then with a UUID-framed error, so the far end reads correctly for
      the entry point the caller actually used.

    This helper is intentionally the *only* place that talks to the
    underlying snippet-resolution helpers so that MCP tools never call
    each other directly (which breaks in some FastMCP environments).
    A resolved-node extraction failure is not a handle miss: it retains its
    file/id/candidates and never triggers symbol fallback or a suppress read.
    """
    client = get_client()
    candidate = (input_str or "").strip()

    # UUID vs symbol detection only in auto mode. THE one UUID-shaped-handle
    # gate ([ap:G5C9BX]): full UUID or any of its prefixes down to the 8-hex
    # first segment (bracketed forms included) -- the same gate
    # _beacon_snippet_impl uses, replacing the former inline len>=32
    # duplicate that made an 8-hex segment fall to the symbol leg.
    is_likely_uuid = _looks_like_uuid_source_handle(candidate)

    async def _snippet_by_symbol(sym: str) -> dict[str, Any]:
        """Resolve ``sym`` through the SHARED symbol pipeline.

        Delegates to the client-level ``read_text_snippet_by_symbol`` helper
        (NOT another MCP tool -- FunctionTool objects are not directly
        awaitable) and returns its client result dict (U01: the dict, with
        file_lines, so the caller can render the numbered view). This is the
        auto-mode non-UUID path; on zero/multiple matches it raises exactly
        what read_text_snippet_by_symbol raises.
        """
        # Dan's ruling [ap:7ORCPL]: the symbol leg ignores suppressed subtrees.
        suppress_tags = await _beacon_symbol_suppress_tags()
        if _rate_limiter:
            await _rate_limiter.acquire()
        try:
            result_local = await client.read_text_snippet_by_symbol(
                symbol=sym,
                file_path=None,
                symbol_kind="auto",
                context=context,
                suppress_tags=suppress_tags,
            )
            if _rate_limiter:
                _rate_limiter.on_success()
        except Exception as e:  # noqa: BLE001
            if (
                _rate_limiter
                and hasattr(e, "__class__")
                and e.__class__.__name__ == "RateLimitError"
            ):
                _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
            raise
        if not isinstance(result_local, dict):
            raise RuntimeError("Unexpected result from read_text_snippet_by_symbol")
        return result_local

    if not explicit_uuid and not is_likely_uuid:
        # Auto mode, non-UUID-looking input: treat as symbol.
        log_event(
            f"read_text_snippet: input {candidate!r} doesn't look like UUID; treating as symbol",
            "SNIPPET",
        )
        return await _snippet_by_symbol(candidate)

    # UUID path: delegate to beacon_get_code_snippet (includes hallucination tolerance).
    if _rate_limiter:
        await _rate_limiter.acquire()

    uuid_error: Exception | None = None
    result: Any = None
    try:
        result = await client.beacon_get_code_snippet(
            beacon_node_id=candidate,
            context=context,
        )
        if _rate_limiter:
            _rate_limiter.on_success()
    except Exception as e:  # noqa: BLE001
        if (
            _rate_limiter
            and hasattr(e, "__class__")
            and e.__class__.__name__ == "RateLimitError"
        ):
            _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
            # A rate-limit is a transient transport failure, NOT a
            # UUID-resolution miss; never mask it with the symbol fallback.
            raise
        if getattr(e, "source_extraction_failed", False):
            raise
        # An AMBIGUOUS handle (a colliding prefix; [ap:G5C9BX]) carries its
        # candidate list on the exception: it is a LOUD did-you-mean, never a
        # resolution miss -- the same stop-on-ambiguity invariant Layer 3
        # enforces. Never mask it with the symbol fallback either.
        if getattr(e, "candidates", None):
            raise
        # Any other exception means the UUID did not resolve to a snippet.
        uuid_error = e

    if uuid_error is None:
        if not isinstance(result, dict):
            raise RuntimeError("Unexpected result from beacon_get_code_snippet")
        if result.get("success", False):
            # U01: return the client result DICT (with file_lines) — the
            # legacy raw-text wrapper extracts the snippet field from it.
            return result
        # success=False is also a UUID-resolution failure -> fall back below.
        uuid_error = RuntimeError(
            result.get("error", "Unknown error from beacon_get_code_snippet")
        )

    # ------------------------------------------------------------------
    # UUID resolution failed -> SYMBOL FALLBACK.
    #
    # An agent that accidentally passes a symbol name to read_text_snippet_by_
    # uuid (a mistake that became more likely once the agent instructions were
    # trimmed for the Claude Code skill migration) should still get a snippet.
    # We reuse the ONE shared symbol-resolution pipeline via its structured,
    # NON-RAISING candidates mode (return_candidates_only=True) so we branch on
    # match_count DETERMINISTICALLY -- no fragile parsing of exception message
    # text. match_count is authoritative:
    #   1 -> read the snippet for that exact UUID (identical to what the symbol
    #        tool returns on a unique match, since both go through
    #        beacon_get_code_snippet).
    #   N -> raise the SAME structured disambiguation the symbol tool surfaces
    #        (candidate list with UUIDs), unchanged in all relevant aspects.
    #   0 -> raise a UUID-framed not-found error (the ONE far-end difference:
    #        the message matches the entry point the caller actually used).
    # ------------------------------------------------------------------
    log_event(
        f"read_text_snippet: UUID resolution failed for {candidate!r} "
        f"({uuid_error}); falling back to shared symbol resolver",
        "SNIPPET",
    )

    # [ap:7ORCPL] Gap 1: the symbol fallback of a UUID-shaped handle is a
    # SYMBOL leg -- the describe promises it honours the global suppression
    # list exactly as the auto-mode symbol path above does. The list is read
    # LAZILY, only now that the fallback actually runs, so an exact UUID
    # that resolves never needs a connected Workflowy tab.
    try:
        suppress_tags = await _beacon_symbol_suppress_tags()
    except Exception as e:  # noqa: BLE001
        raise RuntimeError(
            f"Could not resolve {candidate!r} as a Workflowy UUID "
            f"(UUID lookup failed: {uuid_error}); reading the global "
            f"suppression list the symbol fallback needs failed: {e}"
        ) from e

    if _rate_limiter:
        await _rate_limiter.acquire()
    try:
        cand = await client.read_text_snippet_by_symbol(
            file_path=None,
            symbol=candidate,
            symbol_kind="auto",
            context=context,
            return_candidates_only=True,
            suppress_tags=suppress_tags,
        )
        if _rate_limiter:
            _rate_limiter.on_success()
    except Exception as e:  # noqa: BLE001
        if (
            _rate_limiter
            and hasattr(e, "__class__")
            and e.__class__.__name__ == "RateLimitError"
        ):
            _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
            raise
        # The candidates-only resolver does NOT raise on zero/many matches; an
        # exception here is a genuine internal failure. Surface it under the
        # UUID framing (that is the entry point the caller used).
        raise RuntimeError(
            f"Could not resolve {candidate!r} as a Workflowy UUID "
            f"(UUID lookup failed: {uuid_error}); the symbol-fallback resolver "
            f"itself errored: {e}"
        ) from e

    match_count = int(cand.get("match_count", 0)) if isinstance(cand, dict) else 0
    candidates = cand.get("candidates", []) if isinstance(cand, dict) else []

    if match_count == 1 and candidates:
        resolved_uuid = str(candidates[0].get("uuid") or "").strip()
        if resolved_uuid:
            log_event(
                f"read_text_snippet: symbol fallback resolved {candidate!r} -> "
                f"UUID {resolved_uuid}",
                "SNIPPET",
            )
            if _rate_limiter:
                await _rate_limiter.acquire()
            try:
                result2 = await client.beacon_get_code_snippet(
                    beacon_node_id=resolved_uuid,
                    context=context,
                )
                if _rate_limiter:
                    _rate_limiter.on_success()
            except Exception as e:  # noqa: BLE001
                if (
                    _rate_limiter
                    and hasattr(e, "__class__")
                    and e.__class__.__name__ == "RateLimitError"
                ):
                    _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
                raise
            if not isinstance(result2, dict) or not result2.get("success", False):
                raise RuntimeError(
                    f"Symbol fallback matched {candidate!r} to UUID {resolved_uuid}, "
                    f"but reading its snippet failed: "
                    f"{result2.get('error') if isinstance(result2, dict) else result2!r}"
                )
            # U01: return the client result DICT (with file_lines).
            return result2

    if match_count > 1:
        # AMBIGUOUS: surface the SAME disambiguation the symbol tool would,
        # including each candidate's UUID -- so the caller can retry with an
        # exact handle. Structured detection (match_count), not string-parsing.
        lines = [
            f"{candidate!r} did not resolve as a Workflowy UUID, and as a symbol "
            f"it is AMBIGUOUS ({match_count} matches). Retry with an exact UUID "
            f"(or a file_path via read_text_snippet_by_symbol):"
        ]
        for c in candidates:
            nm = c.get("name") or ""
            fp = c.get("file_path") or ""
            aq = c.get("ast_qualname") or ""
            uu = c.get("uuid") or ""
            detail = " | ".join(x for x in (nm, aq, fp) if x)
            lines.append(f"  - {uu}  {detail}".rstrip())
        raise RuntimeError("\n".join(lines))

    # ZERO matches by UUID AND by symbol: the one intentional far-end
    # difference -- a UUID-framed not-found error for the UUID entry point.
    raise RuntimeError(
        f"Could not resolve {candidate!r} as a Workflowy UUID "
        f"(UUID lookup failed: {uuid_error}) and no symbol matched it either. "
        f"Check the UUID, or pass a valid function/class/beacon symbol."
    )


# @beacon[
#   id=auto-beacon@_read_text_snippet_impl-lsln,
#   role=⚡ _read_text_snippet_impl(input_str: str, context: int),
#   slice_labels=nexus-md-header-path,ra-snippet-range,ra-reconcile,ra-read-text-snippet,
#   kind=ast,
#   comment=Legacy raw-text delegate of _read_text_snippet_result_impl: resolves through the one shared body, then returns only the snippet field as plain text (the pre-2026-09-27 output, byte-identical).,
# ]
async def _read_text_snippet_impl(
    input_str: str,
    context: int,
    *,
    explicit_uuid: bool = False,
) -> str:
    """Legacy raw-text wrapper: resolve through the one shared resolution
    body, then return only the snippet field as plain text."""
    result = await _read_text_snippet_result_impl(
        input_str, context, explicit_uuid=explicit_uuid
    )
    snippet = result.get("snippet", "")
    return snippet if isinstance(snippet, str) else str(snippet)


# Tool: Beacon-based text snippet (read_text_file twin)
@_legacy_tool(
    name="read_text_snippet",
    description=(
        "Return a raw text snippet anchored by a Cartographer beacon/AST/heading/file "
        "node, using the same resolution pipeline as beacon_get_code_snippet, but "
        "returning only the snippet text. This is the go-to replacement for "
        "read_text_file on Cartographer-mapped code: always use this (or its UUID/" "symbol "
        "variants) instead of read_text_file when working with mapped repos."
    ),
)
# @beacon[
#   id=auto-beacon@read_text_snippet-37kd,
#   role=⚡ read_text_snippet(beacon_node_id: str, context: int),
#   slice_labels=nexus-md-header-path,ra-snippet-range,ra-reconcile,ra-read-text-snippet,
#   kind=ast,
# ]
async def read_text_snippet(
    beacon_node_id: str,
    context: int = 20,
) -> str:
    """Return raw text snippet anchored by a Cartographer node.

    This is a thin wrapper around WorkFlowyClientNexus.beacon_get_code_snippet and
    read_text_snippet_by_symbol that returns only the ``snippet`` field as plain
    text. It uses the same resolution pipeline as beacon_get_code_snippet:

    - BEACON (AST|SPAN) metadata when present
    - AST_QUALNAME / MD_PATH when present for .py/.md
    - Implicit search or top-of-file fallback for other Cartographer FILE/child nodes

    Robustness:
    - If beacon_node_id doesn't look like a UUID (no hyphens, <8 chars, etc.),
      treats it as a symbol and routes through the client-level
      read_text_snippet_by_symbol helper.
    - Supports UUID hallucination tolerance (prefix matching) via
      beacon_get_code_snippet.

    This is the advanced, Cartographer-aware twin of read_text_file and should
    be used instead of read_text_file for any Cartographer-mapped code.
    """
    return await _read_text_snippet_impl(
        input_str=beacon_node_id,
        context=context,
        explicit_uuid=False,
    )


# Tool: UUID-based text snippet (explicit UUID variant)
@_legacy_tool(
    name="read_text_snippet_by_uuid",
    description=(
        "Return a raw text snippet anchored by a Workflowy UUID. "
        "Explicit UUID variant of read_text_snippet. Use this for "
        "Cartographer-mapped code when you have a UUID from GLIMPSE; do not "
        "fall back to read_text_file. If the value does not resolve as a UUID, "
        "it is retried through the shared symbol resolver (so a symbol passed "
        "here by mistake still works); only if neither resolves is an error "
        "returned."
    ),
)
# @beacon[
#   id=auto-beacon@read_text_snippet_by_uuid-ji9w,
#   role=⚡ read_text_snippet_by_uuid(beacon_node_id: str, context: int),
#   slice_labels=nexus-md-header-path,ra-snippet-range,ra-reconcile,ra-read-text-snippet,
#   kind=ast,
# ]
async def read_text_snippet_by_uuid(
    beacon_node_id: str,
    context: int = 20,
) -> str:
    """Return raw text snippet anchored by a Cartographer node UUID.

    This is an explicit-UUID variant of read_text_snippet: input is treated as
    a UUID FIRST. Provided for naming symmetry:

    - read_text_snippet: accepts UUID or symbol (auto-detects)
    - read_text_snippet_by_uuid: explicit UUID intent
    - read_text_snippet_by_symbol: explicit symbol intent

    Supports UUID hallucination tolerance via prefix matching in the
    underlying beacon_get_code_snippet implementation.

    SYMBOL FALLBACK (added July 2026): if the value does NOT resolve as a UUID,
    it is retried through the SAME shared symbol-resolution pipeline that backs
    read_text_snippet_by_symbol / read_uuid_from_symbol (via its structured,
    non-raising candidates mode). So a symbol name accidentally passed to this
    UUID entry point still returns a snippet on a unique match, or a structured
    disambiguation list (with UUIDs) on an ambiguous one. Only when the value
    resolves as NEITHER a UUID NOR a symbol is an error raised -- and then it
    is framed as a UUID-not-found error, matching this entry point. This makes
    the by-uuid tool forgiving of the common UUID-vs-symbol mix-up without
    changing the unique-match result (identical to the symbol tool, since both
    ultimately read via beacon_get_code_snippet).
    """
    return await _read_text_snippet_impl(
        input_str=beacon_node_id,
        context=context,
        explicit_uuid=True,
    )


# Tool: Symbol-based text snippet (handle-first variant)
@_legacy_tool(
    name="read_text_snippet_by_symbol",
    description=(
        "Return a raw text snippet by optional file path/name and symbol "
        "(function name, AST_QUALNAME, or beacon id/role). Avoids requiring "
        "agents to supply Workflowy UUIDs; the server resolves symbol → node → snippet."
    ),
)
# @beacon[
#   id=auto-beacon@read_text_snippet_by_symbol-ewti,
#   role=⚡ read_text_snippet_by_symbol(symbol: str, file_path, symbol_kind: str, context: int),
#   slice_labels=nexus-md-header-path,ra-snippet-range,ra-reconcile,ra-read-text-snippet,handle-resolution,
#   kind=ast,
# ]
async def read_text_snippet_by_symbol(
    symbol: str,
    file_path: str | None = None,
    symbol_kind: str = "auto",
    context: int = 10,
) -> str:
    """Return raw text snippet resolved from symbol + optional file path.

    This is the go-to symbol-based snippet tool for Cartographer-mapped code;
    use this instead of read_text_file when you know a symbol and optional
    file path.

    This is a handle-based companion to read_text_snippet that resolves
    symbols (function names, AST_QUALNAME, beacon ids/roles) without
    requiring Workflowy UUIDs from agents. It:

    - Loads the cached /nodes-export snapshot.
    - Identifies Cartographer FILE nodes by their Path:/Root: headers.
    - Optionally restricts search to FILE(s) matching file_path (basename or full path).
    - Matches symbol within chosen FILE subtree(s) by:
        - Beacon id or role (BEACON blocks in note),
        - AST_QUALNAME (Python/JS/TS AST nodes),
        - Normalized node name (function/method/heading).
    - On unique match, delegates to beacon_get_code_snippet and returns snippet text.
    - On zero/multiple matches, raises NetworkError with disambiguation hints.

    Args:
        symbol: Function name, AST_QUALNAME, or beacon id/role to search for.
        file_path: Optional file path (basename or full path) to restrict search.
                   If None, searches all Cartographer FILE nodes.
        symbol_kind: "auto" (default), "beacon", "ast", or "name".
                     Controls which matching strategies are enabled.
        context: Lines of context around the snippet (default 10).

    Returns:
        Raw snippet text (same format as read_text_snippet).

    Raises:
        NetworkError when symbol is not found or is ambiguous.
    """
    client = get_client()

    async def _call(file_path_arg: str | None) -> dict:
        if _rate_limiter:
            await _rate_limiter.acquire()

        try:
            r = await client.read_text_snippet_by_symbol(
                file_path=file_path_arg,
                symbol=symbol,
                symbol_kind=symbol_kind,
                context=context,
            )
            if _rate_limiter:
                _rate_limiter.on_success()
        except Exception as e:  # noqa: BLE001
            if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
                _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
            raise

        if not isinstance(r, dict):
            raise RuntimeError("Unexpected result from read_text_snippet_by_symbol")

        if not r.get("success", False):
            raise RuntimeError(r.get("error", "Unknown error from read_text_snippet_by_symbol"))

        return r

    try:
        result = await _call(file_path)
    except Exception as e_original:  # noqa: BLE001
        # Common failure mode: caller over-specifies file_path (wrong basename or
        # a partial/incorrect path). In those cases, resolving by symbol alone
        # often succeeds.
        fp = (file_path or "").strip()
        if fp:
            log_event(
                "read_text_snippet_by_symbol: first attempt failed with file_path="
                f"{file_path!r}; retrying without file_path. Error: {e_original}",
                "SNIPPET",
            )
            try:
                result = await _call(None)
            except Exception:  # noqa: BLE001
                # Prefer surfacing the original error (it contains the path that
                # was requested, which is useful for debugging).
                raise e_original
        else:
            raise

    snippet = result.get("snippet", "")
    if not isinstance(snippet, str):
        snippet = str(snippet)

    return snippet


# Tool: Symbol-to-UUID resolver (UUID-returning twin of read_text_snippet_by_symbol)
@_legacy_tool(
    name="read_uuid_from_symbol",
    description=(
        "Resolve a symbol (function name, AST_QUALNAME, or beacon id/role) to its "
        "Workflowy UUID(s) WITHOUT reading source. Same parameters and resolution "
        "pipeline as read_text_snippet_by_symbol, but returns the resolved node "
        "UUID(s) instead of a code snippet. Use this to cheaply recover the UUID of "
        "a node you saw in a Markdown-mode GLIMPSE (which strips UUIDs) so you can "
        "tag/move/edit it, WITHOUT re-GLIMPSEing the whole slice in full/UUID mode. "
        "Returns match_count (0/1/N) and a structured candidates list; on a single "
        "match you get exactly one UUID, on many you get a disambiguation list (each "
        "with its UUID), and on none you get an empty list."
    ),
)
# @beacon[
#   id=auto-beacon@read_uuid_from_symbol-uuidsym,
#   role=⚡ read_uuid_from_symbol(symbol: str, file_path, symbol_kind: str),
#   slice_labels=nexus-md-header-path,ra-snippet-range,ra-reconcile,ra-read-text-snippet,handle-resolution,
#   kind=ast,
# ]
async def read_uuid_from_symbol(
    symbol: str,
    file_path: str | None = None,
    symbol_kind: str = "auto",
) -> dict:
    """Resolve a symbol to its Workflowy UUID(s) without reading source.

    The UUID-returning twin of read_text_snippet_by_symbol. It runs the
    IDENTICAL symbol-resolution pipeline (FILE-node discovery, HIDE
    CARTOGRAPHER filtering, beacon/AST_QUALNAME/name matching, dotted-tail and
    contains fallbacks, and the very same per-candidate disambiguation detail),
    but at the final step returns the resolved node UUID(s) instead of the
    source bytes at that location.

    WHY: Markdown-mode GLIMPSE (the default) does not show UUIDs. Recovering a
    handful of UUIDs out of hundreds of visible nodes by re-GLIMPSEing the
    whole slice in full/UUID mode is hugely token-expensive (the bracketed form
    can be several times larger than the Markdown form). This tool resolves a
    single symbol straight to its UUID at near-zero cost -- ideal when you have
    read a beacon slice in Markdown and now want the UUIDs of the few nodes you
    intend to tag / move / edit.

    Args:
        symbol: Function name, AST_QUALNAME, or beacon id/role to resolve.
        file_path: Optional file path (basename or full path) to restrict the
                   search. If None, searches all Cartographer FILE nodes.
        symbol_kind: "auto" (default), "beacon", "ast", or "name".

    Returns:
        A dict with:
          - success (bool)
          - match_count (int): 0, 1, or N.
          - resolved_symbol / resolved_symbol_kind / resolved_symbol_kind_input
          - candidates (list): one descriptor per resolved node, each with
            uuid, name, file_path, ast_qualname, line, and via (which strategy
            matched). Length == match_count (capped; see truncated).
          - truncated (int): candidates omitted beyond the cap (N case only).

    Notes:
        - Unlike the snippet tool, zero and multiple matches do NOT raise -- the
          structured result reports match_count and the candidate list so the
          caller can decide. (A genuinely empty/invalid symbol still raises.)
        - Like the snippet tool, an over-specified file_path that fails is
          retried once without file_path (symbol alone often resolves).
    """
    client = get_client()

    async def _call(file_path_arg: str | None) -> dict:
        if _rate_limiter:
            await _rate_limiter.acquire()

        try:
            r = await client.read_uuid_from_symbol(
                file_path=file_path_arg,
                symbol=symbol,
                symbol_kind=symbol_kind,
            )
            if _rate_limiter:
                _rate_limiter.on_success()
        except Exception as e:  # noqa: BLE001
            if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
                _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
            raise

        if not isinstance(r, dict):
            raise RuntimeError("Unexpected result from read_uuid_from_symbol")

        if not r.get("success", False):
            raise RuntimeError(r.get("error", "Unknown error from read_uuid_from_symbol"))

        return r

    try:
        result = await _call(file_path)
    except Exception as e_original:  # noqa: BLE001
        # Same retry posture as read_text_snippet_by_symbol: an over-specified
        # file_path (wrong basename / partial path) often resolves by symbol
        # alone. Note this only catches a genuine ERROR (e.g. no FILE node
        # matched the file_path); a successful resolution with match_count==0 is
        # NOT an error here and is returned directly.
        fp = (file_path or "").strip()
        if fp:
            log_event(
                "read_uuid_from_symbol: first attempt failed with file_path="
                f"{file_path!r}; retrying without file_path. Error: {e_original}",
                "SNIPPET",
            )
            try:
                result = await _call(None)
            except Exception:  # noqa: BLE001
                raise e_original
        else:
            raise

    return result


# Tool: AP-ID resolver (pure-Workflowy twin of read_uuid_from_symbol)
@_legacy_tool(
    name="read_uuid_from_anchor_point",
    description=(
        "Resolve an anchor-point handle -- an AP-ID of the form [ap:CORE] (a "
        "variable-length base36 core, e.g. [ap:APRSLV3] or [ap:K7M2QF]) -- to its "
        "Workflowy UUID(s). This is the PURE-WORKFLOWY "
        "twin of read_uuid_from_symbol: AP-IDs are permanent, human-readable "
        "citation handles that live at the START of a plain Workflowy node's NAME "
        "and have NO on-disk backing, so read_uuid_from_symbol (which keys off "
        "Cartographer FILE/AST/beacon mappings) correctly returns 0 matches for "
        "them. Use this instead to turn an [ap:XXXXXX] you saw in a Markdown-mode "
        "GLIMPSE into a UUID you can act on. Input is lenient: pass '[ap:K7M2QF]', "
        "'ap:K7M2QF', or bare 'K7M2QF', in any case. Matching is a strict, exact "
        "match on the 6-char core, found only at the LEADING edge of a node name "
        "(after any leading whitespace/emoji) -- there is deliberately NO prefix or "
        "fuzzy fallback. Returns match_count (0/1/N) and a structured candidates "
        "list; a single match gives one UUID, duplicates (a copy/paste accident) "
        "return all colliding nodes as ambiguities (each with its UUID + node name) "
        "and are never auto-picked, and none gives an empty list."
    ),
)
# @beacon[
#   id=note-sessions@read_uuid_from_anchor_point-apid,
#   role=⚡ read_uuid_from_anchor_point(ap_id: str),
#   slice_labels=nexus-path-resolution-logic,ra-workflowy-cache,handle-resolution,
#   kind=ast,
# ]
async def read_uuid_from_anchor_point(ap_id: str) -> dict:
    """Resolve an AP-ID handle ([ap:XXXXXX]) to its Workflowy UUID(s).

    The pure-Workflowy twin of read_uuid_from_symbol. AP-IDs (Mechanical
    Convention 1) are permanent, human-readable citation handles living at the
    start of a plain Workflowy node NAME with no on-disk backing, so the symbol
    resolver correctly returns zero matches for them; this tool resolves them.

    Args:
        ap_id: The AP-ID handle. Lenient input -- '[ap:K7M2QF]', 'ap:K7M2QF',
            or bare 'K7M2QF', in any case. Exact match on the 6-char core.

    Returns:
        A dict with:
          - success (bool)
          - match_count (int): 0, 1, or N.
          - resolved_ap_id (str | None): the normalized uppercase 6-char core,
            or None when ap_id was not a well-formed handle (match_count 0).
          - candidates (list): one {uuid, name} per matching node. Length ==
            match_count (capped).
          - truncated (int): candidates omitted beyond the cap (N case only).

    Notes:
        - Leading-only match (after leading whitespace/emoji): a note that
          merely REFERENCES an AP-ID mid-text is never matched.
        - Zero and multiple matches do NOT raise -- the structured result
          reports match_count and the candidate list so the caller decides.
          (A genuinely empty ap_id argument still raises.)
        - Delegates to the ONE shared resolver
          (resolve_uuid_from_anchor_point) that also backs the client method
          and the forthcoming anchor-point-family generalization.
    """
    client = get_client()

    if _rate_limiter:
        await _rate_limiter.acquire()

    try:
        result = await client.read_uuid_from_anchor_point(ap_id=ap_id)
        if _rate_limiter:
            _rate_limiter.on_success()
    except Exception as e:  # noqa: BLE001
        if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
            _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
        return {"success": False, "error": str(e)}

    if not isinstance(result, dict):
        return {"success": False, "error": "Unexpected result from read_uuid_from_anchor_point"}

    return result


@_legacy_tool(
    name="update_beacon_from_node",
    description=(
        "Update/create/delete a Cartographer beacon based on a single Workflowy "
        "node's name/note (F12-per-node). This only edits the underlying source "
        "file; the client should update the cached node name/note separately."
    ),
)
# @beacon[
#   id=auto-beacon@update_beacon_from_node-kiam,
#   role=⚡ update_beacon_from_node(node_id: str, name: str, note: str),
#   slice_labels=ra-reconcile,nexus--tags,beacon-writeback,
#   kind=ast,
#   comment=Legacy single-node tool retains its existing Q3 lease rate limiter and fail-closed writer result while delegating an explicitly labelled post-writer current-disk findings and noop-reason projection.,
# ]
async def update_beacon_from_node(
    node_id: str,
    name: str,
    note: str,
) -> dict:
    """Legacy wrapper retains writer success and adds current-disk evidence.

    U06's projection observes after the protected writer, not its precommit
    snapshot. Findings do not gate the write or change noop success mapping.

    The client is expected to:
    - Call this tool when F12 is pressed on a Cartographer-mapped node.
    - Use the returned "base_name" to update the cached node name (stripping
      trailing tags) via update_cached_node_name or equivalent.
    - Use the returned beacon metadata (role/slice_labels/comment) to
      rebuild the note's BEACON block for local cache sync.
    """
    client = get_client()

    if _rate_limiter:
        await _rate_limiter.acquire()

    leases: list[dict[str, Any]] = []
    primary_error: BaseException | None = None
    try:
        leases = await _acquire_single_beacon_q3_lease(node_id)
        result = await client.update_beacon_from_node(
            node_id=node_id,
            name=name,
            note=note,
        )
        if isinstance(result, dict):
            from .beacon_batch import project_sync_result

            result = await asyncio.to_thread(project_sync_result, result, client=client, node_id=node_id)
        if _rate_limiter:
            _rate_limiter.on_success()
        return result
    except asyncio.CancelledError as exc:
        primary_error = exc
        raise
    except Exception as e:  # noqa: BLE001
        primary_error = e
        if _rate_limiter and hasattr(e, "__class__") and e.__class__.__name__ == "RateLimitError":
            _rate_limiter.on_rate_limit(getattr(e, "retry_after", None))
        return {"success": False, "error": str(e)}
    finally:
        if leases:
            await _release_q3_leases_preserving_primary(
                leases,
                primary_error=primary_error,
            )


