def _reattach_stored_order_index(stored_name: str, new_name: str) -> str:
    """Preserve the stored ``[n]`` order index when a rename omits it (U7).

    [ap:256S33] postcondition 3: the trailing ``[-N]`` leaf index and the
    leading ``[n]`` expander index are DATA of the stored name's grammar.
    Both names are parsed with the ONE grammar authority
    (:func:`parse_slice_group_name` in f8_slice_policy — no hand-rolled
    suffix parsing). When the supplied new name carries NO order index and
    the stored name carried one, the stored index is re-attached in the
    stored form: ``… [N]`` on the last segment for a leaf, or the ``[n]``
    prefix for an expander. An explicitly supplied index is honored
    verbatim (that is how an index changes). Explicit REMOVAL of an index
    by rename is not supported (recorded, Tier 3 — no caller has ever had
    that path). Pure; no I/O.
    """
    stored_parts = parse_slice_group_name(stored_name)
    new_parts = parse_slice_group_name(new_name)
    if new_parts["index"] is not None or stored_parts["index"] is None:
        return new_name
    if stored_parts["is_expander"]:
        return f"[{stored_parts['index']}]{new_name}"
    return f"{new_name} [{stored_parts['index']}]"


@_legacy_tool(
    name="update_slice_group",
    description=(
        "Update an existing F8 slice group, resolved by group_id (preferred) "
        "OR name -- the FULL stored name OR the semantic SHORT name (final "
        "pipe segment, [n] index stripped), case-insensitive; errors with "
        "colliding ids on a duplicate name. Pass ONLY "
        "the fields you want to change; any omitted field is left UNCHANGED. "
        "RENAME NOTE: 'new_name' replaces the WHOLE stored string -- to "
        "rename a group that lives inside a category path, supply the FULL "
        "path with the new leaf (a bare name lifts it out of its category); "
        "to re-file or reorder it, edit the pipe path / trailing [n] "
        "accordingly. "
        "Updatable fields: name; description (free text, may be set to empty); "
        "tags (REPLACES the whole tag list - comma-separated string OR list, "
        "'#'-optional, normalized + postfix-variants collapsed to base exactly "
        "like create_slice_group); root_uuid (exact UUID, its 8-hex first segment, "
        "a unique longer prefix, or [ap:CORE], resolved by the standard resolver "
        "and stored as the full UUID; unresolvable/ambiguous refuses before persistence); default_sort_by "
        "('none'|'created'|'modified') and/or default_sort_direction "
        "('asc'|'desc') - the group's SAVED DEFAULT render sort (only the "
        "supplied field changes; the other keeps its stored value). Also "
        "make_active (default false) "
        "to make this the active F8 group. Common use: the agent GLIMPSEs a "
        "slice and writes a better description. Returns the updated record "
        "(plus collapsed/dropped tag report when tags were changed). Reads+"
        "writes live config on the target tab; fails loudly if no tab."
    ),
)
# @beacon[
#   id=slice-groups@tool_update_slice_group,
#   slice_labels=nexus--config,slices,
#   kind=ast,
#   comment=MCP tool: resolve a group by id/name, apply ONLY the supplied fields (name/description/tags[replace, normalized]/root_uuid/default sort/make_active), resolve a supplied root handle through the standard generic-node boundary and store the full UUID (unresolvable/ambiguous refuses before persistence), persist the whole array via set_slice_groups, return the updated record. Omitted fields unchanged.,
# ]
async def _slice_group_update_core(
    group_id: str | None = None,
    name: str | None = None,
    new_name: str | None = None,
    description: str | None = None,
    tags=None,
    root_uuid: str | None = None,
    default_sort_by: str | None = None,
    default_sort_direction: str | None = None,
    make_active: bool = False,
    target_tab: str | None = None,
) -> dict:
    """Legacy surface: name resolves identity and new_name performs rename."""
    group_handle = group_id or name or ""
    root_handle = root_uuid
    canonical_name = new_name
    try:
        if not isinstance(group_handle, str) or not group_handle.strip():
            return {"success": False, "error": "Provide group_handle to identify the group."}
        # U7 ([ap:256S33]): RMW site 1/4 — serialized by
        # _SLICE_GROUP_CONFIG_LOCK from the config read until the write ack
        # (see the lock's definition), so a parallel create/update/delete/
        # merge.persist can never interleave a stale base into this merge.
        async with _SLICE_GROUP_CONFIG_LOCK:
            groups, active_id, postfixes, _gn, _reply = (
                await _resolve_slice_group_config(target_tab)
            )
            resolved, error = _resolve_slice_group_handle(groups, group_handle)
            if error:
                return error
            idx = next(
                (
                    i
                    for i, group in enumerate(groups)
                    if str(group.get("id")) == str(resolved.get("id"))
                ),
                -1,
            )
            if idx < 0:
                return {"success": False, "error": f"Slice group {group_handle!r} disappeared during resolution."}

            next_groups = [dict(g) for g in groups]
            target = next_groups[idx]
            collapsed: list = []
            dropped: list = []
            if isinstance(canonical_name, str) and canonical_name.strip():
                # U7 postcondition 3: the [n] order index rides INSIDE the
                # stored name and is data, not decoration — a rename that
                # omits it preserves the stored one (ONE grammar parser, no
                # hand-rolled suffix logic); an explicit index is honored.
                target["name"] = _reattach_stored_order_index(
                    str(target.get("name") or ""), canonical_name.strip()
                )
            if description is not None:
                target["description"] = str(description).strip()
            if root_handle is not None:
                target["root_uuid"] = await _resolve_generic_node_handle(
                    str(root_handle), label="slice_group.update root_handle"
                )
            if default_sort_by is not None or default_sort_direction is not None:
                existing_sort_by, existing_sort_direction = _slice_group_default_sort_fields(target)
                next_sort_by, next_sort_direction = _slice_group_default_sort_fields(
                    {
                        "default_sort_by": (
                            default_sort_by if default_sort_by is not None else existing_sort_by
                        ),
                        "default_sort_direction": (
                            default_sort_direction
                            if default_sort_direction is not None
                            else existing_sort_direction
                        ),
                    }
                )
                target["default_sort_by"] = next_sort_by
                target["default_sort_direction"] = next_sort_direction
            if tags is not None:
                norm = normalize_slice_group_tags(
                    tags,
                    auto_expand_postfix=postfixes["auto_expand"],
                    suppress_postfix=postfixes["suppress"],
                    deprecated_postfix=postfixes["deprecated"],
                )
                target["prefixes"] = norm["bases"]
                collapsed = norm["collapsed"]
                dropped = norm["dropped"]

            next_active = str(target.get("id")) if make_active else active_id
            ws_conn, ws_queue = await get_ws_connection_with_grace_wait(max_wait_seconds=6.0)
            if not (ws_conn and ws_queue):
                return {"success": False, "error": "No live Workflowy tab to persist the slice group."}
            client = get_client()
            ack = await client.set_slice_groups(
                ws_connection=ws_conn,
                ws_queue=ws_queue,
                expand_groups=next_groups,
                active_group=next_active,
                target_tab=target_tab,
            )
        persisted = list(ack.get("expand_groups") or next_groups)
        persisted_active = ack.get("active_group") or next_active
        updated = next(
            (g for g in persisted if str(g.get("id")) == str(target.get("id"))), target
        )
        return {
            "success": True,
            "slice_group": _slice_group_public_view(updated, persisted_active),
            "tags_collapsed_from_variants": collapsed,
            "tags_dropped": dropped,
            "short_name_collisions": (
                _short_name_collisions(
                    groups,
                    # U7: advise on the ACTUAL stored name (post order-index
                    # preservation), not the raw supplied string — identical
                    # for leaves (the parser strips the trailing index from
                    # short_name) and truthful for an expander re-attachment
                    # (an expander candidate yields no rows by design).
                    str(target.get("name") or ""),
                    exclude_id=str(target.get("id") or ""),
                )
                if isinstance(canonical_name, str) and canonical_name.strip()
                else []
            ),
        }
    except Exception as e:  # noqa: BLE001
        return {"success": False, "error": str(e)}


async def _slice_group_update_impl(
    group_handle: str,
    name: str | None = None,
    description: str | None = None,
    tags=None,
    root_handle: str | None = None,
    default_sort_by: str | None = None,
    default_sort_direction: str | None = None,
    make_active: bool = False,
    target_tab: str | None = None,
) -> dict:
    """Internal resolver/new-name split for canonical slice_group.update."""

    return await _slice_group_update_core(
        group_id=group_handle,
        new_name=name,
        description=description,
        tags=tags,
        root_uuid=root_handle,
        default_sort_by=default_sort_by,
        default_sort_direction=default_sort_direction,
        make_active=make_active,
        target_tab=target_tab,
    )


async def update_slice_group(
    group_id: str | None = None,
    name: str | None = None,
    new_name: str | None = None,
    description: str | None = None,
    tags=None,
    root_uuid: str | None = None,
    default_sort_by: str | None = None,
    default_sort_direction: str | None = None,
    make_active: bool = False,
    target_tab: str | None = None,
) -> dict:
    """Legacy delegate preserving resolver-name/new_name semantics."""

    if not group_id and not name:
        return {"success": False, "error": "Provide either group_id or name to identify the group."}
    return await _slice_group_update_impl(
        group_id or name or "",
        new_name,
        description,
        tags,
        root_uuid,
        default_sort_by,
        default_sort_direction,
        make_active,
        target_tab,
    )


# @beacon-close[
#   id=svcv1@shared-context-surface,
# ]
# @beacon-close[
#   id=svcv1@file-boundary,
# ]
if __name__ == "__main__":
    server_bootstrap.refuse_wsl_server("full server")
    # ☢️ NUCLEAR LOGGING OPTION ☢️
    # Redirect diagnostic text to stderr; binary MCP protocol output stays on stdout.
    import sys
    import logging
    
    # 1. Setup Root Logger to DEBUG
    root = logging.getLogger()
    root.setLevel(logging.DEBUG)
    
    # 2. Clear existing handlers to prevent duplicate/swallowed logs
    for h in root.handlers[:]:
        root.removeHandler(h)
        
    # 3. Create NUCLEAR StreamHandler to stderr
    handler = logging.StreamHandler(sys.stderr)
    # Simple format: [TIME] [LEVEL] Message
    handler.setFormatter(logging.Formatter('[%(asctime)s] [%(levelname)s] %(name)s: %(message)s', datefmt='%H:%M:%S'))
    root.addHandler(handler)
    
    # Redirect text print diagnostics while exposing the original stdout buffer to the MCP SDK.
    class StderrRedirector:
        """Redirect diagnostic text to stderr; preserve the original binary stdout for MCP."""
        def __init__(self, protocol_stdout):
            self.buffer = protocol_stdout.buffer

        def write(self, message):
            if message.strip(): # Avoid empty newline spam
                sys.stderr.write(f"[STDOUT] {message}\n")
        def flush(self):
            sys.stderr.flush()
            
    sys.stdout = StderrRedirector(sys.stdout)

    # 5. Log startup confirmation (via DAGGER logger + root logger)
    log_event("☢️ NUCLEAR LOGGING ACTIVE: DEBUG LEVEL ☢️", "SERVER")
    local_logger = _ClientLogger("SERVER")
    local_logger.error("STDERR TEST: This should appear in console (via logger.error)")
    print("Standard Output Redirection Test", file=sys.stderr)

    # Run the server
    mcp.run(transport="stdio")
